def _create_runbook_step(plan, *, now: int):
    """Create the exact, separate one-time shell approval for the current runbook step."""
    index = plan.current_index
    if plan.owner_id != ADMIN_ID or plan.requester_id != ADMIN_ID or not 0 <= index < len(plan.steps):
        return None
    try:
        pending = command_approval.create_pending(
            plan.requester_id, plan.owner_id, plan.device_id, plan.steps[index], now,
        )
    except (ValueError, command_approval.PendingStoreFull):
        return None
    if not shell_runbook.bind_pending(plan.plan_id, pending.request_id, step_index=index, now=now):
        command_approval.cancel_pending(pending.request_id, plan.owner_id)
        return None
    return pending


def _runbook_step_preview(pending, plan) -> str:
    return (
        f"<b>Runbook · шаг {plan.current_index + 1}/{len(plan.steps)}</b>\n"
        f"Устройство: {html.escape(plan.device_id)}\n"
        f"Срок подтверждения: {pending.expires_at}\n"
        "План подтверждён, но этот шаг ещё не запускался. Для каждого шага требуется отдельное одноразовое подтверждение владельца.\n"
        f"SHA-256: <code>{pending.command_hash}</code>\n<pre>{html.escape(pending.command_text)}</pre>"
    )


def _stop_runbook_for_request(
    request_id: str,
    *,
    now: int,
    outcome: str = "failed",
    exit_code: int | None = None,
) -> None:
    plan = shell_runbook.find_by_request(request_id, now=now)
    if plan is not None:
        if plan.state == "awaiting_step":
            shell_runbook.complete_step(
                request_id, success=False, now=now, outcome=outcome, exit_code=exit_code,
            )
        else:
            shell_runbook.fail_plan(
                plan.plan_id, owner_id=ADMIN_ID, now=now, outcome=outcome, exit_code=exit_code,
            )


@router.callback_query(OwnerFilter(), F.data == "cmd:shell_runbook")
async def on_cmd_shell_runbook(cq: CallbackQuery, state: FSMContext):
    target = str(SESSION.get("target") or "")
    if not target or target == "all":
        await cq.answer(_lex("single_device_only"), show_alert=True)
        return
    if cq.from_user is None or cq.from_user.id != ADMIN_ID or not _shell_request_allowed(ADMIN_ID, target):
        await cq.answer("Runbook доступен владельцу только для выбранного устройства с поддержкой shell approval.", show_alert=True)
        return
    await _start_authorized_input(state, Form.wait_shell_runbook, "cmd:shell_runbook", target, command_target=target)
    await _replace_callback_message(
        cq,
        "Введи 2–8 точных однострочных команд, по одной на строку. Сначала появится предпросмотр всего плана; затем каждый шаг потребует отдельного подтверждения.",
        reply_markup=back_to_device_kb(),
    )
    await cq.answer()


@router.message(OwnerFilter(), Form.wait_shell_runbook)
async def on_shell_runbook_input(message: Message, state: FSMContext):
    form_data = await state.get_data()
    await state.clear()
    target = form_data.get("command_target")
    actor = message.from_user.id if message.from_user else None
    if actor != ADMIN_ID or not target or target == "all" or SESSION.get("target") != target:
        await _replace_user_card(message, "Runbook отменён: владелец или выбранное устройство изменились.", reply_markup=back_to_device_kb())
        return
    if not _shell_request_allowed(actor, target):
        await _replace_user_card(message, "Runbook отменён: доступ к shell отозван или агент не поддерживает подтверждения.", reply_markup=back_to_device_kb())
        return
    try:
        plan = shell_runbook.create_plan(actor, ADMIN_ID, target, message.text or "", now=int(time.time()))
    except (ValueError, shell_runbook.RunbookStoreFull):
        await _replace_user_card(message, "План не принят. Нужны 2–8 непустых строк и не больше 3000 байт.", reply_markup=back_to_device_kb())
        return
    preview = _shell_runbook_draft_preview(plan)
    await _replace_user_card(message, "Черновик runbook передан владельцу на просмотр.", reply_markup=back_to_device_kb())
    delivered = await _notify_owner(preview, reply_markup=_shell_runbook_draft_keyboard(plan.plan_id), strict_delivery=True)
    if delivered is not True:
        shell_runbook.cancel_plan(plan.plan_id, owner_id=ADMIN_ID, now=int(time.time()))


async def _show_shell_runbook_templates(cq: CallbackQuery, offset: int):
    actor = cq.from_user.id if cq.from_user else None
    target = str(SESSION.get("target") or "")
    if actor != ADMIN_ID or not target or target == "all" or not _shell_request_allowed(actor, target):
        await cq.answer("Библиотека доступна владельцу при выбранном устройстве с shell approval.", show_alert=True)
        return
    rows = devices.list_shell_runbook_templates(actor, ADMIN_ID) or []
    if type(offset) is not int or offset < 0 or offset % 10 or offset >= max(len(rows), 10):
        await cq.answer("Страница шаблонов устарела.", show_alert=True)
        return
    page_rows = rows[offset:offset + 10]
    if rows:
        body = f"<b>Шаблоны runbook</b> · {offset + 1}–{min(offset + len(page_rows), len(rows))}/{len(rows)}\nЭто сохранённые заготовки, не история запусков. Выбор шаблона создаёт только черновик; запуск остаётся за отдельными подтверждениями.\n\n"
        body += "\n".join(
            f"• <b>{html.escape(row['name'])}</b> · {len(row['commands'])} шаг(а/ов) · изменён <code>{row['updated_at']}</code>"
            for row in page_rows
        )
    else:
        body = "<b>Шаблоны runbook</b>\nПока пусто. Создай черновик плана и сохрани его в библиотеку отдельной кнопкой."
    await _replace_callback_message(
        cq, body,
        reply_markup=_shell_runbook_template_library_keyboard(page_rows, offset=offset, total=len(rows)),
    )
    await cq.answer()


@router.callback_query(OwnerFilter(), F.data == "cmd:shell_runbook_templates")
async def on_cmd_shell_runbook_templates(cq: CallbackQuery):
    await _show_shell_runbook_templates(cq, 0)


