@router.callback_query(OwnerFilter(), F.data.startswith("cmd:shell-approve:"))
async def on_shell_approve(cq: CallbackQuery):
    actor = cq.from_user.id if cq.from_user else None
    if actor != ADMIN_ID:
        await cq.answer("Подтверждение доступно только владельцу.", show_alert=True)
        return
    pending = command_approval.get_pending(str(cq.data or "").removeprefix("cmd:shell-approve:"))
    runbook = shell_runbook.find_by_request(pending.request_id, now=int(time.time())) if pending is not None else None
    if (pending is None or pending.owner_id != ADMIN_ID
            or hashlib.sha256(pending.command_text.encode("utf-8")).hexdigest() != pending.command_hash
            or not _shell_request_allowed(pending.requester_id, pending.device_id)):
        if runbook is not None:
            _stop_runbook_for_request(pending.request_id, now=int(time.time()), outcome="authority_changed")
        await cq.answer("Запрос недействителен или права изменились.", show_alert=True)
        return
    if runbook is not None and (
        runbook.owner_id != ADMIN_ID or runbook.state != "awaiting_step"
        or runbook.device_id != pending.device_id
        or runbook.steps[runbook.current_index] != pending.command_text
        or not _shell_request_allowed(ADMIN_ID, pending.device_id)
    ):
        _stop_runbook_for_request(pending.request_id, now=int(time.time()), outcome="approval_invalid")
        await cq.answer("Runbook больше не действителен; следующий шаг не запускается.", show_alert=True)
        return
    # No await between the current authorization check and atomic consumption.
    approved = command_approval.consume_pending(pending.request_id, actor, pending.device_id, pending.command_hash, int(time.time()))
    if approved is None:
        _stop_runbook_for_request(pending.request_id, now=int(time.time()), outcome="approval_expired")
        await cq.answer("Запрос истёк или уже обработан.", show_alert=True)
        return
    try:
        ticket = shell_command_queue.enqueue(approved.device_id, approved.request_id)
    except ValueError:
        _stop_runbook_for_request(approved.request_id, now=int(time.time()), outcome="queue_error")
        await cq.answer("Не удалось поставить запрос в очередь. Создайте новый запрос.", show_alert=True)
        return
    try:
        if ticket.position > 1:
            await cq.answer()
            await _replace_callback_message(
                cq,
                f"⏳ Команда подтверждена и ждёт очередь на устройстве (позиция при постановке: {ticket.position}). "
                "Исходное подтверждение не продлевается.",
                reply_markup=back_to_device_kb(),
            )
        remaining = max(0.0, float(approved.expires_at - int(time.time())))
        if not await shell_command_queue.wait_turn(ticket, remaining):
            _audit_shell_result(approved, actor, "queue_expired", None)
            _stop_runbook_for_request(approved.request_id, now=int(time.time()), outcome="queue_expired")
            await _replace_callback_message(
                cq, "⌛ Срок подтверждения истёк в очереди. Команда не отправлялась; запроси её заново.",
                reply_markup=back_to_device_kb(),
            )
            return
        remaining = max(0.0, float(approved.expires_at - int(time.time())))
        capacity_wait = asyncio.create_task(shell_command_queue.acquire_capacity(
            ticket, limit=shell_command_queue.MAX_CONCURRENT_OWNER_TASKS, timeout=remaining,
        ))
        await asyncio.sleep(0)
        if ticket.capacity_position:
            await cq.answer()
            await _replace_callback_message(
                cq,
                f"⏳ Общий лимит параллельных задач владельца занят. "
                f"Позиция в очереди при постановке: {ticket.capacity_position}; "
                "срок подтверждения не продлевается.",
                reply_markup=back_to_device_kb(),
            )
        if not await capacity_wait:
            _audit_shell_result(approved, actor, "queue_expired", None)
            _stop_runbook_for_request(approved.request_id, now=int(time.time()), outcome="queue_expired")
            await _replace_callback_message(
                cq, "⌛ Срок подтверждения истёк в очереди общего лимита. Команда не отправлялась; запроси её заново.",
                reply_markup=back_to_device_kb(),
            )
            return
        await _dispatch_approved_shell(cq, approved, actor)
    finally:
        shell_command_queue.release(ticket)


async def _dispatch_approved_shell(cq: CallbackQuery, approved, actor: int) -> None:
    try:
        envelope = command_signing.sign_approved_command(
            request_id=approved.request_id, requester_id=approved.requester_id,
            approver_id=actor, device_id=approved.device_id, command=approved.command_text,
            issued_at=approved.created_at, expires_at=approved.expires_at,
            nonce=approved.nonce, key_id=command_signing.signing_key_id(),
        )
        if command_signing.verify_approved_command(
            envelope, command=approved.command_text,
            expected_device_id=approved.device_id, now=int(time.time()),
        ) is None:
            raise command_signing.CommandSigningUnavailable("command signing configuration is invalid")
        try:
            _audit_shell_result(approved, actor, "attempting", None)
        except OSError:
            _stop_runbook_for_request(approved.request_id, now=int(time.time()), outcome="audit_unavailable")
            await cq.answer("Журнал выполнения недоступен. Команда не отправлена.", show_alert=True)
            return
        sent = _publish_device_command(approved.device_id, "shell", id=approved.request_id,
                                       command=approved.command_text, approval=envelope)
    except (ValueError, command_signing.CommandSigningUnavailable):
        _audit_shell_result(approved, actor, "signing_unavailable", None)
        _stop_runbook_for_request(approved.request_id, now=int(time.time()), outcome="signing_unavailable")
        await cq.answer("Подпись команды недоступна. Создайте новый запрос после настройки сервера.", show_alert=True)
        return
    _audit_shell_result(approved, actor, "sent" if sent is True else "publish_unknown" if sent is None else "publish_failed", None)
    await cq.answer()
    dispatch_text = ("Команда отправлена." if sent is True else
                     "Доставка команды пока не подтверждена. Ожидаю ответ на тот же запрос; повторная отправка не выполняется."
                     if sent is None else _lex("mqtt_disconnected"))
    if sent is not False:
        active_shell_requests[approved.request_id] = {
            "device_id": approved.device_id,
            "owner_id": actor,
            "requester_id": approved.requester_id,
            "approver_id": actor,
            "command_hash": approved.command_hash,
        }
    await _replace_callback_message(
        cq, dispatch_text,
        reply_markup=_shell_running_kb(approved.request_id) if sent is not False else back_to_device_kb(),
    )
    if sent is False:
        _stop_runbook_for_request(approved.request_id, now=int(time.time()), outcome="publish_failed")
        return
    shell_runbook.mark_started(approved.request_id, now=int(time.time()))
    try:
        result = await shell_collector.wait_for(approved.device_id, "shell", 20.0, approved.request_id)
    except Exception:
        log.exception("Shell result collector failed for an approved request")
        result = None
    code = (result or {}).get("returncode")
    code = code if type(code) is int else None
    status = (result or {}).get("status")
    if result is None:
        status = "result_timeout"
    elif not isinstance(status, str) or status not in {"completed", "failed", "timeout", "error", "rejected", "cancelled"}:
        status = "completed" if code == 0 else "failed" if code is not None else "error"
    active_shell_requests.pop(approved.request_id, None)
    _audit_shell_result(approved, actor, status, code)
    runbook = shell_runbook.find_by_request(approved.request_id, now=int(time.time()))
    runbook_next_pending = None
    if runbook is not None:
        succeeded = status == "completed" and code == 0
        terminal_outcome = "failed" if status == "completed" and code != 0 else status
        updated = shell_runbook.complete_step(
            approved.request_id, success=succeeded, now=int(time.time()),
            exit_code=code, outcome=terminal_outcome,
        )
        if updated is not None and updated.state == "ready_next":
            if _shell_request_allowed(ADMIN_ID, updated.device_id) and SESSION.get("target") == updated.device_id:
                runbook_next_pending = _create_runbook_step(updated, now=int(time.time()))
            if runbook_next_pending is None:
                updated = shell_runbook.fail_plan(updated.plan_id, owner_id=ADMIN_ID, now=int(time.time())) or updated
            else:
                updated = shell_runbook.get_plan(updated.plan_id, owner_id=ADMIN_ID, now=int(time.time())) or updated
        runbook = updated
    if actor != ADMIN_ID:
        return
    if result is not None and ("stdout" in result or "stderr" in result):
        # Redact the entire capped stream before limiting the Telegram card.
        raw_output = str(result.get("stdout") or "")
        stderr = str(result.get("stderr") or "")
        if stderr:
            raw_output += "\n[STDERR]\n" + stderr
    else:
        raw_output = str((result or {}).get("output") or "")
    safe_output, redaction = access_store.redact_shell_output_with_summary(raw_output)
    suffix = f"\n[{status}; exit={code}]"
    for stream in ("stdout", "stderr"):
        if (result or {}).get(f"{stream}_truncated") is True:
            suffix += f"\n[{stream.upper()}: вывод ограничен 8192 байт]"
    if result is not None:
        category_labels = {
            "bearer_token": "Bearer-токены",
            "credential_field": "секретные поля",
            "private_key": "приватные ключи",
            "telegram_token": "Telegram-токены",
        }
        categories = redaction.get("categories", {})
        detected = [
            f"{label}: {categories[key]}"
            for key, label in category_labels.items()
            if type(categories.get(key)) is int and categories[key] > 0
        ]
        summary_text = (f"🔎 Redactor: замаскировано {redaction['total']} фрагм. · " + ", ".join(detected)
                        if redaction.get("total", 0) else
                        "🔎 Redactor: совпадений не обнаружено в полученном выводе.")
        suffix += "\n" + summary_text
    result_markup = back_to_device_kb()
    if result is not None:
        structured_output = shell_json_view.format_json_fields(safe_output)
        page = (shell_result_pager.create(owner_id=actor, device_label=target_label(approved.device_id),
                                          text=safe_output, structured_text=structured_output, footer=suffix,
                                          now=int(time.time())) if safe_output else None)
        if page is not None:
            if result is not None and status in {"completed", "failed"}:
                shell_repeat.create(owner_id=actor, device_id=approved.device_id,
                                    command=approved.command_text, outcome=status,
                                    now=int(time.time()), result_token=page.token)
            result_text = "[Очищенный вывод скрыт до предпросмотра; доступен 5 минут.]\n" + suffix.lstrip()
            result_markup = _shell_result_preview_keyboard(page)
        else:
            result_text = (("[Пустой вывод команды.]" if not safe_output else
                            "[Предпросмотр временно недоступен; вывод не показан.]") + suffix)
        output = html.escape(result_text)
        text = _lex("command_result", emoji="💻", label="Shell", device=html.escape(target_label(approved.device_id)), text=output)
    else:
        text = "Результат команды неизвестен: ответ за 20 секунд не получен. Команда могла выполниться; повторно она не отправлялась."
    if runbook is not None:
        text += "\n\n<pre>" + html.escape(shell_runbook.format_report(runbook)) + "</pre>"
        if runbook_next_pending is not None:
            text += "\n\n" + _runbook_step_preview(runbook_next_pending, runbook)
            result_markup = _runbook_result_step_keyboard(runbook_next_pending.request_id, page)
        elif runbook.state in {"failed", "expired", "cancelled"}:
            text += "\n\n<b>Runbook остановлен.</b> Следующие шаги не отправлялись."
        elif runbook.state == "completed":
            text += "\n\n<b>Runbook завершён.</b>"
    await _replace_callback_message(cq, text, reply_markup=result_markup)


def _shell_result_pager_keyboard(view):
    kb = InlineKeyboardBuilder()
    suffix = f":{view.view}" if view.view == "structured" else ""
    if view.page > 0:
        kb.button(text=_lex("versions_notes_previous"),
                  callback_data=f"cmd:shell-page:{view.token}:{view.page - 1}{suffix}")
    if view.page + 1 < view.total_pages:
        kb.button(text=_lex("versions_notes_next"),
                  callback_data=f"cmd:shell-page:{view.token}:{view.page + 1}{suffix}")
    if view.view == "structured":
        kb.button(text="🧾 Исходный текст", callback_data=f"cmd:shell-source:{view.token}")
    elif view.has_structured:
        kb.button(text="🧩 Поля JSON", callback_data=f"cmd:shell-json:{view.token}")
    kb.button(text="🆚 Выбрать для сравнения", callback_data=f"cmd:shell-compare-select:{view.token}")
    if shell_repeat.peek(view.token, owner_id=ADMIN_ID, now=int(time.time())) is not None:
        kb.button(text="🔁 Повторить как запрос", callback_data=f"cmd:shell-repeat:{view.token}")
    kb.button(text=_nav("back_device"), callback_data="back:device")
    kb.adjust(2)
    return _filter_device_keyboard(kb.as_markup(), ADMIN_ID)


