def _shell_repeat_approval_text(pending, *, previous_outcome: str) -> str:
    previous = ("Предыдущий исход: ошибка. Повтор может затронуть состояние, которое команда успела изменить частично."
                if previous_outcome == "failed" else "Предыдущий исход: команда завершилась.")
    return (
        "<b>Повтор · новый запрос</b>\n"
        f"Устройство: {html.escape(pending.device_id)}\n"
        f"Срок подтверждения: {pending.expires_at}\n"
        f"{previous}\n"
        "Команда не запускалась. Это новый одноразовый approval — для запуска нажми подтверждение отдельно."
        "\n"
        f"SHA-256: <code>{pending.command_hash}</code>\n"
        f"<pre>{html.escape(pending.command_text)}</pre>"
    )


@router.callback_query(OwnerFilter(), F.data.startswith("cmd:shell-repeat:"))
async def on_shell_result_repeat(cq: CallbackQuery):
    actor = cq.from_user.id if cq.from_user else None
    parts = str(cq.data or "").split(":")
    now = int(time.time())
    if actor != ADMIN_ID or len(parts) != 3:
        await cq.answer("Повтор доступен только владельцу.", show_alert=True)
        return
    candidate = shell_repeat.peek(parts[2], owner_id=actor, now=now)
    if (candidate is None or SESSION.get("target") != candidate.device_id
            or not _shell_request_allowed(actor, candidate.device_id)):
        await cq.answer("Повтор недоступен: результат истёк или права/устройство изменились.", show_alert=True)
        return
    candidate = shell_repeat.consume(parts[2], owner_id=actor, now=now)
    if candidate is None:
        await cq.answer("Запрос повтора уже обработан или истёк.", show_alert=True)
        return
    try:
        pending = command_approval.create_pending(
            actor, ADMIN_ID, candidate.device_id, candidate.command_text, now,
        )
    except (ValueError, command_approval.PendingStoreFull):
        await cq.answer("Не удалось создать новый approval; команда не запускалась.", show_alert=True)
        return
    text = _shell_repeat_approval_text(pending, previous_outcome=candidate.outcome)
    await _replace_callback_message(cq, text, reply_markup=_shell_repeat_approval_keyboard(pending))
    await cq.answer("Создан новый approval; выполнение не запускалось.")


@router.callback_query(OwnerFilter(), F.data.startswith("cmd:shell-compare-select:"))
async def on_shell_result_compare_select(cq: CallbackQuery):
    actor = cq.from_user.id if cq.from_user else None
    parts = str(cq.data or "").split(":")
    if actor != ADMIN_ID or len(parts) != 3:
        await cq.answer("Сравнение доступно только владельцу.", show_alert=True)
        return
    selected = shell_result_compare.select(parts[2], owner_id=actor, now=int(time.time()))
    if selected.state == "waiting_for_second":
        await cq.answer(selected.text, show_alert=True)
        return
    if selected.state == "same_result":
        await cq.answer(selected.text, show_alert=True)
        return
    if selected.state != "compared":
        await cq.answer("Результат истёк или недоступен; сравнение не выполнено.", show_alert=True)
        return
    text = _lex("command_result", emoji="🆚", label="Сравнение", device="Выбранные результаты",
                text="<pre>" + html.escape(selected.text) + "</pre>")
    await _replace_callback_message(cq, text, reply_markup=back_to_device_kb())
    await cq.answer()


