@router.callback_query(OwnerFilter(), F.data.startswith("cmd:shell-dryrun:"))
async def on_shell_dry_run(cq: CallbackQuery):
    actor = cq.from_user.id if cq.from_user else None
    request_id = str(cq.data or "").removeprefix("cmd:shell-dryrun:")
    pending = command_approval.get_pending(request_id)
    if (
        actor != ADMIN_ID or pending is None or pending.owner_id != ADMIN_ID
        or hashlib.sha256(pending.command_text.encode("utf-8")).hexdigest() != pending.command_hash
        or not _shell_request_allowed(pending.requester_id, pending.device_id)
    ):
        await cq.answer("Запрос недействителен или права изменились.", show_alert=True)
        return
    dry_run_command = shell_dry_run.build_dry_run_command(pending.command_text)
    if dry_run_command is None:
        await cq.answer("Для этой команды нет поддерживаемого безопасного dry-run.", show_alert=True)
        return
    replacement = command_approval.replace_pending_command(
        pending.request_id,
        owner_id=ADMIN_ID,
        original_command_hash=pending.command_hash,
        new_command=dry_run_command,
        now=int(time.time()),
    )
    if replacement is None:
        await cq.answer("Запрос истёк или уже обработан; ничего не запускалось.", show_alert=True)
        return
    kb = InlineKeyboardBuilder()
    kb.button(text=_lex("confirm_yes_button"), callback_data=f"cmd:shell-approve:{replacement.request_id}")
    kb.button(text=_lex("versions_install_cancel_button"), callback_data=f"cmd:shell-cancel:{replacement.request_id}")
    kb.adjust(2)
    text = (
        f"<b>Dry-run preview · D05-F21</b>\nУстройство: {html.escape(replacement.device_id)}\n"
        f"Запросил: {replacement.requester_id}\nДействует до: {replacement.expires_at}\n"
        "Это новая точная команда. При подготовке ничего не запускалось; выполнение требует отдельного подтверждения владельца.\n"
        f"SHA-256: <code>{replacement.command_hash}</code>\n<pre>{html.escape(replacement.command_text)}</pre>"
    )
    await cq.answer()
    await _replace_callback_message(cq, text, reply_markup=kb.as_markup())


