@router.callback_query(OwnerFilter(), F.data.startswith("cmd:shell-stop:"))
async def on_shell_stop(cq: CallbackQuery):
    actor = cq.from_user.id if cq.from_user else None
    request_id = str(cq.data or "").removeprefix("cmd:shell-stop:")
    active = active_shell_requests.get(request_id)
    if actor != ADMIN_ID or active is None or active.get("owner_id") != ADMIN_ID:
        await cq.answer("Нет активного owner-запроса для остановки.", show_alert=True)
        return
    try:
        access_store.append_command_audit(
            request_id=request_id, command_hash=active["command_hash"],
            status="cancel_requested", requester_id=active["requester_id"],
            approver_id=ADMIN_ID, device_id=active["device_id"], exit_code=None,
        )
    except (KeyError, OSError, ValueError):
        await cq.answer("Журнал выполнения недоступен. Stop-запрос не отправлен.", show_alert=True)
        return
    cancel_id = uuid.uuid4().hex
    try:
        sent = _publish_device_command(
            active["device_id"], "shell_cancel", id=cancel_id,
            target_request_id=request_id,
        )
    except Exception:
        sent = False
    await cq.answer()
    await _replace_callback_message(
        cq,
        "⏳ Запрос остановки отправлен. Жду подтверждение агента; отправка сама по себе не означает, что процесс остановлен.",
        reply_markup=back_to_device_kb(),
    )
    if sent is False:
        access_store.append_command_audit(
            request_id=request_id, command_hash=active["command_hash"],
            status="cancel_unknown", requester_id=active["requester_id"],
            approver_id=ADMIN_ID, device_id=active["device_id"], exit_code=None,
        )
        await _replace_callback_message(
            cq, "❔ Остановка неизвестна: запрос не удалось надёжно отправить.",
            reply_markup=back_to_device_kb(),
        )
        return
    result = await shell_cancel_collector.wait_for(
        active["device_id"], "shell_cancel", 8.0, cancel_id,
    )
    confirmed = (
        isinstance(result, dict)
        and result.get("type") == "shell_cancel"
        and result.get("id") == cancel_id
        and result.get("device_id") == active["device_id"]
        and result.get("target_request_id") == request_id
        and result.get("status") == "cancelled"
    )
    access_store.append_command_audit(
        request_id=request_id, command_hash=active["command_hash"],
        status="cancel_confirmed" if confirmed else "cancel_unknown",
        requester_id=active["requester_id"], approver_id=ADMIN_ID,
        device_id=active["device_id"], exit_code=None,
    )
    text = "✅ Агент подтвердил остановку процесса." if confirmed else "❔ Остановка неизвестна: агент не подтвердил завершение именно этого процесса."
    await _replace_callback_message(cq, text, reply_markup=back_to_device_kb())


@router.callback_query(OwnerFilter(), F.data == "cmd:shell_timing_report")
async def on_shell_timing_report(cq: CallbackQuery):
    actor = cq.from_user.id if cq.from_user else None
    report = access_store.shell_execution_timing_summary(actor, ADMIN_ID)
    if report.get("state") == "denied":
        await cq.answer("Только владелец может смотреть сводку.", show_alert=True)
        return
    if report.get("state") != "available":
        body = "⏱ Пока нет достаточных записей для сводки shell-выполнений."
    else:
        dispatch, result = report["dispatch"], report["result"]
        def _stage(label: str, row: dict) -> str:
            if not row["count"]:
                return f"{label}: недостаточно пар событий"
            return (f"{label}: {row['count']} · среднее {row['mean_seconds']:g} с · "
                    f"медиана {row['median_seconds']:g} с · максимум {row['max_seconds']:g} с")
        body = ("⏱ <b>Выполнение shell</b> · только метаданные журнала\n"
                f"Измерения округлены до {report['resolution_seconds']} с; строк сверено: {report['sampled_requests']}\n"
                f"{_stage('Подтверждено → отправлено', dispatch)}\n"
                f"{_stage('Отправлено → итог агента', result)}\n"
                "Ожидание подтверждения владельца не измеряется. Текст команд и их вывод не читаются.")
    await _replace_callback_message(cq, body, reply_markup=back_to_device_kb())
    await cq.answer()


@router.callback_query(OwnerFilter(), F.data == "cmd:shell_runner_diagnostic")
async def on_shell_runner_diagnostic(cq: CallbackQuery):
    actor = int(cq.from_user.id) if cq.from_user else 0
    target = _require_target(cq)
    if actor != ADMIN_ID or not target:
        await cq.answer("Диагностика доступна владельцу для одного выбранного устройства.", show_alert=True)
        return
    if not await _callback_result_access_or_report(cq, target):
        return
    await cq.answer("🔎 Проверяю только протокол и локальные метаданные runner-а…")
    sent, command_id = publish_tracked("capabilities", _target=target)
    if not sent:
        await _replace_callback_message(
            cq, _format_shell_runner_diagnostic({}, link_state="unavailable", authorization_state="unknown"),
            reply_markup=back_to_device_kb(),
        )
        return
    result = await capabilities_collector.wait_for(target, "capabilities", 15.0, command_id)
    if not await _callback_result_access_or_report(cq, target, published=True):
        return
    correlated = (
        isinstance(result, dict) and result.get("type") == "capabilities"
        and result.get("id") == command_id and result.get("device_id") == target
    )
    authorization_state = "allowed" if _shell_request_allowed(actor, target) else "denied"
    await _replace_callback_message(
        cq,
        _format_shell_runner_diagnostic(
            result.get("shell_runner") if correlated else {},
            link_state="fresh" if correlated else "unknown",
            authorization_state=authorization_state,
        ),
        delivery_guard=_callback_delivery_guard(cq, target),
        reply_markup=back_to_device_kb(),
    )


def _parse_shell_runner_diagnostic(value: object) -> dict:
    empty = {"protocol_state": "unknown", "executor_state": "unknown",
             "runner_state": "unknown", "permission_state": "unknown"}
    if type(value) is not dict or type(value.get("schema")) is not int or value.get("schema") != 1:
        return empty
    valid = {
        "protocol_state": {"ready", "unavailable", "unknown"},
        "executor_state": {"available", "unavailable", "unknown"},
        "runner_state": {"available", "unavailable", "unknown"},
        "permission_state": {"available", "unavailable", "unknown"},
    }
    parsed = {}
    for key, states in valid.items():
        state = value.get(key)
        if not isinstance(state, str) or state not in states:
            return empty
        parsed[key] = state
    return parsed


def _format_shell_runner_diagnostic(value: object, *, link_state: str, authorization_state: str) -> str:
    parsed = _parse_shell_runner_diagnostic(value)
    protocol = {"ready": "готов", "unavailable": "недоступен", "unknown": "неизвестно"}[parsed["protocol_state"]]
    executor = {"available": "доступно", "unavailable": "недоступно", "unknown": "неизвестно"}[parsed["executor_state"]]
    runner = {"available": "найден", "unavailable": "не найден", "unknown": "неизвестно"}[parsed["runner_state"]]
    permission = {"available": "доступны", "unavailable": "недоступны", "unknown": "неизвестно"}[parsed["permission_state"]]
    link = {"fresh": "свежий ответ получен", "unavailable": "не удалось отправить запрос", "unknown": "неизвестно: нет свежего корректного ответа"}.get(link_state, "неизвестно: нет свежего корректного ответа")
    authorization = {"allowed": "разрешены", "denied": "нет", "unknown": "неизвестно"}.get(authorization_state, "неизвестно")
    return (
        "🧪 <b>Диагностика shell runner</b> · без запуска команды\n"
        f"Связь: {link}\nПротокол подтверждений: {protocol}\n"
        f"Модуль исполнения: {executor}\nRunner ОС: {runner}\n"
        f"Права процесса на runner: {permission}\nПрава владельца на shell-действие: {authorization}\n"
        "Проверка прав ОС — файловая, не тест запуска; UAC, AppLocker, TCC и MDM могут дополнительно ограничивать работу."
    )


@router.callback_query(OwnerFilter(), F.data == "cmd:shell_approval_inbox")
async def on_shell_approval_inbox(cq: CallbackQuery):
    actor = cq.from_user.id if cq.from_user else None
