@router.callback_query(OwnerFilter(), F.data == "cmd:shell_late_results")
async def on_shell_late_results(cq: CallbackQuery):
    actor = cq.from_user.id if cq.from_user else None
    target = str(SESSION.get("target") or "")
    now = int(time.time())
    if actor != ADMIN_ID or not target or target == "all":
        await cq.answer("Выбери одно устройство; очередь доступна только владельцу.", show_alert=True)
        return
    rows = access_store.filter_audit(actor, ADMIN_ID, event_type="command_execution",
                                     device_id=target, since=max(0, now - 30), limit=500) or []
    latest: dict[str, dict] = {}
    for row in rows:
        request_id = row.get("request_id")
        if isinstance(request_id, str) and request_id not in latest:
            latest[request_id] = row
    candidates = []
    for request_id, row in latest.items():
        if row.get("status") != "result_timeout":
            continue
        reply = shell_collector.recent_for(target, "shell", request_id)
        if reply is None:
            continue
        reply_id = str(reply.get("request_id") or reply.get("id") or "")
        if (reply.get("type") != "shell" or reply.get("device_id") != target
                or reply_id != request_id):
            continue
        candidates.append({"device_id": target, "request_id": request_id,
                           "timed_out_at": row.get("at"), "status": "result_timeout"})
    entries = shell_late_result_inbox_store.refresh(actor, ADMIN_ID, candidates,
                                                    now=now, device_id=target)
    kb = InlineKeyboardBuilder()
    for entry in entries:
        kb.button(text=f"{target_label(target)} · поздний ответ · {entry['request_id'][:12]}",
                  callback_data=f"cmd:shell-late:view:{entry['token']}")
    kb.button(text=_nav("back_device"), callback_data="back:device")
    kb.adjust(1)
    body = ("📥 <b>Поздние результаты shell</b>\nОткрой точный ответ, полученный после таймаута. Команда повторно не запускается."
            if entries else
            "📥 <b>Поздних результатов нет</b>\nПроверяются только ответы последних 30 секунд для выбранного устройства.")
    await _replace_callback_message(cq, body, reply_markup=kb.as_markup())
    await cq.answer()


@router.callback_query(OwnerFilter(), F.data.startswith("cmd:shell-late:view:"))
async def on_shell_late_result_view(cq: CallbackQuery):
    actor = cq.from_user.id if cq.from_user else None
    token = str(cq.data or "").removeprefix("cmd:shell-late:view:")
    now = int(time.time())
    ref = shell_late_result_inbox_store.consume(actor, ADMIN_ID, token, now=now)
    target = str(SESSION.get("target") or "")
    if actor != ADMIN_ID or ref is None or ref["device_id"] != target:
        await cq.answer("Поздний ответ истёк, уже открыт или устройство сменилось.", show_alert=True)
        return
    result = shell_collector.take_recent(target, "shell", ref["request_id"])
    if (result is None or result.get("device_id") != target
            or str(result.get("request_id") or result.get("id") or "") != ref["request_id"]):
        await cq.answer("Точный ответ больше недоступен; повторного запуска не будет.", show_alert=True)
        return
    raw = str(result.get("stdout") or result.get("output") or "")
    stderr = str(result.get("stderr") or "")
    if stderr:
        raw += "\n[STDERR]\n" + stderr
    safe, summary = access_store.redact_shell_output_with_summary(raw)
    code = result.get("returncode")
    status = str(result.get("status") or "unknown")
    footer = f"[{status}; exit={code if type(code) is int else 'unknown'}]"
    if summary.get("total"):
        footer += f"\n🔎 Redactor: замаскировано {summary['total']} фрагм."
    text = _lex("command_result", emoji="💻", label="Shell · поздний ответ",
                device=html.escape(target_label(target)),
                text=html.escape((safe[:3500] if safe else "[Пустой вывод команды.]") + "\n" + footer))
    await _replace_callback_message(cq, text, reply_markup=back_to_device_kb())
    await cq.answer("Показан исходный поздний ответ; команда не запускалась повторно.")


