XIDER_VERSION = VERSION
XIDER_BUILD   = BUILD_DATE
XIDER_BUILD_CODE = BUILD_CODE
XIDER_AUTHOR  = bot_settings.developer_contact()
# =====================================



def get_server_autostart_status() -> bool:
    if sys.platform != "win32":
        return False
    try:
        import winreg
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\Microsoft\Windows\CurrentVersion\Run", 0, winreg.KEY_READ) as key:
            winreg.QueryValueEx(key, "XIDER_BOT")
            return True
    except Exception:
        return False


def toggle_server_autostart() -> tuple[bool, str]:
    if sys.platform != "win32":
        return False, "Автозапуск поддерживается только на Windows."
    try:
        import winreg
        key_path = r"Software\Microsoft\Windows\CurrentVersion\Run"
        currently_enabled = get_server_autostart_status()
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, key_path, 0, winreg.KEY_ALL_ACCESS) as key:
            if not currently_enabled:
                cur_dir = Path(__file__).resolve().parent
                bat = cur_dir / "start_bot.bat"
                cmd = f'"{bat}"'
                winreg.SetValueEx(key, "XIDER_BOT", 0, winreg.REG_SZ, cmd)
                return True, "✅ Автозапуск сервера XIDER включен в реестре Windows!"
            else:
                try:
                    winreg.DeleteValue(key, "XIDER_BOT")
                except FileNotFoundError:
                    pass
                return False, "🛑 Автозапуск сервера XIDER отключен в реестре Windows."
    except Exception as exc:
        return False, f"⚠️ Ошибка реестра: {exc}"


def _technical_ui() -> bool:
    return xlex.normalize_style(bot_settings.get("ui_style", "technical")) == "xtech"


def _custom_ui() -> bool:
    return xlex.normalize_style(bot_settings.get("ui_style", "technical")) == "xperson"


def _ui_phrase(technical: str, conversational: str, custom: str) -> str:
    style = xlex.normalize_style(bot_settings.get("ui_style", "technical"))
    if style == "xperson":
        return custom
    return technical if style == "xtech" else conversational


def _lex(key: str, **values: str) -> str:
    return xlex.render(key, bot_settings.get("ui_style", "technical"), **values)


def _lex_html(key: str, **values: str) -> str:
    safe_values = {name: html.escape(str(value)) for name, value in values.items()}
    return _lex(key, **safe_values)


def _nav(key: str) -> str:
    return xlex.nav(key, bot_settings.get("ui_style", "technical"))


def main_menu(user_id: int | None = None):
    user_id = int(user_id if user_id is not None else CURRENT_TG_USER.get())
    role = get_user_role(user_id)
    kb = InlineKeyboardBuilder()
    if role == Role.BLOCKED:
        return kb.as_markup()
    role_id = str(role.value if hasattr(role, "value") else role)
    pages = feature_catalog.visible_navigation_pages(
        feature_catalog.load_registry(), parent="home", role=role_id,
        grants=set(access_store.get_effective_grants(user_id)["callbacks"]), platform="telegram",
    )
    for page in pages:
        presentation = page["presentation"]
        if presentation == "home_devices":
            callback = "menu:guest_devices" if role == Role.GUEST else str(page["callback"])
            text = _lex(
                "devices_button" if role == Role.OWNER else
                "my_devices_button" if role == Role.USER else "guest_devices_button"
            )
        elif presentation == "home_server":
            text = _lex("server_button" if role == Role.OWNER else "server_overview_button")
            callback = str(page["callback"])
        elif presentation == "home_admin":
            text = _nav("admin")
            callback = str(page["callback"])
        elif presentation == "home_catalog":
            text = feature_catalog.button_text("areas")
            callback = str(page["callback"])
        elif presentation == "home_access_request":
            text = _ui_phrase("🔐 Запросить доступ", "🔐 Попросить доступ", "🔐 Выдать мне пропуск")
            callback = str(page["callback"])
        else:
            text = _lex("about_button")
            callback = str(page["callback"])
        kb.button(text=text, callback_data=callback, style=str(page["style"]))
    kb.adjust(2)
    return kb.as_markup()


def _catalog_navigation_state(user_id: int):
    getter = getattr(devices, "get_navigation_state", None)
    return getter(user_id) if callable(getter) else None


def _catalog_selected_device(user_id: int) -> str | None:
    state = _catalog_navigation_state(user_id)
    if state and state.get("stale_device"):
        return None
    selected = state.get("selected_device_id") if state else SESSION.get("target")
    return selected if selected in _visible_device_items(user_id) else None


def _catalog_selected_platform(user_id: int) -> str | None:
    """Return the selected device's declared platform; unknown OS stays unknown."""
    selected = _catalog_selected_device(user_id)
    if selected is None:
        return None
    device = _visible_device_items(user_id).get(selected) or {}
    os_name = str(device.get("os") or "").strip().lower()
    if os_name.startswith(("mac", "darwin")):
        return "macos"
    if os_name.startswith("win"):
        return "windows"
    if os_name.startswith("linux"):
        return "linux"
    return "unknown"


def _catalog_current_permission_states(user_id: int) -> dict[str, str]:
    """Return only fresh, parsed OS permission states for the selected device."""
    selected = _catalog_selected_device(user_id)
    if selected is None:
        return {}
    info = _visible_device_items(user_id).get(selected) or {}
    capabilities = info.get("capabilities")
    raw_snapshot = capabilities.get("snapshot") if isinstance(capabilities, dict) else None
    snapshot = _parse_capability_snapshot(raw_snapshot)
    checked_at = snapshot.get("checked_at")
    if snapshot.get("schema") != 1 or not isinstance(checked_at, str):
        return {}
    expected_snapshot_platform = {
        "macos": "macOS",
        "windows": "Windows",
    }.get(_catalog_selected_platform(user_id))
    if (expected_snapshot_platform is None
            or not str(snapshot.get("platform") or "").startswith(expected_snapshot_platform)):
        return {}
    try:
        stamp = datetime.datetime.fromisoformat(checked_at)
        age = time.time() - stamp.timestamp()
    except (ValueError, TypeError, OverflowError):
        return {}
    if not 0 <= age <= 150:
        return {}
    return {
        row["id"]: row["state"]
        for row in snapshot.get("items", [])
        if isinstance(row, dict)
        and isinstance(row.get("id"), str)
        and isinstance(row.get("state"), str)
    }


def _save_catalog_navigation(
    user_id: int, page_key: str, cursor: int, stack: list[dict],
) -> None:
    saver = getattr(devices, "save_navigation_state", None)
    if not callable(saver):
        return
    selected = _catalog_selected_device(user_id)
    saver(user_id, selected, page_key, cursor, stack)


