def feature_catalog_result_type_page(user_id: int, result_type: str):
    registry = feature_catalog.load_registry()
    role = get_user_role(user_id)
    role_id = str(role.value if hasattr(role, "value") else role)
    grants = set(access_store.get_effective_grants(user_id)["callbacks"])
    type_labels = {
        "text": "текст",
        "image": "изображение",
        "file": "файл",
        "status": "статус",
    }
    if result_type not in type_labels:
        raise ValueError("unknown result type")
    results = []
    for candidate in feature_catalog.filter_features_by_result_type(registry, result_type):
        visible = feature_catalog.find_visible_feature(
            registry, str(candidate.get("feature_id") or ""),
            role=role_id, grants=grants,
        )
        if visible is not None:
            results.append(visible)
    shown = results
    if shown:
        lines = [
            f"<code>{html.escape(str(item['feature_id']))}</code> · "
            f"<b>{html.escape(str(item.get('title') or ''))}</b> · "
            f"<code>{html.escape(str(item.get('support_state') or 'unknown'))}</code>"
            for item in shown
        ]
