def feature_catalog_area_page(user_id: int, area_id: str, page_cursor: int):
    registry = feature_catalog.load_registry()
    role = get_user_role(user_id)
    selected = _catalog_selected_device(user_id)
    visible_devices = _visible_device_items(user_id)
    callbacks = set(access_store.get_effective_grants(user_id)["callbacks"])
    page = feature_catalog.build_feature_page(
        registry,
        user_id,
        selected,
        page_cursor,
        role=role,
        device_ids=set(visible_devices),
        grants=callbacks,
        registered_handlers=set(),
        page_size=8,
        area=area_id,
        platform=_catalog_selected_platform(user_id),
    )
    kb = InlineKeyboardBuilder()
    for item in page["items"]:
        feature_id = str(item.get("feature_id") or "")
        title = str(item.get("title") or feature_id)
        kb.button(
            # The message body already pairs IDs, titles and support states.
            # Keep the tap target focused on readable human text.
            text=_limit_button_label(title),
            callback_data=f"catalog:feature:{feature_id}",
            style="primary",
        )
    role_id = str(role.value if hasattr(role, "value") else role)
    controls = feature_catalog.visible_navigation_pages(
        registry, parent="catalog.area.page", role=role_id,
        grants=callbacks, platform="telegram",
    )
    control_labels = {
        "catalog.page.previous": "previous",
        "catalog.page.next": "next",
        "catalog.page.sections": "sections",
    }
    for control in controls:
        page_id = control["page_id"]
        if page_id == "catalog.page.previous":
            if not page["has_previous"]:
                continue
            cursor = page["page_cursor"] - 1
            text = feature_catalog.button_text(control_labels[page_id])
            callback = str(control["callback"]).replace("*", f"{area_id}:{cursor}")
        elif page_id == "catalog.page.next":
            if not page["has_next"]:
                continue
            cursor = page["page_cursor"] + 1
            text = feature_catalog.button_text(control_labels[page_id])
            callback = str(control["callback"]).replace("*", f"{area_id}:{cursor}")
        elif page_id == "catalog.page.sections":
            text = feature_catalog.button_text(control_labels[page_id])
            callback = str(control["callback"])
        elif page_id == "catalog.page.home":
            text = _nav("home")
            callback = str(control["callback"])
        else:
            raise ValueError("unregistered catalog page-control renderer")
        kb.button(text=text, callback_data=callback, style=str(control["style"]))
    kb.adjust(1)
    if page["state"] == "stale_device":
        body = "Выбранное устройство больше недоступно. Выбери его заново перед действиями."
    elif page["items"]:
        body = "\n".join(
            f"<code>{html.escape(str(item['feature_id']))}</code> "
            f"{html.escape(str(item.get('title') or ''))} · "
            f"<i>{html.escape(str(item.get('support_state') or 'unknown'))}</i>"
            for item in page["items"]
        )
        body += f"\n\nСтраница {page['page_cursor'] + 1}/{page['page_count']}."
        platform = _catalog_selected_platform(user_id)
        if platform is not None:
            body += f"\nФильтр платформы: <code>{html.escape(platform)}</code>."
    else:
        platform = _catalog_selected_platform(user_id)
        if platform == "unknown":
            body = "Неизвестная ОС выбранного устройства — платформенную совместимость подтвердить нельзя."
        else:
            body = "В этом разделе пока нет пунктов, доступных выбранной роли и платформе."
    return f"<b>Каталог · {html.escape(area_id)}</b>\n\n{body}", kb.as_markup()


def feature_catalog_detail(user_id: int, feature_id: str):
    registry = feature_catalog.load_registry()
    role = get_user_role(user_id)
    role_id = str(role.value if hasattr(role, "value") else role)
    grants = set(access_store.get_effective_grants(user_id)["callbacks"])
    item = feature_catalog.find_visible_feature(
        registry, feature_id, role=role_id, grants=grants,
    )
    if item is None:
        return None
    role_values = item.get("role")
    roles = ", ".join(str(value) for value in role_values if isinstance(value, str)) if isinstance(role_values, list) else "unknown"
    grant = item.get("grant") if isinstance(item.get("grant"), dict) else {}
    grant_kind = str(grant.get("kind") or "unknown")
    permission_values = item.get("permissions")
    permissions = ", ".join(str(value) for value in permission_values if isinstance(value, str)) if isinstance(permission_values, list) and permission_values else "none"
    component_versions = item.get("component_min_versions")
    component_status = []
    if isinstance(component_versions, dict):
        for component, metadata in sorted(component_versions.items()):
            if not isinstance(component, str) or not isinstance(metadata, dict):
                continue
            state = str(metadata.get("state") or "unknown")
            if state != "not_applicable":
                component_status.append(f"{component}: {state}")
    checks = item.get("acceptance_level")
    acceptance = ", ".join(str(value) for value in checks if isinstance(value, str)) if isinstance(checks, list) and checks else "unknown"
    baseline = item.get("baseline_evidence")
    novelty_states = sorted({
        str(entry.get("novelty_status"))
        for entry in baseline
        if isinstance(entry, dict) and isinstance(entry.get("novelty_status"), str)
    }) if isinstance(baseline, list) else []
    novelty = ", ".join(novelty_states) or "unknown"
    test_refs = item.get("test_refs")
    test_ref_count = sum(1 for value in test_refs if isinstance(value, str) and value.strip()) if isinstance(test_refs, list) else 0
    state = str(item.get("support_state") or "unknown")
    executable = state == "implemented" and bool(item.get("can_execute"))
    launch_line = (
        "Доступно к запуску зарегистрированным обработчиком."
        if executable else "Пока не команда для запуска: это запись каталога, не вызов handler."
    )
    detail = (
        f"<b>{html.escape(str(item.get('feature_id')))} · {html.escape(str(item.get('title') or ''))}</b>\n\n"
        f"{html.escape(str(item.get('description') or item.get('outcome') or ''))}\n\n"
        f"Статус: <code>{html.escape(state)}</code>\n"
        f"Платформы: <code>{html.escape(', '.join(item.get('platforms') or []))}</code>\n"
        f"Роли: {html.escape(roles)}\n"
        f"Подтверждение: <code>{html.escape(grant_kind)}</code>\n"
        f"Разрешения: <code>{html.escape(permissions)}</code>\n"
        f"Компоненты: <code>{html.escape('; '.join(component_status) or 'unknown')}</code>\n"
        f"Новизна: <code>{html.escape(novelty)}</code>\n"
        f"Проверки: <code>{html.escape(acceptance)}</code>\n"
        f"Ссылки на тесты: <code>{test_ref_count}</code>\n"
        f"{launch_line}"
    )
    selected_device = _catalog_selected_device(user_id)
    if role_id == "owner" and selected_device is not None:
        blockers = feature_catalog.explain_availability(
            item, role=role_id, grants=grants,
            platform=_catalog_selected_platform(user_id),
            permission_states=_catalog_current_permission_states(user_id),
        )
        reason_labels = []
        for blocker in blockers:
            kind = blocker.get("kind")
            if kind == "role":
                reason_labels.append("роль не разрешена политикой этой функции")
            elif kind == "grant":
                reason_labels.append("не выдан требуемый grant")
            elif kind == "os":
                reason_labels.append("ОС не поддерживается выбранным устройством")
            elif kind == "permission":
                reason_labels.append(f"{blocker.get('id', 'OS permission')}: {blocker.get('state', 'unknown')}")
            elif kind == "readiness":
                reason_labels.append(f"реализация не готова: {blocker.get('state', 'unknown')}")
        diagnosis = "\n".join(f"• {html.escape(label)}" for label in reason_labels)
        if not diagnosis:
            diagnosis = "По доступным свежим данным явных блокеров нет."
        detail += f"\n\n<b>Диагностика для выбранного устройства</b>\n{diagnosis}"
    return detail


def feature_catalog_detail_keyboard(user_id: int, feature_id: str):
    registry = feature_catalog.load_registry()
    role = get_user_role(user_id)
    role_id = str(role.value if hasattr(role, "value") else role)
    grants = set(access_store.get_effective_grants(user_id)["callbacks"])
    pages = feature_catalog.visible_navigation_pages(
        registry, parent="catalog.feature.detail", role=role_id,
        grants=grants, platform="telegram",
    )
    kb = InlineKeyboardBuilder()
    for page in pages:
        page_id = page["page_id"]
        if page_id == "catalog.feature.back":
            text = feature_catalog.button_text("detail_back")
        elif page_id == "catalog.feature.home":
            text = _nav("home")
        elif page_id == "catalog.feature.synonym.add":
            if not re.fullmatch(r"[A-Z][A-Z0-9]{1,3}-F\d{2}", feature_id):
                raise ValueError("invalid feature ID for synonym action")
            callback = str(page["callback"]).replace("*", feature_id)
            if callback != f"catalog:synonym:add:{feature_id}":
                raise ValueError("unregistered catalog synonym callback")
            kb.button(
                text=feature_catalog.button_text("synonym_add"),
                callback_data=callback, style=str(page["style"]),
            )
            continue
        else:
            raise ValueError("unregistered catalog detail control renderer")
        kb.button(text=text, callback_data=str(page["callback"]), style=str(page["style"]))
    kb.adjust(2)
    return kb.as_markup()


def feature_catalog_synonym_keyboard(user_id: int):
    registry = feature_catalog.load_registry()
    role = get_user_role(user_id)
    role_id = str(role.value if hasattr(role, "value") else role)
    grants = set(access_store.get_effective_grants(user_id)["callbacks"])
    pages = feature_catalog.visible_navigation_pages(
        registry, parent="catalog.feature.synonym.prompt", role=role_id,
        grants=grants, platform="telegram",
    )
    kb = InlineKeyboardBuilder()
    for page in pages:
        if page["page_id"] != "catalog.feature.synonym.cancel" or page["callback"] != "catalog:synonym:cancel":
            raise ValueError("unregistered catalog synonym prompt control")
        kb.button(
            text=feature_catalog.button_text("synonym_cancel"),
            callback_data=str(page["callback"]), style=str(page["style"]),
        )
    kb.adjust(1)
    return kb.as_markup()


def _feature_catalog_synonym_prompt(feature_id: str, *, notice: str | None = None) -> str:
    aliases = devices.get_feature_search_synonyms(owner_id=ADMIN_ID).get(feature_id, [])
    listing = "\n".join(f"• {html.escape(alias)}" for alias in aliases) if aliases else "Пока пусто."
    prefix = f"{html.escape(notice)}\n\n" if notice else ""
    return (
        f"{prefix}<b>Слова для карточки {html.escape(feature_id)}</b>\n\n"
        "Отправь одну фразу для добавления. Для удаления начни сообщение с <code>- </code> и укажи фразу.\n"
        "До 16 фраз на карточку, каждая — до 64 символов. Это только слова поиска; права и обработчики не меняются.\n\n"
        f"Текущий список:\n{listing}"
    )


def feature_catalog_search_keyboard(user_id: int, *, parent: str, features=()):
    if parent not in {"catalog.search.prompt", "catalog.search.results", "catalog.filter.results"}:
        raise ValueError("unsupported catalog search page")
    registry = feature_catalog.load_registry()
    role = get_user_role(user_id)
    role_id = str(role.value if hasattr(role, "value") else role)
    grants = set(access_store.get_effective_grants(user_id)["callbacks"])
    pages = feature_catalog.visible_navigation_pages(
        registry, parent=parent, role=role_id, grants=grants, platform="telegram",
    )
    labels = {
        "catalog.search.prompt.sections": "sections",
        "catalog.search.prompt.home": "home",
        "catalog.search.results.sections": "sections",
        "catalog.search.results.home": "home",
        "catalog.filter.results.sections": "sections",
        "catalog.filter.results.home": "home",
    }
    kb = InlineKeyboardBuilder()
    result_routes = [page for page in pages if page["presentation"] == "catalog_feature"]
    result_count = 0
    if result_routes:
        if len(result_routes) != 1 or parent not in {"catalog.search.results", "catalog.filter.results"}:
            raise ValueError("unregistered catalog feature-result route")
        template = str(result_routes[0]["callback"])
        if template.count("*") != 1 or not template.endswith("*"):
            raise ValueError("invalid catalog feature-result callback template")
        for feature in features:
            feature_id = str(feature.get("feature_id") or "")
            if not re.fullmatch(r"[A-Z][A-Z0-9]{1,3}-F\d{2}", feature_id):
                continue
            visible = feature_catalog.find_visible_feature(
                registry, feature_id, role=role_id, grants=grants,
            )
            if visible is None:
                continue
            title = str(visible.get("title") or feature_id)
            kb.button(
                text=_limit_button_label(title),
                callback_data=template.replace("*", feature_id),
                style=str(result_routes[0]["style"]),
            )
            result_count += 1
    for page in pages:
        if page["presentation"] == "catalog_feature":
            continue
        label = labels.get(page["page_id"])
        if label == "sections":
            text = feature_catalog.button_text("sections")
        elif label == "home":
            text = _nav("home")
        else:
            raise ValueError("unregistered catalog search control renderer")
        kb.button(text=text, callback_data=str(page["callback"]), style=str(page["style"]))
    kb.adjust(*([1] * result_count), 2)
    return kb.as_markup()


def _visible_device_items(user_id: int | None = None) -> dict[str, dict]:
    user_id = int(user_id if user_id is not None else CURRENT_TG_USER.get())
    all_devices = devices.all()
    archive_reader = getattr(devices, "list_archived_devices", None)
    archived_ids = set()
    if int(ADMIN_ID) > 0 and callable(archive_reader):
        try:
            archived_ids = {
                device_id for device_id, _info in archive_reader(
                    actor_id=ADMIN_ID, owner_id=ADMIN_ID, limit=500,
                )
            }
        except (TypeError, ValueError):
            archived_ids = set()
    return {
        device_id: info
        for device_id, info in all_devices.items()
        if device_id not in archived_ids and access_store.can_use_callback(
            user_id, f"dev:{device_id}", ADMIN_ID, device_id
        )
    }


_DEVICE_CATALOG_PAGE_SIZE = 10
_DEVICE_RESULT_PAGE_SIZE = 20
_DEVICE_VIEW_TTL_SECONDS = 15 * 60
_DEVICE_VIEW_CACHE_LIMIT = 256
_DEVICE_RESULT_VIEWS: dict[str, dict] = {}
_DEVICE_SELECT_REFS: dict[str, dict] = {}


def _prune_device_view_cache(now: float | None = None) -> None:
    now = time.time() if now is None else float(now)
    for cache in (_DEVICE_RESULT_VIEWS, _DEVICE_SELECT_REFS):
        for token, value in list(cache.items()):
            if float(value.get("expires_at", 0)) <= now:
                cache.pop(token, None)
        while len(cache) > _DEVICE_VIEW_CACHE_LIMIT:
            cache.pop(next(iter(cache)))


def _device_select_callback(user_id: int, device_id: str) -> str:
    direct = f"dev:{device_id}"
    if len(direct.encode("utf-8")) <= 64:
        return direct
    _prune_device_view_cache()
    token = uuid.uuid4().hex[:12]
    _DEVICE_SELECT_REFS[token] = {
        "user_id": int(user_id), "device_id": str(device_id),
        "expires_at": time.time() + _DEVICE_VIEW_TTL_SECONDS,
    }
    _prune_device_view_cache()
    return f"devref:{token}"


def _ordered_device_items(user_id: int, visible: dict[str, dict]) -> list[tuple[str, dict]]:
    sort_by = devices.get_device_catalog_sort(user_id, ADMIN_ID) if hasattr(devices, "get_device_catalog_sort") else "name"
    if sort_by == "custom" and hasattr(devices, "get_device_catalog_order"):
        ordered_ids = _catalog_order_ids(user_id, visible)
        return [(device_id, visible[device_id]) for device_id in ordered_ids if device_id in visible]
    return sort_device_inventory(visible, sort_by)


def _device_result_page_markup(
    user_id: int, token: str, page: int, ids: list[str], *, back_callback: str = "menu:devices",
) -> InlineKeyboardMarkup:
    page_count = max(1, math.ceil(len(ids) / _DEVICE_RESULT_PAGE_SIZE))
    page = min(max(0, int(page)), page_count - 1)
    kb = InlineKeyboardBuilder()
    visible = _visible_device_items(user_id)
    for device_id in ids[page * _DEVICE_RESULT_PAGE_SIZE:(page + 1) * _DEVICE_RESULT_PAGE_SIZE]:
        info = visible.get(device_id, {})
        name = str(info.get("name") or device_id)
        kb.button(
            text=_limit_button_label(f"💻 {name}"),
            callback_data=_device_select_callback(user_id, device_id), style="primary",
        )
    if page > 0:
        kb.button(text=_ui_phrase("←", "←", "←"), callback_data=f"devices:results:{token}:{page - 1}", style="primary")
    if page + 1 < page_count:
        kb.button(text=_ui_phrase("→", "→", "→"), callback_data=f"devices:results:{token}:{page + 1}", style="primary")
    kb.button(text=_ui_phrase("← Devices", "← Устройства", "← Устройства"), callback_data=back_callback, style="primary")
    kb.button(text=_nav("home"), callback_data="menu:main", style="primary")
    kb.adjust(*([1] * min(_DEVICE_RESULT_PAGE_SIZE, max(0, len(ids) - page * _DEVICE_RESULT_PAGE_SIZE))), 4)
    # The device IDs came from _visible_device_items, and on_dev repeats that
    # visibility check when a selection is clicked. The result-view callback
    # itself is actor-bound and rechecks the originating permission on every page.
    return kb.as_markup()


def _save_device_result_view(
    user_id: int, matches: dict[str, dict], *, title: str, note: str,
    required_callback: str | None, back_callback: str = "menu:devices",
) -> tuple[str, list[str]]:
    _prune_device_view_cache()
    token = uuid.uuid4().hex[:12]
    ids = list(matches)
    _DEVICE_RESULT_VIEWS[token] = {
        "user_id": int(user_id), "ids": ids, "title": str(title), "note": str(note),
        "required_callback": required_callback, "back_callback": str(back_callback),
        "expires_at": time.time() + _DEVICE_VIEW_TTL_SECONDS,
    }
    _prune_device_view_cache()
    return token, ids


async def _render_device_result_card(
    message: Message, matches: dict[str, dict], *, title: str, note: str,
    required_callback: str | None, back_callback: str = "menu:devices",
) -> None:
    user_id = int(message.from_user.id)
    token, ids = _save_device_result_view(
        user_id, matches, title=title, note=note,
        required_callback=required_callback, back_callback=back_callback,
    )
    count = len(ids)
    pages = max(1, math.ceil(count / _DEVICE_RESULT_PAGE_SIZE))
    body = f"<b>{html.escape(title)}</b> · {count} совпадений"
    if pages > 1:
        body += f" · 1/{pages}"
    if note:
        body += "\n" + html.escape(note)
    if not count:
        body += "\nСовпадений нет."
    await _replace_user_card(
        message, body,
        reply_markup=_device_result_page_markup(user_id, token, 0, ids, back_callback=back_callback),
    )


def _device_result_view_allowed(user_id: int, view: dict) -> bool:
    required = view.get("required_callback")
    role = get_user_role(user_id)
    if required == "owner":
        return role == Role.OWNER
    if required:
        return role == Role.OWNER or (
            role == Role.USER and access_store.can_use_callback(user_id, str(required), ADMIN_ID, None)
        )
    return role in {Role.OWNER, Role.USER}


def _device_result_page_body(view: dict, ids: list[str], page: int) -> str:
    count = len(ids)
    page_count = max(1, math.ceil(count / _DEVICE_RESULT_PAGE_SIZE))
    body = f"<b>{html.escape(str(view.get('title') or 'Устройства'))}</b> · {count} · {page + 1}/{page_count}"
    note = str(view.get("note") or "")
    if note:
        body += "\n" + html.escape(note)
    return body


def search_visible_devices(query: str, visible_devices: dict[str, dict]) -> dict[str, dict]:
    """Search only a caller-supplied, already authorization-filtered device set."""
    normalized = " ".join(str(query or "").split()).casefold()
    if not normalized:
        return {}
    return {
        device_id: info
        for device_id, info in visible_devices.items()
        if any(
            normalized in str(value or "").casefold()
            for value in (device_id, info.get("name"), info.get("hostname"))
        )
    }


def filter_visible_devices_by_platform_version(
    platform: str, version: str | None, visible_devices: dict[str, dict],
) -> dict[str, dict]:
    """Filter only a caller-supplied, already authorization-filtered inventory."""
    normalized_platform = " ".join(str(platform or "").split()).casefold()
    if normalized_platform in {"windows", "win"}:
        markers = ("windows",)
    elif normalized_platform in {"macos", "mac", "darwin"}:
        markers = ("macos", "mac os", "darwin")
    else:
        return {}
    normalized_version = " ".join(str(version or "").split()).casefold()
    if len(normalized_version) > 48:
        return {}

    matches = {}
    for device_id, info in visible_devices.items():
        reported_os = " ".join(str(value or "") for value in (
            info.get("os"), info.get("os_version"),
        )).casefold()
        platform_matches = any(marker in reported_os for marker in markers)
        version_matches = not normalized_version or normalized_version in reported_os
        if platform_matches and version_matches:
            matches[device_id] = info
    return matches


def _parse_heartbeat_age_filter(query: str) -> tuple[str, int] | None:
    match = re.fullmatch(r"\s*(<=|>=)\s*(\d{1,8})\s*([smhd])\s*", str(query or ""), re.IGNORECASE)
    if not match:
        return None
    operator, amount_text, unit = match.groups()
    amount = int(amount_text)
    seconds_per_unit = {"s": 1, "m": 60, "h": 3600, "d": 86400}[unit.casefold()]
    threshold = amount * seconds_per_unit
    if threshold <= 0 or threshold > 365 * 86400:
        return None
    return operator, threshold


def filter_visible_devices_by_heartbeat_age(
    query: str, visible_devices: dict[str, dict], *, now: float | None = None,
) -> dict[str, dict]:
    """Filter visible devices by reported heartbeat age (for example <= 15m)."""
    parsed_filter = _parse_heartbeat_age_filter(query)
    if parsed_filter is None:
        return {}
    operator, threshold = parsed_filter
    current = time.time() if now is None else float(now)
    if not math.isfinite(current) or current <= 0:
        return {}

    matches = {}
    for device_id, info in visible_devices.items():
        try:
            last_seen = float(info.get("last_seen"))
        except (TypeError, ValueError, OverflowError):
            continue
        if not math.isfinite(last_seen) or last_seen <= 0 or last_seen > current:
            continue
        age = current - last_seen
        if (operator == "<=" and age <= threshold) or (operator == ">=" and age >= threshold):
            matches[device_id] = info
    return matches


def filter_visible_devices_by_component_version(
    query: str, visible_devices: dict[str, dict], *, now: float | None = None,
) -> dict[str, dict]:
    """Match exact versions from the named component's own reported record."""
    parts = " ".join(str(query or "").split()).split(maxsplit=1)
    if len(parts) != 2:
        return {}
    component = parts[0].casefold().replace("-", "").replace("_", "")
    component_aliases = {
        "agent": "agent",
        "guardian": "keeper",
        "guardkeeper": "keeper",
        "keeper": "keeper",
        "safari": "safari",
    }
    component = component_aliases.get(component)
    expected = parts[1].strip()
    if component is None or not expected or len(expected) > 128 or any(ord(ch) < 32 for ch in expected):
        return {}
    current = time.time() if now is None else float(now)
    if not math.isfinite(current) or current <= 0:
        return {}

    matches = {}
    for device_id, info in visible_devices.items():
        reported = None
        if component == "agent":
            reported = info.get("version")
        elif component == "keeper":
            reported = companion_status.device_companions(info, now=current)[0].get("version")
        else:
            record = info.get("safari")
            if isinstance(record, dict) and record.get("version_source") == "safari":
                reported = record.get("version")
        if isinstance(reported, str) and reported.strip() == expected:
            matches[device_id] = info
    return matches


def filter_visible_devices_by_declared_capability(
    query: str, visible_devices: dict[str, dict], *, now: float | None = None,
    max_age: float = 900.0,
) -> dict[str, dict]:
    """Match fresh, explicitly declared command/feature identifiers only."""
    normalized = re.sub(r"[\s-]+", "_", str(query or "").strip().casefold())
    if not re.fullmatch(r"[a-z][a-z0-9_]{0,63}", normalized):
        return {}
    current = time.time() if now is None else float(now)
    if not math.isfinite(current) or current <= 0:
        return {}
    try:
        age_limit = float(max_age)
    except (TypeError, ValueError, OverflowError):
        return {}
    if not math.isfinite(age_limit) or age_limit <= 0 or age_limit > 3600:
        return {}

    matches = {}
    for device_id, info in visible_devices.items():
        try:
            reported_at = float(info.get("capabilities_seen"))
        except (TypeError, ValueError, OverflowError):
            continue
        age = current - reported_at
        if not math.isfinite(reported_at) or age < 0 or age > age_limit:
            continue
        capabilities = info.get("capabilities")
        if not isinstance(capabilities, dict):
            continue
        commands = capabilities.get("commands")
        declared_commands = {
            value for value in commands
            if isinstance(value, str) and re.fullmatch(r"[a-z][a-z0-9_]{0,63}", value)
        } if isinstance(commands, (list, tuple, set)) else set()
        features = capabilities.get("features")
        declared_features = {
            key for key, value in features.items()
            if isinstance(key, str)
            and re.fullmatch(r"[a-z][a-z0-9_]{0,63}", key)
            and value is True
        } if isinstance(features, dict) else set()
        if normalized in declared_commands or normalized in declared_features:
            matches[device_id] = info
    return matches


def filter_visible_devices_by_inventory_age(
    query: str, visible_devices: dict[str, dict], inventory_times: dict[str, int | float],
    *, now: float | None = None,
) -> dict[str, dict]:
    """Filter visible cards by persisted hardware-inventory snapshot age, not heartbeat."""
    parsed_filter = _parse_heartbeat_age_filter(query)
    if parsed_filter is None or not isinstance(inventory_times, dict):
        return {}
    operator, threshold = parsed_filter
    current = time.time() if now is None else float(now)
    if not math.isfinite(current) or current <= 0:
        return {}

    matches = {}
    for device_id, info in visible_devices.items():
        try:
            captured_at = float(inventory_times.get(device_id))
        except (TypeError, ValueError, OverflowError):
            continue
        if not math.isfinite(captured_at) or captured_at <= 0 or captured_at > current:
            continue
        age = current - captured_at
        if (operator == "<=" and age <= threshold) or (operator == ">=" and age >= threshold):
            matches[device_id] = info
    return matches


_UNSUPPORTED_ACTION_CALLBACKS_BY_OS = {
    # macOS deliberately reports this action as unavailable: its agent has no
    # stable public CLI for Night Shift/night-light control.
    "cmd:nightlight": {"macos", "darwin"},
}


def _device_supports_callback(callback: str, target: str | None) -> bool:
    if not target or target == "all":
        return True
    info = devices.get(target) or {}
    os_name = str(info.get("os") or "").strip().lower()
    unsupported_markers = _UNSUPPORTED_ACTION_CALLBACKS_BY_OS.get(callback, set())
    return not any(marker in os_name for marker in unsupported_markers)


def _callback_visible_to_user(callback: str, user_id: int | None = None) -> bool:
    """Render a device action only when the same server-side gate will allow it."""
    user_id = int(user_id if user_id is not None else CURRENT_TG_USER.get())
    target = SESSION.get("target")
    return (
        access_store.can_use_callback(user_id, callback, ADMIN_ID, target)
        and _device_supports_callback(callback, target)
    )


def _action_button(kb: InlineKeyboardBuilder, *, text: str, callback: str,
                   style: str = "primary", user_id: int | None = None) -> None:
    if _callback_visible_to_user(callback, user_id):
        kb.button(text=text, callback_data=callback, style=style)


def _filter_device_keyboard(
    markup: InlineKeyboardMarkup, user_id: int | None = None
) -> InlineKeyboardMarkup:
    """Fail-closed rendering for every action in a device-scoped keyboard.

    Device submenu builders have legacy direct ``button`` calls; filtering the
    completed markup ensures each action uses the same callback/device grant as
    its AdminFilter handler. Public ``url:cancel`` remains a ReadOnlyFilter
    escape from an input form.
    """
    user_id = int(user_id if user_id is not None else CURRENT_TG_USER.get())
    role = get_user_role(user_id)
    rows = []
    for row in markup.inline_keyboard:
        visible = []
        for button in row:
            callback = button.callback_data
            action_target = (
                callback.split(":", 1)[1]
                if callback and callback.startswith("dev:")
                else SESSION.get("target")
            )
            if not callback:
                visible.append(button)
            elif callback == "url:cancel":
                if role != Role.BLOCKED:
                    visible.append(button)
            elif callback.startswith("devices:list:"):
                if role in {Role.OWNER, Role.USER} and access_store.can_use_callback(
                    user_id, "menu:devices", ADMIN_ID, None,
                ):
                    visible.append(button)
            elif callback.startswith("devices:results:"):
                parts = callback.split(":")
                view = _DEVICE_RESULT_VIEWS.get(parts[2]) if len(parts) == 4 else None
                if view and int(view.get("user_id", -1)) == user_id and _device_result_view_allowed(user_id, view):
                    visible.append(button)
            elif callback.startswith("devref:"):
                token = callback.partition(":")[2]
                ref = _DEVICE_SELECT_REFS.get(token)
                target = ref.get("device_id") if ref else None
                if (ref and int(ref.get("user_id", -1)) == user_id and target
                        and target in _visible_device_items(user_id)
                        and access_store.can_use_callback(user_id, f"dev:{target}", ADMIN_ID, target)):
                    visible.append(button)
            elif callback.startswith("url:count:"):
                target = SESSION.get("target")
                if role == Role.OWNER or (
                    target
                    and target != "all"
                    and access_store.can_use_callback(
                        user_id, "cmd:url", ADMIN_ID, target
                    )
                ):
                    visible.append(button)
            elif access_store.can_use_callback(user_id, callback, ADMIN_ID, action_target) and (
                not callback.startswith("cmd:")
                or _device_supports_callback(callback, action_target)
            ):
                visible.append(button)
        if visible:
            rows.append(visible)
    return InlineKeyboardMarkup(inline_keyboard=rows)


def sort_device_inventory(devices_by_id: dict[str, dict], sort_by: str) -> list[tuple[str, dict]]:
    """Sort inventory deterministically; unavailable fields always follow known values."""
    selected = sort_by if sort_by in {"name", "platform", "version", "last_seen"} else "name"

    def key(item):
        device_id, info = item
        if selected == "name":
            raw = info.get("name")
            return (0 if isinstance(raw, str) and raw.strip() else 1,
                    str(raw or "").casefold(), str(device_id).casefold())
        if selected == "platform":
            raw = info.get("os")
            return (0 if isinstance(raw, str) and raw.strip() else 1,
                    str(raw or "").casefold(), str(info.get("name") or device_id).casefold(), str(device_id).casefold())
        if selected == "version":
            raw = info.get("version")
            return (0 if isinstance(raw, str) and raw.strip() else 1,
                    str(raw or "").casefold(), str(info.get("name") or device_id).casefold(), str(device_id).casefold())
        try:
            raw = float(info.get("last_seen"))
        except (TypeError, ValueError, OverflowError):
            raw = float("nan")
        valid = math.isfinite(raw) and raw > 0
        return (0 if valid else 1, -raw if valid else 0.0,
                str(info.get("name") or device_id).casefold(), str(device_id).casefold())

    return sorted(devices_by_id.items(), key=key)


def _catalog_order_token(device_ids: list[str]) -> str:
    return hashlib.sha256("\0".join(device_ids).encode("utf-8")).hexdigest()[:8]


def format_device_comparison(
    left_id: str, left: dict, right_id: str, right: dict, *, now: float | None = None,
) -> str:
    """Render a read-only comparison without turning missing/stale reports into claims."""
    checked_at = time.time() if now is None else float(now)

    def value(record: dict, key: str) -> str:
        raw = record.get(key)
        if not isinstance(raw, str) or not raw.strip():
            return "неизвестно"
        return html.escape(raw.strip()[:120])

    def component(record: dict, key: str) -> str:
        raw = record.get(key)
        if not isinstance(raw, dict):
            return "неизвестно"
        version = raw.get("version")
        if not isinstance(version, str) or not version.strip():
            return "неизвестно"
        return html.escape(version.strip()[:80])

    def capabilities(record: dict) -> str:
        snapshot = record.get("capabilities")
        if not isinstance(snapshot, dict):
            return "неизвестно"
        try:
            observed = float(record.get("capabilities_seen"))
        except (TypeError, ValueError, OverflowError):
            return "неизвестно"
        if (not math.isfinite(observed) or observed <= 0 or observed > checked_at
                or checked_at - observed > 900):
            return "неизвестно (отчёт устарел)"
        raw_commands = snapshot.get("commands")
        if not isinstance(raw_commands, list) or any(not isinstance(item, str) for item in raw_commands):
            return "неизвестно (неполный отчёт)"
        commands = list(dict.fromkeys(item.strip()[:48] for item in raw_commands if item.strip()))
        preview = ", ".join(html.escape(item) for item in commands[:8])
        suffix = f" и ещё {len(commands) - 8}" if len(commands) > 8 else ""
        if not preview:
            return "0 команд"
        count = len(commands)
        plural = "команда" if count % 10 == 1 and count % 100 != 11 else (
            "команды" if 2 <= count % 10 <= 4 and not 12 <= count % 100 <= 14 else "команд"
        )
        return f"{count} {plural}: {preview}{suffix}"

    def card(device_id: str, record: dict) -> list[str]:
        name = record.get("name")
        title = name.strip()[:100] if isinstance(name, str) and name.strip() else str(device_id)[:100]
        return [
            f"<b>{html.escape(title)}</b>",
            f"ОС: {value(record, 'os')}",
            f"Агент: {value(record, 'version')}",
            f"Guard Keeper: {component(record, 'guardian')}",
            f"Safari: {component(record, 'safari')}",
            f"Возможности: {capabilities(record)}",
        ]

    left_lines = card(str(left_id), left if isinstance(left, dict) else {})
    right_lines = card(str(right_id), right if isinstance(right, dict) else {})
    return (
        "<b>Сравнение карточек устройств</b>\n"
        "Данные из сохранённых отчётов; это не новая проверка устройств.\n\n"
        + "\n".join(left_lines) + "\n\n" + "\n".join(right_lines)
    )


def format_device_completeness(device_id: str, info: dict, *, now: float | None = None) -> str:
    """Show inventory completeness with only source timestamps explicitly stored on the record."""
    checked_at = time.time() if now is None else float(now)
    record = info if isinstance(info, dict) else {}
    timestamp_keys = {
        "heartbeat": "last_seen",
        "agent report": "capabilities_seen",
        "Guard Keeper report": "guardian_last_seen",
        "Safari report": "safari_last_seen",
    }

    def observed(source: str) -> str:
        key = timestamp_keys.get(source)
        if not key:
            return "unknown"
        try:
            raw = record.get(key)
            if isinstance(raw, bool):
                return "unknown"
            if isinstance(raw, str):
                normalized = _diagnostic_timestamp(raw)
                stamp = datetime.datetime.fromisoformat(normalized)
            else:
                numeric = float(raw)
                if not math.isfinite(numeric) or numeric <= 0 or numeric > checked_at:
                    return "unknown"
                stamp = datetime.datetime.fromtimestamp(numeric, datetime.timezone.utc)
            if stamp.timestamp() > checked_at:
                return "unknown"
            return stamp.astimezone(datetime.timezone.utc).isoformat(timespec="seconds")
        except (TypeError, ValueError, OverflowError, OSError):
            return "unknown"

    def source_label(source: str) -> str:
        key = timestamp_keys.get(source)
        raw = record.get(key) if key else None
        return source if raw is not None and raw != "" else "source not reported"

    def reported(key: str) -> bool:
        raw = record.get(key)
        if isinstance(raw, str):
            return bool(raw.strip())
        if key == "capabilities":
            return isinstance(raw, dict) and isinstance(raw.get("commands"), list)
        return isinstance(raw, dict) and bool(raw.get("version"))

    fields = (
        ("Device name", "name", "heartbeat", "name"),
        ("Hostname", "hostname", "heartbeat", "hostname"),
        ("OS", "os", "heartbeat", "os"),
        ("Agent version", "version", "heartbeat", "version"),
        ("Capabilities", "capabilities", "agent report", "capabilities"),
        ("Guard Keeper version", "guardian", "Guard Keeper report", "guardian"),
        ("Safari version", "safari", "Safari report", "safari"),
    )
    missing = [label for label, _display, _source, key in fields if not reported(key)]
    title = record.get("name")
    if not isinstance(title, str) or not title.strip():
        title = str(device_id)
    lines = [
        "<b>Полнота карточки устройства</b>",
        f"Устройство: {html.escape(title[:100])}",
        "Только сохранённые сведения; неизвестный timestamp не восстанавливается по догадке.",
        "Не заполнено: " + (", ".join(missing) if missing else "ничего из списка ниже"),
        "",
    ]
    for label, _display, source, key in fields:
        present = "есть" if reported(key) else "нет"
        lines.append(f"{html.escape(label)} · {present} · {source_label(source)} · {observed(source)}")
    return "\n".join(lines)


def format_device_registration_origin(device_id: str, info: dict) -> str:
    record = info if isinstance(info, dict) else {}
    origins = {
        "heartbeat": "heartbeat агента",
        "manual_add": "ручное добавление владельцем",
        "re_registration": "повторная регистрация",
        "unknown": "неизвестно (запись существовала до учёта источника)",
    }
    events = {
        "heartbeat": "heartbeat",
        "manual_add": "ручное добавление",
        "re_registration": "повторная регистрация",
    }

    def timestamp(value) -> str:
        if type(value) not in (int, float) or not math.isfinite(value) or value <= 0:
            return "неизвестно"
        try:
            stamp = datetime.datetime.fromtimestamp(value, datetime.timezone.utc)
            if stamp.timestamp() > time.time() + 60:
                return "неизвестно"
            return stamp.isoformat(timespec="seconds")
        except (ValueError, OverflowError, OSError):
            return "неизвестно"

    origin = record.get("registration_origin")
    if not isinstance(origin, str) or origin not in origins:
        origin = "unknown"
    count = record.get("registration_count")
    count_text = str(count) if type(count) is int and 0 <= count <= 1_000_000 else "неизвестно"
    last_event = record.get("last_registration_event")
    last_event_text = events.get(last_event, "неизвестно") if isinstance(last_event, str) else "неизвестно"
    name = record.get("name")
    title = name.strip() if isinstance(name, str) and name.strip() else str(device_id)
    return "\n".join((
        "<b>Происхождение регистрации</b>",
        f"Устройство: {html.escape(title[:100])}",
        "Источник первой учтённой регистрации: " + origins[origin],
        "Первое учтённое время: " + timestamp(record.get("registered_at")),
        f"Наблюдаемых регистраций: {count_text}",
        "Последнее событие: " + last_event_text,
        "Последнее время регистрации: " + timestamp(record.get("last_registered_at")),
        "Старые записи без источника остаются неизвестными; история не восстанавливается задним числом.",
    ))


def _catalog_order_ids(user_id: int, devices_by_id: dict[str, dict]) -> list[str]:
    sort_by = devices.get_device_catalog_sort(user_id, ADMIN_ID) or "name"
    seed_sort = "name" if sort_by == "custom" else sort_by
    seed_ids = [device_id for device_id, _info in sort_device_inventory(devices_by_id, seed_sort)]
    saved = devices.get_device_catalog_order(user_id, ADMIN_ID, seed_ids)
    return saved if saved is not None else seed_ids


DEVICE_COMPARE_PAGE_SIZE = 8


def _device_compare_inventory(user_id: int) -> tuple[list[tuple[str, dict]], str]:
    visible = _visible_device_items(user_id)
    rows = sorted(visible.items(), key=lambda item: item[0].casefold())[:500]
    evidence = []
    for device_id, info in rows:
        evidence.append((device_id, {
            key: info.get(key) for key in (
                "name", "hostname", "os", "version", "last_seen", "guardian",
                "guardian_last_seen", "safari", "safari_last_seen",
                "capabilities_seen", "capabilities", "registration_origin",
                "registration_count", "registered_at", "last_registered_at",
            )
        }))
    encoded = json.dumps(evidence, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str)
    token = hashlib.sha256(encoded.encode("utf-8")).hexdigest()[:8]
    return rows, token


def device_compare_keyboard(user_id: int, token: str, first_index: int, page_index: int):
    rows, current_token = _device_compare_inventory(user_id)
    if (int(user_id) != int(ADMIN_ID) or token != current_token or not rows
            or not 0 <= first_index < len(rows)):
        return InlineKeyboardMarkup(inline_keyboard=[])
    page_count = max(1, math.ceil(len(rows) / DEVICE_COMPARE_PAGE_SIZE))
    if not 0 <= page_index < page_count:
        return InlineKeyboardMarkup(inline_keyboard=[])
    pages = feature_catalog.visible_navigation_pages(
        feature_catalog.load_registry(), parent="catalog.device_compare",
        role=Role.OWNER if int(user_id) == int(ADMIN_ID) else get_user_role(user_id),
        grants=set(access_store.get_effective_grants(user_id)["callbacks"]), platform="telegram",
    )
    kb = InlineKeyboardBuilder()
    for page in pages:
        page_id, callback, presentation = str(page["page_id"]), str(page["callback"]), page["presentation"]
        if page_id == "catalog.device_compare.row" and callback == "catalog:compare:second:*" and presentation == "device_compare_row":
            start = page_index * DEVICE_COMPARE_PAGE_SIZE
            end = min(len(rows), start + DEVICE_COMPARE_PAGE_SIZE)
            for index in range(start, end):
                if index == first_index:
                    continue
                device_id, info = rows[index]
                label = _limit_button_label(f"{_status_dot(info)} {info.get('name') or device_id}")
                kb.button(
                    text=label,
                    callback_data=callback.replace("*", f"{token}:{first_index}:{page_index}:{index}"),
                    style=str(page["style"]),
                )
        elif page_id == "catalog.device_compare.page" and callback == "catalog:compare:page:*" and presentation == "device_compare_page":
            if page_index > 0:
                kb.button(
                    text=_ui_phrase("⬅️ Previous", "⬅️ Назад", "⬅️ Назад"),
                    callback_data=callback.replace("*", f"{token}:{first_index}:{page_index - 1}:prev"),
                    style=str(page["style"]),
                )
            if page_index + 1 < page_count:
                kb.button(
                    text=_ui_phrase(
                        f"Next ➡️ ({page_index + 2}/{page_count})",
                        f"Дальше ➡️ ({page_index + 2}/{page_count})",
                        f"Дальше ➡️ ({page_index + 2}/{page_count})",
                    ),
                    callback_data=callback.replace("*", f"{token}:{first_index}:{page_index + 1}:next"),
                    style=str(page["style"]),
                )
        elif page_id == "catalog.device_compare.back" and callback == "menu:devices" and presentation == "nav":
            kb.button(text=_nav("back_device"), callback_data=callback, style=str(page["style"]))
        else:
            raise ValueError("feature registry has an unregistered device-compare renderer")
    kb.adjust(1)
    markup = kb.as_markup()
    if any(
        button.callback_data and len(button.callback_data.encode("utf-8")) > 64
        for row in markup.inline_keyboard for button in row
    ):
        raise ValueError("device-compare callback exceeds Telegram's limit")
    return _filter_device_keyboard(markup, int(user_id))


