@router.callback_query(OwnerFilter(), F.data.startswith("catalog:completeness:"))
async def on_device_completeness(cq: CallbackQuery):
    if get_user_role(cq.from_user.id) != Role.OWNER or int(cq.from_user.id) != int(ADMIN_ID) or int(ADMIN_ID) <= 0:
        await cq.answer("Доступ только владельцу.", show_alert=True)
        return
    try:
        token, index_text = cq.data.removeprefix("catalog:completeness:").split(":", 1)
        index = int(index_text)
    except (AttributeError, TypeError, ValueError):
        await cq.answer("Кнопка устарела. Открой карточку устройства заново.", show_alert=True)
        return
    rows, current_token = _device_compare_inventory(cq.from_user.id)
    if token != current_token or not 0 <= index < len(rows):
        await cq.answer("Список устройств изменился. Обнови карточку и повтори.", show_alert=True)
        return
    device_id, info = rows[index]
    await _replace_callback_message(
        cq, format_device_completeness(device_id, info),
        reply_markup=device_completeness_result_keyboard(cq.from_user.id),
    )
    await cq.answer()


