async def on_device_compare_page(cq: CallbackQuery):
    if get_user_role(cq.from_user.id) != Role.OWNER or int(cq.from_user.id) != int(ADMIN_ID):
        await cq.answer("Доступ только владельцу.", show_alert=True)
        return
    try:
        token, first_text, page_text, direction = cq.data.removeprefix("catalog:compare:page:").split(":", 3)
        first_index, page_index = int(first_text), int(page_text)
    except (AttributeError, TypeError, ValueError):
        await cq.answer("Кнопка некорректна.", show_alert=True)
        return
    rows, current_token = _device_compare_inventory(cq.from_user.id)
    if (token != current_token or direction not in {"prev", "next"}
            or not 0 <= first_index < len(rows)
            or not 0 <= page_index < max(1, math.ceil(len(rows) / DEVICE_COMPARE_PAGE_SIZE))):
        await cq.answer("Инвентарь изменился. Начни сравнение заново.", show_alert=True)
        return
    first_name = rows[first_index][1].get("name") or rows[first_index][0]
    await _replace_callback_message(
        cq, f"<b>Сравнение устройств</b>\nПервое: {html.escape(str(first_name)[:100])}\nВыбери второе устройство.",
        reply_markup=device_compare_keyboard(cq.from_user.id, token, first_index, page_index),
    )
    await cq.answer()


@router.callback_query(OwnerFilter(), F.data.startswith("catalog:compare:second:"))
async def on_device_compare_select(cq: CallbackQuery):
    if get_user_role(cq.from_user.id) != Role.OWNER or int(cq.from_user.id) != int(ADMIN_ID):
        await cq.answer("Доступ только владельцу.", show_alert=True)
        return
    try:
        token, first_text, _page_text, second_text = cq.data.removeprefix("catalog:compare:second:").split(":", 3)
        first_index, second_index = int(first_text), int(second_text)
    except (AttributeError, TypeError, ValueError):
        await cq.answer("Кнопка некорректна.", show_alert=True)
        return
    rows, current_token = _device_compare_inventory(cq.from_user.id)
    if (token != current_token or not 0 <= first_index < len(rows)
            or not 0 <= second_index < len(rows) or first_index == second_index):
        await cq.answer("Инвентарь изменился. Начни сравнение заново.", show_alert=True)
        return
    left_id, left = rows[first_index]
    right_id, right = rows[second_index]
    await _replace_callback_message(
        cq, format_device_comparison(left_id, left, right_id, right),
        reply_markup=device_compare_result_keyboard(cq.from_user.id),
    )
    await cq.answer()


@router.callback_query(OwnerFilter(), F.data.startswith("catalog:duplicate:compare:"))
async def on_device_duplicate_compare(cq: CallbackQuery):
    user_id = int(cq.from_user.id)
    if user_id != int(ADMIN_ID) or get_user_role(user_id) != Role.OWNER:
        await cq.answer("Доступ только владельцу.", show_alert=True)
        return
    try:
        token, first_text, second_text = cq.data.removeprefix("catalog:duplicate:compare:").split(":", 2)
        first_index, second_index = int(first_text), int(second_text)
    except (AttributeError, TypeError, ValueError):
        await cq.answer("Кнопка некорректна.", show_alert=True)
        return
    rows, current_token = _device_compare_inventory(user_id)
    if (token != current_token or not 0 <= first_index < len(rows)
            or not 0 <= second_index < len(rows) or first_index == second_index):
        await cq.answer("Инвентарь изменился. Открой карточку заново.", show_alert=True)
        return
    left_id, left = rows[first_index]
    right_id, right = rows[second_index]
    detector = getattr(devices, "find_likely_duplicate_device_pairs", None)
    pairs = detector(user_id, ADMIN_ID) if callable(detector) else None
    if not isinstance(pairs, list) or (left_id, right_id) not in pairs:
        await cq.answer("Совпадение больше не подтверждается. Обнови карточку.", show_alert=True)
        return
    report = format_device_comparison(left_id, left, right_id, right)
    raw_hostname = left.get("hostname")
    hostname = html.escape(raw_hostname.strip()[:120]) if isinstance(raw_hostname, str) and raw_hostname.strip() else "неизвестно"
    report += (
        f"\n\n<b>⚠️ Возможный дубль</b>\nОдинаковый сообщённый hostname: <code>{hostname}</code>\n"
        "Совпала и платформа. Это только подсказка для владельца, не доказательство общей машины. "
        "Записи не объединялись и ничего на устройствах не менялось."
    )
    await _replace_callback_message(
        cq, report, reply_markup=device_compare_result_keyboard(user_id),
    )
    await cq.answer()


def device_catalog_order_keyboard(user_id: int):
    """Render a bounded owner-only reorder screen from registry controls."""
    visible = _visible_device_items(user_id)
    order = _catalog_order_ids(user_id, visible)
    pages = feature_catalog.visible_navigation_pages(
        feature_catalog.load_registry(), parent="catalog.device_order",
        role=Role.OWNER if int(user_id) == int(ADMIN_ID) else get_user_role(user_id),
        grants=set(access_store.get_effective_grants(user_id)["callbacks"]), platform="telegram",
    )
    keyboard = InlineKeyboardBuilder()
    token = _catalog_order_token(order)
    controls = {str(page["page_id"]): page for page in pages}
    up_page = controls.get("catalog.device_order.up")
    down_page = controls.get("catalog.device_order.down")
    row_sizes = []
    for index, device_id in enumerate(order):
        row_count = 0
        info = visible.get(device_id, {})
        name = _limit_button_label(str(info.get("name") or device_id))
        if up_page and index > 0:
            keyboard.button(
                text=_limit_button_label(f"⬆️ {name}"), callback_data=str(up_page["callback"]).replace("*", f"{index}:{token}"),
                style=str(up_page["style"]),
            )
            row_count += 1
        if down_page and index < len(order) - 1:
            keyboard.button(
                text=_limit_button_label(f"⬇️ {name}"), callback_data=str(down_page["callback"]).replace("*", f"{index}:{token}"),
                style=str(down_page["style"]),
            )
            row_count += 1
        if row_count:
            row_sizes.append(row_count)
    for page in pages:
        page_id, callback = str(page["page_id"]), str(page["callback"])
        if page_id == "catalog.device_order.back" and callback == "menu:devices" and page["presentation"] == "nav":
            keyboard.button(text=_nav("back_device"), callback_data=callback, style=str(page["style"]))
            row_sizes.append(1)
        elif page_id in {"catalog.device_order.up", "catalog.device_order.down"} and page["presentation"] == "device_order_move":
            continue
        else:
            raise ValueError("feature registry has an unregistered device-order renderer")
    keyboard.adjust(*row_sizes) if row_sizes else keyboard.adjust(1)
    return _filter_device_keyboard(keyboard.as_markup(), int(user_id))


def devices_menu(user_id: int | None = None, *, include_tools: bool = False, page: int = 0):
    user_id = int(user_id if user_id is not None else CURRENT_TG_USER.get())
    requested_page = max(0, int(page))
    role = get_user_role(user_id)
    role_id = str(role.value if hasattr(role, "value") else role)
    is_owner = role == Role.OWNER
    kb = InlineKeyboardBuilder()
    devs = _visible_device_items(user_id)
    pages = feature_catalog.visible_navigation_pages(
        feature_catalog.load_registry(), parent="devices", role=role_id,
        grants=set(access_store.get_effective_grants(user_id)["callbacks"]), platform="telegram",
    )
    device_row = next((page for page in pages if page["presentation"] == "devices_row"), None)
    rendered_devices = 0
    top_actions = {"devices.search", "devices.filter_os", "devices.filter_heartbeat", "devices.filter_version", "devices.filter_capability", "devices.filter_inventory_age", "devices.saved_sets", "devices.collections", "devices.saved_filters", "devices.sort", "devices.order", "devices.pinned", "devices.activity_history", "devices.export", "devices.import", "devices.archive", "devices.all"}
    bottom_actions = {"devices.add", "devices.install", "devices.blocked", "devices.clear", "devices.refresh", "devices.home"}
    rendered_top_actions = 0
    rendered_bottom_actions = 0
    rendered_tool_actions = 0
    rendered_paging_actions = 0
    labels = {
        "devices.add": "devices_add_button",
        "devices.install": "manual_install_button",
        "devices.blocked": "devices_blocked_button",
        "devices.clear": "devices_clear_button",
    }
    for page in pages:
        page_id = str(page["page_id"])
        callback = str(page["callback"])
        if page_id in {"devices.home", "devices.refresh"}:
            # Navigation itself redraws the device list; do not duplicate it
            # as an action inside the tools submenu.
            continue
        if page_id == "devices.row" and page is device_row and callback == "dev:*":
            if include_tools:
                continue
            sort_by = devices.get_device_catalog_sort(user_id, ADMIN_ID) if hasattr(devices, "get_device_catalog_sort") else "name"
            ordered_devices = _ordered_device_items(user_id, devs)
            page_count = max(1, math.ceil(len(ordered_devices) / _DEVICE_CATALOG_PAGE_SIZE))
            selected_page = min(requested_page, page_count - 1)
            page_devices = ordered_devices[
                selected_page * _DEVICE_CATALOG_PAGE_SIZE:(selected_page + 1) * _DEVICE_CATALOG_PAGE_SIZE
            ]
            for device_id, info in page_devices:
                name = info.get("name") or device_id
                dot = _status_dot(info)
                os_name = str(info.get("os") or "").lower()
                if "mac" in os_name or "darwin" in os_name:
                    icon = "🍏"
                elif "win" in os_name:
                    icon = "🪟"
                elif "linux" in os_name:
                    icon = "🐧"
                else:
                    icon = "💻"
                kb.button(
                    text=_limit_button_label(f"{dot} {icon} {name}"),
                    callback_data=_device_select_callback(user_id, device_id),
                    style=str(page["style"]) if dot == "🟢" else "danger",
                )
                rendered_devices += 1
            if page_count > 1:
                if selected_page > 0:
                    kb.button(text=_ui_phrase("←", "←", "←"), callback_data=f"devices:list:{selected_page - 1}", style="primary")
                    rendered_paging_actions += 1
                if selected_page + 1 < page_count:
                    kb.button(text=_ui_phrase(f"→ {selected_page + 1}/{page_count}", f"→ {selected_page + 1}/{page_count}", f"→ {selected_page + 1}/{page_count}"), callback_data=f"devices:list:{selected_page + 1}", style="primary")
                    rendered_paging_actions += 1
            continue
        if page_id in top_actions and page["presentation"] == "devices_list_action":
            if not include_tools:
                rendered_tool_actions += 1
                continue
            if page_id == "devices.search":
                text = _ui_phrase("🔎 Find a device", "🔎 Найти устройство", "🔎 Найти устройство")
            elif page_id == "devices.filter_os":
                text = _ui_phrase("🧩 Filter by OS", "🧩 Фильтр по ОС", "🧩 Фильтр по ОС")
            elif page_id == "devices.filter_heartbeat":
                text = _ui_phrase("🕒 Filter by heartbeat", "🕒 По давности связи", "🕒 Давность связи")
            elif page_id == "devices.filter_version":
                text = _ui_phrase("🏷 Filter by version", "🏷 По версии компонента", "🏷 Версия компонента")
            elif page_id == "devices.filter_capability":
                text = _ui_phrase("🧩 Filter by capability", "🧩 По возможностям", "🧩 Возможности")
            elif page_id == "devices.filter_inventory_age":
                text = _ui_phrase("🗃 Inventory age", "🗃 По давности инвентаризации", "🗃 Инвентаризация")
            elif page_id == "devices.saved_sets":
                text = _ui_phrase("🗂 Saved device sets", "🗂 Сохранённые наборы", "🗂 Наборы устройств")
            elif page_id == "devices.collections":
                text = _ui_phrase("📚 Device collections", "📚 Коллекции устройств", "📚 Коллекции устройств")
            elif page_id == "devices.saved_filters":
                text = _ui_phrase("🎛 Saved filters", "🎛 Сохранённые фильтры", "🎛 Сохранённые фильтры")
            elif page_id == "devices.sort":
                sort_by = devices.get_device_catalog_sort(user_id, ADMIN_ID) if hasattr(devices, "get_device_catalog_sort") else "name"
                sort_labels = {"name": "name", "platform": "OS", "version": "version", "last_seen": "last seen"}
                text = _ui_phrase(f"↕ Sort: {sort_labels.get(sort_by, 'name')}", f"↕ Сортировка: {sort_labels.get(sort_by, 'имя')}", f"↕ Сортировка: {sort_labels.get(sort_by, 'имя')}")
            elif page_id == "devices.order":
                text = _ui_phrase("↕ My device order", "↕ Мой порядок устройств", "↕ Порядок устройств")
            elif page_id == "devices.pinned":
                pinned_count = len(devices.list_pinned_devices(actor_id=user_id, owner_id=ADMIN_ID)) if hasattr(devices, "list_pinned_devices") else 0
                text = _ui_phrase(f"📌 Pinned devices · {pinned_count}", f"📌 Закреплённые · {pinned_count}", f"📌 Закреплённые · {pinned_count}")
            elif page_id == "devices.activity_history":
                text = _ui_phrase("📉 Activity history", "📉 Динамика активности", "📉 Динамика устройств")
            elif page_id == "devices.export":
                text = _ui_phrase("📤 Export device catalog", "📤 Экспорт каталога", "📤 Экспорт устройств")
            elif page_id == "devices.import":
                text = _ui_phrase("📥 Compare imported catalog", "📥 Сверить каталог из файла", "📥 Сверить каталог")
            elif page_id == "devices.archive":
                archived_count = len(devices.list_archived_devices(actor_id=user_id, owner_id=ADMIN_ID)) if hasattr(devices, "list_archived_devices") else 0
                text = _ui_phrase(f"🗄 Archived · {archived_count}", f"🗄 Архив · {archived_count}", f"🗄 Архив · {archived_count}")
            elif page_id == "devices.all":
                text = _nav(str(page["label_id"]))
            else:
                raise ValueError("feature registry has an unregistered device-list action")
            kb.button(text=text, callback_data=callback, style=str(page["style"]))
            rendered_top_actions += 1
            continue
        if page_id in bottom_actions and page["presentation"] == "devices_list_action":
            if page_id == "devices.home":
                continue
            if not include_tools:
                rendered_tool_actions += 1
                continue
            if page_id in labels:
                text = _lex(labels[page_id])
            else:
                text = _nav(str(page["label_id"]))
            kb.button(text=text, callback_data=callback, style=str(page["style"]))
            rendered_bottom_actions += 1
            continue
        raise ValueError("feature registry has an unregistered device-list renderer")
    if include_tools:
        kb.button(
            text=_ui_phrase("← Devices", "← Устройства", "← Устройства"),
            callback_data="menu:devices", style="primary",
        )
        kb.button(text=_nav("home"), callback_data="menu:main", style="primary")
        rendered_bottom_actions += 2
    else:
        if rendered_tool_actions:
            kb.button(
                text=_ui_phrase("🎛 Filters and tools", "🎛 Фильтры и инструменты", "🎛 Фильтры и инструменты"),
                callback_data="devices:tools", style="primary",
            )
        kb.button(text=_nav("home"), callback_data="menu:main", style="primary")
        rendered_bottom_actions = 1 + int(bool(rendered_tool_actions))
    group_size = 2 if is_owner else 1
    adjust_pattern = [1] * (rendered_devices + rendered_paging_actions + rendered_top_actions)
    adjust_pattern.extend([group_size] * (rendered_bottom_actions // group_size))
    if rendered_bottom_actions % group_size:
        adjust_pattern.append(rendered_bottom_actions % group_size)
    if adjust_pattern:
        kb.adjust(*adjust_pattern)
    return _filter_device_keyboard(kb.as_markup(), user_id)


