def device_catalog_import_preview_text(result: dict, row_count: int) -> str:
    lines = [
        "<b>📥 Сверка каталога устройств</b>",
        f"Строк в файле: {int(row_count)}",
        f"Новые ID: {len(result['new_ids'])} · отсутствуют в файле: {len(result['missing_ids'])} · без конфликта: {len(result['unchanged_ids'])} · конфликты: {len(result['conflicts'])}",
    ]
    for title, key in (("Новые", "new_ids"), ("Нет в файле", "missing_ids")):
        values = result[key]
        if values:
            lines.append(f"\n<b>{title}:</b> " + ", ".join(html.escape(value) for value in values[:20]))
    if result["conflicts"]:
        lines.append("\n<b>Изменённые поля:</b>")
        for conflict in result["conflicts"][:20]:
            fields = ", ".join(html.escape(field) for field in conflict["fields"])
            lines.append(f"• {html.escape(conflict['device_id'])}: {fields}")
    lines.append("\nЭто только предпросмотр: устройства и состояние агентов не изменены.")
    if row_count > 20 or len(result["missing_ids"]) > 20 or len(result["new_ids"]) > 20 or len(result["conflicts"]) > 20:
        lines.append("Показаны первые 20 строк каждой группы.")
    return "\n".join(lines)


