def device_snapshot_detail_keyboard(
    user_id: int, snapshot_id: str, *, confirming_delete: bool = False,
):
    """Render owner-only controls for one saved set and its delete confirmation."""
    snapshot_id = str(snapshot_id)
    if not re.fullmatch(r"[0-9a-f]{32}", snapshot_id):
        return InlineKeyboardMarkup(inline_keyboard=[])
    role = get_user_role(int(user_id))
    role_id = str(role.value if hasattr(role, "value") else role)
    parent = "catalog.snapshot.delete.confirm" if confirming_delete else "catalog.snapshot.detail"
    pages = feature_catalog.visible_navigation_pages(
        feature_catalog.load_registry(), parent=parent, role=role_id,
        grants=set(access_store.get_effective_grants(int(user_id))["callbacks"]), platform="telegram",
    )
    expected = (
        {
            "catalog.snapshot.delete.confirm": (f"catalog:snapshot:delete:confirm:{snapshot_id}", "snapshot_delete_confirm"),
            "catalog.snapshot.delete.cancel": (f"catalog:snapshot:view:{snapshot_id}", "snapshot_delete_cancel"),
            "catalog.snapshot.delete.home": ("menu:main", "home"),
        }
        if confirming_delete else {
            "catalog.snapshot.detail.delete": (f"catalog:snapshot:delete:{snapshot_id}", "snapshot_detail_delete"),
            "catalog.snapshot.detail.back": ("catalog:snapshot:list", "back_device"),
            "catalog.snapshot.detail.home": ("menu:main", "home"),
        }
    )
    kb = InlineKeyboardBuilder()
    for page in pages:
        page_id = str(page["page_id"])
        if page.get("presentation") not in {"snapshot_detail_action", "snapshot_delete_action", "nav"} or page_id not in expected:
            raise ValueError("feature registry has an unregistered saved-snapshot detail renderer")
        callback, label_id = expected[page_id]
        template = str(page["callback"])
        if template.replace("*", snapshot_id) != callback or str(page["label_id"]) != label_id:
            raise ValueError("feature registry saved-snapshot action does not match its fixed renderer")
        if label_id == "snapshot_detail_delete":
            text = _ui_phrase("🗑 Delete this set", "🗑 Удалить этот набор", "🗑 Удалить набор")
        elif label_id == "snapshot_delete_confirm":
            text = _ui_phrase("Delete saved set", "Удалить набор", "Удалить набор")
        elif label_id == "snapshot_delete_cancel":
            text = _ui_phrase("Cancel · keep set", "Отмена · оставить набор", "Не удалять")
        elif label_id == "back_device":
            text = _ui_phrase("Back to saved sets", "К сохранённым наборам", "Назад к наборам")
        else:
            text = _nav("home")
        _action_button(kb, text=text, callback=callback, style=str(page["style"]), user_id=int(user_id))
    kb.adjust(1)
    return _filter_device_keyboard(kb.as_markup(), int(user_id))


