def _valid_saved_filter_rule(filter_type: str, query: str) -> bool:
    normalized = " ".join(str(query or "").split())
    if not normalized or len(normalized) > 120:
        return False
    if filter_type == "os":
        parts = normalized.split(maxsplit=1)
        return parts[0].casefold() in {"windows", "win", "macos", "mac", "darwin"} and (len(parts) == 1 or len(parts[1]) <= 48)
    if filter_type in {"heartbeat", "inventory_age"}:
        return len(normalized) <= 32 and _parse_heartbeat_age_filter(normalized) is not None
    if filter_type == "version":
        parts = normalized.split(maxsplit=1)
        return len(parts) == 2 and parts[0].casefold().replace("-", "").replace("_", "") in {"agent", "guardian", "guardkeeper", "keeper", "safari"}
    if filter_type == "capability":
        value = re.sub(r"[\s-]+", "_", normalized.casefold())
        return re.fullmatch(r"[a-z][a-z0-9_]{0,63}", value) is not None
    return False


def device_saved_filter_catalog(user_id: int):
    rows = devices.list_saved_device_filters(actor_id=user_id, owner_id=ADMIN_ID)
    pages = feature_catalog.visible_navigation_pages(
        feature_catalog.load_registry(), parent="catalog.saved_filter.list",
        role=Role.OWNER if int(user_id) == int(ADMIN_ID) else get_user_role(user_id),
        grants=set(access_store.get_effective_grants(user_id)["callbacks"]), platform="telegram",
    )
    keyboard = InlineKeyboardBuilder()
    for page in pages:
        page_id, callback = str(page["page_id"]), str(page["callback"])
        if page_id == "catalog.saved_filter.row" and callback == "catalog:saved-filter:view:*":
            for row in rows:
                text = _limit_button_label(f"🎛 {row['name']} · {row['filter_type']}")
                keyboard.button(text=text, callback_data=callback.replace("*", row["filter_id"]), style=str(page["style"]))
        elif page_id == "catalog.saved_filter.create" and callback == "catalog:saved-filter:create":
            keyboard.button(text=_ui_phrase("➕ Save a filter", "➕ Сохранить фильтр", "➕ Новый фильтр"), callback_data=callback, style=str(page["style"]))
        elif page_id == "catalog.saved_filter.back" and callback == "menu:devices":
            keyboard.button(text=_nav("back_device"), callback_data=callback, style=str(page["style"]))
        elif page_id == "catalog.saved_filter.home" and callback == "menu:main":
            keyboard.button(text=_nav("home"), callback_data=callback, style=str(page["style"]))
        else:
            raise ValueError("feature registry has an unregistered saved-filter list renderer")
    keyboard.adjust(1)
    return rows, _filter_device_keyboard(keyboard.as_markup(), int(user_id))


def device_saved_filter_detail_keyboard(user_id: int, filter_id: str, *, confirming_delete: bool = False):
    parent = "catalog.saved_filter.delete" if confirming_delete else "catalog.saved_filter.detail"
    pages = feature_catalog.visible_navigation_pages(
        feature_catalog.load_registry(), parent=parent,
        role=Role.OWNER if int(user_id) == int(ADMIN_ID) else get_user_role(user_id),
        grants=set(access_store.get_effective_grants(user_id)["callbacks"]), platform="telegram",
    )
    keyboard = InlineKeyboardBuilder()
    for page in pages:
        page_id, callback = str(page["page_id"]), str(page["callback"])
        if confirming_delete:
            if page_id == "catalog.saved_filter.delete.confirm" and callback == "catalog:saved-filter:delete:confirm:*":
                text, callback = _ui_phrase("Delete saved filter", "Удалить фильтр", "Удалить фильтр"), callback.replace("*", filter_id)
            elif page_id == "catalog.saved_filter.delete.cancel" and callback == "catalog:saved-filter:view:*":
                text, callback = _ui_phrase("Cancel", "Отмена", "Оставить"), callback.replace("*", filter_id)
            elif page_id == "catalog.saved_filter.delete.home" and callback == "menu:main":
                text = _nav("home")
            else:
                raise ValueError("feature registry has an unregistered saved-filter delete renderer")
        else:
            if page_id == "catalog.saved_filter.apply" and callback == "catalog:saved-filter:apply:*":
                text, callback = _ui_phrase("▶ Apply to current devices", "▶ Применить к текущим устройствам", "▶ Выполнить фильтр"), callback.replace("*", filter_id)
            elif page_id == "catalog.saved_filter.delete" and callback == "catalog:saved-filter:delete:*":
                text, callback = _ui_phrase("🗑 Delete filter", "🗑 Удалить фильтр", "🗑 Удалить фильтр"), callback.replace("*", filter_id)
            elif page_id == "catalog.saved_filter.detail.back" and callback == "catalog:saved-filter:list":
                text = _ui_phrase("← Saved filters", "← Фильтры", "← Фильтры")
            else:
                raise ValueError("feature registry has an unregistered saved-filter detail renderer")
        keyboard.button(text=text, callback_data=callback, style=str(page["style"]))
    keyboard.adjust(1)
    return _filter_device_keyboard(keyboard.as_markup(), int(user_id))


def _apply_saved_device_filter(saved: dict, visible: dict[str, dict]):
    filter_type, query = saved.get("filter_type"), saved.get("query")
    if not _valid_saved_filter_rule(filter_type, query):
        return None
    if filter_type == "os":
        parts = query.split(maxsplit=1)
        return filter_visible_devices_by_platform_version(parts[0], parts[1] if len(parts) == 2 else None, visible)
    if filter_type == "heartbeat":
        return filter_visible_devices_by_heartbeat_age(query, visible)
    if filter_type == "version":
        return filter_visible_devices_by_component_version(query, visible)
    if filter_type == "capability":
        return filter_visible_devices_by_declared_capability(query, visible)
    if filter_type == "inventory_age":
        inventory_times = {}
        for device_id in visible:
            try:
                snapshots = devices.list_hardware_inventory_snapshots(device_id, limit=1)
            except (AttributeError, OSError, TypeError, ValueError):
                snapshots = []
            if snapshots and isinstance(snapshots[0], dict):
                inventory_times[device_id] = snapshots[0].get("captured_at")
        return filter_visible_devices_by_inventory_age(query, visible, inventory_times)
    return None


