@router.callback_query(OwnerFilter(), F.data.startswith("catalog:note:view:"))
async def on_device_private_note_view(cq: CallbackQuery, state: FSMContext):
    user_id = int(cq.from_user.id)
    if user_id != int(ADMIN_ID) or get_user_role(user_id) != Role.OWNER:
        await cq.answer("Только владелец.", show_alert=True)
        return
    try:
        _, _, _, token, index_text = cq.data.split(":", 4)
        index = int(index_text)
    except (AttributeError, TypeError, ValueError):
        await cq.answer("Карточка устарела. Открой устройство заново.", show_alert=True)
        return
    rows, current_token = _device_compare_inventory(user_id)
    if token != current_token or not 0 <= index < len(rows):
        await cq.answer("Список устройств изменился. Открой карточку заново.", show_alert=True)
        return
    device_id, info = rows[index]
    note_token = uuid.uuid4().hex[:8]
    await state.clear()
    await state.update_data(
        private_note_device=device_id, private_note_token=note_token,
        private_note_started_at=time.time(),
    )
    note = devices.get_private_device_note(user_id, ADMIN_ID, device_id) or ""
    await _replace_callback_message(
        cq, _device_private_note_text(device_id, note),
        reply_markup=device_private_note_keyboard(user_id, note_token),
    )
    await cq.answer()


