def _shell_runbook_template_library_keyboard(rows, *, offset: int = 0, total: int | None = None):
    total = len(rows) if total is None else total
    keyboard_rows = []
    for row in rows[:10]:
        template_id = str(row["template_id"])
        keyboard_rows.append([
            InlineKeyboardButton(text=f"▶️ {str(row['name'])[:48]}", callback_data=f"cmd:shell-template-use:{template_id}"),
        ])
        keyboard_rows.append([
            InlineKeyboardButton(text="✏️ Переименовать", callback_data=f"cmd:shell-template-rename:{template_id}"),
            InlineKeyboardButton(text="🗑", callback_data=f"cmd:shell-tpl-del:{template_id}"),
        ])
    navigation = []
    if offset > 0:
        navigation.append(InlineKeyboardButton(text="◀️", callback_data=f"cmd:shell-tpl-page:{max(0, offset - 10)}"))
    if offset + len(rows) < total:
        navigation.append(InlineKeyboardButton(text="▶️", callback_data=f"cmd:shell-tpl-page:{offset + 10}"))
    if navigation:
        keyboard_rows.append(navigation)
    keyboard_rows.append([
        InlineKeyboardButton(text=feature_catalog.button_text("shell_runbook_new"), callback_data="cmd:shell_runbook"),
    ])
    keyboard_rows.append([InlineKeyboardButton(text=_nav("back_device"), callback_data="back:device")])
    return InlineKeyboardMarkup(inline_keyboard=keyboard_rows)


