@router.callback_query(OwnerFilter(), F.data.startswith("catalog:link:unlink:"))
async def on_device_relation_unlink(cq: CallbackQuery, state: FSMContext):
    user_id = int(cq.from_user.id)
    if user_id != int(ADMIN_ID) or get_user_role(user_id) != Role.OWNER:
        await cq.answer("Только владелец.", show_alert=True)
        return
    try:
        _, _, _, token, source_text, peer_text = cq.data.split(":", 5)
        source_index, peer_index = int(source_text), int(peer_text)
    except (AttributeError, TypeError, ValueError):
        await cq.answer("Кнопка устарела. Открой связи заново.", show_alert=True)
        return
    rows, current_token = _device_compare_inventory(user_id)
    if token != current_token or not (0 <= source_index < len(rows) and 0 <= peer_index < len(rows)):
        await cq.answer("Список устройств изменился. Открой связи заново.", show_alert=True)
        return
    source_id, peer_id = rows[source_index][0], rows[peer_index][0]
    relations = devices.get_device_relations(user_id, ADMIN_ID, source_id) or []
    if peer_id not in relations:
        await cq.answer("Этой связи уже нет.", show_alert=True)
        return
    if not devices.set_device_relation(user_id, ADMIN_ID, source_id, peer_id, False):
        await cq.answer("Нет прав владельца.", show_alert=True)
        return
    audit("device_relation_unlinked", actor_id=user_id, device_a=source_id, device_b=peer_id)
    relations = devices.get_device_relations(user_id, ADMIN_ID, source_id) or []
    await _replace_callback_message(cq, _device_relations_text(source_id, relations), reply_markup=device_relations_keyboard(user_id, token, source_index, source_id))
    await cq.answer()


@router.message(OwnerFilter(), Form.wait_device_relation_id)
async def on_device_relation_input(message: Message, state: FSMContext):
    user_id = int(message.from_user.id)
    context = _device_relation_context(await state.get_data(), user_id)
    if context is None:
        await state.clear()
        await _replace_user_card(message, "Ввод связи истёк или список устройств изменился; изменения не внесены.")
        return
    device_id, token = context
    peer_id = (message.text or "").strip()
    rows, current_token = _device_compare_inventory(user_id)
    visible_ids = {row[0] for row in rows}
    if current_token != token:
        await state.clear()
        await _replace_user_card(message, "Список устройств изменился; начни связь заново из карточки.")
        return
    if not peer_id or peer_id == device_id or peer_id not in visible_ids:
        await _replace_user_card(
            message, "Второй ID не найден в видимом списке устройств или совпадает с первым. Связь не изменена; отправь точный ID ещё раз.",
            reply_markup=device_relations_keyboard(user_id, token, next(i for i, row in enumerate(rows) if row[0] == device_id), device_id),
        )
        return
    try:
        saved = devices.set_device_relation(user_id, ADMIN_ID, device_id, peer_id, True)
    except (TypeError, ValueError):
        saved = False
    if not saved:
        await state.clear()
        await _replace_user_card(message, "Связь не сохранена: проверь права владельца и актуальность обеих карточек.")
        return
    await state.clear()
    audit("device_relation_linked", actor_id=user_id, device_a=device_id, device_b=peer_id)
    source_index = next(i for i, row in enumerate(rows) if row[0] == device_id)
    relations = devices.get_device_relations(user_id, ADMIN_ID, device_id) or []
    await _replace_user_card(
        message, _device_relations_text(device_id, relations),
        reply_markup=device_relations_keyboard(user_id, token, source_index, device_id),
    )
    try:
        await message.delete()
    except Exception:
        pass


