DEVICE_PURPOSE_LABELS = {
    "personal": ("🏠 Personal", "🏠 Личное", "🏠 Личное"),
    "test": ("🧪 Test", "🧪 Тестовое", "🧪 Тестовое"),
    "work": ("💼 Work", "💼 Рабочее", "💼 Рабочее"),
    "other": ("📦 Other", "📦 Другое", "📦 Другое"),
}


def device_purpose_keyboard(user_id: int, token: str, index: int, current: str | None):
    pages = feature_catalog.visible_navigation_pages(
        feature_catalog.load_registry(), parent="catalog.device_purpose",
        role=Role.OWNER if int(user_id) == int(ADMIN_ID) else get_user_role(user_id),
        grants=set(access_store.get_effective_grants(user_id)["callbacks"]), platform="telegram",
    )
    keyboard = InlineKeyboardBuilder()
    expected = {
        f"catalog.device_purpose.{purpose}": (f"catalog:purpose:set:{purpose}:*", "device_purpose_choice")
        for purpose in DEVICE_PURPOSE_LABELS
    }
    expected.update({
        "catalog.device_purpose.clear": ("catalog:purpose:clear:*", "device_purpose_choice"),
        "catalog.device_purpose.back": ("back:device", "nav"),
        "catalog.device_purpose.home": ("menu:main", "nav"),
    })
    for page in pages:
        page_id = str(page["page_id"])
        contract = expected.get(page_id)
        if contract is None or (str(page["callback"]), str(page["presentation"])) != contract:
            raise ValueError("feature registry has an unregistered device-purpose renderer")
        if page_id.startswith("catalog.device_purpose.") and page_id.rsplit(".", 1)[-1] in DEVICE_PURPOSE_LABELS:
            purpose = page_id.rsplit(".", 1)[-1]
            en, ru, lexical = DEVICE_PURPOSE_LABELS[purpose]
            text = _ui_phrase(en, ru, lexical)
        elif page_id == "catalog.device_purpose.clear":
            text = _ui_phrase("Clear purpose", "Очистить назначение", "Очистить назначение")
        else:
            text = _nav(str(page["label_id"]))
        callback = str(page["callback"])
        if "*" in callback:
            callback = callback.replace("*", f"{token}:{index}")
        if len(callback.encode("utf-8")) > 64:
            continue
        if page_id.startswith("catalog.device_purpose.") and page_id.rsplit(".", 1)[-1] == current:
            text = _limit_button_label(f"✓ {text}")
        _action_button(keyboard, text=text, callback=callback, style=str(page["style"]), user_id=int(user_id))
    keyboard.adjust(1)
    return _filter_device_keyboard(keyboard.as_markup(), int(user_id))


def _device_purpose_text(device_id: str, purpose: str | None, *, result: bool = False) -> str:
    labels = {"personal": "Личное", "test": "Тестовое", "work": "Рабочее", "other": "Другое"}
    name = str((devices.get(device_id) or {}).get("name") or device_id)[:100]
    chosen = labels.get(purpose, "не задано")
    heading = "Назначение сохранено" if result else "Назначение устройства"
    return f"<b>🎯 {heading}</b> · {html.escape(name)}\n{html.escape(chosen)}\n\nЭто одна фиксированная классификация; свободные теги устройства не меняются."


