def _device_inventory_metadata_state(user_id: int, device_id: str) -> bool | None:
    """Return True when owner metadata exists, False when blank, None when it cannot be verified."""
    if int(user_id) != int(ADMIN_ID) or get_user_role(user_id) != Role.OWNER:
        return None
    getters = (
        getattr(devices, "get_device_tags", None),
        getattr(devices, "get_device_purpose", None),
        getattr(devices, "typed_fields", None),
    )
    if not all(callable(getter) for getter in getters):
        return None
    try:
        tags = getters[0](user_id, ADMIN_ID, device_id)
        purpose = getters[1](user_id, ADMIN_ID, device_id)
        fields = getters[2](user_id, ADMIN_ID, device_id)
    except (TypeError, ValueError, OSError):
        return None
    if not isinstance(tags, list) or not isinstance(fields, dict):
        return None
    return bool(tags or purpose or fields)


def _device_inventory_template_snapshot(user_id: int) -> tuple[list[dict], str] | None:
    getter = getattr(devices, "list_device_inventory_templates", None)
    if int(user_id) != int(ADMIN_ID) or get_user_role(user_id) != Role.OWNER or not callable(getter):
        return None
    templates = getter(user_id, ADMIN_ID)
    if not isinstance(templates, list) or len(templates) > 50:
        return None
    for row in templates:
        if (not isinstance(row, dict)
                or not isinstance(row.get("template_id"), str)
                or not re.fullmatch(r"[0-9a-f]{32}", row["template_id"])
                or row.get("owner_id") != int(ADMIN_ID)
                or not isinstance(row.get("name"), str)
                or not isinstance(row.get("tags"), list)
                or not isinstance(row.get("typed_values"), dict)):
            return None
    packed = json.dumps(templates, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str)
    return templates, hashlib.sha256(packed.encode("utf-8")).hexdigest()[:8]


def _inventory_template_navigation(user_id: int, mode: str, suffix: str):
    parents = {
        "list": "catalog.device_inventory_template",
        "preview": "catalog.device_inventory_template.preview",
        "save": "catalog.device_inventory_template.prompt",
    }
    parent = parents.get(mode)
    if parent is None or int(user_id) != int(ADMIN_ID) or get_user_role(user_id) != Role.OWNER:
        return InlineKeyboardMarkup(inline_keyboard=[])
    pages = feature_catalog.visible_navigation_pages(
        feature_catalog.load_registry(), parent=parent, role=Role.OWNER,
        grants=set(access_store.get_effective_grants(user_id)["callbacks"]), platform="telegram",
    )
    expected = {
        "catalog.inventory_template.select": ("catalog:template:preview:*", "device_inventory_template_action"),
        "catalog.inventory_template.confirm": ("catalog:template:confirm:*", "device_inventory_template_action"),
        "catalog.inventory_template.cancel": ("catalog:template:cancel:*", "device_inventory_template_action"),
        "catalog.inventory_template.preview_back": ("catalog:template:back:*", "device_inventory_template_action"),
        "catalog.inventory_template.save_cancel": ("catalog:template:save-cancel:*", "device_inventory_template_action"),
        "catalog.inventory_template.back": ("back:device", "nav"),
        "catalog.inventory_template.home": ("menu:main", "nav"),
    }
    keyboard = InlineKeyboardBuilder()
    for page in pages:
        page_id = str(page["page_id"])
        contract = expected.get(page_id)
        if contract is None or (str(page["callback"]), str(page["presentation"])) != contract:
            raise ValueError("feature registry has an unregistered inventory-template renderer")
        callback = str(page["callback"])
        if "*" in callback:
            callback = callback.replace("*", suffix)
        if len(callback.encode("utf-8")) > 64:
            continue
        if page_id == "catalog.inventory_template.select":
            text = _ui_phrase("Choose this template", "Предпросмотр", "Показать шаблон")
        elif page_id == "catalog.inventory_template.confirm":
            text = _ui_phrase("Apply template", "Применить этот шаблон", "Применить шаблон")
        elif page_id in {"catalog.inventory_template.cancel", "catalog.inventory_template.save_cancel"}:
            text = _ui_phrase("Cancel", "Отмена", "Отмена")
        elif page_id == "catalog.inventory_template.preview_back":
            text = _ui_phrase("Back to templates", "К шаблонам", "Назад к шаблонам")
        else:
            text = _nav(str(page["label_id"]))
        _action_button(keyboard, text=text, callback=callback, style=str(page["style"]), user_id=user_id)
    keyboard.adjust(1)
    return _filter_device_keyboard(keyboard.as_markup(), user_id)


def _inventory_template_context(user_id: int, data: dict) -> tuple[str, str, int] | None:
    if (int(user_id) != int(ADMIN_ID) or get_user_role(user_id) != Role.OWNER
            or not isinstance(data, dict)):
        return None
    device_id, token, index, started = (
        data.get("inventory_template_device"), data.get("inventory_template_inventory_token"),
        data.get("inventory_template_device_index"), data.get("inventory_template_started_at"),
    )
    if (not isinstance(device_id, str) or not device_id
            or not isinstance(token, str) or not re.fullmatch(r"[0-9a-f]{8}", token)
            or type(index) is not int or index < 0
            or type(started) not in (int, float) or not math.isfinite(started)
            or time.time() - started > 900 or started > time.time() + 60):
        return None
    rows, current_token = _device_compare_inventory(user_id)
    if token != current_token or not 0 <= index < len(rows) or rows[index][0] != device_id:
        return None
    return device_id, token, index


def _inventory_template_list_text(device_id: str, templates: list[dict]) -> str:
    device_name = html.escape(str((devices.get(device_id) or {}).get("name") or device_id)[:100])
    lines = [f"<b>🧩 Шаблоны инвентаря</b> · {device_name}",
             "Выбери шаблон: сначала покажу точный состав, применение будет отдельным нажатием.", ""]
    for index, row in enumerate(templates, 1):
        lines.append(f"{index}. {html.escape(row['name'][:80])}")
    if not templates:
        lines.append("Шаблонов пока нет — сохрани первый из заполненной карточки устройства.")
    lines.append("\nКопируются только метки, назначение и совместимые пользовательские поля; сведения агента не копируются.")
    return "\n".join(lines)


def _inventory_template_preview_text(device_id: str, template: dict) -> str:
    purpose_labels = {"personal": "Личное", "test": "Тестовое", "work": "Рабочее", "other": "Другое"}
    tags = template.get("tags", [])
    typed_values = template.get("typed_values", {})
    if (not isinstance(tags, list) or not isinstance(typed_values, dict)
            or len(tags) > 16 or len(typed_values) > 64):
        raise ValueError("template metadata is malformed")
    name = html.escape(str((devices.get(device_id) or {}).get("name") or device_id)[:100])
    fields = [
        f"<b>🧩 Предпросмотр шаблона</b> · {name}",
        f"Шаблон: <b>{html.escape(template['name'][:80])}</b>",
        "Метки: " + (", ".join(html.escape(str(value)[:80]) for value in tags) or "—"),
        "Назначение: " + html.escape(purpose_labels.get(template.get("purpose"), "—")),
        "Пользовательские поля:",
    ]
    fields.extend(
        f"• <code>{html.escape(str(key)[:80])}</code>: {html.escape(str(value)[:120])}"
        for key, value in sorted(typed_values.items())
    )
    if not typed_values:
        fields.append("—")
    fields.append("\nПодтверди, чтобы записать только эти локальные поля. ОС/версия и отчёты агента не затрагиваются.")
    return "\n".join(fields)


def _template_callback_suffix(inventory_token: str, template_token: str, device_index: int, template_index: int) -> str:
    return f"{inventory_token}:{template_token}:{device_index}:{template_index}"


@router.callback_query(OwnerFilter(), F.data.startswith("catalog:template:save:"))
async def on_device_inventory_template_save(cq: CallbackQuery, state: FSMContext):
    user_id = int(cq.from_user.id)
    if user_id != int(ADMIN_ID) or get_user_role(user_id) != Role.OWNER:
        await cq.answer("Только владелец.", show_alert=True)
        return
    try:
        token, index_text = cq.data.removeprefix("catalog:template:save:").split(":", 1)
        index = int(index_text)
    except (AttributeError, TypeError, ValueError):
        await cq.answer("Карточка устарела. Открой устройство заново.", show_alert=True)
        return
    rows, current_token = _device_compare_inventory(user_id)
    if token != current_token or not 0 <= index < len(rows):
        await cq.answer("Список устройств изменился. Открой карточку заново.", show_alert=True)
        return
    session_token = uuid.uuid4().hex[:8]
    device_id = rows[index][0]
    await state.clear()
    await state.update_data(
        inventory_template_device=device_id, inventory_template_inventory_token=token,
        inventory_template_device_index=index, inventory_template_session_token=session_token,
        inventory_template_started_at=time.time(),
    )
    await state.set_state(Form.wait_device_inventory_template_name)
    name = html.escape(str(rows[index][1].get("name") or device_id)[:100])
    text = (f"<b>Сохранить шаблон</b> · {name}\n"
            "Введи короткое имя. Сохранятся только метки, назначение и проверенные пользовательские поля — не данные агента.")
    await _replace_callback_message(
        cq, text,
        reply_markup=_inventory_template_navigation(user_id, "save", session_token),
    )
    await cq.answer()


@router.message(OwnerFilter(), Form.wait_device_inventory_template_name)
async def on_device_inventory_template_name(message: Message, state: FSMContext):
    user_id = int(message.from_user.id)
    data = await state.get_data()
    context = _inventory_template_context(user_id, data)
    token = data.get("inventory_template_session_token") if isinstance(data, dict) else None
    if (context is None or not isinstance(token, str) or not re.fullmatch(r"[0-9a-f]{8}", token)):
        await state.clear()
        await _replace_user_card(message, "Ввод шаблона устарел или доступ к устройству изменился. Начни заново из карточки.")
        return
    device_id, _inventory_token, _index = context
    try:
        template = devices.create_device_inventory_template(user_id, ADMIN_ID, message.text or "", device_id)
    except (TypeError, ValueError) as exc:
        await _replace_user_card(
            message, f"Шаблон не сохранён: {html.escape(str(exc))}. Введи другое имя.",
            reply_markup=_inventory_template_navigation(user_id, "save", token),
        )
        return
    if not isinstance(template, dict):
        await state.clear()
        await _replace_user_card(message, "Шаблон не сохранён: проверь права владельца и повтори из карточки.")
        return
    await state.clear()
    audit("device_inventory_template_created", actor_id=user_id, device_id=device_id, template_id=template.get("template_id"))
    await _replace_user_card(
        message,
        f"<b>Шаблон сохранён</b> · {html.escape(template['name'])}\nСохранены только локальные метки и безопасные пользовательские поля.",
        reply_markup=device_menu(device_id, user_id),
    )


@router.callback_query(OwnerFilter(), F.data.startswith("catalog:template:save-cancel:"))
async def on_device_inventory_template_save_cancel(cq: CallbackQuery, state: FSMContext):
    user_id = int(cq.from_user.id)
    data = await state.get_data()
    context = _inventory_template_context(user_id, data)
    token = cq.data.rsplit(":", 1)[-1]
    if context is None or data.get("inventory_template_session_token") != token:
        await state.clear()
        await cq.answer("Сессия уже истекла.", show_alert=True)
        return
    device_id, _inventory_token, _index = context
    await state.clear()
    await _replace_callback_message(cq, "Сохранение шаблона отменено.", reply_markup=device_menu(device_id, user_id))
    await cq.answer()


async def _show_inventory_template_list(cq: CallbackQuery, user_id: int, inventory_token: str, device_index: int):
    rows, current_token = _device_compare_inventory(user_id)
    if inventory_token != current_token or not 0 <= device_index < len(rows):
        await cq.answer("Список устройств изменился. Открой карточку заново.", show_alert=True)
        return
    device_id = rows[device_index][0]
    if _device_inventory_metadata_state(user_id, device_id) is not False:
        await cq.answer("Шаблон применяется только к карточке без меток и пользовательских полей.", show_alert=True)
        return
    snapshot = _device_inventory_template_snapshot(user_id)
    if snapshot is None:
        await cq.answer("Шаблоны недоступны или их каталог повреждён.", show_alert=True)
        return
    templates, template_token = snapshot
    suffix = f"{inventory_token}:{device_index}"
    markup = _inventory_template_navigation(user_id, "list", suffix)
    text = _inventory_template_list_text(device_id, templates)
    if templates:
        selection_page = next((page for page in feature_catalog.visible_navigation_pages(
            feature_catalog.load_registry(), parent="catalog.device_inventory_template", role=Role.OWNER,
            grants=set(access_store.get_effective_grants(user_id)["callbacks"]), platform="telegram",
        ) if page["page_id"] == "catalog.inventory_template.select"), None)
        if selection_page is None or selection_page["callback"] != "catalog:template:preview:*":
            raise ValueError("feature registry is missing the inventory-template preview action")
        keyboard = InlineKeyboardBuilder()
        for index, template in enumerate(templates):
            callback_suffix = _template_callback_suffix(inventory_token, template_token, device_index, index)
            callback = str(selection_page["callback"]).replace("*", callback_suffix)
            if len(callback.encode("utf-8")) > 64:
                continue
            _action_button(
                keyboard,
                text=_limit_button_label(f"🧩 {template['name']}"),
                callback=callback, style=str(selection_page["style"]), user_id=user_id,
            )
        for row in markup.inline_keyboard:
            keyboard.row(*row)
        markup = _filter_device_keyboard(keyboard.as_markup(), user_id)
    await _replace_callback_message(cq, text, reply_markup=markup)
    await cq.answer()


