    if user_id != int(ADMIN_ID) or get_user_role(user_id) != Role.OWNER:
        await cq.answer("Только владелец.", show_alert=True)
        return
    try:
        token, index_text = cq.data.removeprefix("catalog:review:edit:").split(":", 1)
        index = int(index_text)
    except (AttributeError, TypeError, ValueError):
        await cq.answer("Карточка устарела. Открой устройство заново.", show_alert=True)
        return
    rows, current_token = _device_compare_inventory(user_id)
    if token != current_token or not 0 <= index < len(rows):
        await cq.answer("Список устройств изменился. Открой карточку заново.", show_alert=True)
        return
    device_id = rows[index][0]
    state_token = uuid.uuid4().hex[:8]
    await state.clear()
    await state.update_data(
        review_date_device=device_id, review_date_token=state_token,
        review_date_started_at=time.time(),
    )
    await state.set_state(Form.wait_device_review_date)
    current = devices.get_device_review_date(user_id, ADMIN_ID, device_id) or "—"
    name = str((devices.get(device_id) or {}).get("name") or device_id)[:100]
    prompt = (
        f"<b>🗓 Ручная дата пересмотра</b> · {html.escape(name)}\n"
        f"Сейчас: <code>{html.escape(current)}</code>\n\n"
        "Введи дату в формате YYYY-MM-DD. Это заметка владельца: уведомление по расписанию не отправляется и агент не опрашивается. "
        "Чтобы снять дату, отправь <code>clear</code>."
    )
    await _replace_callback_message(cq, prompt, reply_markup=_device_review_date_cancel_keyboard(user_id, state_token))
    await cq.answer()


