def _device_inventory_wizard_keyboard(user_id: int, token: str):
    pages = feature_catalog.visible_navigation_pages(
        feature_catalog.load_registry(), parent="catalog.device_inventory_wizard",
        role=Role.OWNER if int(user_id) == int(ADMIN_ID) else get_user_role(user_id),
        grants=set(access_store.get_effective_grants(user_id)["callbacks"]), platform="telegram",
    )
    keyboard = InlineKeyboardBuilder()
    expected = {
        "catalog.device_inventory_wizard.skip": ("catalog:wizard:skip:*", "device_inventory_wizard_action"),
        "catalog.device_inventory_wizard.cancel": ("catalog:wizard:cancel:*", "device_inventory_wizard_action"),
    }
    for page in pages:
        page_id = str(page["page_id"])
        template = expected.get(page_id)
        if template is None or (str(page["callback"]), str(page["presentation"])) != template:
            raise ValueError("feature registry has an unregistered inventory-wizard action")
        text = (
            _ui_phrase("Skip this step", "Пропустить шаг", "Пропустить")
            if page_id.endswith(".skip")
            else _ui_phrase("Cancel inventory", "Отменить заполнение", "Отмена")
        )
        keyboard.button(
            text=text, callback_data=str(page["callback"]).replace("*", token),
            style=str(page["style"]),
        )
    keyboard.adjust(1)
    return _filter_device_keyboard(keyboard.as_markup(), int(user_id))


def _device_inventory_wizard_context(data: dict, user_id: int) -> tuple[str, str] | None:
    if (get_user_role(user_id) != Role.OWNER or int(user_id) != int(ADMIN_ID)
            or int(ADMIN_ID) <= 0):
        return None
    if not isinstance(data, dict):
        return None
    device_id, token = data.get("inventory_wizard_device"), data.get("inventory_wizard_token")
    started_at = data.get("inventory_wizard_started_at")
    if (not isinstance(device_id, str) or not device_id
            or not isinstance(token, str) or not re.fullmatch(r"[0-9a-f]{8}", token)
            or type(started_at) not in (int, float) or not math.isfinite(started_at)
            or time.time() - started_at > 900 or started_at > time.time() + 60
            or device_id not in _visible_device_items(user_id)):
        return None
    return device_id, token


async def _device_inventory_wizard_step(source, state: FSMContext, user_id: int, device_id: str, token: str):
    data = await state.get_data()
    field_keys = data.get("inventory_wizard_field_keys")
    index = data.get("inventory_wizard_field_index")
    if not isinstance(field_keys, list) or type(index) is not int or index < 0:
        schemas = devices.typed_field_schemas(user_id, ADMIN_ID) or {}
        values = devices.typed_fields(user_id, ADMIN_ID, device_id) or {}
        field_keys = [key for key in sorted(schemas) if key not in values]
        index = 0
    await state.update_data(
        inventory_wizard_stage="fields", inventory_wizard_field_keys=field_keys,
        inventory_wizard_field_index=index,
    )
    while index < len(field_keys):
        key = field_keys[index]
        current_schemas = devices.typed_field_schemas(user_id, ADMIN_ID) or {}
        current_values = devices.typed_fields(user_id, ADMIN_ID, device_id) or {}
        schema = current_schemas.get(key)
        if key in current_values or not isinstance(schema, dict):
            index += 1
            continue
        kind = schema.get("type")
        choices = schema.get("choices", [])
        safe_key = html.escape(key)
        if kind == "enum" and isinstance(choices, list):
            detail = "Допустимые значения: " + ", ".join(html.escape(str(item)) for item in choices)
        elif kind == "date":
            detail = "Формат: <code>YYYY-MM-DD</code>."
        elif kind == "boolean":
            detail = "Ответь <code>да</code> или <code>нет</code>."
        else:
            index += 1
            continue
        await state.update_data(inventory_wizard_field_index=index, inventory_wizard_field_key=key)
        await state.set_state(Form.wait_device_inventory_wizard_value)
        await _replace_callback_message(
            source,
            f"<b>Инвентаризация устройства</b> · шаг {index + 2}/{len(field_keys) + 1}\n"
            f"Поле <code>{safe_key}</code> ({html.escape(str(kind))}). {detail}\n"
            "Данные останутся в каталоге владельца и не отправятся агенту.",
            reply_markup=_device_inventory_wizard_keyboard(user_id, token),
        ) if isinstance(source, CallbackQuery) else await _replace_user_card(
            source,
            f"<b>Инвентаризация устройства</b> · шаг {index + 2}/{len(field_keys) + 1}\n"
            f"Поле <code>{safe_key}</code> ({html.escape(str(kind))}). {detail}\n"
            "Данные останутся в каталоге владельца и не отправятся агенту.",
            reply_markup=_device_inventory_wizard_keyboard(user_id, token),
        )
        return
    await state.clear()
    tags = devices.get_device_tags(user_id, ADMIN_ID, device_id) or []
    stored = devices.typed_fields(user_id, ADMIN_ID, device_id) or {}
    tag_text = ", ".join(html.escape(value) for value in tags) or "—"
    field_text = "\n".join(
        f"• <code>{html.escape(str(key))}</code>: {html.escape(str(value))}"
        for key, value in sorted(stored.items())
    ) or "—"
    summary = (
        "<b>Инвентаризация завершена</b>\n"
        f"Устройство: {html.escape(str((devices.get(device_id) or {}).get('name') or device_id)[:100])}\n"
        f"Метки: {tag_text}\nПоля:\n{field_text}\n\n"
        "Это только локальные данные каталога; удалённые команды не запускались."
    )
    if isinstance(source, CallbackQuery):
        await _replace_callback_message(source, summary, reply_markup=device_menu(device_id, user_id))
    else:
        await _replace_user_card(source, summary, reply_markup=device_menu(device_id, user_id))


@router.callback_query(OwnerFilter(), F.data.startswith("catalog:wizard:start:"))
async def on_device_inventory_wizard_start(cq: CallbackQuery, state: FSMContext):
    user_id = int(cq.from_user.id)
    if user_id != int(ADMIN_ID) or get_user_role(user_id) != Role.OWNER or int(ADMIN_ID) <= 0:
        await cq.answer("Доступ только владельцу.", show_alert=True)
        return
    try:
        token, index_text = cq.data.removeprefix("catalog:wizard:start:").split(":", 1)
        index = int(index_text)
    except (AttributeError, TypeError, ValueError):
        await cq.answer("Карточка устарела. Открой устройство заново.", show_alert=True)
        return
    rows, current_token = _device_compare_inventory(user_id)
    if token != current_token or not 0 <= index < len(rows):
        await cq.answer("Список устройств изменился. Открой карточку заново.", show_alert=True)
        return
    device_id = rows[index][0]
    wizard_token = uuid.uuid4().hex[:8]
    await state.clear()
    await state.update_data(
        inventory_wizard_device=device_id, inventory_wizard_token=wizard_token,
        inventory_wizard_started_at=time.time(), inventory_wizard_stage="tags",
    )
    await state.set_state(Form.wait_device_inventory_wizard_tags)
    existing = devices.get_device_tags(user_id, ADMIN_ID, device_id) or []
    text = (
        f"<b>Инвентаризация · шаг 1</b>\nУстройство: {html.escape(str(rows[index][1].get('name') or device_id)[:100])}\n"
        f"Текущие метки: {', '.join(html.escape(value) for value in existing) or '—'}\n\n"
        "Введи метки через запятую. Пустой ввод оставит текущие; слово <code>clear</code> очистит их.\n"
        "Дальше мастер пройдёт по пустым типизированным полям. Никакие команды устройству не отправляются."
    )
    await _replace_callback_message(cq, text, reply_markup=_device_inventory_wizard_keyboard(user_id, wizard_token))
    await cq.answer()


@router.callback_query(OwnerFilter(), F.data.startswith("catalog:wizard:skip:"))
async def on_device_inventory_wizard_skip(cq: CallbackQuery, state: FSMContext):
    user_id = int(cq.from_user.id)
    data = await state.get_data()
    context = _device_inventory_wizard_context(data, user_id)
    token = cq.data.rsplit(":", 1)[-1]
    if context is None or token != context[1]:
        await state.clear()
        await cq.answer("Мастер устарел. Запусти его из карточки заново.", show_alert=True)
        return
    device_id, _ = context
    if data.get("inventory_wizard_stage") == "tags":
        await _device_inventory_wizard_step(cq, state, user_id, device_id, token)
    elif data.get("inventory_wizard_stage") == "fields":
        field_keys = data.get("inventory_wizard_field_keys")
        index = data.get("inventory_wizard_field_index")
        if not isinstance(field_keys, list) or type(index) is not int or index < 0:
            await state.clear()
            await cq.answer("Шаг повреждён. Запусти мастер заново.", show_alert=True)
            return
        await state.update_data(inventory_wizard_field_index=index + 1)
        await _device_inventory_wizard_step(cq, state, user_id, device_id, token)
    else:
        await state.clear()
        await cq.answer("Мастер устарел.", show_alert=True)
        return
    await cq.answer()


@router.callback_query(OwnerFilter(), F.data.startswith("catalog:wizard:cancel:"))
async def on_device_inventory_wizard_cancel(cq: CallbackQuery, state: FSMContext):
    user_id = int(cq.from_user.id)
    data = await state.get_data()
    context = _device_inventory_wizard_context(data, user_id)
    if context is None or cq.data.rsplit(":", 1)[-1] != context[1]:
        await state.clear()
        await cq.answer("Мастер уже завершён или устарел.", show_alert=True)
        return
    device_id, _ = context
    await state.clear()
    await _replace_callback_message(cq, "Заполнение отменено; сохранённые значения не изменены.", reply_markup=device_menu(device_id, user_id))
    await cq.answer()


@router.message(OwnerFilter(), Form.wait_device_inventory_wizard_tags)
async def on_device_inventory_wizard_tags(message: Message, state: FSMContext):
    user_id = int(message.from_user.id)
    data = await state.get_data()
    context = _device_inventory_wizard_context(data, user_id)
    if context is None or data.get("inventory_wizard_stage") != "tags":
        await state.clear()
        await _replace_user_card(message, "Мастер устарел или устройство недоступно. Запусти его заново из карточки.")
        return
    device_id, token = context
    raw = message.text or ""
    if len(raw) > 1400:
        await _replace_user_card(message, "Слишком длинный список меток; ничего не изменено. Отправь до 16 меток.", reply_markup=_device_inventory_wizard_keyboard(user_id, token))
        return
    if not raw.strip():
        tags = devices.get_device_tags(user_id, ADMIN_ID, device_id) or []
    elif raw.strip().casefold() == "clear":
        tags = []
    else:
        tags = [part.strip() for part in raw.split(",") if part.strip()]
    try:
        saved = devices.set_device_tags(user_id, ADMIN_ID, device_id, tags)
    except (TypeError, ValueError):
        await _replace_user_card(message, "Метки не изменены: допустимо до 16 значений, по 80 символов каждое. Попробуй снова.", reply_markup=_device_inventory_wizard_keyboard(user_id, token))
        return
    if not saved:
        await state.clear()
        await _replace_user_card(message, "Метки не сохранены: владелец или устройство больше недоступны.")
        return
    audit("device_inventory_wizard_tags_saved", actor_id=user_id, device_id=device_id, tag_count=len(tags))
    await _device_inventory_wizard_step(message, state, user_id, device_id, token)


@router.message(OwnerFilter(), Form.wait_device_inventory_wizard_value)
async def on_device_inventory_wizard_value(message: Message, state: FSMContext):
    user_id = int(message.from_user.id)
    data = await state.get_data()
    context = _device_inventory_wizard_context(data, user_id)
    if context is None or data.get("inventory_wizard_stage") != "fields":
        await state.clear()
        await _replace_user_card(message, "Мастер устарел или устройство недоступно. Запусти его заново из карточки.")
        return
    device_id, token = context
    key = data.get("inventory_wizard_field_key")
    schemas = devices.typed_field_schemas(user_id, ADMIN_ID) or {}
    schema = schemas.get(key) if isinstance(key, str) else None
    raw = (message.text or "").strip()
    if not isinstance(schema, dict):
        await state.clear()
        await _replace_user_card(message, "Схема поля изменилась. Запусти мастер заново.", reply_markup=device_menu(device_id, user_id))
        return
    kind, value = schema.get("type"), raw
    if kind == "boolean":
        normalized = raw.casefold()
        if normalized in {"да", "yes", "true", "1"}:
            value = True
        elif normalized in {"нет", "no", "false", "0"}:
            value = False
        else:
            await _replace_user_card(message, "Ответь <code>да</code> или <code>нет</code>.", reply_markup=_device_inventory_wizard_keyboard(user_id, token))
            return
    elif kind == "enum" and raw not in schema.get("choices", []):
        choices = ", ".join(html.escape(str(item)) for item in schema.get("choices", []))
        await _replace_user_card(message, f"Выбери ровно одно значение: {choices}.", reply_markup=_device_inventory_wizard_keyboard(user_id, token))
        return
    try:
        saved = devices.set_typed_field(user_id, ADMIN_ID, device_id, key, value)
    except ValueError as exc:
        await _replace_user_card(message, f"Значение не сохранено: {html.escape(str(exc))}. Проверь формат и повтори.", reply_markup=_device_inventory_wizard_keyboard(user_id, token))
        return
    if not saved:
        await state.clear()
        await _replace_user_card(message, "Поле не сохранено: схема или устройство больше недоступны.", reply_markup=device_menu(device_id, user_id))
        return
    audit("device_inventory_wizard_field_saved", actor_id=user_id, device_id=device_id, field=key)
    data["inventory_wizard_field_index"] = int(data.get("inventory_wizard_field_index", 0)) + 1
    await state.update_data(inventory_wizard_field_index=data["inventory_wizard_field_index"])
    await _device_inventory_wizard_step(message, state, user_id, device_id, token)


