@router.message(OwnerFilter(), Form.wait_device_collection_create)
async def on_device_collection_create_name(message: Message, state: FSMContext):
    name = " ".join((message.text or "").split())
    if not name or len(name) > 80:
        await _replace_user_card(message, "Название должно быть длиной от 1 до 80 символов. Попробуй ещё раз.")
        return
    await state.update_data(device_collection_name=name)
    await state.set_state(Form.wait_device_collection_members)
