    await _replace_user_card(
        message,
        "Теперь отправь ID устройств через запятую. Доступные ID:\n" + "\n".join(f"<code>{html.escape(item)}</code>" for item in ids[:100]),
        reply_markup=back_to_device_kb(),
    )


