async def on_device_collection_create_members(message: Message, state: FSMContext):
    data = await state.get_data()
    name = str(data.get("device_collection_name") or "")
    device_ids = [part.strip() for part in (message.text or "").split(",") if part.strip()]
    try:
        saved = devices.create_device_collection(message.from_user.id, ADMIN_ID, name, device_ids)
    except ValueError as exc:
        await _replace_user_card(message, f"Коллекция не создана: {html.escape(str(exc))}. Отправь ID ещё раз.", reply_markup=back_to_device_kb())
        return
