@router.message(OwnerFilter(), Form.wait_saved_device_filter_create)
async def on_device_saved_filter_create_input(message: Message, state: FSMContext):
    user_id = int(message.from_user.id)
    parts = (message.text or "").split("|", maxsplit=2)
    if len(parts) != 3:
        await _replace_user_card(message, "Нужны три части: имя | тип | условие. Например: Мои Mac | os | macOS.")
        return
    name, filter_type, query = (" ".join(part.split()) for part in parts)
    filter_type = filter_type.casefold()
    if not name or len(name) > 80 or not _valid_saved_filter_rule(filter_type, query):
        await _replace_user_card(message, "Фильтр не сохранён. Проверь имя, тип и пример условия в подсказке и отправь строку заново.")
        return
    try:
        saved = devices.create_saved_device_filter(user_id, ADMIN_ID, name, filter_type, query)
    except ValueError as exc:
        await _replace_user_card(message, f"Фильтр не сохранён: {html.escape(str(exc))}. Исправь строку и отправь заново.")
        return
    await state.clear()
    if saved is None:
        await _replace_user_card(message, "Сохранение доступно только владельцу.", reply_markup=devices_menu(user_id))
        return
    audit("device_filter_saved", actor_id=user_id, filter_id=saved["filter_id"], filter_type=filter_type)
    rows, markup = device_saved_filter_catalog(user_id)
    await _replace_user_card(message, f"Фильтр <b>{html.escape(saved['name'])}</b> сохранён. Он будет применяться к текущей выборке при каждом запуске.", reply_markup=markup)


