def confirm_power_menu(action: str):
    """Подтверждение опасного действия."""
    labels = {
        "shutdown": "ВЫКЛЮЧИТЬ",
        "reboot": "ПЕРЕЗАГРУЗИТЬ",
        "sleep": "ОТПРАВИТЬ В СОН",
    }
    kb = InlineKeyboardBuilder()
    user_id = int(CURRENT_TG_USER.get())
    role = get_user_role(user_id)
    grants = set(access_store.get_effective_grants(user_id)["callbacks"])
    target = str(SESSION.get("target") or "")
    info = devices.get(target) or {}
    os_name = str(info.get("os") or "").lower()
    platform = "macos" if "mac" in os_name or "darwin" in os_name else "windows" if "win" in os_name else None
    for page in feature_catalog.visible_navigation_pages(
        feature_catalog.load_registry(), parent="power.confirm",
        role=str(role.value if hasattr(role, "value") else role), grants=grants,
        platform=platform,
    ):
        callback = str(page["callback"])
        label_id = str(page["label_id"])
        presentation = page["presentation"]
        if presentation == "power_confirmation":
            expected_callback = f"power_confirm:{action}"
            if action not in labels or callback != expected_callback or label_id != "power_confirm_button":
                continue
            text = _lex(label_id, action=labels[action])
        elif presentation == "nav" and callback == "back:device" and label_id == "cancel":
            text = _nav(label_id)
        elif presentation == "nav" and callback == "menu:main" and label_id == "home":
            text = _nav(label_id)
        else:
            raise ValueError("feature registry has an unregistered power confirmation renderer")
        kb.button(text=text, callback_data=callback, style=str(page["style"]))
    kb.adjust(1, 2)
    return _filter_device_keyboard(kb.as_markup(), user_id)


def rotate_menu():
    user_id = int(CURRENT_TG_USER.get())
    target = str(SESSION.get("target") or "")
    info = devices.get(target) or {}
    os_name = str(info.get("os") or "").lower()
    platform = "macos" if "mac" in os_name or "darwin" in os_name else "windows" if "win" in os_name else None
    kb = InlineKeyboardBuilder()
    labels_by_angle = {
        "rotate:0": "rotate_standard_button",
        "rotate:90": "rotate_right_button",
        "rotate:180": "rotate_inverted_button",
        "rotate:270": "rotate_left_button",
    }
    for page in feature_catalog.visible_navigation_pages(
        feature_catalog.load_registry(), parent="rotate.options", role=get_user_role(user_id),
        grants=set(access_store.get_effective_grants(user_id)["callbacks"]), platform=platform,
    ):
        callback = str(page["callback"])
        presentation = page["presentation"]
        if presentation == "rotate_angle":
            label_id = labels_by_angle.get(callback)
            if label_id is None or page["label_id"] != label_id:
                raise ValueError("feature registry has an invalid display-rotation option")
            text = _lex(label_id)
        elif presentation == "screen_action" and callback == "cat:screen" and page["label_id"] == "rotate_screen_button":
            text = _lex(str(page["label_id"]))
        elif presentation == "nav" and callback == "menu:main" and page["label_id"] == "home":
            text = _nav(str(page["label_id"]))
        else:
            raise ValueError("feature registry has an unregistered display-rotation renderer")
        _action_button(
            kb, text=text, callback=callback, style=str(page["style"]), user_id=user_id,
        )
    kb.adjust(2, 2, 2)
    return _filter_device_keyboard(kb.as_markup(), user_id)


def media_menu(user_id: int | None = None):
    # Backward-compatible entry point; display and media share one screen.
    return screen_menu(user_id=user_id)


def screen_menu(target: str | None = None, user_id: int | None = None):
    target = target or SESSION.get("target") or ""
    is_nl = bool(SESSION.get(f"nightlight_{target}", False))
    kb = InlineKeyboardBuilder()
    user_id = int(user_id if user_id is not None else CURRENT_TG_USER.get())
    info = devices.get(target) or {}
    os_name = str(info.get("os") or "").lower()
    platform = "macos" if "mac" in os_name or "darwin" in os_name else "windows" if "win" in os_name else None
    navigation = feature_catalog.visible_navigation_pages(
        feature_catalog.load_registry(), parent="screen", role=get_user_role(user_id),
        grants=set(access_store.get_effective_grants(user_id)["callbacks"]), platform=platform,
    )
    for page in navigation:
        callback = str(page["callback"])
        label_id = str(page["label_id"])
        style = str(page["style"])
        if callback == "cmd:geo_location":
            text = _limit_button_label("⚠️ " + _lex(label_id))
        elif callback == "camera:catalog":
            text = _lex(label_id)
