def wallpaper_menu(user_id: int | None = None):
    user_id = int(user_id if user_id is not None else CURRENT_TG_USER.get())
    target = str(SESSION.get("target") or "")
    info = devices.get(target) or {}
    os_name = str(info.get("os") or "").lower()
    platform = "macos" if "mac" in os_name or "darwin" in os_name else "windows" if "win" in os_name else None
    kb = InlineKeyboardBuilder()
    for page in feature_catalog.visible_navigation_pages(
        feature_catalog.load_registry(), parent="wallpaper.options", role=get_user_role(user_id),
        grants=set(access_store.get_effective_grants(user_id)["callbacks"]), platform=platform,
    ):
        callback = str(page["callback"])
        label_id = str(page["label_id"])
        presentation = page["presentation"]
        if presentation == "screen_action":
            text = _lex(label_id)
        elif presentation == "nav" and callback == "menu:main" and label_id == "home":
            text = _nav(label_id)
        else:
            raise ValueError("feature registry has an unregistered wallpaper renderer")
        _action_button(
            kb, text=text, callback=callback, style=str(page["style"]), user_id=user_id,
        )
    kb.adjust(2)
    return _filter_device_keyboard(kb.as_markup(), user_id)


