def cpu_history_period_keyboard(user_id: int | None = None):
    user_id = int(user_id if user_id is not None else CURRENT_TG_USER.get())
    target = str(SESSION.get("target") or "")
    os_name = str((devices.get(target) or {}).get("os") or "").lower()
    platform = "macos" if "mac" in os_name or "darwin" in os_name else "windows" if "win" in os_name else None
    role = get_user_role(user_id)
    role_id = str(role.value if hasattr(role, "value") else role)
    grants = set(access_store.get_effective_grants(user_id)["callbacks"])
    navigation = feature_catalog.visible_navigation_pages(
        feature_catalog.load_registry(), parent="system.cpu_history", role=role_id,
        grants=grants, platform=platform,
    )
    kb = InlineKeyboardBuilder()
    for page in navigation:
        callback = str(page["callback"])
        if page["presentation"] == "cpu_history_period":
            match = re.fullmatch(r"cpu:history:(15|30|60)", callback)
            if match is None:
                continue
            text = feature_catalog.button_text(f"cpu_history_{match.group(1)}s")
        elif callback == "cat:system":
            text = _nav("back_device")
        elif callback == "menu:main":
            text = _nav("home")
        else:
            raise ValueError("unregistered CPU history navigation renderer")
        kb.button(text=_limit_button_label(text), callback_data=callback, style=str(page["style"]))
    kb.adjust(1)
    return _filter_device_keyboard(kb.as_markup(), user_id)


