def _file_inbox_keyboard(
    parent: str, user_id: int, *, items: list[dict] | None = None, item_id: str | None = None,
    can_place: bool = True,
):
    item_id = str(item_id or "")
    if item_id and not re.fullmatch(r"[0-9a-f]{32}", item_id):
        return InlineKeyboardMarkup(inline_keyboard=[])
    role = get_user_role(int(user_id))
    role_id = str(role.value if hasattr(role, "value") else role)
    pages = feature_catalog.visible_navigation_pages(
        feature_catalog.load_registry(), parent=parent, role=role_id,
        grants=set(access_store.get_effective_grants(int(user_id))["callbacks"]), platform="telegram",
    )
    labels = {
        "files.inbox.upload": _ui_phrase("📤 Stage a file", "📤 Guardar archivo", "📤 Положить файл"),
        "files.inbox.back": _nav("back_device"),
        "files.inbox.home": _nav("home"),
        "files.inbox.detail.place": _ui_phrase("📥 Place on selected device", "📥 Colocar en dispositivo", "📥 Разместить на устройстве"),
        "files.inbox.detail.delete": _ui_phrase("🗑 Delete staged file", "🗑 Eliminar archivo", "🗑 Удалить из входящих"),
        "files.inbox.detail.back": _ui_phrase("Back to inbox", "Volver a bandeja", "К входящим"),
        "files.inbox.detail.home": _nav("home"),
        "files.inbox.place.confirm": _ui_phrase("Confirm placement", "Confirmar", "Подтвердить размещение"),
        "files.inbox.place.cancel": _ui_phrase("Cancel · keep staged", "Cancelar · conservar", "Отмена · оставить файл"),
        "files.inbox.place.home": _nav("home"),
        "files.inbox.delete.confirm": _ui_phrase("Confirm deletion", "Confirmar borrado", "Подтвердить удаление"),
        "files.inbox.delete.cancel": _ui_phrase("Cancel · keep file", "Cancelar · conservar", "Отмена · оставить файл"),
        "files.inbox.delete.home": _nav("home"),
    }
    expected = {
        "files.inbox.upload": ("files:inbox:upload", "file_inbox_action"),
        "files.inbox.row": ("files:inbox:view:*", "file_inbox_row"),
        "files.inbox.back": ("cat:files", "nav"),
        "files.inbox.home": ("menu:main", "nav"),
        "files.inbox.detail.place": ("files:inbox:place:*", "file_inbox_action"),
        "files.inbox.detail.delete": ("files:inbox:delete:*", "file_inbox_action"),
        "files.inbox.detail.back": ("files:inbox", "nav"),
        "files.inbox.detail.home": ("menu:main", "nav"),
        "files.inbox.place.confirm": ("files:inbox:place:confirm:*", "file_inbox_action"),
        "files.inbox.place.cancel": ("files:inbox:view:*", "nav"),
        "files.inbox.place.home": ("menu:main", "nav"),
        "files.inbox.delete.confirm": ("files:inbox:delete:confirm:*", "file_inbox_action"),
        "files.inbox.delete.cancel": ("files:inbox:view:*", "nav"),
        "files.inbox.delete.home": ("menu:main", "nav"),
    }
    kb = InlineKeyboardBuilder()
    for page in pages:
        page_id = str(page["page_id"])
        if page_id not in expected:
            raise ValueError("feature registry has an unregistered file-inbox renderer")
        template, presentation = expected[page_id]
        if str(page["presentation"]) != presentation or str(page["callback"]) != template:
            raise ValueError("feature registry file-inbox action does not match its renderer")
        if page_id == "files.inbox.row":
            for item in items or []:
                row_id = str(item.get("item_id") or "")
                if not re.fullmatch(r"[0-9a-f]{32}", row_id):
                    continue
                size = int(item.get("size") or 0)
                name = str(item.get("name") or "upload.bin")
                text = _limit_button_label(_ui_phrase(
                    f"📄 {name} · {size} B", f"📄 {name} · {size} B", f"📄 {name} · {size} Б",
                ))
                callback = template.replace("*", row_id)
        else:
            if page_id == "files.inbox.detail.place" and not can_place:
                continue
            if page_id not in labels:
                raise ValueError("feature registry file-inbox label is not registered")
            text = labels[page_id]
            callback = template.replace("*", item_id) if "*" in template else template
        _action_button(kb, text=text, callback=callback, style=str(page["style"]), user_id=int(user_id))
    kb.adjust(1)
    return _filter_device_keyboard(kb.as_markup(), int(user_id))


def _file_inbox_list_text(items: list[dict]) -> str:
    if not items:
        return (
            "<b>📥 Входящие файлы</b>\n\nОчередь пуста. Загрузка только сохраняет файл в карантинную staging-область;"
            " ничего не открывается и не запускается."
        )
    lines = ["<b>📥 Входящие файлы</b>", "", "Выбери файл для просмотра метаданных, размещения или удаления:"]
    for item in items[:100]:
        lines.append(f"• {html.escape(str(item.get('name') or 'upload.bin'))} · {int(item.get('size') or 0)} байт")
    return "\n".join(lines)


def _file_inbox_item_text(item: dict) -> str:
    created = datetime.datetime.fromtimestamp(int(item["created_at"]), tz=datetime.timezone.utc)
    expires = datetime.datetime.fromtimestamp(int(item["expires_at"]), tz=datetime.timezone.utc)
    return (
        f"<b>{html.escape(str(item.get('name') or 'upload.bin'))}</b>\n"
        f"Размер: {int(item.get('size') or 0)} байт\n"
        f"Тип: <code>{html.escape(str(item.get('mime_type') or 'application/octet-stream'))}</code>\n"
        f"SHA-256: <code>{html.escape(str(item.get('sha256') or ''))}</code>\n"
        f"Принят: <code>{created.isoformat()}</code>\nИстекает: <code>{expires.isoformat()}</code>\n\n"
        "Файл хранится как непрозрачные байты. Для переноса на устройство нужно отдельно выбрать цель, путь и подтвердить действие."
    )


