def admin_permission_requests_keyboard(actor_id: int, page: int = 0):
    if type(actor_id) is not int or actor_id != int(ADMIN_ID) or type(page) is not int or page < 0:
        return InlineKeyboardBuilder().as_markup()
    rows = access_store.list_permission_requests(actor_id, int(ADMIN_ID), limit=500)
    pages = max(1, (len(rows) + 19) // 20)
    if page >= pages:
        return InlineKeyboardBuilder().as_markup()
    routes = feature_catalog.visible_navigation_pages(
        feature_catalog.load_registry(), parent="admin.permission_requests", role=Role.OWNER,
        grants=set(), platform="telegram",
    )
    expected = {
        ("admin.permission_requests.row", "admin:access-request:view:*", "access_request_row", "permission_request_row"),
        ("admin.permission_requests.refresh", "admin:access-requests", "access_requests_refresh", "permission_requests"),
        ("admin.permission_requests.page", "admin:access-requests:page:*", "access_requests_page", "permission_requests"),
        ("admin.permission_requests.back", "menu:admin", "back", "nav"),
    }
    actual = {
        (str(row.get("page_id")), str(row.get("callback")), str(row.get("label_id")), str(row.get("presentation")))
        for row in routes
    }
    if actual != expected:
        raise ValueError("feature registry is missing an access-request queue route")
    by_id = {str(row["page_id"]): row for row in routes}
    kb = InlineKeyboardBuilder()
    row_route = by_id["admin.permission_requests.row"]
    for request in rows[page * 20:(page + 1) * 20]:
        kind_label = "кнопка" if request["grant_kind"] == "callback" else "устройство"
        label = f"{kind_label} · {request['actor_id']} · {request['item']}"
        kb.button(
            text=_limit_button_label(label, 62),
            callback_data=str(row_route["callback"]).replace("*", request["request_id"]),
            style=str(row_route["style"]),
        )
    refresh = by_id["admin.permission_requests.refresh"]
    page_route = by_id["admin.permission_requests.page"]
    back = by_id["admin.permission_requests.back"]
    kb.button(
        text=feature_catalog.button_text("access_requests_refresh"),
        callback_data=str(refresh["callback"]), style=str(refresh["style"]),
    )
    if page > 0:
        kb.button(text=feature_catalog.button_text("access_requests_previous"), callback_data=str(page_route["callback"]).replace("*", str(page - 1)), style=str(page_route["style"]))
    if page + 1 < pages:
        kb.button(text=feature_catalog.button_text("access_requests_next"), callback_data=str(page_route["callback"]).replace("*", str(page + 1)), style=str(page_route["style"]))
    kb.button(text=_nav("back"), callback_data=str(back["callback"]), style=str(back["style"]))
    kb.adjust(1)
    return kb.as_markup()


