def _render_stale_device_grants(report: dict) -> str:
    rows = report.get("rows") if isinstance(report, dict) else None
    if not isinstance(rows, list):
        return "<b>Права на отсутствующие устройства</b>\n\nОтчёт недоступен: каталог или данные прав не прошли проверку. Ничего не изменено."
    lines = [
        "<b>Права на отсутствующие устройства</b>", "",
        "Только действующие права, для которых нет точной записи в каталоге устройств.",
    ]
    if not rows:
        lines.extend(["", "✅ Таких прав не найдено."])
    else:
        for row in rows[:30]:
            if not isinstance(row, dict):
                continue
            user_id = html.escape(str(row.get("target_id", "?")), quote=False)
            device_id = html.escape(str(row.get("device_id", "?")), quote=False)
            state = " · заблокирован" if row.get("blocked") else ""
            expiry_text = ""
            expiry = row.get("expires_at")
            if type(expiry) is int and expiry >= 0:
                try:
                    expiry_text = " · до " + datetime.datetime.fromtimestamp(
                        expiry, datetime.timezone.utc,
                    ).strftime("%Y-%m-%d %H:%M UTC")
                except (OverflowError, OSError, ValueError):
                    expiry_text = " · срок неизвестен"
            lines.append(f"• Пользователь <code>{user_id}</code> · устройство <code>{device_id}</code>{state}{expiry_text}")
    if report.get("truncated"):
        lines.append("\nПоказана только часть результатов; обновите отчёт после проверки каталога.")
    lines.append("\nЭто только проверка: ничего не отозвано, права и записи не изменены.")
    output = "\n".join(lines)
    return output[:3850] + ("…" if len(output) > 3850 else "")


