def _notification_recipients() -> list[int]:
    """Владелец и добавленные администраторы получают watchdog-уведомления."""
    ids = [int(ADMIN_ID)]
    for value in bot_settings.get("admins", []) or []:
        try:
            uid = int(value)
        except (TypeError, ValueError):
            continue
        if uid not in ids:
            ids.append(uid)
    return ids


async def _notify_admins(text: str, reply_markup=None) -> bool:
    """Deliver notifications and report whether the protected owner received it."""
    owner_delivered = False
    for user_id in _notification_recipients():
        try:
            await bot.send_message(user_id, text, reply_markup=reply_markup)
            if user_id == int(ADMIN_ID):
                owner_delivered = True
        except Exception:
            log.exception("Не удалось отправить уведомление администратору %s", user_id)
    return owner_delivered


def _schedule_admin_notice(text: str, reply_markup=None) -> None:
    """Безопасно отправить уведомление из MQTT-потока в asyncio-цикл."""
    if LOOP is None or LOOP.is_closed():
        log.warning("Уведомление не отправлено: asyncio loop ещё не запущен")
        return
    future = asyncio.run_coroutine_threadsafe(_notify_admins(text, reply_markup), LOOP)
    future.add_done_callback(
        lambda done: done.exception() if not done.cancelled() else None
    )


def _schedule_traffic_owner_notice(text: str, reply_markup=None) -> None:
    """Traffic threshold details go only to the configured owner."""
    if LOOP is None or LOOP.is_closed():
        log.warning("D04-F19 notice not sent: asyncio loop is unavailable")
        return

    async def _send():
        await bot.send_message(int(ADMIN_ID), text, reply_markup=reply_markup)

    future = asyncio.run_coroutine_threadsafe(_send(), LOOP)
    future.add_done_callback(lambda done: done.exception() if not done.cancelled() else None)


async def _notify_owner(text: str, reply_markup=None, *, strict_delivery: bool = False) -> bool:
    try:
        owner = int(ADMIN_ID)
        if strict_delivery:
            # Approval previews are owner security alerts. A separate message
            # provides a real delivery result, rather than a stale-card fallback.
            await bot.send_message(owner, text, reply_markup=reply_markup)
            return True
        async def answer(value, **kwargs):
            return await bot.send_message(owner, value, **kwargs)
        await _replace_user_card(
            SimpleNamespace(chat=SimpleNamespace(id=owner), from_user=SimpleNamespace(id=owner), answer=answer),
            text, reply_markup=reply_markup if reply_markup is not None else main_menu(owner),
        )
        return True
    except Exception:
        log.exception("Не удалось отправить владельцу результат операции жизненного цикла")
        return False


def _schedule_owner_notice(text: str, reply_markup=None) -> bool:
    if LOOP is None or LOOP.is_closed():
        return False
    future = asyncio.run_coroutine_threadsafe(_notify_owner(text, reply_markup), LOOP)
    future.add_done_callback(
        lambda done: done.exception() if not done.cancelled() else None
    )
    return True


def _schedule_lifecycle_failure_notice(device_id: str, payload: dict) -> None:
    """Deferred failures must remain visible after a command waiter closes."""
    kind, state = payload.get("type"), payload.get("state")
    if not isinstance(kind, str) or not isinstance(state, str):
        return
    failures = {
        ("agent_update", "restart_failed"): False,
        ("agent_update", "guardian_restart_failed"): True,
        ("uninstall_agent", "uninstall_incomplete"): False,
    }
    expected_ok = failures.get((kind, state))
    if (kind, state) not in failures or payload.get("ok") is not expected_ok:
        return
    if bot_settings.is_blocked(device_id):
        return
    command_id = str(payload.get("id") or "")[:128]
    key = (device_id, command_id, state)
    now = time.monotonic()
    with _LIFECYCLE_NOTICE_LOCK:
        for old_key, seen in list(_LIFECYCLE_NOTICE_LAST.items()):
            if now - seen >= 600:
                _LIFECYCLE_NOTICE_LAST.pop(old_key, None)
        if key in _LIFECYCLE_NOTICE_LAST:
            return
        text = _lex_html(
            "lifecycle_failure_notice", device=target_label(device_id),
            state=state, text=str(payload.get("text") or state)[:2000],
        )
        if not _schedule_owner_notice(text):
            return
        if len(_LIFECYCLE_NOTICE_LAST) >= 128:
            oldest = min(_LIFECYCLE_NOTICE_LAST, key=_LIFECYCLE_NOTICE_LAST.get)
            _LIFECYCLE_NOTICE_LAST.pop(oldest, None)
        _LIFECYCLE_NOTICE_LAST[key] = now
    audit("agent_lifecycle_failure", device_id=device_id, command_id=command_id, state=state)

def _queue_device_status_notice(
    device_id: str,
    online: bool,
    name: str,
    *,
    delay: float | None = None,
    offline_reason: str | None = None,
) -> None:
    """Send one notice only after the device has held the new state steadily."""
    loop = LOOP
    if loop is None or loop.is_closed():
        log.warning("Статусное уведомление не поставлено в очередь: asyncio loop недоступен")
        return

    async def _send_if_stable() -> None:
        await asyncio.sleep(_STATUS_NOTICE_DELAY_SEC if delay is None else max(0.0, delay))
        current = devices.get(device_id) or {}
        if bool(current.get("online", False)) != online:
            return
        with _STATUS_NOTICE_LOCK:
            previous = _STATUS_NOTICE_STATE.get(device_id)
            if previous is None or previous == online:
                return
            _STATUS_NOTICE_STATE[device_id] = online

        quiet = bot_settings.quiet_active()
        enabled = bot_settings.get("notify_online" if online else "notify_offline", True)
        if not enabled or quiet:
            return
        event = "вернулся онлайн" if online else (offline_reason or "ушёл в оффлайн")
        icon = "🟢" if online else "🔴"
        _schedule_admin_notice(f"{icon} <b>{html.escape(name)}</b> {event}")

    future = asyncio.run_coroutine_threadsafe(_send_if_stable(), loop)
    with _STATUS_NOTICE_LOCK:
        previous_future = _STATUS_NOTICE_PENDING.get(device_id)
        _STATUS_NOTICE_PENDING[device_id] = future
    if previous_future is not None:
        previous_future.cancel()


def _maybe_battery_alert(device_id: str, payload: dict) -> None:
    """Watchdog по батарее: алерт при заряде <=20% не чаще раза в 30 минут."""
    batt = payload.get("battery") if isinstance(payload.get("battery"), dict) else payload
    if not batt.get("available"):
        return
    try:
        percent = float(batt.get("percent", 100))
    except (TypeError, ValueError):
        return
    if not math.isfinite(percent) or not 0 <= percent <= 100 or percent > 20:
        return
    now = time.time()
    if now - LAST_BATTERY_ALERT.get(device_id, 0) < 1800:
        return
    LAST_BATTERY_ALERT[device_id] = now
    if not bot_settings.get("notify_battery_low", True):
        return
    if bot_settings.quiet_active():
        return
    name = target_label(device_id)
    if LOOP is None:
        return
    _schedule_owner_notice(
        f"🔋 <b>{html.escape(name)}</b>: низкий заряд батареи — {percent:.0f}%",
    )


def _notify_confirmed_resource_thresholds(device_id: str, alerts: list[dict]) -> None:
    if not alerts or bot_settings.is_blocked(device_id):
        return
    labels = {
        "cpu_percent": "CPU",
        "ram_percent": "RAM",
        "disk_percent": "Диск",
        "temperature_celsius": "Температура",
    }
    lines = []
    metrics = []
    for alert in alerts[:4]:
        metric = alert.get("metric")
        threshold, observed = alert.get("threshold"), alert.get("observed")
        if metric not in labels or not all(
            isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)
            for value in (threshold, observed)
        ):
            continue
        unit = "°C" if metric == "temperature_celsius" else "%"
        lines.append(f"• {labels[metric]}: {observed:g}{unit} (порог {threshold:g}{unit})")
        metrics.append(metric)
    if not lines:
        return
    name = html.escape(target_label(device_id))
    audit("system_resource_threshold_alert", device_id=device_id, metrics=sorted(set(metrics)))
    _schedule_owner_notice(
        f"📊 <b>{name}</b> — два последовательных замера выше заданного порога:\n" + "\n".join(lines)
    )


def on_mqtt_message(topic: str, data: dict) -> None:
    """Вызывается из потока MQTT при получении сообщения от клиента."""
    server_ops.observe("broker", "message_received")
    parts = topic.split("/")
    prefix_len = len(MQTT_PREFIX.split("/"))
    if len(parts) != prefix_len + 2 or parts[:prefix_len] != MQTT_PREFIX.split("/"):
        return
    device_id = parts[prefix_len]
    msg_type = parts[-1]
    try:
        message_key = key_for_device(device_id)
    except (OSError, ValueError):
        log.warning("Ключ устройства %s недоступен; сообщение отклонено", device_id)
        return
    payload, verification_reason = verify_message_detailed(data, key=message_key)
    if payload is None:
        timestamp_delta = (
            timestamp_delta_seconds(data)
            if verification_reason == "stale_timestamp" else None
        )
        if timestamp_delta is not None:
            log.warning(
                "MQTT-сообщение отклонено (%s, timestamp_delta_s=%d) в топике %s",
                verification_reason,
                timestamp_delta,
                topic,
            )
            return
        log.warning(
            "MQTT-сообщение отклонено (%s) в топике %s",
            verification_reason,
            topic,
        )
        return
    signed_payload = data.get("payload") if isinstance(data, dict) else None
    signed_timestamp = signed_payload.get("ts") if isinstance(signed_payload, dict) else None
    observed_at = (
        float(signed_timestamp)
        if type(signed_timestamp) in (int, float) and math.isfinite(float(signed_timestamp))
        else time.time()
    )
    # LWT exposes only its signed offline/session envelope. Everything else
    # still requires the encrypted body whenever encryption is configured.
    clear_lwt = (
        msg_type == "status"
        and payload.get("type") == "status"
        and str(payload.get("status", "")).lower() == "offline"
        and isinstance(payload.get("mqtt_session_id"), str)
        and re.fullmatch(r"[0-9a-f]{32}", payload["mqtt_session_id"]) is not None
    )
    if ENCRYPT_PAYLOAD and "enc" not in payload and not clear_lwt:
        log.warning("Незашифрованный MQTT-payload отклонён в топике %s", topic)
        return
    if "enc" in payload:
        inner = decrypt_payload(payload, key=message_key)
        if inner is None:
            log.warning("Не удалось расшифровать payload из %s", topic)
            return
        payload = inner
    # A broker identity is bound to one device topic. Never let a signed
    # response on that topic claim a different device in its payload.
    if payload.get("device_id", device_id) != device_id:
        return
    if msg_type == "update_progress" and payload.get("type") == "agent_update_progress":
        if bot_settings.is_blocked(device_id):
            return
        info = devices.get(device_id) or {}
        component = release_catalog.component_for(str(info.get("os") or ""))
        if payload.get("component", component) != component:
            return
        try:
            update_coordinator.handle_event(device_id, {**payload, "component": component}, received_at=time.time())
        except (OSError, ValueError):
            log.warning("Update journal unavailable; progress remains unconfirmed")
        return

    # Блок-лист: устройства в нём не принимаем и не показываем.
    if msg_type == "status" and bot_settings.is_blocked(device_id):
        log.info("Статус от заблокированного устройства %s — игнорируем", device_id)
        return

    if msg_type == "status" and payload.get("type") == "status":
        raw_status = str(payload.get("status", "online")).lower()
        online = raw_status != "offline"
        is_standby = (raw_status == "standby")
        old = devices.get(device_id) or {}
        session_id = payload.get("mqtt_session_id")
        if not online and (
            not isinstance(session_id, str)
            or re.fullmatch(r"[0-9a-f]{32}", session_id) is None
            or session_id != old.get("mqtt_session_id")
        ):
            log.info("Устаревший MQTT Last Will от %s отклонён: сессия уже сменилась", device_id)
            return
        # Для LWT нельзя вычислять прошлое состояние через _status_dot():
        # старый online-агент может быть уже старше 120 секунд, но событие
        # «ушёл офлайн» всё равно должно прийти владельцу.
        was_online = bool(old.get("online", False))
        mqtt_session_id = payload.get("mqtt_session_id")
        valid_mqtt_session = (
            isinstance(mqtt_session_id, str)
            and re.fullmatch(r"[0-9a-f]{32}", mqtt_session_id) is not None
        )
        active_mqtt_session = old.get("mqtt_session_id")
        if not online and (
            not valid_mqtt_session
            or not isinstance(active_mqtt_session, str)
            or mqtt_session_id != active_mqtt_session
        ):
            # A delayed QoS 1 Last Will from a prior MQTT connection must not
            # mark the newly reconnected device offline.
            log.info("Rejected stale MQTT offline status for %s (session mismatch)", device_id)
            audit("stale_device_lwt_rejected", device_id=device_id)
            return
        info = {
            "name": str(payload.get("name") or device_id),
            "os": str(payload.get("os") or "unknown"),
            "version": str(payload.get("version") or "?"),
            "online": online,
            "mqtt_session_id": mqtt_session_id if valid_mqtt_session else None,
            "standby": is_standby,
            "command_approval_protocol": payload.get("command_approval_protocol") if type(payload.get("command_approval_protocol")) is int else 0,
        }
        if online:
            info["mqtt_session_id"] = (
                session_id
                if isinstance(session_id, str) and re.fullmatch(r"[0-9a-f]{32}", session_id)
                else None
            )
        if "companions" in payload:
            info["companion_records"] = companion_status.clean_layer_records(
                payload.get("companions"), now=time.time(),
            )
        update_mode = payload.get("update_mode")
        info["update_mode"] = (
            update_mode
            if isinstance(update_mode, str) and update_mode in {"source", "frozen"}
            else "unknown"
        )
        info["release_update_ready"] = (
            info["update_mode"] == "source"
            and payload.get("release_update_ready") is True
        )
        info["update_manifest_binding_protocol"] = payload.get("update_manifest_binding_protocol") if type(payload.get("update_manifest_binding_protocol")) is int else 0
        if not online:
            # A minimal Will must not overwrite the known device label,
            # platform, version, or last fresh heartbeat. Clearing the active
            # session also makes this old Will single-use at the device state layer.
            info = {**old, "online": False, "standby": False, "mqtt_session_id": None}
        if online:
            info["last_seen"] = observed_at
        is_new = device_id not in devices.all()
        if is_new:
            info["approved"] = not bool(bot_settings.get("require_device_approval", True))
        devices.upsert(
            device_id, info,
            registration_event="heartbeat" if is_new else "re_registration" if online and not was_online else "heartbeat",
        )
        receipt = payload.get("agent_update")
        if not online:
            try:
                update_coordinator.heartbeat_lost(device_id, now=time.time())
            except (OSError, ValueError):
                log.warning("Update journal unavailable; offline update remains unconfirmed")
        if online and isinstance(receipt, dict):
            component = release_catalog.component_for(info["os"])
            if receipt.get("component", component) == component:
                try:
                    update_coordinator.reconcile(
                        device_id, {**receipt, "component": component},
                        received_at=time.time(), heartbeat_at=info["last_seen"],
                    )
                except (OSError, ValueError):
                    log.warning("Update journal unavailable; health remains unconfirmed")
        status_collector.submit(device_id, info)
        multi_status.submit(device_id, info)
        audit("device_online" if online else "device_offline",
              device_id=device_id, name=info["name"], is_new=is_new)
        with _STATUS_NOTICE_LOCK:
            _STATUS_NOTICE_STATE.setdefault(device_id, online if is_new else was_online)
            if is_new:
                _STATUS_NOTICE_STATE[device_id] = online
        if not is_new and online != was_online:
            _queue_device_status_notice(device_id, online, info["name"])
        if is_new and LOOP is not None and not info.get("approved", True):
            kb = InlineKeyboardBuilder()
            kb.button(text=_lex("device_approve_button"), callback_data=f"devmg:allow:{device_id}", style="success")
            kb.button(text=_lex("device_block_button"), callback_data=f"devmg:block:{device_id}", style="danger")
            kb.adjust(1)
            _schedule_owner_notice(
                f"🆕 Новое устройство: <b>{html.escape(info['name'])}</b> "
                f"(<code>{device_id}</code>)\nПодтверди, чтобы работать с ним:",
                reply_markup=kb.as_markup(),
            )

    elif msg_type == "screenshot" and payload.get("type") == "screenshot":
        allowed_states = {
            "success", "permission_denied", "session_unavailable", "tool_missing",
            "command_failed", "file_empty", "file_oversized", "file_unreadable",
            "timeout", "transport_failed",
        }
        raw_state = payload.get("state")
        state = raw_state if isinstance(raw_state, str) and raw_state in allowed_states else "unknown"
        raw_platform = payload.get("platform")
        platform = (
            raw_platform
            if isinstance(raw_platform, str) and raw_platform in {"macOS", "Windows"}
            else "unknown"
        )
        encoded_image = payload.get("image")
        image_b64_chars = len(encoded_image) if isinstance(encoded_image, str) else 0
        raw_command_id = payload.get("id")
        command_id = (
            raw_command_id
            if isinstance(raw_command_id, str) and re.fullmatch(r"[A-Za-z0-9_-]{1,64}", raw_command_id)
            else "unknown"
        )
        log.info(
            "Screenshot response received: device_id=%s id=%s state=%s platform=%s "
            "image_present=%s image_b64_chars=%d",
            device_id,
            command_id,
            state,
            platform,
            bool(image_b64_chars),
            image_b64_chars,
        )
        screenshot_collector.submit(device_id, payload)
        multi_screenshot.submit(device_id, payload)

    elif msg_type == "display_catalog" and payload.get("type") == "display_catalog":
        display_catalog_collector.submit(device_id, payload)
