@router.callback_query(OwnerFilter(), F.data == "admin:policy-compare")
async def on_admin_policy_compare(cq: CallbackQuery):
    if not await _admin_owner(cq):
        return
    snapshots = access_store.list_rbac_policy_snapshots(ADMIN_ID, ADMIN_ID, limit=2)
    markup = InlineKeyboardBuilder()
    if snapshots is None or len(snapshots) < 2:
        markup.button(text=_limit_button_label("Создать снимок RBAC", 62),
                      callback_data="admin:policy-snapshot", style="primary")
        markup.button(text=_nav("back_users"), callback_data="admin:users", style="primary")
        markup.adjust(1)
        await _replace_callback_message(
            cq, "Для сравнения нужны два сохранённых снимка RBAC. Сначала создайте второй снимок — он ничего не меняет в правах.",
            reply_markup=markup.as_markup(),
        )
        await cq.answer()
        return
    older, newer = snapshots[1], snapshots[0]
    diff = access_store.compare_rbac_policy_snapshots(
        ADMIN_ID, ADMIN_ID, older["snapshot_id"], newer["snapshot_id"],
    )
    if diff is None:
        await cq.answer("Не удалось проверить оба снимка. Повреждённые или чужие записи не сравниваются.", show_alert=True)
        return

    def stamp(value: int) -> str:
        return datetime.datetime.fromtimestamp(int(value)).strftime("%d.%m.%Y %H:%M:%S")

    lines = [
        "<b>Сравнение снимков RBAC</b>",
        f"Старый: <code>{stamp(diff['from_created_at'])}</code> · <code>{diff['from_snapshot_id']}</code>",
        f"Новый: <code>{stamp(diff['to_created_at'])}</code> · <code>{diff['to_snapshot_id']}</code>",
        f"Изменившихся пользователей: <code>{len(diff['changes'])}</code>",
    ]
    for change in diff["changes"][:20]:
        details = []
        role = change.get("role")
        if role:
            details.append(f"роль {role['before']} → {role['after']}")
        blocked = change.get("blocked")
        if blocked:
            details.append(f"блокировка {blocked['before']} → {blocked['after']}")
        paused = change.get("permissions_paused")
        if paused:
            details.append(f"пауза прав {paused['before']} → {paused['after']}")
        for field, label in (("stored_callbacks", "кнопки"), ("stored_devices", "устройства"),
                             ("effective_callbacks", "активные кнопки"), ("effective_devices", "активные устройства")):
            delta = change.get(field)
            if delta:
                added = ", ".join(delta.get("added", [])) or "—"
                removed = ", ".join(delta.get("removed", [])) or "—"
                details.append(f"{label}: +{added}; −{removed}")
        expiry = change.get("expirations")
        if expiry:
            details.append(f"сроки grants: +{len(expiry['added'])}, −{len(expiry['removed'])}, изменено {len(expiry['changed'])}")
        summary = html.escape("; ".join(details) or "изменение записи")
        lines.append(f"\n• <code>{int(change['user_id'])}</code>: {summary}")
    if len(diff["changes"]) > 20:
        lines.append(f"\n… и ещё {len(diff['changes']) - 20}; полный отчёт ограничен 20 строками Telegram.")
    if not diff["changes"]:
        lines.append("\nИзменений между снимками нет.")
    markup.button(text=_nav("back_users"), callback_data="admin:users", style="primary")
    markup.adjust(1)
    await _replace_callback_message(cq, "\n".join(lines)[:3900], reply_markup=markup.as_markup())
    await cq.answer()


@router.callback_query(OwnerFilter(), F.data.startswith("admin:grant-undo:"))
async def on_admin_grant_undo(cq: CallbackQuery):
    if not await _admin_owner(cq):
        return
    raw = cq.data.rsplit(":", 1)[-1]
    if not raw.isdigit() or int(raw) == ADMIN_ID:
        await cq.answer(_lex("admin_invalid_user"), show_alert=True)
        return
    target_id = int(raw)
    latest = access_store.get_latest_grant_change(cq.from_user.id, target_id, ADMIN_ID)
    if latest is None:
        await cq.answer("История grants для этого пользователя недоступна.", show_alert=True)
        return
    if not latest["reversible"]:
        await cq.answer("Последнее изменение слишком старое или неполное для безопасной отмены.", show_alert=True)
        return
    action_text = "снять выданное право" if latest["action"] == "granted" else "вернуть отозванное право"
    stamp = datetime.datetime.fromtimestamp(latest["at"], datetime.timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    def state_text(state):
        if not state["present"]:
            return "права нет"
        expiry = state.get("expires_at")
        if expiry is None:
            return "право сохранено без срока"
        expiry_text = datetime.datetime.fromtimestamp(int(expiry), datetime.timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
        return f"право сохранено до {expiry_text}"
    markup = InlineKeyboardBuilder()
    markup.button(text=_lex("confirm_yes_button"), callback_data=f"admin:grant-undo-confirm:{target_id}:{latest['reference']}", style="danger")
    markup.button(text=_nav("back"), callback_data=f"admin:user:{target_id}", style="primary")
    markup.adjust(1)
    body = (
        "<b>Последнее изменение grants</b>\n"
        f"Пользователь: <code>{target_id}</code>\n"
        f"Право: <code>{html.escape(latest['kind'])}:{html.escape(latest['item'])}</code>\n"
        f"Действие: {html.escape(action_text)}\nВремя: <code>{stamp}</code>\n\n"
        f"Предыдущее состояние: {html.escape(state_text(latest['before']))}.\n"
        f"Текущее состояние: {html.escape(state_text(latest['after']))}.\n\n"
        "Перед выполнением будет повторно проверено, что это всё ещё последнее изменение, "
        "состояние grant совпадает с записью, а роль/блокировка/пауза не менялись."
    )
    await _replace_callback_message(cq, body, reply_markup=markup.as_markup())
    await cq.answer()


@router.callback_query(OwnerFilter(), F.data.startswith("admin:grant-undo-confirm:"))
async def on_admin_grant_undo_confirm(cq: CallbackQuery):
    if not await _admin_owner(cq):
        return
    parts = cq.data.split(":")
    if len(parts) != 4 or not parts[2].isdigit() or not re.fullmatch(r"[0-9a-f]{20}", parts[3]):
        await cq.answer("Подтверждение некорректно или устарело.", show_alert=True)
        return
    target_id, reference = int(parts[2]), parts[3]
    if target_id == ADMIN_ID:
        await cq.answer(_lex("admin_invalid_user"), show_alert=True)
        return
    registry = feature_catalog.load_registry()
    valid_callbacks = {
        str(row.get("callback")) for row in registry.get("navigation", [])
        if isinstance(row, dict) and isinstance(row.get("callback"), str)
        and "*" not in row["callback"] and row["callback"] != "noop"
    }
    valid_callbacks.update(access_store.OWNER_ONLY_CALLBACKS)
    valid_devices = set(devices.all())
    result = access_store.undo_latest_grant_change(
        cq.from_user.id, target_id, ADMIN_ID, reference,
        valid_callbacks=valid_callbacks, valid_devices=valid_devices,
    )
    if not result.get("ok"):
        reasons = {
            "not_reversible": "У этой старой записи нет безопасного снимка состояния.",
            "target_no_longer_valid": "Право больше не существует в актуальном каталоге; восстановление отменено.",
        }
        await cq.answer(reasons.get(result.get("reason"), "Состояние изменилось или подтверждение устарело; ничего не менял."), show_alert=True)
        return
    action = "выданное право снято" if not result["restored"] else "отозванное право восстановлено"
    body = (
        "<b>Изменение отменено</b>\n"
        f"Пользователь: <code>{target_id}</code>\n"
        f"Право: <code>{html.escape(result['kind'])}:{html.escape(result['item'])}</code>\n"
        f"Результат: {html.escape(action)}.\n"
        "Действие записано в аудит."
    )
    markup = InlineKeyboardBuilder()
    markup.button(text=_nav("back"), callback_data=f"admin:user:{target_id}", style="primary")
    markup.adjust(1)
    await _replace_callback_message(cq, body, reply_markup=markup.as_markup())
    await cq.answer()


