@router.callback_query(OwnerFilter(), F.data.startswith("admin:blocktemp:"))
async def on_admin_temporary_block(cq: CallbackQuery, state: FSMContext):
    if not await _admin_owner(cq):
        return
    parts = cq.data.split(":")
    if len(parts) not in {3, 4} or not parts[2].isdigit():
        await cq.answer(_lex("admin_invalid_user"), show_alert=True)
        return
    user_id = int(parts[2])
    if user_id == ADMIN_ID or not access_store.get_user(user_id):
        await cq.answer(_lex("admin_invalid_user"), show_alert=True)
        return
    if access_store.get_role(user_id, ADMIN_ID) == Role.BLOCKED and not (len(parts) == 4):
        # Re-entering the duration picker is the explicit extension path.
        pass
    kb = InlineKeyboardBuilder()
    if len(parts) == 3:
        duration_labels = ((3_600, "1 час"), (86_400, "24 часа"), (604_800, "7 дней"))
        for seconds, label in duration_labels:
            kb.button(text=label, callback_data=f"admin:blocktemp:{user_id}:{seconds}", style="danger")
        kb.button(text=_nav("back"), callback_data=f"admin:user:{user_id}", style="primary")
        kb.adjust(1)
        await _replace_callback_message(
            cq, "Выбери срок временной блокировки. Уже заблокированного пользователя это продлит.",
            reply_markup=kb.as_markup(),
        )
        await cq.answer()
        return
    seconds = int(parts[3])
    if seconds not in {3_600, 86_400, 604_800}:
        await cq.answer(_lex("admin_invalid_data"), show_alert=True)
        return
    await state.set_state(Form.wait_block_reason)
    await state.update_data(block_reason_target=user_id, block_reason_seconds=seconds)
    kb.button(text=_nav("back"), callback_data=f"admin:blocktempcancel:{user_id}", style="primary")
    await _replace_callback_message(
        cq, "Напиши краткую причину блокировки (до 240 символов). Пока причину не отправишь, блокировка не ставится.",
        reply_markup=kb.as_markup(),
    )
    await cq.answer()


@router.callback_query(OwnerFilter(), F.data.startswith("admin:blocktempcancel:"))
async def on_admin_temporary_block_cancel(cq: CallbackQuery, state: FSMContext):
    if not await _admin_owner(cq):
        return
