@router.message(OwnerFilter(), Form.wait_admin_bulk_grant)
async def on_admin_bulk_grant_text(message: Message, state: FSMContext):
    if not await _admin_owner(message):
        await state.clear()
        return
    raw = (message.text or "").strip()
    if raw.lower() == "/cancel":
        await state.clear()
        await _replace_user_card(message, "Массовая выдача отменена.", reply_markup=admin_menu())
        return
    parts = [part.strip() for part in raw.split("|")]
    if len(parts) not in (3, 4):
        await _replace_user_card(
            message, "Формат не совпал. Нужны три поля и необязательный срок через `|`; повтори ввод или /cancel.",
        )
        return
    target_field, callback_field, device_field = parts[:3]
    expires_at = None
    if len(parts) == 4 and parts[3] != "-":
        duration_s = {"1h": 3_600, "24h": 86_400, "7d": 604_800}.get(parts[3].lower())
        if duration_s is None:
            await _replace_user_card(message, "Срок должен быть 1h, 24h, 7d или -. Повтори ввод или /cancel.")
            return
        expires_at = int(time.time()) + duration_s
    if not re.fullmatch(r"\d+(?:\s*,\s*\d+)*", target_field):
        await _replace_user_card(message, "ID получателей должны быть числами через запятую. Повтори ввод или /cancel.")
        return
    targets = [int(item.strip()) for item in target_field.split(",")]
    callbacks = [] if callback_field == "-" else [item.strip() for item in callback_field.split(",")]
    device_ids = [] if device_field == "-" else [item.strip() for item in device_field.split(",")]
    if any(item not in USER_PERMISSION_CHOICES for item in callbacks):
        await _replace_user_card(
            message, "В списке есть неизвестное действие. Допустимые права перечислены в экране выдачи; повтори ввод или /cancel.",
        )
        return
    preview = access_store.preview_bulk_grants(
        message.from_user.id, ADMIN_ID, targets, callbacks=callbacks,
        device_ids=device_ids, available_device_ids=set(devices.all().keys()), expires_at=expires_at,
    )
    if not isinstance(preview, dict):
        await _replace_user_card(
            message,
            "Не удалось проверить точный список: проверь существование пользователей, устройств и права. Ничего не изменено; повтори ввод или /cancel.",
        )
        return
    await state.clear()
    staged_value = {
        "targets": preview["targets"], "callbacks": preview["callbacks"], "devices": preview["devices"],
    }
    if len(parts) == 4:
        staged_value["expires_at"] = preview["expires_at"]
    await _admin_stage(message, "bulk_grant", value=staged_value)


