def _render_permission_request(request: dict) -> str:
    request_id = html.escape(str(request.get("request_id") or "?"), quote=False)
    target = html.escape(str(request.get("actor_id") or "?"), quote=False)
    kind = "действие-кнопка" if request.get("grant_kind") == "callback" else "устройство"
    item = html.escape(str(request.get("item") or "?"), quote=False)
    try:
        deadline = datetime.datetime.fromtimestamp(
            int(request["expires_at"]), datetime.timezone.utc,
        ).strftime("%Y-%m-%d %H:%M UTC")
    except (KeyError, TypeError, ValueError, OverflowError, OSError):
        deadline = "неизвестно"
    return (
        "<b>Заявка на доступ</b>\n"
        f"ID: <code>{request_id}</code>\nПользователь: <code>{target}</code>\n"
        f"Тип: {kind}\nЗапрошено: <code>{item}</code>\nЗаявка истекает: {html.escape(deadline)}\n\n"
        "Одобрение выдаст только это право на 24 часа. Отклонение ничего не выдаёт."
    )


@router.callback_query(OwnerFilter(), F.data == "admin:access-requests")
@router.callback_query(OwnerFilter(), F.data.startswith("admin:access-requests:page:"))
async def on_admin_permission_requests(cq: CallbackQuery):
    if not await _admin_owner(cq):
        return
    page = 0
    if cq.data.startswith("admin:access-requests:page:"):
        raw = cq.data.rsplit(":", 1)[-1]
        if not raw.isdigit() or len(raw) > 4:
            await cq.answer(_lex("admin_invalid_data"), show_alert=True)
            return
        page = int(raw)
    rows = access_store.list_permission_requests(int(cq.from_user.id), int(ADMIN_ID), limit=500)
    pages = max(1, (len(rows) + 19) // 20)
    if page >= pages:
        await cq.answer("Очередь обновилась; заявки не применены.", show_alert=True)
        page = 0
    lines = ["<b>Очередь заявок на доступ</b>", f"Ожидают решения: {len(rows)} · страница {page + 1}/{pages}"]
    if rows:
        lines.append("Выбери заявку, чтобы посмотреть точное право и принять решение.")
    else:
        lines.append("Ожидающих заявок нет.")
    await _replace_callback_message(
        cq, "\n".join(lines), reply_markup=admin_permission_requests_keyboard(int(cq.from_user.id), page),
    )
    await cq.answer()


