@router.callback_query(OwnerFilter(), F.data.startswith("admin:access-request:approve:"))
@router.callback_query(OwnerFilter(), F.data.startswith("admin:access-request:reject:"))
async def on_admin_permission_request_decision(cq: CallbackQuery):
    if not await _admin_owner(cq):
        return
    parts = str(cq.data or "").split(":")
    if len(parts) != 4 or parts[2] not in {"approve", "reject"} or not re.fullmatch(r"[0-9a-f]{12}", parts[3]):
        await cq.answer(_lex("admin_invalid_data"), show_alert=True)
        return
    try:
        available = set(devices.all())
        archived_reader = getattr(devices, "list_archived_devices", None)
        if callable(archived_reader):
            available.difference_update(
                device_id for device_id, _info in archived_reader(
                    actor_id=int(ADMIN_ID), owner_id=int(ADMIN_ID), limit=500,
                )
            )
    except (OSError, TypeError, ValueError):
        await cq.answer("Не удалось проверить каталог устройств; решение не применено.", show_alert=True)
        return
    result = access_store.decide_permission_request(
        int(cq.from_user.id), int(ADMIN_ID), parts[3], parts[2],
        available_device_ids=available,
    )
    if result is None:
        await cq.answer("Заявка уже закрыта, истекла или больше не доступна. Ничего не изменено.", show_alert=True)
        return
    if result["status"] == "approved":
        if result.get("grant_written"):
            outcome = "Одобрено: точное право выдано на 24 часа."
        else:
            outcome = "Заявка одобрена; такое право уже активно, существующий grant не менялся."
    elif result["status"] == "rejected":
        outcome = "Заявка отклонена; права не изменены."
    else:
        outcome = "Заявка устарела (роль, устройство или право изменились); ничего не выдано."
    await _replace_callback_message(
        cq, f"<b>{outcome}</b>", reply_markup=admin_permission_requests_keyboard(int(cq.from_user.id)),
    )
    await cq.answer()


def admin_audit_event_keyboard(actor_id: int | None = None):
    actor_id = int(actor_id if actor_id is not None else CURRENT_TG_USER.get()) or int(ADMIN_ID)
    if actor_id != int(ADMIN_ID):
        return InlineKeyboardBuilder().as_markup()
    rows = feature_catalog.visible_navigation_pages(
        feature_catalog.load_registry(), parent="admin.audit.event", role=Role.OWNER,
        grants=set(), platform="telegram",
    )
    kb = InlineKeyboardBuilder()
    if len(rows) != 1:
        raise ValueError("feature registry has an invalid audit-event back route")
    row = rows[0]
    if (row.get("page_id") != "admin.audit.event.back" or row.get("callback") != "admin:audit"
            or row.get("presentation") != "nav" or row.get("label_id") != "back"):
        raise ValueError("feature registry has an invalid audit-event back route")
    kb.button(text=_nav("back"), callback_data="admin:audit", style=str(row.get("style") or "primary"))
    kb.adjust(1)
    return kb.as_markup()


def _render_audit_event(event: dict) -> str:
    at = event.get("at")
    if type(at) is not int or at < 0:
        moment = "время неизвестно"
    else:
        try:
            moment = datetime.datetime.fromtimestamp(at, datetime.timezone.utc).strftime("%d.%m.%Y %H:%M:%S UTC")
        except (OverflowError, OSError, ValueError):
            moment = "время неизвестно"
    kind = event.get("kind") if isinstance(event.get("kind"), str) else "event"
    outcome = event.get("outcome") if isinstance(event.get("outcome"), str) else "unknown"
    lines = [
        "<b>Карточка события аудита</b>",
        f"<b>Тип:</b> {html.escape(kind[:80])}",
        f"<b>Исход:</b> {html.escape(outcome[:80])}",
        f"<b>Время:</b> <code>{html.escape(moment)}</code>",
    ]
    for key, label in (("actor_id", "Актор"), ("target_id", "Цель")):
        value = event.get(key)
        if type(value) is int and value > 0:
            lines.append(f"<b>{label}:</b> <code>{value}</code>")
    device = event.get("device_id")
    if isinstance(device, str) and device:
        lines.append(f"<b>Устройство:</b> <code>{html.escape(device[:256])}</code>")
    fields = event.get("fields") if isinstance(event.get("fields"), dict) else {}
    allowed = {
        "requester_id": "Инициатор (requester_id)", "approver_id": "Подтвердил (approver_id)", "exit_code": "Код завершения (exit_code)",
        "grant_kind": "Тип права", "item": "Объект права", "expires_at": "Истекает (Unix UTC)",
        "role": "Роль", "restored_role": "Восстановленная роль", "permission": "Разрешение",
    }
    for key, label in allowed.items():
        value = fields.get(key)
        if type(value) is int or isinstance(value, str):
            rendered = html.escape(str(value)[:256])
            lines.append(f"<b>{label}:</b> <code>{rendered}</code>")
    reference = event.get("event_id")
    if isinstance(reference, str) and re.fullmatch(r"[0-9a-f]{20}", reference):
        lines.append(f"<b>ID события:</b> <code>{reference}</code>")
    return "\n".join(lines)[:3900]


