def _render_audit_rows(rows: list[dict], *, title: str = "Журнал действий") -> str:
    if not rows:
        return f"<b>{html.escape(title)}</b>\nЗаписей по фильтру не найдено."
    lines = []
    for row in rows[:30]:
        at = row.get("at")
        if type(at) is not int or at < 0:
            continue
        try:
            moment = datetime.datetime.fromtimestamp(at, datetime.timezone.utc).strftime("%d.%m %H:%M UTC")
        except (OverflowError, OSError, ValueError):
            continue
        kind = html.escape(str(row.get("kind") or "event")[:80])
        actor_value = row.get("actor_id")
        if type(actor_value) is not int:
            actor_value = row.get("requester_id")
        actor = str(actor_value) if type(actor_value) is int else "system"
        device = row.get("device_id")
        device_text = f" · <code>{html.escape(device[:120])}</code>" if isinstance(device, str) and device else ""
        detail = html.escape(str(row.get("detail") or "")[:280])
        lines.append(f"<code>{moment}</code> {kind} [{html.escape(actor)}]{device_text} {detail}".rstrip())
    if not lines:
        return f"<b>{html.escape(title)}</b>\nПодходящих корректных записей нет."
    header = f"<b>{html.escape(title)}</b>\n"
    bounded: list[str] = []
    size = len(header)
    for line in lines:
        if size + len(line) + (1 if bounded else 0) > 3700:
            break
        bounded.append(line)
        size += len(line) + (1 if len(bounded) > 1 else 0)
    if len(bounded) < len(lines):
        bounded.append("… список ограничен")
    return header + "\n".join(bounded)


def _parse_audit_filter_input(text: str) -> dict | None:
    """Parse one UTC day plus optional exact actor, event kind and device filters."""
    parts = [part.strip() for part in str(text or "").split("|")]
    if len(parts) != 4:
        return None
    day_text, actor_text, event_text, device_text = parts
    since = until = None
    if day_text != "-":
        try:
            day = datetime.date.fromisoformat(day_text)
            start = datetime.datetime.combine(day, datetime.time.min, tzinfo=datetime.timezone.utc)
            since = int(start.timestamp())
            until = since + 86_400 - 1
        except (TypeError, ValueError, OverflowError, OSError):
            return None
    actor_id = None
    if actor_text != "-":
        try:
            actor_id = int(actor_text)
        except (TypeError, ValueError, OverflowError):
            return None
        if actor_id <= 0:
            return None
    event_type = None if event_text == "-" else event_text
    device_id = None if device_text == "-" else device_text
    if ((event_type is not None and (not event_type or len(event_type) > 80))
            or (device_id is not None and (not device_id or len(device_id.encode("utf-8")) > 256))):
        return None
    return {
        "since": since, "until": until, "actor_id": actor_id,
        "event_type": event_type, "device_id": device_id,
    }


def _parse_audit_export_input(text: str) -> dict | None:
    """Parse inclusive UTC dates plus the same optional exact audit filters."""
    parts = [part.strip() for part in str(text or "").split("|")]
    if len(parts) != 5:
        return None
    try:
        first = datetime.date.fromisoformat(parts[0])
        last = datetime.date.fromisoformat(parts[1])
        since = int(datetime.datetime.combine(first, datetime.time.min, tzinfo=datetime.timezone.utc).timestamp())
        until = int(datetime.datetime.combine(last, datetime.time.max, tzinfo=datetime.timezone.utc).timestamp())
    except (TypeError, ValueError, OverflowError, OSError):
        return None
    if until < since or until - since > (31 * 86_400 - 1):
        return None
    filters = _parse_audit_filter_input(f"- | {parts[2]} | {parts[3]} | {parts[4]}")
    if filters is None:
        return None
    return {**filters, "since": since, "until": until}


def _parse_shell_metadata_export_input(text: str) -> dict | None:
    """Parse an inclusive UTC date range and exact shell outcomes."""
    parts = [part.strip() for part in str(text or "").split("|")]
    if len(parts) != 3:
        return None
    try:
        first = datetime.date.fromisoformat(parts[0])
        last = datetime.date.fromisoformat(parts[1])
        if first.isoformat() != parts[0] or last.isoformat() != parts[1]:
            return None
        since = int(datetime.datetime.combine(first, datetime.time.min, tzinfo=datetime.timezone.utc).timestamp())
        until = int(datetime.datetime.combine(last, datetime.time.max, tzinfo=datetime.timezone.utc).timestamp())
    except (TypeError, ValueError, OverflowError, OSError):
        return None
    if until < since or until - since > (31 * 86_400 - 1):
        return None
    statuses = [status.strip() for status in parts[2].split(",")]
    if (not statuses or len(statuses) > len(access_store.COMMAND_AUDIT_STATUSES)
            or len(statuses) != len(set(statuses))
            or any(status not in access_store.COMMAND_AUDIT_STATUSES for status in statuses)):
        return None
    return {"since": since, "until": until, "statuses": sorted(statuses)}


