@router.message(OwnerFilter(), Form.wait_shell_metadata_export)
async def on_shell_metadata_export_text(message: Message, state: FSMContext):
    if not await _admin_owner(message):
        await state.clear()
        return
    form_data = await state.get_data()
    await state.clear()
    parsed = _parse_shell_metadata_export_input(message.text or "")
    if parsed is None:
        await _replace_user_card(
            message,
            "<b>Экспорт не создан</b>\nПроверь даты, лимит 31 день и статусы из журнала команд.",
            reply_markup=terminal_menu(int(message.from_user.id)),
        )
        return
    device_id = form_data.get("device_id")
    if not isinstance(device_id, str) or not device_id or len(device_id.encode("utf-8")) > 256:
        await _replace_user_card(
            message, "<b>Экспорт не создан</b>\nВыбранное устройство устарело; открой раздел заново.",
            reply_markup=terminal_menu(int(message.from_user.id)),
        )
        return
    exported = access_store.export_shell_command_audit(
        int(message.from_user.id), int(ADMIN_ID), **parsed, device_id=device_id, limit=100,
    )
    if exported is None:
        await _replace_user_card(
            message, "<b>Экспорт не создан</b>\nПериод, статус или доступ недопустимы.",
            reply_markup=terminal_menu(int(message.from_user.id)),
        )
        return
    access_store.append_audit(
        "shell_metadata_export_requested", actor_id=int(message.from_user.id),
        detail=(f"since={parsed['since']};until={parsed['until']};statuses={','.join(parsed['statuses'])};"
                f"device={device_id};events={len(exported['events'])};truncated={bool(exported['truncated'])}"),
    )
    payload = json.dumps(exported, ensure_ascii=False, indent=2).encode("utf-8")
    first = datetime.datetime.fromtimestamp(parsed["since"], datetime.timezone.utc).strftime("%Y%m%d")
    last = datetime.datetime.fromtimestamp(parsed["until"], datetime.timezone.utc).strftime("%Y%m%d")
    await _replace_user_card_with_document(
        message,
        BufferedInputFile(payload, filename=f"xider-shell-audit-{first}-{last}.json"),
        "Экспорт shell-метаданных готов: только разрешённые поля; "
        f"записей: {len(exported['events'])}" + (" (список ограничен)" if exported["truncated"] else ""),
        reply_markup=terminal_menu(int(message.from_user.id)),
    )


