@router.callback_query(ReadOnlyFilter(), F.data == "access:request")
async def on_access_request_start(cq: CallbackQuery, state: FSMContext):
    user_id = int(cq.from_user.id)
    if user_id == int(ADMIN_ID) or get_user_role(user_id) != Role.USER:
        await cq.answer("Запрос доступен только роли «пользователь».", show_alert=True)
        return
    await state.clear()
    await state.set_state(Form.wait_permission_request)
    await _replace_callback_message(
        cq,
        "<b>Запрос права доступа</b>\n"
        "Отправь одну строку в формате <code>callback:cmd:screenshot</code> "
        "или <code>device:ID-устройства</code>.\n"
        "Запрос уйдёт владельцу на рассмотрение; право само не включится. Для отмены отправь <code>/cancel</code>.",
        reply_markup=main_menu(user_id),
    )
    await cq.answer()


@router.message(Form.wait_permission_request)
async def on_access_request_input(message: Message, state: FSMContext):
    actor_id = int(message.from_user.id) if message.from_user else 0
    if actor_id <= 0 or actor_id == int(ADMIN_ID) or get_user_role(actor_id) != Role.USER:
        await state.clear()
        await _replace_user_card(message, "Запрос не создан: нужна активная роль «пользователь».", reply_markup=main_menu(actor_id or ADMIN_ID))
        return
    text = (message.text or "").strip()
    if text.split(maxsplit=1)[0].split("@", 1)[0].lower() == "/cancel" if text else False:
        await state.clear()
        await _replace_user_card(message, "Запрос отменён.", reply_markup=main_menu(actor_id))
        return
    kind, sep, item = text.partition(":")
    kind = kind.strip().lower()
    item = item.strip()
    if not sep or kind not in {"callback", "device"} or not item or len(item) > 256:
        await _replace_user_card(
            message,
            "Формат не распознан; ничего не отправлено. Пример: <code>callback:cmd:screenshot</code> или <code>device:mac-a</code>.",
            reply_markup=main_menu(actor_id),
        )
        return
    available_device_ids = set(devices.all())
    archived_reader = getattr(devices, "list_archived_devices", None)
    if callable(archived_reader):
        try:
            available_device_ids.difference_update(
                device_id for device_id, _info in archived_reader(actor_id=ADMIN_ID, owner_id=ADMIN_ID, limit=500)
            )
        except (TypeError, ValueError):
            await _replace_user_card(message, "Не удалось проверить реестр устройств; запрос не отправлен.", reply_markup=main_menu(actor_id))
            return
    request = access_store.submit_permission_request(
        actor_id, int(ADMIN_ID), kind, item,
        available_device_ids=available_device_ids,
    )
    await state.clear()
    if request is None:
        await _replace_user_card(
            message,
            "Запрос не создан: проверь точное имя права/устройства, либо оно уже недоступно.",
            reply_markup=main_menu(actor_id),
        )
        return
    if request["status"] == "already_granted":
        await _replace_user_card(message, "Это право уже активно; новая заявка не нужна.", reply_markup=main_menu(actor_id))
        return
    if request.get("duplicate"):
        await _replace_user_card(message, "Такая заявка уже ждёт владельца; повторно не отправлял.", reply_markup=main_menu(actor_id))
        return
    username = getattr(message.from_user, "username", None)
    requester = f"{actor_id}" + (f" (@{html.escape(username)})" if username else "")
    owner_notice = (
        "<b>Новая заявка на доступ</b>\n"
        f"ID: <code>{html.escape(request['request_id'])}</code>\n"
        f"Пользователь: {requester}\n"
        f"Тип: <code>{html.escape(kind)}</code>\n"
        f"Запрошено: <code>{html.escape(item)}</code>\n"
        "Статус: ожидает решения. Право ещё не выдано."
    )
    delivered = await _notify_owner(owner_notice, strict_delivery=True)
    if delivered:
        await _replace_user_card(message, "Заявка передана владельцу. Доступ появится только если он отдельно её одобрит.", reply_markup=main_menu(actor_id))
    else:
        await _replace_user_card(message, "Заявка сохранена, но уведомление владельцу не доставлено. Доступ не выдан.", reply_markup=main_menu(actor_id))


