def _catalog_search_prompt(mode: str) -> str:
    if mode == "exact":
        return "Введи ID или название функции для точного поиска. До 120 символов."
    if mode == "outcome":
        return "Опиши желаемый результат — найду подходящие карточки по описанию. До 120 символов."
    if mode == "fuzzy":
        return "Введи ID или название функции. Исправлю небольшие опечатки только в ID/названии; короткий запрос должен быть точным. До 120 символов."
    raise ValueError("unsupported feature catalog search mode")


@router.callback_query(ReadOnlyFilter(), F.data.in_({"catalog:search:exact", "catalog:search:outcome", "catalog:search:fuzzy"}))
async def on_feature_catalog_search_start(cq: CallbackQuery, state: FSMContext):
    mode = (cq.data or "").removeprefix("catalog:search:")
    if mode not in {"exact", "outcome", "fuzzy"}:
        await cq.answer("Режим поиска не распознан.", show_alert=True)
        return
    await state.set_state(Form.wait_catalog_search)
    await state.update_data(catalog_search_mode=mode)
    await _replace_callback_message(
        cq, _catalog_search_prompt(mode),
        reply_markup=feature_catalog_search_keyboard(cq.from_user.id, parent="catalog.search.prompt"),
    )
    await cq.answer()


