async def on_feature_catalog_synonym_add(cq: CallbackQuery, state: FSMContext):
    feature_id = (cq.data or "").removeprefix("catalog:synonym:add:")
    if cq.from_user.id != ADMIN_ID or get_user_role(cq.from_user.id) != Role.OWNER or not re.fullmatch(
        r"[A-Z][A-Z0-9]{1,3}-F\d{2}", feature_id,
    ):
        await cq.answer("Изменять словарь поиска может только владелец.", show_alert=True)
        return
    registry = feature_catalog.load_registry()
    if feature_catalog.find_visible_feature(
        registry, feature_id, role="owner", grants=(),
    ) is None:
        await cq.answer("Карточка каталога не найдена.", show_alert=True)
        return
    await state.clear()
    await state.update_data(catalog_synonym_feature_id=feature_id)
    await state.set_state(Form.wait_catalog_synonym)
    await _replace_callback_message(
        cq, _feature_catalog_synonym_prompt(feature_id),
        reply_markup=feature_catalog_synonym_keyboard(cq.from_user.id),
    )
    await cq.answer()


@router.callback_query(OwnerFilter(), F.data == "catalog:synonym:cancel")
async def on_feature_catalog_synonym_cancel(cq: CallbackQuery, state: FSMContext):
    form_data = await state.get_data()
    await state.clear()
    feature_id = str(form_data.get("catalog_synonym_feature_id") or "")
    detail = feature_catalog_detail(cq.from_user.id, feature_id) if re.fullmatch(
        r"[A-Z][A-Z0-9]{1,3}-F\d{2}", feature_id,
    ) else None
    if detail is None:
        await _replace_callback_message(
            cq, "Редактирование словаря отменено.",
            reply_markup=feature_catalog_areas_menu(cq.from_user.id),
        )
    else:
        await _replace_callback_message(
            cq, detail,
            reply_markup=feature_catalog_detail_keyboard(cq.from_user.id, feature_id),
        )
    await cq.answer()


@router.message(OwnerFilter(), Form.wait_catalog_synonym)
async def on_feature_catalog_synonym_input(message: Message, state: FSMContext):
    form_data = await state.get_data()
    feature_id = str(form_data.get("catalog_synonym_feature_id") or "")
    await state.clear()
    if message.from_user.id != ADMIN_ID or get_user_role(message.from_user.id) != Role.OWNER:
        return
    if not re.fullmatch(r"[A-Z][A-Z0-9]{1,3}-F\d{2}", feature_id) or feature_catalog.find_visible_feature(
        feature_catalog.load_registry(), feature_id, role="owner", grants=(),
    ) is None:
        await _replace_user_card(
            message, "Карточка каталога устарела. Открой её заново.",
            reply_markup=feature_catalog_areas_menu(message.from_user.id),
        )
        return
    value = message.text if isinstance(message.text, str) else ""
    remove = value.startswith("-")
    synonym = value[1:].strip() if remove else value
    if not remove and synonym.startswith("+"):
        synonym = synonym[1:].strip()
    try:
        if remove:
            changed = devices.remove_feature_search_synonym(
                feature_id, synonym, actor_id=message.from_user.id, owner_id=ADMIN_ID,
            )
            notice = "Слово удалено." if changed else "Такого слова в списке нет."
            audit_action = "removed" if changed else "remove_missing"
        else:
            devices.add_feature_search_synonym(
                feature_id, synonym, actor_id=message.from_user.id, owner_id=ADMIN_ID,
            )
            notice = "Слово добавлено (повторное добавление не создаёт дубль)."
            audit_action = "added"
    except (ValueError, PermissionError):
        notice = "Не сохранил: проверь длину, лимит и чтобы фраза не была назначена другой карточке."
        audit_action = "rejected"
    access_store.append_audit(
        "catalog_search_synonym", actor_id=message.from_user.id,
        detail=f"feature={feature_id}; action={audit_action}",
    )
    await _replace_user_card(
        message, _feature_catalog_synonym_prompt(feature_id, notice=notice),
        reply_markup=feature_catalog_synonym_keyboard(message.from_user.id),
    )


@router.callback_query(ReadOnlyFilter(), F.data == "catalog:back")
async def on_feature_catalog_back(cq: CallbackQuery):
    state = _catalog_navigation_state(cq.from_user.id)
    stack = list(state.get("stack", [])) if state else []
    if stack:
        previous = stack.pop()
    else:
        previous = {"page": "catalog:areas", "cursor": 0}
    page_key = str(previous.get("page") or "catalog:areas")
    cursor = int(previous.get("cursor") or 0)
    if page_key == "catalog:areas":
        registry = feature_catalog.load_registry()
        body = (
            f"<b>Каталог функций XIDER</b>\n\n{len(registry.get('areas', []))} разделов. "
            "Карточки описывают возможности и их статус; просмотр не запускает действия устройства."
        )
        markup = feature_catalog_areas_menu(cq.from_user.id)
    elif page_key.startswith("catalog:area:"):
        area_id = page_key.removeprefix("catalog:area:")
        registry = feature_catalog.load_registry()
        if not any(item.get("area_id") == area_id for item in registry.get("areas", [])):
            previous = {"page": "catalog:areas", "cursor": 0}
            stack = []
            body = (
                f"<b>Каталог функций XIDER</b>\n\n{len(registry.get('areas', []))} разделов. "
                "Карточки описывают возможности и их статус; просмотр не запускает действия устройства."
            )
            markup = feature_catalog_areas_menu(cq.from_user.id)
        else:
            body, markup = feature_catalog_area_page(cq.from_user.id, area_id, cursor)
    elif page_key == "catalog:filter:types":
        registry = feature_catalog.load_registry()
        body = (
            "<b>Фильтр по типу результата</b>\n\n"
            "Покажу только карточки с явно указанным типом результата в реестре."
        )
        markup = feature_catalog_result_type_keyboard(cq.from_user.id)
    elif page_key.startswith("catalog:filter:result:"):
        result_type = page_key.removeprefix("catalog:filter:result:")
        if result_type not in feature_catalog.RESULT_TYPES:
            previous = {"page": "catalog:filter:types", "cursor": 0}
            stack = []
            body = "<b>Фильтр по типу результата</b>\n\nВыбери тип из списка."
            markup = feature_catalog_result_type_keyboard(cq.from_user.id)
        else:
            body, markup = feature_catalog_result_type_page(cq.from_user.id, result_type)
    elif page_key == "catalog:filter:permission":
        body, markup = feature_catalog_permission_page(cq.from_user.id)
    elif page_key == "catalog:filter:access":
        body, markup = feature_catalog_access_page(cq.from_user.id)
    else:
        previous = {"page": "catalog:areas", "cursor": 0}
        stack = []
        registry = feature_catalog.load_registry()
        body = (
            f"<b>Каталог функций XIDER</b>\n\n{len(registry.get('areas', []))} разделов. "
            "Карточки описывают возможности и их статус; просмотр не запускает действия устройства."
        )
        markup = feature_catalog_areas_menu(cq.from_user.id)
    _save_catalog_navigation(cq.from_user.id, str(previous["page"]), int(previous.get("cursor") or 0), stack)
    await _replace_callback_message(cq, body, reply_markup=markup)
    await cq.answer()


@router.callback_query(AdminFilter(), F.data == "menu:devices")
async def on_menu_devices(cq: CallbackQuery):
    await _show_device_catalog_page(cq, 0)


async def _show_device_catalog_page(cq: CallbackQuery, page: int) -> None:
    visible_devices = _visible_device_items(cq.from_user.id)
    ordered_devices = _ordered_device_items(cq.from_user.id, visible_devices)
    page_count = max(1, math.ceil(len(ordered_devices) / _DEVICE_CATALOG_PAGE_SIZE))
    selected_page = min(max(0, int(page)), page_count - 1)
    page_devices = ordered_devices[
        selected_page * _DEVICE_CATALOG_PAGE_SIZE:(selected_page + 1) * _DEVICE_CATALOG_PAGE_SIZE
    ]
    lines = []
    for device_id, info in page_devices:
        state = "🟢 онлайн" if _status_dot(info) == "🟢" else "⚪ офлайн"
        name = html.escape(_limit_button_label(str(info.get("name") or device_id), 24))
        short_id = html.escape(_limit_button_label(str(device_id), 20))
        lines.append(f"{state} <b>{name}</b> <code>{short_id}</code>")
    if lines:
        text = f"💻 <b>Устройства</b> · {len(visible_devices)} · {selected_page + 1}/{page_count}\n\n" + "\n".join(lines)
    else:
        if get_user_role(cq.from_user.id) == Role.OWNER:
            text = "💻 Пока нет ни одного устройства.\nЗапустите клиент — оно появится само."
        else:
            text = "💻 Вам пока не выдан доступ к устройствам. Обратитесь к владельцу."
    await _replace_callback_message(
        cq, text, reply_markup=devices_menu(cq.from_user.id, page=selected_page),
    )


@router.callback_query(AdminFilter(), F.data.startswith("devices:list:"))
async def on_devices_list_page(cq: CallbackQuery):
    try:
        requested_page = int(cq.data.rsplit(":", 1)[1])
    except (IndexError, ValueError):
        await cq.answer("Страница каталога устарела.", show_alert=True)
        return
    if requested_page < 0 or requested_page > 100000:
        await cq.answer("Страница каталога устарела.", show_alert=True)
        return
    await _show_device_catalog_page(cq, requested_page)
    await cq.answer()


@router.callback_query(AdminFilter(), F.data.startswith("devices:results:"))
async def on_devices_results_page(cq: CallbackQuery):
    parts = cq.data.split(":")
    if len(parts) != 4 or not parts[2].isalnum():
        await cq.answer("Результаты устарели. Запусти поиск заново.", show_alert=True)
        return
    try:
        requested_page = int(parts[3])
    except ValueError:
        await cq.answer("Страница результатов устарела.", show_alert=True)
        return
    _prune_device_view_cache()
    view = _DEVICE_RESULT_VIEWS.get(parts[2])
    if (not view or int(view.get("user_id", -1)) != int(cq.from_user.id)
            or not _device_result_view_allowed(cq.from_user.id, view)):
        await cq.answer("Результаты устарели или доступ отозван.", show_alert=True)
        return
    visible = _visible_device_items(cq.from_user.id)
    ids = [device_id for device_id in view["ids"] if device_id in visible]
    page_count = max(1, math.ceil(len(ids) / _DEVICE_RESULT_PAGE_SIZE))
    if requested_page < 0 or requested_page >= page_count:
        await cq.answer("Страница результатов устарела.", show_alert=True)
        return
    await _replace_callback_message(
        cq, _device_result_page_body(view, ids, requested_page),
        reply_markup=_device_result_page_markup(
            cq.from_user.id, parts[2], requested_page, ids,
            back_callback=str(view.get("back_callback") or "menu:devices"),
        ),
    )
    await cq.answer()


