@router.message(ReadOnlyFilter(), Form.wait_device_search)
async def on_device_search_input(message: Message, state: FSMContext):
    user_id = int(message.from_user.id)
    role = get_user_role(user_id)
    await state.clear()
    if role not in {Role.OWNER, Role.USER}:
        await _replace_user_card(message, "Поиск устройства больше недоступен для этой роли.")
        return
    if role == Role.USER and not access_store.can_use_callback(
        user_id, "devices:search", ADMIN_ID, None,
    ):
        await _replace_user_card(message, "Доступ к поиску отозван. Открой раздел устройств заново.")
        return
    query = " ".join((message.text or "").split())
    if not query or len(query) > 120:
        await _replace_user_card(
            message,
            "Запрос пустой или длиннее 120 символов. Открой поиск заново.",
            reply_markup=devices_menu(user_id),
        )
        return
    matches = search_visible_devices(query, _visible_device_items(user_id))
    await _render_device_result_card(
        message, matches,
        title="Совпадения по запросу" if matches else "Совпадений нет",
        note="Показаны только доступные устройства.", required_callback="devices:search",
    )


