@router.callback_query(OwnerFilter(), F.data.startswith("devices:sort:"))
async def on_device_sort_choice(cq: CallbackQuery):
    sort_by = cq.data.rsplit(":", 1)[-1]
    try:
        if sort_by == "custom":
            visible = _visible_device_items(cq.from_user.id)
            current_sort = devices.get_device_catalog_sort(cq.from_user.id, ADMIN_ID) or "name"
            seed_sort = "name" if current_sort == "custom" else current_sort
            seed = [device_id for device_id, _info in sort_device_inventory(visible, seed_sort)]
            current = devices.get_device_catalog_order(cq.from_user.id, ADMIN_ID, seed)
            devices.set_device_catalog_order(cq.from_user.id, ADMIN_ID, current or seed)
        saved = devices.set_device_catalog_sort(cq.from_user.id, ADMIN_ID, sort_by)
    except ValueError:
        saved = False
    if not saved:
        await cq.answer("Не удалось сохранить режим сортировки.", show_alert=True)
        return
    labels = {"name": "имя", "platform": "платформа / ОС", "version": "версия агента", "last_seen": "последняя связь", "custom": "мой порядок"}
    access_store.append_audit("device_catalog_sort_changed", actor_id=cq.from_user.id, sort_by=sort_by)
    await _replace_callback_message(
        cq, f"Сортировка сохранена: <b>{labels[sort_by]}</b>.", reply_markup=devices_menu(cq.from_user.id),
    )
    await cq.answer()


