@router.callback_query(OwnerFilter(), F.data.startswith("catalog:pinned:toggle:"))
async def on_device_pin_toggle(cq: CallbackQuery):
    device_id = cq.data.removeprefix("catalog:pinned:toggle:")
    if not devices._valid_pinned_device_id(device_id) or not access_store.can_use_callback(
        cq.from_user.id, f"dev:{device_id}", ADMIN_ID, device_id
    ):
        await cq.answer("Устройство недоступно или ссылка устарела.", show_alert=True)
        return
    if devices.get(device_id) is None:
        await cq.answer("Устройство больше не зарегистрировано.", show_alert=True)
        return
    pinned = devices.list_pinned_devices(actor_id=cq.from_user.id, owner_id=ADMIN_ID)
    if device_id in pinned:
        changed = devices.unpin_device(cq.from_user.id, ADMIN_ID, device_id)
        event = "device_unpinned"
        result = "Устройство откреплено."
    else:
        changed = devices.pin_device(cq.from_user.id, ADMIN_ID, device_id)
        event = "device_pinned"
        result = "Устройство закреплено."
    if not changed:
        await cq.answer("Не удалось изменить закрепления. Возможно, достигнут лимит в 20 устройств.", show_alert=True)
        return
    access_store.append_audit(event, actor_id=cq.from_user.id, device_id=device_id)
    await _replace_callback_message(
        cq, device_card(device_id),
        reply_markup=device_menu(device_id, cq.from_user.id, include_tools=True),
    )
    await cq.answer(result)


