@router.message(ReadOnlyFilter(), Form.wait_device_os_filter)
async def on_device_filter_os_input(message: Message, state: FSMContext):
    user_id = int(message.from_user.id)
    await state.clear()
    if get_user_role(user_id) != Role.OWNER:
        await _replace_user_card(message, "Фильтр ОС доступен только владельцу устройства.")
        return
    query = " ".join((message.text or "").split())
    if not query or len(query) > 64:
        await _replace_user_card(
            message,
            "Укажи Windows или macOS и, если нужно, версию. Фильтр доступен в разделе устройств.",
            reply_markup=devices_menu(user_id),
        )
        return
    parts = query.split(maxsplit=1)
    platform_key = parts[0].casefold()
    if platform_key in {"windows", "win"}:
        platform = "Windows"
    elif platform_key in {"macos", "mac", "darwin"}:
        platform = "macOS"
    else:
        await _replace_user_card(
            message,
            "Не понял платформу. Укажи Windows или macOS, затем при желании версию.",
            reply_markup=devices_menu(user_id),
        )
        return
    version = parts[1] if len(parts) > 1 else None
    matches = filter_visible_devices_by_platform_version(
        platform, version, _visible_device_items(user_id),
    )
    await _render_device_result_card(
        message, matches, title='OS matches', note='Only reported OS data is used.', required_callback="owner",
    )


