@router.message(ReadOnlyFilter(), Form.wait_device_inventory_age_filter)
async def on_device_filter_inventory_age_input(message: Message, state: FSMContext):
    user_id = int(message.from_user.id)
    await state.clear()
    if get_user_role(user_id) != Role.OWNER:
        await _replace_user_card(message, "Фильтр давности инвентаризации доступен только владельцу устройства.")
        return
    query = " ".join((message.text or "").split())
    if _parse_heartbeat_age_filter(query) is None:
        await _replace_user_card(
            message, "Укажи порог в формате >= 30d или <= 7d (s/m/h/d, максимум 365 дней).",
            reply_markup=devices_menu(user_id),
        )
        return
    visible = _visible_device_items(user_id)
    inventory_times = {}
    for device_id in visible:
        try:
            snapshots = devices.list_hardware_inventory_snapshots(device_id, limit=1)
        except (AttributeError, OSError, TypeError, ValueError):
            snapshots = []
        if snapshots and isinstance(snapshots[0], dict):
            inventory_times[device_id] = snapshots[0].get("captured_at")
    matches = filter_visible_devices_by_inventory_age(query, visible, inventory_times)
    await _render_device_result_card(
        message, matches, title='Inventory snapshot matches', note='Age is measured from the latest saved hardware-inventory snapshot; heartbeat is not used.', required_callback="owner",
    )


def _inactivity_navigation_pages(user_id: int | None, *, parent: str):
    role = (
        Role.OWNER
        if user_id is None or int(user_id) == int(ADMIN_ID)
        else get_user_role(user_id)
    )
    return feature_catalog.visible_navigation_pages(
        feature_catalog.load_registry(), parent=parent, role=role,
        grants=set(access_store.get_effective_grants(user_id or ADMIN_ID)["callbacks"]),
        platform="telegram",
    )


def inactivity_history_screen(user_id: int | None = None):
    rows = devices.list_inactivity_snapshots(limit=20)
    kb = InlineKeyboardBuilder()
    for page in _inactivity_navigation_pages(user_id, parent="catalog.inactivity.list"):
        page_id = str(page["page_id"])
        callback = str(page["callback"])
        presentation = page["presentation"]
        label_id = str(page["label_id"])
        style = str(page["style"])
        if (
            page_id == "catalog.inactivity.capture"
            and callback == "catalog:inactivity:capture"
            and presentation == "inactivity_action"
            and label_id == "inactivity_capture"
        ):
            kb.button(
                text=_ui_phrase("📸 Capture aggregate snapshot", "📸 Снять агрегированный снимок", "📸 Снять снимок"),
                callback_data=callback, style=style,
            )
        elif (
            page_id == "catalog.inactivity.compare"
            and callback == "catalog:inactivity:compare"
            and presentation == "inactivity_action"
            and label_id == "inactivity_compare"
        ):
            if len(rows) >= 2:
                kb.button(
                    text=_ui_phrase("Compare latest two", "Сравнить два последних", "Сравнить последние два"),
                    callback_data=callback, style=style,
                )
        elif (
            page_id == "catalog.inactivity.back"
            and callback == "menu:devices"
            and presentation == "nav"
            and label_id == "back_device"
        ):
            kb.button(text=_nav(label_id), callback_data=callback, style=style)
        elif (
            page_id == "catalog.inactivity.home"
            and callback == "menu:main"
            and presentation == "nav"
            and label_id == "home"
        ):
            kb.button(text=_nav(label_id), callback_data=callback, style=style)
        else:
            raise ValueError("feature registry has an unregistered inactivity-history renderer")
    kb.adjust(1)

    lines = ["<b>Динамика активности устройств</b>", "Сохраняются только агрегированные количества по ОС и возрасту heartbeat — без имён и ID устройств."]
    if not rows:
        lines.append("\nСнимков пока нет. Нажми кнопку ниже, чтобы сохранить первый baseline.")
    for row in rows[:8]:
        stamp = datetime.datetime.fromtimestamp(int(row.get("captured_at", 0))).strftime("%d.%m.%Y %H:%M")
        platforms = []
        for platform, buckets in sorted((row.get("counts") or {}).items()):
            counts = ", ".join(f"{key}={int(value)}" for key, value in sorted(buckets.items()))
            platforms.append(f"{platform}: {counts}")
        lines.append(f"\n{stamp}\n" + ("; ".join(platforms) if platforms else "Нет данных по платформам"))
    return rows, "\n".join(lines), kb.as_markup()


def inactivity_compare_keyboard(user_id: int | None = None):
    kb = InlineKeyboardBuilder()
    for page in _inactivity_navigation_pages(user_id, parent="catalog.inactivity.compare"):
        page_id = str(page["page_id"])
        callback = str(page["callback"])
        presentation = page["presentation"]
        label_id = str(page["label_id"])
        if (
            page_id == "catalog.inactivity.result.back"
            and callback == "catalog:inactivity:list"
            and presentation == "nav"
            and label_id == "back"
        ) or (
            page_id == "catalog.inactivity.result.home"
            and callback == "menu:main"
            and presentation == "nav"
            and label_id == "home"
        ):
            kb.button(text=_nav(label_id), callback_data=callback, style=str(page["style"]))
        else:
            raise ValueError("feature registry has an unregistered inactivity-compare renderer")
    kb.adjust(2)
    return kb.as_markup()


@router.callback_query(OwnerFilter(), F.data == "catalog:inactivity:list")
async def on_inactivity_list(cq: CallbackQuery):
    if not await _admin_owner(cq):
        return
    _, text, markup = inactivity_history_screen(cq.from_user.id)
    await _replace_callback_message(cq, text, reply_markup=markup)
    await cq.answer()


@router.callback_query(OwnerFilter(), F.data == "catalog:inactivity:capture")
async def on_inactivity_capture(cq: CallbackQuery):
    if not await _admin_owner(cq):
        return
    snapshot = devices.capture_inactivity_snapshot()
    access_store.append_audit(
        "device_inactivity_snapshot", actor_id=cq.from_user.id,
        detail=f"platforms={len(snapshot.get('counts', {}))}",
    )
    _, text, markup = inactivity_history_screen(cq.from_user.id)
    await _replace_callback_message(cq, text, reply_markup=markup)
    await cq.answer()


@router.callback_query(OwnerFilter(), F.data == "catalog:inactivity:compare")
async def on_inactivity_compare(cq: CallbackQuery):
    if not await _admin_owner(cq):
        return
    rows = devices.list_inactivity_snapshots(limit=2)
    if len(rows) < 2:
        await cq.answer("Нужно минимум два сохранённых снимка.", show_alert=True)
        return
    try:
        delta = devices.compare_inactivity_snapshots(rows[1]["snapshot_id"], rows[0]["snapshot_id"])
    except (KeyError, ValueError):
        await cq.answer("Снимок устарел. Обнови историю и попробуй ещё раз.", show_alert=True)
        return
    lines = ["<b>Изменение между двумя последними снимками</b>", "Разница = новый снимок минус предыдущий."]
    for platform, buckets in sorted(delta.items()):
        values = ", ".join(f"{key}: {value:+d}" for key, value in sorted(buckets.items()))
        lines.append(f"\n{html.escape(platform)}: {html.escape(values)}")
    if not delta:
        lines.append("\nНет данных для сравнения.")
    await _replace_callback_message(
        cq, "\n".join(lines), reply_markup=inactivity_compare_keyboard(cq.from_user.id)
    )
    await cq.answer()


def _typed_fields_text(device_id: str, schemas: dict, values: dict) -> str:
    info = devices.get(device_id) or {}
    device_name = html.escape(str(info.get("name") or device_id))
    lines = [
        f"<b>Поля инвентаря · {device_name}</b>",
        "Значения видны только владельцу и не отправляются агенту.",
    ]
    if not schemas:
        lines.append("\nПока полей нет. Создай поле типа enum, date или boolean.")
    else:
        for key in sorted(schemas):
            schema = schemas[key]
            value = values.get(key, "—")
            if type(value) is bool:
                value = "Да" if value else "Нет"
            lines.append(f"\n• <code>{html.escape(key)}</code> · {html.escape(schema['type'])}: {html.escape(str(value))}")
    return "\n".join(lines)


