@router.message(OwnerFilter(), Form.wait_typed_field_definition)
async def on_typed_field_definition_input(message: Message, state: FSMContext):
    data = await state.get_data()
    device_id = data.get("typed_field_device")
    if not device_id or devices.get(device_id) is None:
        await state.clear()
        await _replace_user_card(message, "Устройство уже недоступно. Начни из актуальной карточки.", reply_markup=devices_menu(message.from_user.id))
        return
    parts = [part.strip() for part in (message.text or "").split("|")]
    if len(parts) not in {2, 3}:
        await _replace_user_card(message, "Неверный формат. Используй: <code>key | enum | option1, option2</code> или <code>key | date</code>/<code>boolean</code>.")
        return
    key, field_type = parts[:2]
    choices = [item.strip() for item in parts[2].split(",")] if len(parts) == 3 else None
    try:
        devices.define_typed_field(message.from_user.id, ADMIN_ID, key, field_type, choices=choices)
    except ValueError as exc:
        await _replace_user_card(message, f"Поле не создано: {html.escape(str(exc))}. Попробуй ещё раз.")
        return
    audit("device_typed_field_defined", actor_id=message.from_user.id, device_id=device_id, field=key, field_type=field_type)
    schemas, values, keys, markup = typed_fields_menu(message.from_user.id, device_id)
    await state.clear()
    await state.update_data(typed_field_device=device_id, typed_field_keys=keys)
    await _replace_user_card(message, _typed_fields_text(device_id, schemas, values), reply_markup=markup)


@router.callback_query(OwnerFilter(), F.data.startswith("catalog:fields:edit:"))
async def on_typed_field_edit(cq: CallbackQuery, state: FSMContext):
    data = await state.get_data()
    device_id = data.get("typed_field_device")
    keys = data.get("typed_field_keys")
    raw_index = cq.data.rsplit(":", 1)[-1]
    schemas = devices.typed_field_schemas(cq.from_user.id, ADMIN_ID) or {}
    if (not device_id or devices.get(device_id) is None or not isinstance(keys, list)
            or not raw_index.isdigit() or int(raw_index) >= len(keys)
            or keys != sorted(schemas)):
        await cq.answer("Схема или карточка изменилась. Обнови список полей.", show_alert=True)
        return
    key = keys[int(raw_index)]
    schema = schemas[key]
    await state.update_data(typed_field_key=key, typed_field_type=schema["type"], typed_field_choices=schema["choices"])
    if schema["type"] == "date":
        await state.set_state(Form.wait_typed_field_value)
        prompt = f"Отправь дату для <code>{html.escape(key)}</code> в формате <code>YYYY-MM-DD</code>."
        await _replace_callback_message(cq, prompt, reply_markup=back_to_device_kb())
    else:
        choices = schema["choices"] if schema["type"] == "enum" else [False, True]
        kb = InlineKeyboardBuilder()
        for index, value in enumerate(choices):
            label = ("Да" if value else "Нет") if type(value) is bool else str(value)
            kb.button(text=_limit_button_label(label), callback_data=f"catalog:fields:value:{index}", style="primary")
        kb.button(text=_nav("cancel"), callback_data="catalog:fields:list", style="danger")
        kb.adjust(1)
        await _replace_callback_message(
            cq, f"Выбери значение для <code>{html.escape(key)}</code> ({schema['type']}):",
            reply_markup=kb.as_markup(),
        )
    await cq.answer()


async def _save_typed_field_value(cq, state: FSMContext, value) -> bool:
    data = await state.get_data()
    device_id, key, field_type = data.get("typed_field_device"), data.get("typed_field_key"), data.get("typed_field_type")
    schemas = devices.typed_field_schemas(cq.from_user.id, ADMIN_ID) or {}
    if (not device_id or devices.get(device_id) is None or key not in schemas
            or schemas[key]["type"] != field_type):
        await cq.answer("Схема или карточка изменилась. Начни заново.", show_alert=True)
        return False
    try:
        saved = devices.set_typed_field(cq.from_user.id, ADMIN_ID, device_id, key, value)
    except ValueError as exc:
        await cq.answer(str(exc), show_alert=True)
        return False
    if not saved:
        await cq.answer("Поле или устройство недоступно.", show_alert=True)
        return False
    audit("device_typed_field_saved", actor_id=cq.from_user.id, device_id=device_id, field=key)
    await state.clear()
    await _show_typed_fields(cq, state, device_id)
    await cq.answer("Сохранено.")
    return True


@router.callback_query(OwnerFilter(), F.data.startswith("catalog:fields:value:"))
async def on_typed_field_value_choice(cq: CallbackQuery, state: FSMContext):
    data = await state.get_data()
    choices = data.get("typed_field_choices")
    field_type = data.get("typed_field_type")
    raw_index = cq.data.rsplit(":", 1)[-1]
    allowed = choices if field_type == "enum" else [False, True] if field_type == "boolean" else []
    if not isinstance(choices, list) or not raw_index.isdigit() or int(raw_index) >= len(allowed):
        await cq.answer("Выбор устарел. Открой поле заново.", show_alert=True)
        return
    value = allowed[int(raw_index)]
    await _save_typed_field_value(cq, state, value)


