async def on_typed_field_date_input(message: Message, state: FSMContext):
    data = await state.get_data()
    device_id, key = data.get("typed_field_device"), data.get("typed_field_key")
    if not device_id or devices.get(device_id) is None:
        await state.clear()
        await _replace_user_card(message, "Карточка устарела. Открой устройство заново.", reply_markup=devices_menu(message.from_user.id))
        return
    value = (message.text or "").strip()
    try:
        saved = devices.set_typed_field(message.from_user.id, ADMIN_ID, device_id, key, value)
    except ValueError as exc:
        await _replace_user_card(message, f"Дата не сохранена: {html.escape(str(exc))}. Нужен формат <code>YYYY-MM-DD</code>.")
        return
    if not saved:
        await state.clear()
        await _replace_user_card(message, "Поле устарело. Открой карточку заново.", reply_markup=device_menu(device_id))
        return
    audit("device_typed_field_saved", actor_id=message.from_user.id, device_id=device_id, field=key)
    await state.clear()
    schemas, values, keys, markup = typed_fields_menu(message.from_user.id, device_id)
    await state.update_data(typed_field_device=device_id, typed_field_keys=keys)
    await _replace_user_card(message, _typed_fields_text(device_id, schemas, values), reply_markup=markup)


