@router.callback_query(OwnerFilter(), F.data.startswith("catalog:export"))
async def on_device_catalog_export(cq: CallbackQuery):
    user_id = int(cq.from_user.id)
    message_id = int(cq.message.message_id)
    if (user_id != int(ADMIN_ID) or int(ADMIN_ID) <= 0 or get_user_role(user_id) != Role.OWNER
            or not access_store.can_use_callback(user_id, cq.data, ADMIN_ID, None)):
        await cq.answer("Экспорт каталога доступен только владельцу.", show_alert=True)
        return

    if cq.data == "catalog:export":
        snapshot = _device_export_snapshot(user_id)
        if snapshot is None:
            await cq.answer("Каталог недоступен или превышает лимит выгрузки.", show_alert=True)
            return
        rows, token = snapshot
        state = {"fields": [], "format": "json", "inventory_token": token,
                 "message_id": message_id, "expires_at": time.time() + 600}
        DEVICE_EXPORT_SESSIONS[user_id] = state
        await _replace_callback_message(
            cq, device_catalog_export_text(rows, state),
            reply_markup=device_catalog_export_keyboard(user_id, state),
        )
        await cq.answer()
        return

    state = DEVICE_EXPORT_SESSIONS.get(user_id)
    if (not isinstance(state, dict) or state.get("message_id") != message_id
            or type(state.get("expires_at")) not in (int, float) or state["expires_at"] < time.time()):
        DEVICE_EXPORT_SESSIONS.pop(user_id, None)
        await cq.answer("Экран экспорта истёк. Открой его заново.", show_alert=True)
        return
    snapshot = _device_export_snapshot(user_id)
    if snapshot is None or snapshot[1] != state.get("inventory_token"):
        DEVICE_EXPORT_SESSIONS.pop(user_id, None)
        await cq.answer("Каталог изменился. Открой экспорт заново.", show_alert=True)
        return
    rows, _token = snapshot

    if cq.data.startswith("catalog:export:field:"):
        field = cq.data.removeprefix("catalog:export:field:")
        if field not in _DEVICE_EXPORT_FIELDS:
            await cq.answer("Неизвестное поле экспорта.", show_alert=True)
            return
        if field in state["fields"]:
            state["fields"].remove(field)
        else:
            state["fields"].append(field)
        state["fields"] = [name for name in _DEVICE_EXPORT_FIELDS if name in state["fields"]]
    elif cq.data in {"catalog:export:format:json", "catalog:export:format:csv"}:
        state["format"] = cq.data.rsplit(":", 1)[-1]
    elif cq.data == "catalog:export:cancel":
        DEVICE_EXPORT_SESSIONS.pop(user_id, None)
        await _replace_callback_message(cq, "Экспорт отменён.", reply_markup=devices_menu(user_id))
        await cq.answer()
        return
    elif cq.data == "catalog:export:run":
        if not state["fields"]:
            await cq.answer("Сначала выбери хотя бы одно поле.", show_alert=True)
            return
        filename, payload = _build_device_catalog_export(rows, state["fields"], state["format"])
        try:
            await _replace_callback_with_media(
                cq, bot.send_document,
                document=BufferedInputFile(payload, filename=filename),
                caption=f"Экспорт каталога · {len(rows)} записей · поля: {html.escape(', '.join(state['fields']))}",
                delivery_guard=lambda: access_store.can_use_callback(user_id, "catalog:export:run", ADMIN_ID, None),
                raise_delivery_error=True,
            )
        except Exception:
            log.exception("Не удалось доставить owner device-catalog export")
            await cq.answer("Файл не отправлен; карточка сохранена. Попробуй ещё раз.", show_alert=True)
            return
        DEVICE_EXPORT_SESSIONS.pop(user_id, None)
        audit("device_catalog_exported", actor_id=user_id,
              fields=",".join(state["fields"]), export_format=state["format"], row_count=len(rows))
        await cq.answer()
        return
    else:
        await cq.answer("Действие экспорта устарело.", show_alert=True)
        return

    await _replace_callback_message(
        cq, device_catalog_export_text(rows, state),
        reply_markup=device_catalog_export_keyboard(user_id, state),
    )
    await cq.answer()


