@router.message(OwnerFilter(), Form.wait_device_catalog_import)
async def on_device_catalog_import_document(message: Message, state: FSMContext):
    user_id = int(message.from_user.id)
    data = await state.get_data()
    if (user_id != int(ADMIN_ID) or int(ADMIN_ID) <= 0 or get_user_role(user_id) != Role.OWNER
            or data.get("chat_id") != int(message.chat.id)
            or type(data.get("expires_at")) not in (int, float) or data["expires_at"] < time.time()):
        await state.clear()
        return
    document = message.document
    if document is None:
        await _replace_user_card(message, "Пришли экспортированный .json или .csv как файл.", reply_markup=device_catalog_import_keyboard(user_id))
        return
    if document.file_size is not None and int(document.file_size) > device_catalog_import.MAX_IMPORT_BYTES:
        result_text = "Файл больше 1 МиБ — отклонён, каталог не изменён."
    else:
        try:
            buffer = await bot.download(document)
            payload = buffer.getvalue() if hasattr(buffer, "getvalue") else buffer.read()
            imported = device_catalog_import.parse_device_catalog_import(payload, document.file_name or "")
            snapshot = _device_export_snapshot(user_id)
            if snapshot is None or snapshot[1] != data.get("inventory_token"):
                raise ValueError("Каталог изменился после открытия сверки; открой её заново.")
            current = {device_id: info for device_id, info in snapshot[0]}
            result = device_catalog_import.compare_device_catalogs(imported, current)
            result_text = device_catalog_import_preview_text(result, len(imported))
            audit("device_catalog_import_previewed", actor_id=user_id, row_count=len(imported),
                  new_count=len(result["new_ids"]), missing_count=len(result["missing_ids"]),
                  conflict_count=len(result["conflicts"]))
        except ValueError as exc:
            result_text = f"Файл отклонён: {html.escape(str(exc))}. Каталог не изменён."
        except Exception:
            log.exception("Не удалось обработать owner device-catalog import preview")
            result_text = "Не удалось прочитать файл; каталог не изменён. Проверь формат и повтори."

    try:
        await message.delete()
    except Exception:
        log.info("Incoming catalog comparison document could not be deleted")
    await state.clear()
    card_id = data.get("message_id")
    if type(card_id) is int:
        await _replace_message_card(
            _card_message(message, card_id), user_id, result_text,
            reply_markup=devices_menu(user_id),
        )


