@router.callback_query(OwnerFilter(), F.data.startswith("catalog:snapshot:toggle:"))
async def on_device_snapshot_toggle(cq: CallbackQuery, state: FSMContext):
    data = await state.get_data()
    available = data.get("snapshot_device_ids")
    selected = data.get("selected_snapshot_device_ids")
    raw_index = cq.data.rsplit(":", 1)[-1]
    if (await state.get_state()) != Form.wait_device_snapshot_selection.state or not isinstance(available, list) or not isinstance(selected, list) or not raw_index.isdigit():
        await cq.answer("Сессия выбора истекла. Начни заново.", show_alert=True)
        return
    index = int(raw_index)
    visible = _visible_device_items(cq.from_user.id)
    if sorted(visible) != available:
        await state.clear()
        await cq.answer(
            _ui_phrase(
                "The device list changed. Start the selection again.",
                "Список устройств изменился. Начни выбор заново.",
                "Список устройств поменялся — начни заново.",
            ),
            show_alert=True,
        )
        return
    if index >= len(available) or available[index] not in visible:
        await cq.answer("Устройство больше недоступно — обнови набор.", show_alert=True)
        return
    device_id = available[index]
    if device_id in selected:
        selected.remove(device_id)
    else:
        selected.append(device_id)
    await state.update_data(selected_snapshot_device_ids=selected)
    await _replace_callback_message(
        cq,
        f"<b>Новый набор устройств</b>\n\nВыбрано: {len(selected)}. Состав можно менять до сохранения.",
        reply_markup=device_snapshot_selection_menu(cq.from_user.id, selected),
    )
    await cq.answer()


