@router.message(OwnerFilter(), Form.wait_device_snapshot_name)
async def on_device_snapshot_name_input(message: Message, state: FSMContext):
    data = await state.get_data()
    name = " ".join((message.text or "").split())
    selected = data.get("selected_snapshot_device_ids")
    if not name or len(name) > 80 or not isinstance(selected, list):
        await _replace_user_card(message, "Название должно быть от 1 до 80 символов. Отправь его ещё раз.", reply_markup=back_to_device_kb())
        return
    try:
        saved = devices.save_selected_snapshot(
            message.from_user.id, ADMIN_ID, name, selected,
        )
    except ValueError:
        saved = None
    await state.clear()
    if saved is None:
        await _replace_user_card(message, "Набор не сохранён: состав устарел или пуст. Начни создание заново.", reply_markup=devices_menu(message.from_user.id))
        return
