@router.callback_query(OwnerFilter(), F.data == "display:region:begin")
async def on_display_region_begin(cq: CallbackQuery, state: FSMContext):
    data = await state.get_data()
    target = str(data.get("authorization_target") or "")
    catalog = data.get("display_catalog")
    selected = data.get("display_selected")
    if (await state.get_state() != Form.wait_display_selection.state
            or data.get("display_mode") != "single"
            or not _pending_device_input_still_allowed(cq.message, data, target)
            or not isinstance(catalog, dict) or not isinstance(selected, list) or len(selected) != 1):
        await state.clear()
        await _replace_callback_message(cq, "⚠️ Выбор экрана устарел или доступ изменился; снимок области не сделан.",
                                        reply_markup=back_to_device_kb())
        await cq.answer("Устарело", show_alert=True)
        return
    device = devices.get(target) or {}
    if _device_declares_command(device, "display_region_screenshot") is False:
        await state.clear()
        await _replace_callback_message(cq, "⚠️ Обнови агент: он ещё не поддерживает снимок области экрана.",
                                        reply_markup=back_to_device_kb())
        await cq.answer("Нужна новая версия агента", show_alert=True)
        return
    display = next((row for row in catalog.get("displays", [])
                    if isinstance(row, dict) and row.get("id") == selected[0]), None)
    if not display:
        await state.clear()
        await _replace_callback_message(cq, "⚠️ Экран не найден в актуальном каталоге; запроси список заново.",
                                        reply_markup=back_to_device_kb())
        await cq.answer("Каталог устарел", show_alert=True)
        return
    await _start_authorized_input(
        state, Form.wait_display_region_input, "display:screenshot", target,
        display_catalog=catalog, display_selected=selected, display_mode="single",
        display_region_id=selected[0], display_region_dimensions={"width": display["width"], "height": display["height"]},
    )
    prompt = (
        f"▧ Область экрана {display['width']}×{display['height']} · {html.escape(selected[0])}\n"
        "Введи координаты как `x, y, ширина, высота` в пикселях. Будет снята и отправлена только эта область."
    )
    await _replace_callback_message(cq, prompt, delivery_guard=_callback_delivery_guard(cq, target),
                                    reply_markup=_display_region_cancel_keyboard())
    await cq.answer("Жду координаты")


def _display_region_cancel_keyboard():
    kb = InlineKeyboardBuilder()
    kb.button(text=_ui_phrase("✖ Cancel", "✖ Cancelar", "✖ Отмена"), callback_data="display:cancel", style="danger")
    kb.adjust(1)
    return kb.as_markup()


@router.message(OwnerFilter(), Form.wait_display_region_input)
async def on_display_region_input(message: Message, state: FSMContext):
    owner_id = int(message.from_user.id)
    data = await state.get_data()
    target = str(data.get("authorization_target") or "")
    catalog = data.get("display_catalog")
    display_id = data.get("display_region_id")
    dimensions = data.get("display_region_dimensions")
    if (not _pending_device_input_still_allowed(message, data, target)
            or not isinstance(catalog, dict) or not isinstance(dimensions, dict)
            or not isinstance(display_id, str)
            or await state.get_state() != Form.wait_display_region_input.state):
        await state.clear()
        await _reject_revoked_device_input(message)
        return
    try:
        region = _parse_display_region_input(message.text or "", width=dimensions.get("width"),
                                             height=dimensions.get("height"))
    except ValueError as exc:
        await _replace_user_card(
            message,
            f"⚠️ {html.escape(str(exc))}\nВведи область как `x, y, ширина, высота` или отмени запрос.",
            reply_markup=_display_region_cancel_keyboard(),
            delivery_guard=lambda: _pending_device_input_still_allowed(message, data, target),
        )
        return
    if _device_declares_command(devices.get(target) or {}, "display_region_screenshot") is False:
        await state.clear()
        await _replace_user_card(message, "⚠️ Обнови агент: он ещё не поддерживает снимок области экрана.",
                                 reply_markup=back_to_device_kb())
        return
    if not _pending_device_input_still_allowed(message, data, target):
        await state.clear()
        await _reject_revoked_device_input(message)
        return
    await _replace_user_card(
        message, "▧ Снимаю только выбранную область…",
        reply_markup=_display_region_cancel_keyboard(),
        delivery_guard=lambda: _pending_device_input_still_allowed(message, data, target),
    )
    if await state.get_state() != Form.wait_display_region_input.state:
        return
    sent, request_id = publish_tracked(
        "display_region_screenshot", _target=target,
        display_id=display_id, topology_id=catalog.get("topology_id"), region=region,
    )
    if not sent:
        await state.clear()
        await _replace_user_card(message, _lex("mqtt_disconnected"), reply_markup=back_to_device_kb())
        return
    try:
        result = await display_region_screenshot_collector.wait_for(target, "display_region_screenshot", 20.0, request_id)
        if await state.get_state() != Form.wait_display_region_input.state:
            return
        if not _pending_device_input_still_allowed(message, data, target):
            await _report_revoked_after_publish(message)
            return
        expected_region = {"id": display_id, **region}
        image = _validate_display_region_screenshot_result(
            result, expected_device_id=target, expected_request_id=request_id,
            expected_region=expected_region, expected_source=catalog.get("source"),
        )
        if not _pending_device_input_still_allowed(message, data, target):
            await _report_revoked_after_publish(message)
            return
        await _replace_user_card_with_photo(
            message, image,
            caption=f"▧ Область {region['width']}×{region['height']} · {html.escape(target_label(target))}",
            reply_markup=back_to_device_kb(),
            delivery_guard=lambda: _pending_device_input_still_allowed(message, data, target),
        )
    except Exception as exc:
        log.warning("Display region screenshot unavailable: %s", type(exc).__name__)
        await _replace_user_card(
            message, f"⚠️ {html.escape(str(exc)[:240]) or 'Не удалось получить снимок области.'}",
            reply_markup=back_to_device_kb(),
            delivery_guard=lambda: _pending_device_input_still_allowed(message, data, target),
        )
    finally:
        await state.clear()


