@router.callback_query(OwnerFilter(), F.data == "window:screenshot")
async def on_window_catalog(cq: CallbackQuery, state: FSMContext):
    owner_id = int(cq.from_user.id)
    target = str(SESSION.get("target") or "")
    if not target or target == "all" or devices.get(target) is None:
        await cq.answer(_lex("single_device_only"), show_alert=True)
        return
    if not await _callback_result_access_or_report(cq, target):
        return
    os_name = str((devices.get(target) or {}).get("os") or "").lower()
    expected_source = "windows_enum_windows" if "win" in os_name else "macos_quartz_window_list" if "mac" in os_name or "darwin" in os_name else None
    if expected_source is None:
        await _replace_callback_message(cq, "⚠️ Выбор окна доступен только на Windows/macOS.", reply_markup=back_to_device_kb())
        await cq.answer()
        return
    if _device_declares_command(devices.get(target) or {}, "window_catalog") is False:
        await _replace_callback_message(cq, "⚠️ Обнови агент: он ещё не поддерживает выбор окна.", reply_markup=back_to_device_kb())
        await cq.answer("Нужна новая версия", show_alert=True)
        return
    await cq.answer("Получаю список окон…")
    sent, request_id = publish_tracked("window_catalog", _target=target)
    if not sent:
        await _replace_callback_message(cq, _lex("mqtt_disconnected"), reply_markup=back_to_device_kb())
        return
    result = await window_catalog_collector.wait_for(target, "window_catalog", 15.0, request_id)
    if not await _callback_result_access_or_report(cq, target, published=True):
        return
    try:
        catalog = _parse_window_catalog_result(result, expected_device_id=target,
                                                expected_request_id=request_id, expected_source=expected_source)
    except ValueError as exc:
        await state.clear()
        await _replace_callback_message(cq, f"⚠️ {html.escape(str(exc))}",
                                        delivery_guard=_callback_delivery_guard(cq, target),
                                        reply_markup=back_to_device_kb())
        return
    await state.clear()
    await _start_authorized_input(state, Form.wait_window_selection, "window:screenshot", target,
                                  window_catalog=catalog, window_selected=None)
    lines = ["Выбери одно окно. Снимок появится только после отдельного нажатия; целый экран не захватывается."]
    lines.extend(f"• {html.escape(row['title'])} · {html.escape(row['app'])} · {row['width']}×{row['height']}"
                 for row in catalog["windows"])
    await _replace_callback_message(cq, "\n".join(lines), delivery_guard=_callback_delivery_guard(cq, target),
                                    reply_markup=_window_selection_keyboard(catalog["windows"]))


