@router.message(OwnerFilter(), Form.wait_screenshot_annotation_input)
async def on_screenshot_annotation_input(message: Message, state: FSMContext):
    owner_id = int(message.from_user.id)
    data = await state.get_data()
    token = str(data.get("annotation_token") or "")
    target = str(data.get("authorization_target") or "")
    chat_id = int(data.get("annotation_chat_id") or 0)
    message_id = int(data.get("annotation_message_id") or 0)
    entry = _get_screenshot_delivery_cache(owner_id, token, chat_id=chat_id, message_id=message_id)
    if (
        not entry or entry.get("target") != target or int(message.chat.id) != chat_id
        or not _pending_device_input_still_allowed(message, data, target)
    ):
        _clear_screenshot_delivery_cache(owner_id, token=token)
        await state.clear()
        await _replace_user_card(message, "⚠️ Preview устарел или доступ изменился; исходник удалён из памяти.", reply_markup=back_to_device_kb())
        return
    try:
        import screenshot_annotation
        annotated = screenshot_annotation.annotate_screenshot(entry["original"], str(message.text or ""))
        preview = _screenshot_delivery_preview_image(annotated)
    except ValueError as exc:
        try:
            await message.delete()
        except Exception:
            log.debug("Could not remove invalid screenshot annotation input")
        await bot.edit_message_caption(
            chat_id=chat_id, message_id=message_id,
            caption=f"⚠️ {html.escape(str(exc))}. Попробуй ещё раз или отмени.",
            reply_markup=_screenshot_mask_cancel_keyboard(),
        )
        return
    except Exception:
        log.exception("Could not annotate screenshot copy")
        _clear_screenshot_delivery_cache(owner_id, token=token)
        await state.clear()
        await _replace_user_card(message, "⚠️ Не удалось создать помеченную копию; исходник удалён из памяти.", reply_markup=back_to_device_kb())
        return
    try:
        await message.delete()
    except Exception:
        log.debug("Could not remove screenshot annotation input message")
    entry["annotated"] = annotated
    entry["preview"] = preview
    await state.clear()
    await bot.edit_message_media(
        chat_id=chat_id, message_id=message_id,
        media=InputMediaPhoto(
            media=BufferedInputFile(preview, filename="xider-annotated-preview.jpg"),
            caption=(
                f"🔎 Preview помеченной копии · {html.escape(target_label(target))}\n"
                "Исходный снимок не изменён. Выбери, какую версию отправить."
            ),
        ),
        reply_markup=_screenshot_preview_keyboard(
            token, has_annotation=True, has_comparison=bool(entry.get("comparison")),
        ),
    )
    ui_cards.set_card(chat_id, owner_id, message_id)
    audit("screenshot_annotation_created", actor_id=owner_id, device_id=target)


@router.callback_query(OwnerFilter(), F.data.startswith("screenshot:preview:send:"))
async def on_screenshot_preview_send(cq: CallbackQuery, state: FSMContext | None = None):
    owner_id = int(cq.from_user.id)
    token = str(cq.data or "").rsplit(":", 1)[-1]
    message = cq.message
    if message is None:
        await cq.answer("Preview недоступен", show_alert=True)
        return
    entry = _get_screenshot_delivery_cache(
        owner_id, token, chat_id=message.chat.id, message_id=message.message_id,
    )
    target = str(entry.get("target") or "") if entry else ""
    if not entry or not _simple_command_still_allowed(owner_id, "screenshot:preview", target):
        _clear_screenshot_delivery_cache(owner_id, token=token)
        await _replace_callback_message(
            cq, "⚠️ Preview устарел или доступ изменился; исходный файл удалён и не отправлен.",
            reply_markup=back_to_device_kb(),
        )
        await cq.answer("Preview уже недоступен", show_alert=True)
        return

    original = entry["original"]
    try:
        await bot.edit_message_media(
            chat_id=message.chat.id,
            message_id=message.message_id,
            media=InputMediaDocument(
                media=BufferedInputFile(original, filename=_screenshot_filename(original)),
                caption=f"📸 Исходный снимок · {html.escape(target_label(target))}",
            ),
            reply_markup=back_to_device_kb(),
        )
        ui_cards.set_card(message.chat.id, owner_id, message.message_id)
        audit("screenshot_original_confirmed", actor_id=owner_id, device_id=target)
    except Exception as exc:
        log.exception("Screenshot original delivery was not confirmed")
        await _replace_callback_message(
            cq,
            "⚠️ Telegram не подтвердил замену preview исходным файлом. Исходник удалён из памяти; проверь карточку перед повторным запросом.",
            reply_markup=back_to_device_kb(),
        )
        audit("screenshot_original_delivery_unknown", actor_id=owner_id, device_id=target, error_type=type(exc).__name__)
    finally:
        if state is not None:
            await state.clear()
        _clear_screenshot_delivery_cache(owner_id, token=token)
    await cq.answer("Подтверждено")


