@router.callback_query(OwnerFilter(), F.data.startswith("screenshot:mask:send:"))
async def on_screenshot_mask_send(cq: CallbackQuery, state: FSMContext):
    owner_id = int(cq.from_user.id)
    token = str(cq.data or "").rsplit(":", 1)[-1]
    data = await state.get_data()
    target = str(data.get("authorization_target") or "")
    entry = _get_screenshot_mask_cache(owner_id, token, phase="preview")
    if (
        await state.get_state() != Form.wait_screenshot_mask_confirm.state
        or not entry or entry.get("target") != target or not entry.get("final_image")
        or not _simple_command_still_allowed(owner_id, "screenshot:mask", target)
    ):
        _clear_screenshot_mask_cache(owner_id)
        await state.clear()
        await _replace_callback_message(cq, "⚠️ Preview устарел или доступ изменился; ничего не отправлено.", reply_markup=back_to_device_kb())
        await cq.answer("Устарело", show_alert=True)
        return
    final_image = entry["final_image"]
    try:
        await bot.edit_message_media(
            chat_id=cq.message.chat.id,
            message_id=cq.message.message_id,
            media=InputMediaPhoto(
                media=BufferedInputFile(final_image, filename=_screenshot_filename(final_image)),
                caption=f"📸 Маскированный скриншот · {html.escape(target_label(target))}",
            ),
            reply_markup=back_to_device_kb(),
        )
        ui_cards.set_card(cq.message.chat.id, owner_id, cq.message.message_id)
    except Exception:
        log.exception("Ошибка доставки подтверждённого маскированного снимка")
        await _replace_callback_message(cq, "⚠️ Не получилось отправить итоговый снимок. Временные данные удалены.", reply_markup=back_to_device_kb())
    finally:
        _clear_screenshot_mask_cache(owner_id)
        await state.clear()
    await cq.answer("Подтверждено")


def _format_media_temp_cleanup_result(
    result: dict | None, *, expected_device_id: str, expected_request_id: str,
    now: datetime.datetime | None = None,
) -> str:
    if not isinstance(result, dict):
        return "⚠️ Устройство не вернуло подтверждённый отчёт; результат очистки неизвестен."
    if (
        result.get("schema") != "xider.media-temp-cleanup.v1"
        or result.get("feature_id") != "D02-F23"
        or result.get("device_id") != expected_device_id
        or result.get("request_id") != expected_request_id
        or result.get("id") != expected_request_id
        or result.get("source") != "xider_owned_media_temp_v1"
    ):
        return "⚠️ Ответ очистки устарел, не совпал с устройством/запросом или имеет неизвестную схему."
    data = result.get("data")
    if not isinstance(data, dict):
        return "⚠️ Отчёт очистки имеет неизвестный формат."
    counts = {key: data.get(key) for key in ("scanned", "deleted", "skipped", "failed")}
    if any(isinstance(value, bool) or not isinstance(value, int) or not 0 <= value <= 512 for value in counts.values()):
        return "⚠️ Отчёт содержит некорректные счётчики; ничего не подтверждаю."
    if counts["deleted"] + counts["skipped"] + counts["failed"] > counts["scanned"] + 1:
        return "⚠️ Отчёт содержит противоречивые счётчики; результат неизвестен."
    try:
        checked_at = datetime.datetime.fromisoformat(str(result.get("checked_at")))
        if checked_at.tzinfo is None:
            return "⚠️ В отчёте отсутствует часовой пояс; результат неизвестен."
    except (TypeError, ValueError):
        return "⚠️ Время проверки в отчёте некорректно; результат неизвестен."
    current_time = now or datetime.datetime.now(datetime.timezone.utc)
    if current_time.tzinfo is None:
        raise ValueError("current time must be timezone-aware")
    age_seconds = (current_time.astimezone(datetime.timezone.utc) - checked_at.astimezone(datetime.timezone.utc)).total_seconds()
    if age_seconds < -60 or age_seconds > 120:
        return "⚠️ Отчёт очистки устарел или имеет время из будущего; результат неизвестен."
    if result.get("state") == "success" and data.get("state") == "success":
        status = "✅ Очистка завершена"
    elif result.get("state") in {"partial", "error"} and data.get("state") == result.get("state"):
        status = "⚠️ Очистка завершилась частично или с ошибкой"
    else:
        return "⚠️ Состояние очистки неизвестно; отчёт не подтверждён."
    return (
        f"{status}. Проверено собственных media-temp файлов: {counts['scanned']}; "
        f"удалено просроченных: {counts['deleted']}; пропущено: {counts['skipped']}; "
        f"ошибок: {counts['failed']}.\nПути и содержимое файлов не собирались. "
        f"Проверено: {checked_at.astimezone(datetime.timezone.utc).isoformat()} UTC."
    )


_MEDIA_HISTORY_ACTION_LABELS = {
    "screenshot": "скриншот", "display_region_screenshot": "область экрана",
    "window_screenshot": "снимок окна", "display_contact_sheet": "контакт-лист экранов",
    "webcam": "камера", "camera_series": "серия кадров", "camera_quality": "проверка камеры",
    "microphone_catalog": "список микрофонов", "mic": "запись микрофона",
    "microphone_level": "уровень микрофона", "microphone_balance": "баланс микрофона",
    "microphone_test": "проверка микрофона", "audio_output_catalog": "список аудиовыходов",
    "audio_output_switch": "переключение аудиовыхода", "media_temp_cleanup": "очистка media-temp",
}
_MEDIA_HISTORY_OUTCOMES = {
    "captured": "захвачено", "completed": "завершено", "unavailable": "недоступно",
    "denied": "отказано", "unknown": "неизвестно", "failed": "ошибка",
}


def _validated_media_history_result(
    result: object, *, expected_device_id: str, expected_request_id: str,
    now: datetime.datetime | None = None,
) -> tuple[list[dict[str, str]], datetime.datetime] | None:
    if (not isinstance(result, dict)
            or result.get("type") != "media_history"
            or result.get("schema") != "xider.media-history.v1"
            or result.get("feature_id") != "D02-F24"
            or result.get("device_id") != expected_device_id
            or result.get("request_id") != expected_request_id
            or result.get("id") != expected_request_id
            or result.get("state") != "supported"
            or result.get("source") != "local_metadata_journal"):
        return None
    try:
        checked_at = datetime.datetime.fromisoformat(str(result.get("checked_at")))
        if checked_at.tzinfo is None or checked_at.utcoffset() is None:
            return None
    except (TypeError, ValueError):
        return None
    current = now or datetime.datetime.now(datetime.timezone.utc)
    if current.tzinfo is None or current.utcoffset() is None:
        raise ValueError("current time must be timezone-aware")
    age = (current.astimezone(datetime.timezone.utc) - checked_at.astimezone(datetime.timezone.utc)).total_seconds()
    if age < -60 or age > 120:
        return None
    data = result.get("data")
    events = data.get("events") if isinstance(data, dict) else None
    if not isinstance(events, list) or len(events) > 50:
        return None
    validated = []
    for event in events:
        if not isinstance(event, dict):
            return None
        action, outcome = event.get("action"), event.get("outcome")
        if action not in _MEDIA_HISTORY_ACTION_LABELS or outcome not in _MEDIA_HISTORY_OUTCOMES:
            return None
        try:
            at = datetime.datetime.fromisoformat(str(event.get("at")))
            if at.tzinfo is None or at.utcoffset() is None:
                return None
        except (TypeError, ValueError):
            return None
        at_utc = at.astimezone(datetime.timezone.utc)
        if at_utc > current.astimezone(datetime.timezone.utc) + datetime.timedelta(seconds=60):
            return None
        if at_utc < current.astimezone(datetime.timezone.utc) - datetime.timedelta(days=30, minutes=1):
            return None
        validated.append({"at": at_utc.isoformat(timespec="seconds"), "action": action, "outcome": outcome})
    return validated, checked_at.astimezone(datetime.timezone.utc)


def _format_media_history_result(
    result: object, *, expected_device_id: str, expected_request_id: str,
    now: datetime.datetime | None = None,
) -> str:
    validated = _validated_media_history_result(
        result, expected_device_id=expected_device_id, expected_request_id=expected_request_id, now=now,
    )
    if validated is None:
        return "⚠️ История не подтверждена: ответ устарел, не совпал с устройством/запросом или имеет неизвестный формат."
    events, checked_at = validated
    if not events:
        return f"🧾 История медиа пуста за последние 30 дней. Проверено: {checked_at.isoformat()} UTC."
    lines = [
        f"• {event['at']} · {_MEDIA_HISTORY_ACTION_LABELS[event['action']]} — {_MEDIA_HISTORY_OUTCOMES[event['outcome']]}"
        for event in events[:20]
    ]
    return "🧾 <b>История медиа · только время, действие и исход</b>\n" + "\n".join(lines)


@router.callback_query(OwnerFilter(), F.data == "media:history")
async def on_media_history(cq: CallbackQuery):
    target = str(SESSION.get("target") or "")
    if not target or target == "all" or devices.get(target) is None:
        await cq.answer(_lex("single_device_only"), show_alert=True)
        return
    if not await _callback_result_access_or_report(cq, target):
        return
    if _device_declares_command(devices.get(target) or {}, "media_history") is not True:
        await cq.answer("Этот агент не объявляет поддержку истории медиа; запрос не отправлен.", show_alert=True)
