    if not sent:
        await _replace_callback_message(cq, _lex("mqtt_disconnected"), reply_markup=back_to_device_kb())
        return
    guard = _callback_delivery_guard(cq, target)
    await _replace_callback_message(cq, "⏳ Читаю локальную историю медиа: только время, действие и исход…",
                                    delivery_guard=guard, reply_markup=back_to_device_kb())
    result = await media_history_collector.wait_for(target, "media_history", 8.0, command_id)
    if not await _callback_result_access_or_report(cq, target, published=True):
        return
    text = _format_media_history_result(result, expected_device_id=target, expected_request_id=command_id)
    await _replace_callback_message(cq, text, delivery_guard=guard, reply_markup=back_to_device_kb())


