@router.callback_query(OwnerFilter(), F.data.startswith("agentfiles:file:"))
async def on_agent_file_content(cq: CallbackQuery):
    parts = str(cq.data or "").split(":")
    if (len(parts) != 6 or not parts[2].isalnum()
            or not parts[3].isdigit() or not parts[4].isdigit()
            or _AGENT_FILE_ID_RE.fullmatch(parts[5]) is None):
        await cq.answer(_lex("agent_files_invalid_file"), show_alert=True)
        return
    token, index, file_index, file_id = parts[2], int(parts[3]), int(parts[4]), parts[5]
    owner_id = int(cq.from_user.id)
    entry = _agent_files_view_entry(token, owner_id=owner_id)
    if entry is None or SESSION.get("target") != entry.get("target"):
        await cq.answer(_lex("agent_files_view_expired"), show_alert=True)
        return
    if not await _callback_result_access_or_report(cq, str(entry["target"])):
        return
    components = entry["report"].get("components", [])
    if (not 0 <= index < len(components)
            or not 0 <= file_index < len(components[index].get("files", []))
            or components[index]["files"][file_index].get("file_id") != file_id):
        await cq.answer(_lex("agent_files_file_not_in_snapshot"), show_alert=True)
        return

    target = str(entry["target"])
    guard = _callback_delivery_guard(cq, target)
    await cq.answer(_lex("agent_files_reading_file_toast"))
    sent, command_id = publish_tracked("agent_file_get", file_id=file_id, _target=target)
    if not sent:
        result = {"state": "publish_failed", "content": "", "truncated": False}
    else:
        payload = await fun_text_collector.wait_for(target, "agent_file_get", 12.0, command_id)
        if not await _callback_result_access_or_report(cq, target, published=True):
            return
        # A changed or expired inventory view invalidates the selected file even
        # when the agent response itself is correctly correlated.
        current_entry = _agent_files_view_entry(token, owner_id=owner_id)
        if (current_entry is None or current_entry.get("target") != target
                or SESSION.get("target") != target):
            await cq.answer(_lex("agent_files_view_expired"), show_alert=True)
            return
        if payload is None:
            result = {"state": "timeout", "content": "", "truncated": False}
        else:
            result = _agent_file_content_response(
                payload, target=target, command_id=command_id, file_id=file_id,
            ) or {"state": "invalid", "content": "", "truncated": False}
    body, markup = _agent_file_content_card(
        token, index, file_index, file_id, result, owner_id=owner_id,
    )
    if body is None:
        await cq.answer(_lex("agent_files_file_unavailable"), show_alert=True)
        return
    await _replace_callback_message(cq, body, delivery_guard=guard, reply_markup=markup)


@router.callback_query(AdminFilter(), F.data == "cmd:capabilities")
async def on_cmd_capabilities(cq: CallbackQuery):
    target = SESSION.get("target")
    if not target:
        await cq.answer(_lex("target_required"), show_alert=True)
        return
    if target == "all":
        await cq.answer(_lex("single_device_only"), show_alert=True)
        return
    await cq.answer("📊 Запрашиваю возможности...")
    if not await _callback_result_access_or_report(cq, target):
        return
    sent, command_id = publish_tracked("capabilities", _target=target)
    if not sent:
        await _replace_callback_message(cq, _lex("mqtt_disconnected"), reply_markup=back_to_device_kb())
        return
    res = await capabilities_collector.wait_for(target, "capabilities", 15.0, command_id)
    if not await _callback_result_access_or_report(cq, target, published=True):
        return
    if not res:
        user_id = int(cq.from_user.id) if cq.from_user else 0
        await _replace_callback_message(
            cq,
            _lex("device_no_response"),
            delivery_guard=_callback_delivery_guard(cq, target),
            reply_markup=_capabilities_keyboard(user_id=user_id),
        )
        return
    user_id = int(cq.from_user.id) if cq.from_user else 0
    device_record = devices.get(target) or {}
    current_companions = companion_status.clean_layer_records(res.get("companions"), now=time.time())
    cached_companions = companion_status.clean_layer_records(
        device_record.get("companion_records"), now=time.time(),
    )
    for role, record in cached_companions.items():
        current = current_companions.get(role)
        if current is None or record["last_seen"] > current["last_seen"]:
            current_companions[role] = record
    render_result = {
        **res,
        "companions": current_companions,
        "_guardian_record": device_record.get("guardian"),
        "_guardian_last_seen": device_record.get("guardian_last_seen"),
    }
    await _replace_callback_message(
        cq,
        _format_capabilities(render_result),
        delivery_guard=_callback_delivery_guard(cq, target),
        reply_markup=_capabilities_keyboard(res, user_id=user_id),
    )


@router.callback_query(OwnerFilter(), F.data.startswith("permhelp:"))
async def on_permission_help(cq: CallbackQuery):
    """Show a fixed, OS-specific permission guide on the existing bot card."""
    target = _require_target(cq)
    permission = str(cq.data or "").partition(":")[2]
    if not target:
        await cq.answer(_lex("target_required"), show_alert=True)
        return
    if permission not in _SNAPSHOT_LABELS:
        await cq.answer("Неизвестное разрешение; ничего не открыто.", show_alert=True)
        return

    info = devices.get(target)
    if not isinstance(info, dict):
        await cq.answer(_lex("device_no_response"), show_alert=True)
        return
    os_name = str(info.get("os") or "").lower()
    platform = (
        "macOS" if os_name.startswith(("mac", "darwin"))
        else "Windows" if os_name.startswith("windows")
        else None
    )
    text = _format_permission_help(platform, permission)
    if text is None:
        await cq.answer("Для этой ОС нет проверенной инструкции.", show_alert=True)
        return

    capabilities = info.get("capabilities")
    commands = capabilities.get("commands", []) if isinstance(capabilities, dict) else []
    commands = (
        {command for command in commands if isinstance(command, str)}
        if isinstance(commands, list) else set()
    )
    kb = InlineKeyboardBuilder()
    permission_state = "unknown"
    if isinstance(info.get("capabilities"), dict):
        snapshot = _parse_capability_snapshot(info["capabilities"].get("snapshot"))
        permission_state = next(
            (item["state"] for item in snapshot["items"] if item["id"] == permission),
            "unknown",
        )
    if permission in _CAPABILITY_SETTINGS.get(platform, {}) and "permission_settings" in commands:
        kb.button(
            text=_permission_action_label(platform, permission, permission_state),
            callback_data=f"permsettings:{permission}",
            style="primary",
        )
    kb.button(text=_nav("refresh"), callback_data="cmd:capabilities")
    kb.button(text=_nav("back_device"), callback_data="back:device", style="primary")
    kb.adjust(1)
    await cq.answer()
    await _replace_callback_message(cq, text, reply_markup=kb.as_markup())


@router.callback_query(OwnerFilter(), F.data.startswith("permsettings:"))
async def on_permission_settings(cq: CallbackQuery):
    """Start the OS permission flow only after the owner taps its button."""
    target = _require_target(cq)
    permission = str(cq.data or "").partition(":")[2]
    if not target:
        await cq.answer(_lex("target_required"), show_alert=True)
        return
    info = devices.get(target) or {}
    os_name = str(info.get("os") or "").lower()
    platform = (
        "macOS" if os_name.startswith(("mac", "darwin"))
        else "Windows" if os_name.startswith("windows")
        else None
    )
    if not platform or permission not in _CAPABILITY_SETTINGS[platform]:
        await cq.answer("Неизвестный раздел настроек; ничего не отправлено.", show_alert=True)
        return
    commands = (info.get("capabilities") or {}).get("commands", [])
    if not isinstance(commands, list) or "permission_settings" not in commands:
        await cq.answer()
        await _replace_callback_message(
            cq,
            "Агент пока не умеет удалённо открывать панель разрешений. Сначала обнови его, затем снова запусти проверку возможностей.",
            reply_markup=back_to_device_kb(),
        )
        return
    callback = f"permsettings:{permission}"
    if not _device_action_still_allowed(int(cq.from_user.id), callback, target):
        await cq.answer(_lex("input_access_revoked"), show_alert=True)
        return
    await cq.answer("Отправляю запрос разрешения на устройство…")
    result = await simple_command(
        cq,
        "permission_settings",
        "⚙️",
        _SNAPSHOT_LABELS[permission],
        timeout=100.0 if platform == "macOS" else 120.0 if permission == "location" else 15.0,
        permission=permission,
    )
    if not isinstance(result, dict) or result.get("ok") is not True:
        return

    # A successful settings launch creates one short-lived, owner/device/
    # permission-bound opportunity for a fresh check after the owner returns.
    token = uuid.uuid4().hex[:16]
    now = time.monotonic()
    with _PENDING_PERMISSION_RECHECKS_LOCK:
        for key, pending in list(_PENDING_PERMISSION_RECHECKS.items()):
            if float(pending.get("expires_at", 0)) <= now:
                _PENDING_PERMISSION_RECHECKS.pop(key, None)
        _PENDING_PERMISSION_RECHECKS[token] = {
            "user_id": int(cq.from_user.id), "target": target,
            "permission": permission, "expires_at": now + 600,
        }
    kb = InlineKeyboardBuilder()
    kb.button(
        text=f"✅ Вернулся — проверить: {_SNAPSHOT_LABELS[permission]}",
        callback_data=f"permverify:{token}", style="primary",
    )
    kb.button(text=f"❔ Как изменить: {_SNAPSHOT_LABELS[permission]}", callback_data=f"permhelp:{permission}")
    kb.button(text=_nav("back_device"), callback_data="back:device")
    kb.adjust(1)
    await _replace_callback_message(
        cq,
        f"{html.escape(str(result.get('text') or 'Действие ОС выполнено.'))} "
        f"После ответа проверь: {_SNAPSHOT_LABELS[permission]}. Сам факт запроса не означает, что доступ выдан.",
        reply_markup=kb.as_markup(),
        delivery_guard=_callback_delivery_guard(cq, target),
    )


@router.callback_query(OwnerFilter(), F.data.startswith("permverify:"))
async def on_permission_recheck(cq: CallbackQuery):
    """Consume a one-shot permission check created by a successful settings launch."""
    target = _require_target(cq)
    token = str(cq.data or "").partition(":")[2]
    user_id = int(cq.from_user.id) if cq.from_user else 0
    if not target or not re.fullmatch(r"[0-9a-f]{16}", token):
        await cq.answer("Проверка устарела; снова открой нужные настройки.", show_alert=True)
        return
    now = time.monotonic()
    with _PENDING_PERMISSION_RECHECKS_LOCK:
        pending = _PENDING_PERMISSION_RECHECKS.get(token)
        if (not isinstance(pending, dict)
                or pending.get("user_id") != user_id
                or pending.get("target") != target
                or float(pending.get("expires_at", 0)) <= now):
            _PENDING_PERMISSION_RECHECKS.pop(token, None)
            pending = None
        else:
            _PENDING_PERMISSION_RECHECKS.pop(token, None)
    permission = pending.get("permission") if pending else None
    if not pending or permission not in _SNAPSHOT_LABELS:
        await cq.answer("Проверка уже использована или истекла. Открой настройки ещё раз.", show_alert=True)
        return
    if not _device_action_still_allowed(user_id, "cmd:capabilities", target):
        await cq.answer(_lex("input_access_revoked"), show_alert=True)
        return
    await cq.answer("🔎 Запрашиваю свежую одноразовую проверку...")
    if not await _callback_result_access_or_report(cq, target):
        return
    sent, command_id = publish_tracked("capabilities", _target=target)
    result = None
    if sent:
        result = await capabilities_collector.wait_for(target, "capabilities", 15.0, command_id)
    if not await _callback_result_access_or_report(cq, target, published=bool(sent)):
        return

    snapshot = _parse_capability_snapshot(result or {})
    info = devices.get(target) or {}
    expected_platform = "macOS" if str(info.get("os") or "").lower().startswith(("mac", "darwin")) else "Windows"
    item = next((row for row in snapshot["items"] if row["id"] == permission), None)
    if (not sent or not result or snapshot["schema"] != 1
            or not str(snapshot["platform"] or "").startswith(expected_platform)):
        state, checked_at = "unknown", None
    else:
        state, checked_at = item["state"], snapshot["checked_at"]
    label = _SNAPSHOT_LABELS[permission]
    state_text = _SNAPSHOT_STATES.get(state, _SNAPSHOT_STATES["unknown"])
    checked_text = f"\nПроверено: {html.escape(checked_at)}" if checked_at else "\nПроверено: ответа нет; состояние оставлено неизвестным."
    await _replace_callback_message(
        cq,
        f"Одноразовая проверка после перехода в настройки\n{html.escape(label)}: {state_text}{checked_text}",
        delivery_guard=_callback_delivery_guard(cq, target),
        reply_markup=_permission_recheck_keyboard(permission, state, expected_platform, user_id),
    )


def format_location_result(result: dict) -> str:
    """Pure bounded presentation; ignore old free-form/provider coordinate text."""
    import math
    import datetime
    source, state = result.get("source"), result.get("state")
    checked = result.get("checked_at")
    try:
        stamp = datetime.datetime.fromisoformat(checked)
        valid_stamp = stamp.utcoffset() == datetime.timedelta(0)
    except (TypeError, ValueError):
        valid_stamp = False
    if (not isinstance(source, str) or not isinstance(state, str)
            or source not in {"system", "ip_estimate", "comparison"}
            or state not in _SNAPSHOT_STATES or not valid_stamp):
        return "Локация: неизвестно; нужен новый запрос к обновлённому агенту."
    safe = lambda value, limit: html.escape(str(value)[:limit])
    label = safe(result.get("label", ""), 500)
    when = safe(checked, 50)
    if source == "comparison":
        system = result.get("system_location")
        estimate = result.get("ip_estimate")
        if not isinstance(system, dict) or not isinstance(estimate, dict):
            return "Сравнение источников: неизвестно; ответ агента неполный."
        return (
            "Сравнение источников (разовый запрос; координаты не сохраняются)\n"
            "Системный источник:\n" + format_location_result(system) + "\n"
            "IP estimate (город/регион, не GPS):\n" + format_location_result(estimate) + "\n"
            "Сравнено: " + when
        )
    if source == "ip_estimate":
        return ("Приблизительная оценка города/региона по IP, не GPS; точность неизвестна.\n"
                + label + "\nСостояние: " + _SNAPSHOT_STATES[state] + "\nПроверено: " + when)
    if state == "granted":
        lat, lon, accuracy = (result.get(key) for key in ("latitude", "longitude", "accuracy_m"))
        if (not all(type(value) in (int, float) and math.isfinite(value) for value in (lat, lon, accuracy))
                or not (-90 <= lat <= 90 and -180 <= lon <= 180 and accuracy >= 0)):
            return "Системная локация: неизвестно; некорректный результат."
        return (f"Системная геолокация (источник ОС, не обязательно GPS): {lat}, {lon}\n"
                f"Погрешность: {accuracy} м\nПроверено: " + when)
    return ("Системная локация: " + _SNAPSHOT_STATES[state] + "\n"
            + label + "\nПроверено: " + when)


def _capabilities_keyboard(result: dict | None = None, user_id: int | None = None):
    kb = InlineKeyboardBuilder()
    snapshot = _parse_capability_snapshot(result or {})
    user_id = int(user_id if user_id is not None else CURRENT_TG_USER.get())
    commands = result.get("commands") if isinstance(result, dict) else None
    commands = set(commands) if isinstance(commands, list) else set()
    platform = next((name for name in _CAPABILITY_SETTINGS
                     if isinstance(snapshot["platform"], str) and snapshot["platform"].startswith(name)), None)
    if get_user_role(user_id) == Role.OWNER and platform:
        for item in snapshot["items"]:
            has_direct_settings = (
                "permission_settings" in commands
                and bool(_CAPABILITY_SETTINGS[platform].get(item["id"]))
            )
            if has_direct_settings:
                kb.button(
                    text=_permission_action_label(platform, item["id"], item["state"]),
                    callback_data=f"permsettings:{item['id']}",
                    style="primary",
                )
            else:
                kb.button(
                    text=f"❔ Как проверить: {_SNAPSHOT_LABELS[item['id']]}",
                    callback_data=f"permhelp:{item['id']}",
                )
    kb.button(text=_nav("refresh"), callback_data="cmd:capabilities")
    kb.button(text=_nav("back_device"), callback_data="back:device", style="primary")
    kb.adjust(1)
    return kb.as_markup()


def _permission_recheck_keyboard(permission: str, state: str, platform: str, user_id: int):
    """Keep the owner one tap away from the exact OS permission flow after a failed check."""
    kb = InlineKeyboardBuilder()
    if (get_user_role(user_id) == Role.OWNER
            and permission in _CAPABILITY_SETTINGS.get(platform, {})):
        kb.button(
            text=_permission_action_label(platform, permission, state),
            callback_data=f"permsettings:{permission}", style="primary",
        )
    if (get_user_role(user_id) == Role.OWNER
            and permission not in _CAPABILITY_SETTINGS.get(platform, {})):
        kb.button(text=f"❔ Как изменить: {_SNAPSHOT_LABELS[permission]}", callback_data=f"permhelp:{permission}")
    kb.button(text=_nav("back_device"), callback_data="back:device")
    kb.adjust(1)
    return kb.as_markup()


def _permission_action_label(platform: str, permission: str, state: str) -> str:
    """Name the real OS flow: native consent only while macOS has no decision yet."""
    label = _SNAPSHOT_LABELS.get(permission, "доступ")
    if platform == "macOS":
        if state == "not_determined":
            return f"🔔 Запросить у macOS: {label}"
        if state == "denied":
            return f"⚙️ Разрешить в настройках: {label}"
        if state == "granted":
            return f"⚙️ Изменить в настройках: {label}"
        if permission == "file_access" or state == "unavailable":
            return f"⚙️ Открыть настройки macOS: {label}"
        if state in {"unknown", "needs_live_test"}:
            return f"🔐 Запросить или открыть настройки: {label}"
        return f"⚙️ Открыть настройки macOS: {label}"
    if permission == "location" and state in {"not_determined", "needs_live_test", "unknown"}:
        return f"🔔 Запросить у Windows: {label}"
    return f"⚙️ Изменить в настройках Windows: {label}"


def _location_result_keyboard(result: dict, user_id: int):
    kb = InlineKeyboardBuilder()
    if get_user_role(user_id) == Role.OWNER and result.get("source") != "comparison":
        if result.get("state") != "granted":
            kb.button(text=_lex("geo_beta"), callback_data="location:ip")
        kb.button(text=feature_catalog.button_text("location_compare"), callback_data="location:compare")
    kb.button(text=_nav("back_device"), callback_data="back:device", style="primary")
    kb.adjust(1)
    return kb.as_markup()


