def _format_permission_help(platform: str | None, permission: str) -> str | None:
    """Return static, allowlisted guidance; agent-provided text and URIs are never used."""
    if platform not in _PERMISSION_HELP or permission not in _SNAPSHOT_LABELS:
        return None
    instructions = _PERMISSION_HELP[platform].get(permission)
    if not instructions:
        return None
    label = html.escape(_SNAPSHOT_LABELS[permission])
    instructions = html.escape(instructions)
    return (
        f"🧭 <b>Как разрешить: {label}</b>\n\n"
        f"{instructions}\n\n"
        "Это только инструкция: она не выдаёт разрешение и не доказывает доступ. "
        "После изменения вернись к проверке; "
        "доступ подтверждает только разрешённое пробное действие."
    )


def _parse_capability_snapshot(result: dict) -> dict:
    """Normalize untrusted data; old or malformed envelopes cannot imply grants."""
    empty = {"schema": None, "platform": None, "checked_at": None,
             "items": [{"id": key, "state": "unknown", "detail": "", "settings_uri": None}
                       for key in _SNAPSHOT_LABELS]}
    if not isinstance(result, dict) or type(result.get("schema")) is not int or result["schema"] != 1:
        return empty
    raw_platform = result.get("platform")
    if not isinstance(raw_platform, str):
        return empty
    match = re.fullmatch(r"(macOS|Windows)(?: [0-9.]+)?", raw_platform.strip())
    if not match:
        return empty
    platform = match.group(1)
    checked_at = result.get("checked_at")
    try:
        if not isinstance(checked_at, str) or len(checked_at) > 40:
            return empty
        stamp = datetime.datetime.fromisoformat(checked_at)
        if stamp.utcoffset() is None:
            return empty
    except (ValueError, TypeError, OverflowError):
        return empty
    raw_items = result.get("items")
    if not isinstance(raw_items, list) or len(raw_items) > 64:
        return empty
    seen = {}
    duplicates = set()
    for item in raw_items:
        if not isinstance(item, dict):
            continue
        key = item.get("id")
        if not isinstance(key, str) or key not in _SNAPSHOT_LABELS:
            continue
        if key in seen:
            duplicates.add(key)
        seen[key] = item
    items = []
    for key in _SNAPSHOT_LABELS:
        item = seen.get(key, {})
        state = item.get("state")
        detail = item.get("detail")
        valid = (key not in duplicates and isinstance(state, str) and state in _SNAPSHOT_STATES
                 and isinstance(detail, str) and bool(detail.strip()))
        items.append({"id": key, "state": state if valid else "unknown",
                      "detail": detail[:200] if valid else "",
                      # Route selection belongs to this bot, never to the agent.
                      "settings_uri": _CAPABILITY_SETTINGS[platform].get(key) if valid else None})
    return {"schema": 1, "platform": raw_platform, "checked_at": checked_at, "items": items}


def _format_capabilities(result: dict) -> str:
    """Render bounded capability data without treating declarations as health checks."""
    def safe(value, limit=100):
        chunks = []
        length = 0
        for char in str(value or "?")[:limit]:
            chunk = html.escape(char, quote=False)
            if length + len(chunk) > limit:
                break
            chunks.append(chunk)
            length += len(chunk)
        return "".join(chunks)

    if not isinstance(result, dict):
        result = {}
    snapshot = _parse_capability_snapshot(result)

    lines = ["📊 <b>Проверка возможностей</b>"]
    lines.append(f"Устройство: <b>{safe(result.get('hostname'))}</b>")
    lines.append(f"ОС: {safe(result.get('platform'))} · агент: {safe(result.get('version'), 40)}")
    lines.append(f"Проверено: {safe(snapshot['checked_at'], 40)}")
    lines.append("\n<b>Разрешения</b> <i>(это не тест реального действия)</i>")
    for item in snapshot["items"]:
        lines.append(f"• {_SNAPSHOT_LABELS[item['id']]}: {_SNAPSHOT_STATES[item['state']]}")
        if item["detail"]:
            lines.append(safe(item["detail"], 200 if item["id"] == "location" else 100))
    if snapshot["schema"] == 1 and any(item["settings_uri"] for item in snapshot["items"]):
        lines.append("Системный запрос или нужный раздел настроек открывается кнопкой соответствующего разрешения ниже.")
    if any(item["state"] == "needs_live_test" for item in snapshot["items"]):
        lines.append("Не для всех разрешений ОС отдаёт пассивный статус; фактический доступ подтверждает только отдельное разрешённое пробное действие.")
    lines.append("Снимок не выдаёт разрешения. Владелец меняет их на самом устройстве.")
    if snapshot["schema"] == 1:
        if snapshot["platform"].startswith("macOS"):
            lines.append("macOS: Системные настройки → Конфиденциальность и безопасность → нужный раздел. "
                         "Разреши фактическое приложение XIDER; при запросе ОС перезапусти его.")
            commands = result.get("commands") if isinstance(result.get("commands"), list) else []
            if "permission_settings" in commands:
                lines.append("Для камеры, микрофона, геолокации, записи экрана и Универсального доступа агент вызывает запрос macOS там, где ОС его поддерживает. Если решение уже принято, откроется точный раздел для изменения. Файловый доступ меняется только в настройках. Результат можно проверить кнопкой ниже.")
            else:
                lines.append("Удалённое открытие раздела появится после обновления агента до версии с поддержкой этой команды.")
        else:
            lines.append("Windows: Параметры → Конфиденциальность и безопасность → Камера / Микрофон / Расположение. "
                         "Для камеры и микрофона проверь «Разрешить классическим приложениям».")
            commands = result.get("commands") if isinstance(result.get("commands"), list) else []
            if "permission_settings" in commands:
                lines.append("Для камеры/микрофона кнопка открывает системную страницу общего доступа классических приложений: отдельного переключателя XIDER у этого EXE нет. Для геолокации кнопка вызывает подтверждённый на самом ПК системный запрос Windows, если решения ещё нет; иначе открывает настройки. Само разрешение не доказывает, что действие сработало — это проверяется отдельно.")
            else:
                lines.append("Кнопки перехода появятся после обновления агента; пока открой раздел вручную.")
            lines.append("Для файлового доступа отдельного разрешения нет: проверь ACL. UAC подтверждает владелец.")

    # Show the actual supervisor chain from fresh, component-owned reports.
    # A stale/missing report is unknown; never infer that a component is alive
    # just because its parent or the Agent answered this request.
    platform = str(result.get("platform") or "")
    if platform.startswith("macOS") or "windows" in platform.casefold():
        now = time.time()
        lines.append("\n<b>Состояние сторожей</b> <i>(устаревший отчёт = неизвестно)</i>")
        lines.append("• Агент: ответил на текущую проверку")

        def health_line(label: str, state: str | None, stamp: object) -> str:
            if type(stamp) not in (int, float) or not math.isfinite(stamp) or stamp <= 0 or stamp > now + 5:
                return f"• {label}: неизвестно (нет корректного отчёта)"
            age = max(0, int(now - stamp))
            if age >= companion_status.FRESHNESS_SECONDS:
                return f"• {label}: неизвестно (отчёт устарел, {age} сек назад)"
            shown_state = state if state in {"running", "waiting", "error", "stopped"} else "unknown"
            return f"• {label}: {shown_state} · отчёт {age} сек назад"

        guardian = result.get("_guardian_record")
        guardian_seen = result.get("_guardian_last_seen")
        # A fresh Guardian status reply proves it is alive; task_registered and
        # launchd_loaded describe registrations, not the Guardian process.
        guardian_state = "running" if isinstance(guardian, dict) else None
        lines.append(health_line("Guard Keeper → агент", guardian_state, guardian_seen))

        if platform.startswith("macOS"):
            layer_records = companion_status.clean_layer_records(result.get("companions"), now=now)
            for role, label in (("safari", "Safari → Guard Keeper"), ("siri", "Siri → Safari")):
                record = layer_records.get(role)
                if record is None:
                    lines.append(f"• {label}: неизвестно (нет отчёта слоя)")
                else:
                    lines.append(health_line(label, record.get("state"), record.get("last_seen")))

    raw_statuses = result.get("feature_status")
    raw_features = result.get("features")
    statuses = raw_statuses if isinstance(raw_statuses, dict) else {}
    legacy = raw_features if isinstance(raw_features, dict) else {}
    # Legacy declarations stay explicitly unverified, never become schema v1 grants.
    for key, label in (_CAPABILITY_LABELS.items() if snapshot["schema"] is None else []):
        state = statuses.get(key)
        if isinstance(state, dict):
            state = state.get("state")
        if not isinstance(state, str) or state not in _CAPABILITY_STATES:
            old_key = {"microphone": "mic", "webcam": "camera_api"}.get(key, key)
            old_value = legacy.get(old_key)
            state_text = (
                "заявлено старым агентом; реальная проверка не выполнена"
                if old_value is True
                else "нет свежего статуса"
            )
        else:
            state_text = _CAPABILITY_STATES[state]
        lines.append(f"• {label}: {state_text}")

    commands = result.get("commands")
    if isinstance(commands, list):
        clean = sorted({
            command for command in commands[:256]
            if isinstance(command, str) and re.fullmatch(r"[a-z][a-z0-9_]{0,63}", command)
        })
        budget = max(0, 3900 - len("\n".join(lines)))
        shown = []
        for command in clean[:32]:
            if len(", ".join(shown + [command])) > budget:
                break
            shown.append(command)
        suffix = f"\n… ещё {len(clean) - len(shown)}" if len(clean) > len(shown) else ""
        lines.append(f"\n<b>Заявлено команд:</b> {len(clean)}")
        if shown:
            lines.append(html.escape(", ".join(shown), quote=False) + suffix)
    else:
        lines.append("\nСписок команд не получен.")
    return "\n".join(lines)

@router.callback_query(AdminFilter(), F.data == "cmd:sysinfo")
async def on_cmd_sysinfo(cq: CallbackQuery):
    target = SESSION.get("target")
    if not target:
        await cq.answer(_lex("target_required"), show_alert=True)
        return
    if target == "all":
        await cq.answer(_lex("single_device_only"), show_alert=True)
        return
    await cq.answer("💻 Запрашиваю...")
    if not await _callback_result_access_or_report(cq, target):
        return
    sent, command_id = publish_tracked("sysinfo", _target=target)
    if not sent:
        await _replace_callback_message(
            cq,
            _lex("mqtt_disconnected"),
            reply_markup=back_to_device_kb(),
        )
        return
    result = await sysinfo_collector.wait_for(target, "sysinfo", 12.0, command_id)
    if not await _callback_result_access_or_report(cq, target, published=True):
        return
    if result is None:
        await _replace_callback_message(
            cq,
            _lex("device_timeout", seconds="12"),
            delivery_guard=_callback_delivery_guard(cq, target), reply_markup=back_to_device_kb(),
        )
        return
    await _replace_callback_message(
        cq,
        _format_sysinfo(
            result,
            (devices.get(result.get("device_id")) or {}).get("name", "?"),
            expected_request_id=command_id,
        ),
        delivery_guard=_callback_delivery_guard(cq, target), reply_markup=back_to_device_kb(),
    )


@router.callback_query(OwnerFilter(), F.data == "sysinfo:uncertainty")
async def on_sysinfo_uncertainty(cq: CallbackQuery):
    target = SESSION.get("target")
    if not target or target == "all":
        await cq.answer(_lex("single_device_only"), show_alert=True)
        return
    if not await _callback_result_access_or_report(cq, target):
        return
    if _device_declares_command(devices.get(target) or {}, "sysinfo") is False:
        await cq.answer("Агент не объявляет поддержку sysinfo; запрос не отправлялся.", show_alert=True)
        await _replace_callback_message(
            cq, "📊 <b>Качество показаний (D01-F30)</b>\n\nНет данных: агент не объявляет поддержку системной сводки.",
            reply_markup=back_to_device_kb(),
        )
        return
    await cq.answer("Проверяю свежесть и источник показаний…")
    sent, command_id = publish_tracked("sysinfo", _target=target)
    if not sent:
        await _replace_callback_message(cq, _lex("mqtt_disconnected"), reply_markup=back_to_device_kb())
        return
    guard = _callback_delivery_guard(cq, target)
    await _replace_callback_message(
        cq,
        "Проверяю один свежий ответ агента. Будут показаны только проценты ресурсов, их время и качество; без сохранения истории.",
        delivery_guard=guard, reply_markup=back_to_device_kb(),
    )
    result = await sysinfo_collector.wait_for(target, "sysinfo", 12.0, command_id)
    if not await _callback_result_access_or_report(cq, target, published=True):
        return
    body = _format_sysinfo_uncertainty(
        result, (devices.get(target) or {}).get("name", "?"),
        expected_device_id=target, expected_request_id=command_id,
    )
    await _replace_callback_message(cq, body, delivery_guard=guard, reply_markup=back_to_device_kb())


