@router.callback_query(OwnerFilter(), F.data.startswith("memory:history:"))
async def on_memory_history_period(cq: CallbackQuery):
    target = SESSION.get("target")
    match = re.fullmatch(r"memory:history:(15|30|60)", str(cq.data or ""))
    if not target or target == "all" or match is None:
        await cq.answer(_lex("single_device_only"), show_alert=True)
        return
    if not await _callback_result_access_or_report(cq, target):
        return
    if _device_declares_command(devices.get(target) or {}, "memory_history") is False:
        await cq.answer("Обнови агент перед этой проверкой.", show_alert=True)
        await _replace_callback_message(
            cq,
            "Этот агент ещё не объявляет поддержку истории памяти. Обнови агент и повтори запрос; команда не отправлялась.",
            reply_markup=back_to_device_kb(),
        )
        return
    period = int(match.group(1))
    await cq.answer("Собираю локальные замеры RAM и swap…")
    sent, command_id = publish_tracked("memory_history", _target=target, period_seconds=period)
    if not sent:
        await _replace_callback_message(
            cq, _lex("mqtt_disconnected"),
            reply_markup=memory_history_period_keyboard(cq.from_user.id),
        )
        return
    await _replace_callback_message(
        cq,
        f"🧠 История RAM/swap · {period} секунд. Собираю локальные замеры; это сообщение обновится с результатом.",
        delivery_guard=_callback_delivery_guard(cq, target),
        reply_markup=memory_history_period_keyboard(cq.from_user.id),
    )
    result = await memory_history_collector.wait_for(
        target, "memory_history", period + 10.0, command_id,
    )
    if not await _callback_result_access_or_report(cq, target, published=True):
        return
    if result is None:
        body = (
            f"🧠 История памяти (D01-F03) · {period} секунд: <b>неизвестно</b>. "
            "Агент не прислал полный результат; возможно, он старой версии или отключён."
        )
    else:
        body = _format_memory_history(
            result, (devices.get(target) or {}).get("name", "?"),
            expected_device_id=target, expected_request_id=command_id,
        )
    await _replace_callback_message(
        cq, body, delivery_guard=_callback_delivery_guard(cq, target),
        reply_markup=back_to_device_kb(),
    )


