def _system_summary_export_keyboard(rows: list[dict]):
    """Build metadata-only export choices outside async route AST auditing."""
    kb = InlineKeyboardBuilder()
    for row in rows:
        summary = row["summary"]
        stamp = datetime.datetime.fromtimestamp(row["captured_at"], datetime.timezone.utc).strftime("%m-%d %H:%M UTC")
        cpu = "—" if summary["cpu_percent"] is None else f"{summary['cpu_percent']:g}%"
        kb.button(
            text=f"{stamp} · CPU {cpu}",
            callback_data=f"sysinfo:export:{row['snapshot_id']}", style="primary",
        )
    kb.button(text=_nav("back_device"), callback_data="back:device", style="danger")
    kb.adjust(1)
    return kb.as_markup()


def _system_summary_interval_keyboard(current: dict):
    kb = InlineKeyboardBuilder()
    current_interval = current.get("interval_seconds", 0)
    for seconds, label in ((900, "15 мин"), (1800, "30 мин"), (3600, "60 мин"), (0, "Выключить")):
        prefix = "✓ " if seconds == current_interval else ""
        kb.button(text=prefix + label, callback_data=f"sysinfo:interval:{seconds}", style="success" if seconds else "danger")
    kb.button(text=_nav("back_device"), callback_data="back:device", style="primary")
    kb.adjust(2, 2, 1)
    return kb.as_markup()


_SYSTEM_THRESHOLD_LABELS = {
    "cpu_percent": "CPU",
    "ram_percent": "RAM",
    "disk_percent": "Диск",
    "temperature_celsius": "Температура",
}


def _system_summary_threshold_keyboard(thresholds: dict, *, include_temperature: bool):
    kb = InlineKeyboardBuilder()
    metrics = ("cpu_percent", "ram_percent", "disk_percent")
    if include_temperature:
        metrics += ("temperature_celsius",)
    for metric in metrics:
        current = thresholds.get(metric)
        suffix = "выкл." if current is None else f"{current:g}{'°C' if metric == 'temperature_celsius' else '%'}"
        kb.button(
            text=f"{_SYSTEM_THRESHOLD_LABELS[metric]} · {suffix}",
            callback_data=f"sysinfo:threshold:{metric}", style="primary",
        )
    kb.button(text=_nav("back_device"), callback_data="back:device", style="danger")
    kb.adjust(2, 2, 1)
    return kb.as_markup()


def _system_summary_threshold_choice_keyboard(metric: str, current: float | None):
    levels = (65, 70, 75, 80, 85, 90) if metric == "temperature_celsius" else (70, 75, 80, 85, 90, 95)
    unit = "°C" if metric == "temperature_celsius" else "%"
    kb = InlineKeyboardBuilder()
    for level in levels:
        kb.button(
            text=("✓ " if current == level else "") + f"{level}{unit}",
            callback_data=f"sysinfo:threshold:{metric}:{level}", style="success",
        )
    kb.button(
        text=("✓ " if current is None else "") + "Выключить",
        callback_data=f"sysinfo:threshold:{metric}:off", style="danger",
    )
    kb.button(text=_nav("back_device"), callback_data="sysinfo:threshold", style="primary")
    kb.adjust(3, 3, 1, 1)
    return kb.as_markup()


@router.callback_query(OwnerFilter(), F.data == "sysinfo:threshold")
async def on_system_summary_thresholds(cq: CallbackQuery):
    target = SESSION.get("target")
    if not target or target == "all":
        await cq.answer(_lex("single_device_only"), show_alert=True)
        return
    if not await _callback_result_access_or_report(cq, target):
        return
    thresholds = devices.get_system_summary_thresholds(target)
    schedule = devices.get_system_summary_schedule(target)
    os_name = str((devices.get(target) or {}).get("os") or "").casefold()
    is_windows = "win" in os_name
    body = (
        "<b>D01-F27 · Пороговые уведомления</b>\n\n"
        + ("Уведомления работают только при включённом интервале D01-F26. "
           "Срабатывание — после двух свежих замеров подряд; повтор не приходит, пока показатель не опустится ниже порога."
           if schedule["interval_seconds"] else
           "Сначала включи интервал D01-F26 — без него новых замеров и уведомлений не будет.")
    )
    if not is_windows:
        body += "\n\nТемпература: unsupported на этой платформе; датчик не подменяется оценкой."
    await _replace_callback_message(
        cq, body, reply_markup=_system_summary_threshold_keyboard(thresholds, include_temperature=is_windows),
    )
    await cq.answer()


@router.callback_query(OwnerFilter(), F.data.startswith("sysinfo:threshold:"))
async def on_system_summary_threshold_selected(cq: CallbackQuery):
    target = SESSION.get("target")
    parts = cq.data.split(":") if isinstance(cq.data, str) else []
    if (not target or target == "all" or len(parts) not in {3, 4}
            or parts[0:2] != ["sysinfo", "threshold"] or parts[2] not in _SYSTEM_THRESHOLD_LABELS):
        await cq.answer("Порог или устройство выбраны некорректно.", show_alert=True)
        return
    if not await _callback_result_access_or_report(cq, target):
        return
    metric = parts[2]
    info = devices.get(target) or {}
    if metric == "temperature_celsius" and "win" not in str(info.get("os") or "").casefold():
        await cq.answer("Температурный порог недоступен: на устройстве нет поддержанного датчика.", show_alert=True)
        return
    thresholds = devices.get_system_summary_thresholds(target)
    if len(parts) == 3:
        unit = "°C" if metric == "temperature_celsius" else "%"
        await cq.answer()
        await _replace_callback_message(
            cq, f"<b>Порог · {_SYSTEM_THRESHOLD_LABELS[metric]}</b>\n\nВыбери значение {unit} или выключи уведомления для этого показателя.",
            reply_markup=_system_summary_threshold_choice_keyboard(metric, thresholds.get(metric)),
        )
        return
    raw_value = parts[3]
    try:
        threshold = None if raw_value == "off" else int(raw_value)
        updated = devices.set_system_summary_threshold(target, metric, threshold)
    except (TypeError, ValueError, OSError):
        await cq.answer("Такого порога нет в разрешённом списке.", show_alert=True)
        return
    audit("system_resource_threshold_changed", actor_id=cq.from_user.id, device_id=target, metric=metric,
          threshold="off" if threshold is None else threshold)
    schedule = devices.get_system_summary_schedule(target)
    is_windows = "win" in str(info.get("os") or "").casefold()
    body = (
        f"Порог для {_SYSTEM_THRESHOLD_LABELS[metric]} {('выключен' if threshold is None else f'установлен: {threshold:g}' + ('°C' if metric == 'temperature_celsius' else '%'))}.\n"
        + ("D01-F26 включён; уведомление появится после двух последовательных превышений."
           if schedule["interval_seconds"] else "Порог сохранён, но уведомления начнутся после включения D01-F26.")
    )
    await cq.answer("Сохранено.")
    await _replace_callback_message(
        cq, body, reply_markup=_system_summary_threshold_keyboard(updated, include_temperature=is_windows),
    )


