@router.callback_query(OwnerFilter(), F.data.startswith("sysinfo:interval:"))
async def on_system_summary_interval_selected(cq: CallbackQuery):
    target = SESSION.get("target")
    raw = cq.data.removeprefix("sysinfo:interval:") if isinstance(cq.data, str) else ""
    try:
        interval = int(raw)
    except (TypeError, ValueError):
        interval = -1
    if not target or target == "all" or interval not in {0, 900, 1800, 3600}:
        await cq.answer("Выбран интервал или устройство некорректны.", show_alert=True)
        return
    if not await _callback_result_access_or_report(cq, target):
        return
    info = devices.get(target) or {}
    if _device_declares_command(info, "sysinfo_interval") is False:
        await cq.answer("Агент не поддерживает расписание; запрос не отправлен.", show_alert=True)
        return
    schedule_id = uuid.uuid4().hex
    sent, command_id = publish_tracked(
        "sysinfo_interval", _target=target, interval_seconds=interval, schedule_id=schedule_id,
    )
    if not sent:
        await _replace_callback_message(cq, _lex("mqtt_disconnected"), reply_markup=back_to_device_kb())
        return
    guard = _callback_delivery_guard(cq, target)
    await cq.answer("Применяю интервал на выбранном устройстве…")
    await _replace_callback_message(cq, "Запрос расписания отправлен агенту; жду подтверждение и время следующего замера.",
                                    delivery_guard=guard, reply_markup=back_to_device_kb())
    result = await sysinfo_schedule_collector.wait_for(target, "sysinfo_schedule_status", 12.0, command_id)
    if not await _callback_result_access_or_report(cq, target, published=True):
        return
    try:
        valid = (isinstance(result, dict) and result.get("schema") == "xider.sysinfo-schedule.v1"
                 and result.get("feature_id") == "D01-F26" and result.get("device_id") == target
                 and result.get("request_id") == command_id and result.get("schedule_id") == schedule_id
                 and result.get("state") == "supported" and result.get("interval_seconds") == interval
                 and (type(result.get("next_sample_at")) is int if interval else result.get("next_sample_at") is None))
        if not valid:
            raise ValueError("invalid schedule response")
        schedule = devices.save_system_summary_schedule(
            target, interval_seconds=interval, schedule_id=schedule_id,
            next_sample_at=result.get("next_sample_at"),
        )
        body = ("Сбор сводных метрик выключен." if interval == 0 else
                f"Сбор включён раз в {interval // 60} мин. Следующий замер: "
                f"{datetime.datetime.fromtimestamp(schedule['next_sample_at'], datetime.timezone.utc):%Y-%m-%d %H:%M UTC}.")
    except (AttributeError, TypeError, ValueError, OSError):
        body = "Агент не подтвердил расписание валидным ответом; состояние оставлено без изменений."
    await _replace_callback_message(cq, body, delivery_guard=guard, reply_markup=back_to_device_kb())


@router.callback_query(OwnerFilter(), F.data.startswith("sysinfo:export:"))
async def on_system_snapshot_export_selected(cq: CallbackQuery):
    target = SESSION.get("target")
    snapshot_id = cq.data.removeprefix("sysinfo:export:") if isinstance(cq.data, str) else ""
    if not target or target == "all" or not re.fullmatch(r"[0-9a-f]{32}", snapshot_id):
        await cq.answer("Выбранный снимок некорректен или устройство не выбрано.", show_alert=True)
        return
    if not await _callback_result_access_or_report(cq, target):
        return
    try:
        row = devices.get_system_summary_snapshot(target, snapshot_id)
    except (AttributeError, TypeError, ValueError, OSError):
        row = None
    if row is None:
        await cq.answer("Снимок истёк или не относится к выбранному устройству.", show_alert=True)
        await _replace_callback_message(
            cq, "Экспорт отменён: снимок больше недоступен для этого устройства.",
            reply_markup=back_to_device_kb(),
        )
        return
    summary = row["summary"]
    export = {
        "schema": "xider.system-summary-export.v1",
        "captured_at": datetime.datetime.fromtimestamp(row["captured_at"], datetime.timezone.utc).isoformat(),
        "platform": summary["platform"],
        "cpu_percent": summary["cpu_percent"],
        "ram_percent": summary["ram_percent"],
        "disk_percent": summary["disk_percent"],
    }
    stamp = datetime.datetime.fromtimestamp(row["captured_at"], datetime.timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    document = BufferedInputFile(
        json.dumps(export, ensure_ascii=False, indent=2, allow_nan=False).encode("utf-8"),
        filename=f"xider-system-summary-{stamp}.json",
    )
    await cq.answer()
    await _replace_user_card_with_document(
        cq.message, document, "Снимок системной сводки экспортирован: только дата, платформа и проценты CPU/RAM/диска.",
        back_to_device_kb(), delivery_guard=_callback_delivery_guard(cq, target),
    )


def _format_system_summary_comparison(comparison: dict, device_name: str) -> str:
    """Render only the known allowlist of differences between two saved summaries."""
    safe_name = html.escape(str(device_name)[:160])
    if not isinstance(comparison, dict):
        return f"📊 <b>{safe_name}</b>\n\nСравнение: неизвестно — некорректные данные."
    before, after, changes = comparison.get("before"), comparison.get("after"), comparison.get("changes")
    if not isinstance(before, dict) or not isinstance(after, dict) or not isinstance(changes, list) or len(changes) > 4:
        return f"📊 <b>{safe_name}</b>\n\nСравнение: неизвестно — некорректные данные."
    labels = {"platform": "Платформа", "cpu_percent": "CPU", "ram_percent": "RAM", "disk_percent": "Диск"}
    allowed = set(labels)
    if any(not isinstance(row, dict) or set(row) != {"field", "before", "after"} or row["field"] not in allowed for row in changes):
        return f"📊 <b>{safe_name}</b>\n\nСравнение: неизвестно — некорректные поля."
    try:
        first_at = int(before["captured_at"])
        second_at = int(after["captured_at"])
        if first_at < 0 or second_at <= first_at:
            raise ValueError("invalid snapshot dates")
        first_date = datetime.datetime.fromtimestamp(first_at, datetime.timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
        second_date = datetime.datetime.fromtimestamp(second_at, datetime.timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    except (KeyError, TypeError, ValueError, OverflowError, OSError):
        return f"📊 <b>{safe_name}</b>\n\nСравнение: неизвестно — некорректные даты."
    if not changes:
        details = "Изменений в сохранённых полях нет."
    else:
        rendered = []
        for row in changes:
            field = row["field"]
            old, new = row["before"], row["after"]
            if field == "platform":
                if not isinstance(old, str) or not isinstance(new, str):
                    return f"📊 <b>{safe_name}</b>\n\nСравнение: неизвестно — некорректная платформа."
                old_text, new_text = html.escape(old[:80]), html.escape(new[:80])
            else:
                if any(isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value) or not 0 <= value <= 100 for value in (old, new)):
                    return f"📊 <b>{safe_name}</b>\n\nСравнение: неизвестно — некорректные метрики."
                old_text, new_text = f"{old:g}%", f"{new:g}%"
            rendered.append(f"• {labels[field]}: {old_text} → {new_text}")
        details = "\n".join(rendered)
    return f"📊 <b>{safe_name}</b>\n\nСравнение сохранённых снимков (D01-F25):\n{first_date} → {second_date}\n{details}\n\nСравниваются только платформа и проценты CPU/RAM/диска."


def _device_declares_command(info: dict, command: str) -> bool | None:
    """Return advertised support, unsupported, or unknown for legacy snapshots."""
    capabilities = info.get("capabilities") if isinstance(info, dict) else None
    commands = capabilities.get("commands") if isinstance(capabilities, dict) else None
    if not isinstance(commands, list) or any(not isinstance(value, str) for value in commands):
        return None
    return command in commands


def _format_sysinfo_uncertainty(
    result: dict | None, device_name: str, *, expected_device_id: str,
    expected_request_id: str, now: int | None = None,
) -> str:
    """Explain freshness and provenance without treating missing data as zero."""
    safe_name = html.escape(str(device_name)[:160])
    unknown = f"📊 <b>{safe_name}</b>\n\nКачество показаний (D01-F30): коррелированный замер не получен; все значения неизвестно."
    region = result.get("regional_settings") if isinstance(result, dict) else None
    valid = (
        isinstance(result, dict) and result.get("type") == "sysinfo"
        and result.get("device_id") == expected_device_id
        and isinstance(region, dict) and region.get("schema") == 1
        and region.get("feature_id") == "D01-F23"
        and region.get("device_id") == expected_device_id
        and region.get("request_id") == expected_request_id
        and region.get("source") == "local_os_runtime_apis"
        and region.get("state") in {"supported", "unknown"}
    )
    try:
        checked_at = datetime.datetime.fromisoformat(region.get("checked_at"))
        age = (int(now if now is not None else time.time()) - checked_at.timestamp())
        valid = valid and checked_at.utcoffset() is not None and -30 <= age
    except (AttributeError, TypeError, ValueError, OverflowError, OSError):
        valid = False
    if not valid:
        return unknown

    fields = (("cpu_percent", "CPU"), ("ram_percent", "RAM"), ("disk_percent", "Диск"))
    qualities = result.get("metric_quality")
    # Current Windows/macOS sysinfo implementations use psutil's direct readings.
    # A future explicitly supplied quality map overrides that default.
    quality_map_valid = qualities is None or isinstance(qualities, dict)
    checked_label = checked_at.isoformat(timespec="seconds")
    lines = [f"📊 <b>{safe_name}</b>", "Качество показаний (D01-F30):", f"Снято: {html.escape(checked_label)}"]
    for field, label in fields:
        value = result.get(field)
        valid_value = (not isinstance(value, bool) and isinstance(value, (int, float))
                       and math.isfinite(value) and 0 <= value <= 100)
        if not valid_value:
            lines.append(f"• {label}: нет данных (unavailable)")
            continue
        if age > 120:
            lines.append(f"• {label}: устарело (stale); значение скрыто")
            continue
        if not quality_map_valid:
            lines.append(f"• {label}: неизвестно — некорректная метка качества")
            continue
        if isinstance(qualities, dict) and field not in qualities:
            lines.append(f"• {label}: неизвестно — метка качества отсутствует")
            continue
        quality = qualities[field] if isinstance(qualities, dict) else "measured"
        if quality == "unavailable":
            lines.append(f"• {label}: нет данных (unavailable)")
        elif quality == "estimated":
            lines.append(f"• {label}: оценочное (estimated) — {float(value):g}%")
        elif quality == "measured":
            lines.append(f"• {label}: измерено (measured) — {float(value):g}%")
        else:
            lines.append(f"• {label}: неизвестно — некорректная метка качества")
    lines.append("Пропуск не считается нулём; оценка показывается только при явной метке источника.")
    return "\n".join(lines)


def _format_camera_quality(
    result: dict | None, device_name: str, *, expected_device_id: str,
    expected_request_id: str, now: int | None = None,
) -> str:
    """Render only a fresh, correlated, allowlisted local camera-quality summary."""
    safe_name = html.escape(str(device_name)[:160])
    unknown = f"📷 <b>{safe_name}</b>\n\nКачество кадра (D02-F13): не совпал запрос/устройство или нет свежего корректного ответа; метрики скрыты."
    if not isinstance(result, dict):
        return unknown
    if result.get("state") == "unsupported":
        return f"📷 <b>{safe_name}</b>\n\nКачество кадра (D02-F13): функция недоступна на этом агенте. Кадр не отправлялся."
    if (result.get("type") != "camera_quality_snapshot"
            or result.get("schema") != "xider.camera-quality.v1"
            or result.get("feature_id") != "D02-F13"
            or result.get("device_id") != expected_device_id
            or result.get("request_id") != expected_request_id
            or result.get("source") != "opencv_laplacian_local"
            or result.get("state") != "supported"):
        return unknown
    data = result.get("data")
    expected_fields = {
        "width_px", "height_px", "sharpness_variance", "mean_luma",
        "dark_clipped_percent", "bright_clipped_percent",
    }
    if not isinstance(data, dict) or set(data) != expected_fields:
        return unknown
    try:
        checked_at = datetime.datetime.fromisoformat(result.get("checked_at"))
        age = int(now if now is not None else time.time()) - checked_at.timestamp()
        if checked_at.utcoffset() is None or age < -30:
            return unknown
    except (AttributeError, TypeError, ValueError, OverflowError, OSError):
        return unknown
    if age > 120:
        return f"📷 <b>{safe_name}</b>\n\nКачество кадра (D02-F13): замер устарел; числовые показатели скрыты."

    def valid_number(value, minimum, maximum):
        return (not isinstance(value, bool) and isinstance(value, (int, float))
                and math.isfinite(value) and minimum <= value <= maximum)

    width, height = data.get("width_px"), data.get("height_px")
    if (type(width) is not int or not 1 <= width <= 7680
            or type(height) is not int or not 1 <= height <= 4320
            or not valid_number(data.get("sharpness_variance"), 0, 1_000_000_000)
            or not valid_number(data.get("mean_luma"), 0, 255)
            or not valid_number(data.get("dark_clipped_percent"), 0, 100)
            or not valid_number(data.get("bright_clipped_percent"), 0, 100)):
        return unknown
    stamp = html.escape(checked_at.isoformat(timespec="seconds"))
    return (
        f"📷 <b>{safe_name}</b>\nКачество кадра (D02-F13) · локально, кадр не сохранён\n"
        f"Снято: {stamp}\nРазмер: {width}×{height}\n"
        f"Резкость, дисперсия Лапласиана: {data['sharpness_variance']:g}\n"
        f"Средняя яркость: {data['mean_luma']:g}/255\n"
        f"Тёмное отсечение: {data['dark_clipped_percent']:g}% · светлое: {data['bright_clipped_percent']:g}%\n"
        "Это локальные эвристики одного кадра, не являются гарантией резкости или правильной экспозиции."
    )


def _format_sysinfo(result: dict, device_name: str, expected_request_id: str | None = None) -> str:
    """Render raw system facts plus validated D01 health and regional summaries."""
    esc = lambda value: html.escape(str(value)[:160])
    lines = [
        f"💻 <b>{esc(device_name)}</b>", "",
        f"🔲 CPU: {esc(_sysinfo_percent_display(result.get('cpu_percent')))}%",
        f"🧠 RAM: {esc(result.get('ram_used_gb', '?'))} / {esc(result.get('ram_total_gb', '?'))} ГБ ({esc(_sysinfo_percent_display(result.get('ram_percent')))}%)",
        f"💾 Диск: {esc(result.get('disk_used_gb', '?'))} / {esc(result.get('disk_total_gb', '?'))} ГБ ({esc(_sysinfo_percent_display(result.get('disk_percent')))}%)",
        f"⏱ Аптайм: {esc(result.get('uptime', '?'))}",
    ]
    lines.extend(_format_resource_health(result, expected_request_id))
    region = result.get("regional_settings")
    valid = (
        isinstance(region, dict) and region.get("schema") == 1
        and region.get("feature_id") == "D01-F23"
        and region.get("source") == "local_os_runtime_apis"
        and isinstance(result.get("device_id"), str)
        and region.get("device_id") == result.get("device_id")
        and isinstance(expected_request_id, str)
        and region.get("request_id") == expected_request_id
        and isinstance(region.get("data"), dict)
    )
    if not valid:
        lines.append("🌐 Региональные параметры: агент не передал отдельный снимок.")
        return "\n".join(lines)

    data = region["data"]
    timezone_data = data.get("timezone") if isinstance(data.get("timezone"), dict) else {}
    locale_data = data.get("locale") if isinstance(data.get("locale"), dict) else {}
    timezone_name = timezone_data.get("name") if timezone_data.get("state") == "supported" else None
    offset = timezone_data.get("utc_offset_minutes")
    offset_text = ""
    if type(offset) is int and -840 <= offset <= 840:
        sign = "+" if offset >= 0 else "-"
        hours, minutes = divmod(abs(offset), 60)
        offset_text = f" UTC{sign}{hours:02d}:{minutes:02d}"
    locale_name = locale_data.get("name") if locale_data.get("state") == "supported" else None
    lines.extend([
        "🌐 Региональные параметры (D01-F23):",
        "• Часовой пояс: " + (esc(timezone_name) if isinstance(timezone_name, str) and timezone_name else "неизвестно") + offset_text,
        "• Локаль процесса: " + (esc(locale_name) if isinstance(locale_name, str) and locale_name else "неизвестно"),
    ])
    checked_at = region.get("checked_at")
    if isinstance(checked_at, str) and len(checked_at) <= 40:
        try:
            stamp = datetime.datetime.fromisoformat(checked_at)
            if stamp.utcoffset() is not None:
                lines.append("• Проверено: " + esc(checked_at))
        except (ValueError, TypeError, OverflowError):
            pass
    return "\n".join(lines)


def _format_cpu_history(
    result: dict, device_name: str, *, expected_device_id: str, expected_request_id: str,
) -> str:
    """Render only a complete, bounded CPU series tied to this exact request."""
    safe_name = html.escape(str(device_name)[:160])
    data = result.get("data") if isinstance(result, dict) else None
    valid = (
        isinstance(result, dict)
        and result.get("type") == "cpu_history"
        and result.get("schema") == "xider.cpu-history.v1"
        and result.get("feature_id") == "D01-F02"
        and result.get("device_id") == expected_device_id
        and result.get("request_id") == expected_request_id
        and result.get("state") == "supported"
        and result.get("source") == "psutil.cpu_percent"
        and isinstance(data, dict)
    )
    period = data.get("period_seconds") if valid else None
    interval = data.get("sample_interval_seconds") if valid else None
    samples = data.get("samples") if valid else None
    valid = (
        valid and type(period) is int and period in {15, 30, 60}
        and type(interval) is int and interval == 5
        and isinstance(samples, list) and len(samples) == period // interval
    )
    parsed = []
    if valid:
        for index, sample in enumerate(samples):
            if not isinstance(sample, dict):
                valid = False
                break
            offset = sample.get("offset_seconds")
            value = sample.get("percent")
            if (
                type(offset) is not int or offset != (index + 1) * interval
                or isinstance(value, bool) or not isinstance(value, (int, float))
                or not math.isfinite(value) or not 0 <= value <= 100
            ):
                valid = False
                break
            parsed.append((offset, float(value)))
    checked_at = result.get("checked_at") if isinstance(result, dict) else None
    if valid:
        try:
            stamp = datetime.datetime.fromisoformat(checked_at)
            valid = stamp.utcoffset() is not None
        except (TypeError, ValueError, OverflowError):
            valid = False
    if not valid:
        return (
            f"📈 <b>{safe_name}</b>\n\nИстория CPU (D01-F02): <b>неизвестно</b>. "
            "Нет полного свежего ответа, подходящего именно этому запросу."
        )

    lines = [
        f"📈 <b>{safe_name}</b>",
        f"История нагрузки CPU (D01-F02) · {period} секунд",
        "Локальные измерения раз в 5 секунд; это не прогноз и не системный журнал.",
    ]
    for offset, value in parsed:
        bar = "▰" * round(value / 10) + "▱" * (10 - round(value / 10))
        lines.append(f"{offset:02d} с  {bar}  {value:g}%")
    lines.append("Проверено: " + html.escape(checked_at, quote=False))
    return "\n".join(lines)


def _format_memory_history(
    result: dict, device_name: str, *, expected_device_id: str, expected_request_id: str,
) -> str:
    """Render only a complete RAM series and truthful, explicitly stated swap state."""
    safe_name = html.escape(str(device_name)[:160])
    data = result.get("data") if isinstance(result, dict) else None
    valid = (
        isinstance(result, dict)
        and result.get("type") == "memory_history"
        and result.get("schema") == "xider.memory-history.v1"
        and result.get("feature_id") == "D01-F03"
        and result.get("device_id") == expected_device_id
        and result.get("request_id") == expected_request_id
        and result.get("state") == "supported"
        and result.get("source") == "psutil.virtual_memory+psutil.swap_memory"
        and isinstance(data, dict)
    )
    period = data.get("period_seconds") if valid else None
    interval = data.get("sample_interval_seconds") if valid else None
    swap_state = data.get("swap_state") if valid else None
    samples = data.get("samples") if valid else None
    valid = (
        valid and type(period) is int and period in {15, 30, 60}
        and type(interval) is int and interval == 5
        and swap_state in ("supported", "unsupported", "unknown")
        and isinstance(samples, list) and len(samples) == period // interval
    )
    parsed = []
    if valid:
        for index, sample in enumerate(samples):
            if not isinstance(sample, dict):
                valid = False
                break
            offset = sample.get("offset_seconds")
            ram = sample.get("ram_percent")
            swap = sample.get("swap_percent")
            valid_ram = (
                not isinstance(ram, bool) and isinstance(ram, (int, float))
                and math.isfinite(ram) and 0 <= ram <= 100
            )
            if swap_state == "supported":
                valid_swap = (
                    not isinstance(swap, bool) and isinstance(swap, (int, float))
                    and math.isfinite(swap) and 0 <= swap <= 100
                )
            elif swap_state == "unsupported":
                valid_swap = swap is None
            else:
                # The agent may have partial readings when swap capabilities
                # change between samples. Keep the valid RAM series, but never
                # display any member of an incomplete swap series.
                valid_swap = True
            if type(offset) is not int or offset != (index + 1) * interval or not valid_ram or not valid_swap:
                valid = False
                break
            parsed.append((offset, float(ram), None if swap is None else float(swap)))
    checked_at = result.get("checked_at") if isinstance(result, dict) else None
    if valid:
        try:
            stamp = datetime.datetime.fromisoformat(checked_at)
            valid = stamp.utcoffset() is not None
        except (TypeError, ValueError, OverflowError):
            valid = False
    if not valid:
        return (
            f"🧠 <b>{safe_name}</b>\n\nИстория памяти (D01-F03): <b>неизвестно</b>. "
            "Нет полного свежего ответа, подходящего именно этому запросу."
        )

    lines = [
        f"🧠 <b>{safe_name}</b>",
        f"История памяти (D01-F03) · {period} секунд",
        "Локальные измерения раз в 5 секунд; это не фоновой журнал.",
    ]
    if swap_state == "unsupported":
        lines.append("swap: не поддерживается данной ОС или средой")
    elif swap_state == "unknown":
        lines.append("swap: неизвестно — источник не дал полного ряда")
    for offset, ram, swap in parsed:
        line = f"{offset:02d} с  RAM {ram:g}%"
        if swap_state == "supported":
            line += f" · swap {swap:g}%"
        lines.append(line)
    lines.append("Проверено: " + html.escape(checked_at, quote=False))
    return "\n".join(lines)


def _format_memory_pressure_history(
    result: dict, device_name: str, *, expected_device_id: str, expected_request_id: str,
) -> str:
    """Render only correlated samples while preserving each OS source's exact meaning."""
    safe_name = html.escape(str(device_name)[:160])
    data = result.get("data") if isinstance(result, dict) else None
    source = result.get("source") if isinstance(result, dict) else None
    source_states = {
        "windows_memory_resource_notification": {"low", "intermediate", "high", "unknown"},
        "macos_memory_pressure_utility_free_percent": {"supported", "unsupported", "unknown"},
    }
    valid = (
        isinstance(result, dict) and result.get("type") == "memory_pressure_history"
        and result.get("schema") == "xider.memory-pressure-history.v1"
        and result.get("feature_id") == "D01-F05"
        and result.get("device_id") == expected_device_id and result.get("request_id") == expected_request_id
        and result.get("state") in {"supported", "unsupported"}
        and source in source_states and isinstance(data, dict)
    )
    period = data.get("period_seconds") if valid else None
    interval = data.get("sample_interval_seconds") if valid else None
    samples = data.get("samples") if valid else None
    valid = (
        valid and type(period) is int and period in {15, 30, 60}
        and type(interval) is int and interval == 5
        and isinstance(samples, list) and len(samples) == period // interval
    )
    parsed = []
    if valid:
        for index, sample in enumerate(samples):
            if not isinstance(sample, dict) or type(sample.get("offset_seconds")) is not int:
                valid = False
                break
            state, available = sample.get("state"), sample.get("available_percent")
            if sample["offset_seconds"] != (index + 1) * interval or state not in source_states[source]:
                valid = False
                break
            if source == "windows_memory_resource_notification":
                if available is not None or state == "supported":
                    valid = False
                    break
            elif state == "supported":
                if (isinstance(available, bool) or not isinstance(available, (int, float))
                        or not math.isfinite(available) or not 0 <= available <= 100):
                    valid = False
                    break
            elif available is not None:
                valid = False
                break
            parsed.append((sample["offset_seconds"], state, None if available is None else float(available)))
    checked_at = result.get("checked_at") if isinstance(result, dict) else None
    if valid:
        try:
            stamp = datetime.datetime.fromisoformat(checked_at)
            valid = stamp.utcoffset() is not None
        except (TypeError, ValueError, OverflowError):
            valid = False
    if not valid:
        return (
            f"🧠 <b>{safe_name}</b>\n\nИстория системной памяти (D01-F05): <b>неизвестно</b>. "
            "Нет полного свежего ответа, совпадающего с этим запросом."
        )
    if result["state"] == "unsupported" or all(state == "unsupported" for _, state, _ in parsed):
        return f"🧠 <b>{safe_name}</b>\n\nИстория системной памяти (D01-F05): источник на этой системе не поддерживается."

    lines = [f"🧠 <b>{safe_name}</b>", f"История системной памяти (D01-F05) · {period} секунд"]
    if source == "macos_memory_pressure_utility_free_percent":
        lines.append("Источник: macOS memory_pressure, system-wide free-% метрика; это не график давления Activity Monitor.")
        for offset, state, available in parsed:
            value = f"{available:g}% свободной по метрике источника" if state == "supported" else "неизвестно"
            lines.append(f"{offset:02d} с  {value}")
    else:
        lines.append("Источник: системные Windows memory-resource notifications (пороги Low/High).")
        lines.append("Промежуточное значит: ни Low, ни High-сигнал не активен; это не отдельный уровень диагностики.")
        labels = {"low": "Low: сигнал низкой доступной памяти", "intermediate": "между порогами", "high": "High: сигнал высокой доступной памяти", "unknown": "неизвестно"}
        for offset, state, _available in parsed:
            lines.append(f"{offset:02d} с  {labels[state]}")
    lines.append("Снято только на время запроса; после его окончания агент не ведёт фоновые замеры.")
    lines.append("Проверено: " + html.escape(checked_at, quote=False))
    return "\n".join(lines)


def _format_thermal_snapshot(
    result: dict, device_name: str, *, expected_device_id: str, expected_request_id: str,
) -> str:
    """Render only bounded sensor records from the expected native provider and request."""
    safe_name = html.escape(str(device_name)[:160])
    data = result.get("data") if isinstance(result, dict) else None
    source = result.get("source") if isinstance(result, dict) else None
    valid = (
        isinstance(result, dict) and result.get("type") == "thermal_snapshot"
        and result.get("schema") == "xider.thermal-snapshot.v1" and result.get("feature_id") == "D01-F06"
        and result.get("device_id") == expected_device_id and result.get("request_id") == expected_request_id
        and result.get("state") in {"supported", "unsupported"}
        and source in {"windows_wmi_MSAcpi_ThermalZoneTemperature", "macos_public_temperature_sensor_api_unavailable"}
        and isinstance(data, dict) and isinstance(data.get("sensors"), list) and len(data["sensors"]) <= 32
    )
    checked_at = result.get("checked_at") if isinstance(result, dict) else None
    if valid:
        try:
            valid = datetime.datetime.fromisoformat(checked_at).utcoffset() is not None
        except (TypeError, ValueError, OverflowError):
            valid = False
    sensors = []
    if valid:
        for row in data["sensors"]:
            if not isinstance(row, dict):
                valid = False
                break
            label, temperature, quality = row.get("label"), row.get("temperature_c"), row.get("quality")
            if (not isinstance(label, str) or not label or len(label) > 64
                    or quality != "native_provider" or source != "windows_wmi_MSAcpi_ThermalZoneTemperature"
                    or isinstance(temperature, bool) or not isinstance(temperature, (int, float))
                    or not math.isfinite(temperature) or not -40 <= temperature <= 150):
                valid = False
                break
            sensors.append((label, float(temperature)))
        if result.get("state") == "supported" and not sensors:
            valid = False
        if result.get("state") == "unsupported" and data["sensors"]:
            valid = False
    if not valid:
        return f"🌡 <b>{safe_name}</b>\n\nТепловой обзор (D01-F06): <b>неизвестно</b>. Ответ пустой, устарел или не прошёл проверку."
    if result["state"] == "unsupported":
        return f"🌡 <b>{safe_name}</b>\n\nТепловые датчики: <b>не поддерживаются</b> доступным системным источником на этом устройстве. Значения не подменяются нулём."
    source_label = "Windows WMI ACPI thermal-zone provider"
    lines = [f"🌡 <b>{safe_name}</b>", "Тепловой обзор (D01-F06)", f"Источник: {source_label}; только показания, которые вернул драйвер."]
    for label, temperature in sensors:
        lines.append(f"{html.escape(label, quote=False)}: <b>{temperature:.1f}°C</b>")
    lines.append("Это не полная карта всех внутренних датчиков: аппаратный/драйверный источник может быть недоступен или неполон.")
    lines.append("Проверено: " + html.escape(checked_at, quote=False))
    return "\n".join(lines)


def _format_battery_health_snapshot(
    result: dict, device_name: str, *, expected_device_id: str, expected_request_id: str,
) -> str:
    """Render matched design/full capacity data, never current charge as battery health."""
    safe_name = html.escape(str(device_name)[:160])
    unknown = f"🔋 <b>{safe_name}</b>\n\nЗдоровье батареи (D01-F07): <b>неизвестно</b>. Ответ пустой, устарел или не прошёл проверку."
    if not isinstance(result, dict):
        return unknown
    source = result.get("source")
    data = result.get("data")
    state = result.get("state")
    valid = (
        result.get("type") == "battery_health_snapshot"
        and result.get("schema") == "xider.battery-health.v1" and result.get("feature_id") == "D01-F07"
        and result.get("device_id") == expected_device_id and result.get("request_id") == expected_request_id
        and state in {"supported", "unsupported", "unknown"}
        and source in {"windows_wmi_battery_capacity", "macos_system_profiler_battery_capacity"}
    )
    checked_at = result.get("checked_at")
    try:
        valid = valid and isinstance(checked_at, str) and datetime.datetime.fromisoformat(checked_at).utcoffset() is not None
    except (TypeError, ValueError, OverflowError):
        valid = False
    if not valid:
        return unknown
    if state == "unknown":
        if data not in (None, {"batteries": []}):
            return unknown
        return f"🔋 <b>{safe_name}</b>\n\nЗдоровье батареи: <b>неизвестно</b>. Источник не выдал достоверную пару ёмкостей."
    if not isinstance(data, dict) or not isinstance(data.get("batteries"), list) or len(data["batteries"]) > 8:
        return unknown
    if state == "unsupported":
        if data["batteries"]:
            return unknown
        return f"🔋 <b>{safe_name}</b>\n\nИсточник ёмкости батареи на этом устройстве недоступен. Значение не подменяется нулём."
    if not data["batteries"]:
        return unknown
    lines = [f"🔋 <b>{safe_name}</b>", "Здоровье батареи (D01-F07)"]
    for row in data["batteries"]:
        if not isinstance(row, dict):
            return unknown
        label = row.get("label")
        quality = row.get("quality")
        health = row.get("health_percent")
        if not isinstance(label, str) or not label or len(label) > 48 or isinstance(health, bool) or not isinstance(health, (int, float)) or not math.isfinite(health):
            return unknown
        if source == "windows_wmi_battery_capacity":
            design, full = row.get("design_capacity_mwh"), row.get("full_charge_capacity_mwh")
            expected_quality, unit = "native_provider", "mWh"
        else:
            design, full = row.get("design_capacity_mah"), row.get("full_charge_capacity_mah")
            expected_quality, unit = "system_profiler", "mAh"
        if (quality != expected_quality or isinstance(design, bool) or not isinstance(design, int)
                or isinstance(full, bool) or not isinstance(full, int)
                or not 0 < design < 10_000_000 or not 0 < full < 10_000_000
                or not 1 <= health <= 150 or abs(health - full * 100.0 / design) > 0.2):
            return unknown
        lines.append(
            f"{html.escape(label, quote=False)}: <b>{health:.1f}%</b> от проектной ёмкости "
            f"({full:,} / {design:,} {unit})".replace(",", " ")
        )
        if source == "macos_system_profiler_battery_capacity":
            condition = row.get("condition")
            if condition not in {"Normal", "Service Recommended", "Replace Soon", "Replace Now", "Fair", "Poor", "Unknown"}:
                return unknown
            lines.append("Состояние macOS: " + html.escape(condition, quote=False))
    lines.append("Это оценка сохранённой ёмкости относительно проектной, не текущий заряд и не диагноз производителя.")
    lines.append("Проверено: " + html.escape(checked_at, quote=False))
    return "\n".join(lines)


def _format_battery_cycle_snapshot(
    result: dict, device_name: str, *, expected_device_id: str, expected_request_id: str,
) -> str:
    """Render only a correlated, provider-reported battery cycle counter."""
    safe_name = html.escape(str(device_name)[:160])
    unknown = f"🔋 <b>{safe_name}</b>\n\nЦиклы батареи (D01-F08): <b>неизвестно</b>. Ответ пустой, устарел или не прошёл проверку."
    if not isinstance(result, dict):
        return unknown
    source, data, state = result.get("source"), result.get("data"), result.get("state")
    valid = (
        result.get("type") == "battery_cycle_snapshot"
        and result.get("schema") == "xider.battery-cycles.v1" and result.get("feature_id") == "D01-F08"
        and result.get("device_id") == expected_device_id and result.get("request_id") == expected_request_id
        and state in {"supported", "unsupported", "unknown"}
        and source in {"windows_wmi_battery_cycle_count", "macos_system_profiler_battery_cycle_count"}
    )
    checked_at = result.get("checked_at")
    try:
        valid = valid and isinstance(checked_at, str) and datetime.datetime.fromisoformat(checked_at).utcoffset() is not None
    except (TypeError, ValueError, OverflowError):
        valid = False
    if not valid:
        return unknown
    if state == "unknown":
        if data not in (None, {"batteries": []}):
            return unknown
        return f"🔋 <b>{safe_name}</b>\n\nСистемный источник не вернул достоверное число циклов."
    if not isinstance(data, dict) or not isinstance(data.get("batteries"), list) or len(data["batteries"]) > 8:
        return unknown
    if state == "unsupported":
        if data["batteries"]:
            return unknown
        return f"🔋 <b>{safe_name}</b>\n\nСчётчик циклов не предоставлен системой на этом устройстве; это не означает ноль циклов."
    if not data["batteries"]:
        return unknown
    expected_quality = "native_provider" if source == "windows_wmi_battery_cycle_count" else "system_profiler"
    lines = [f"🔋 <b>{safe_name}</b>", "Циклы батареи (D01-F08)"]
    for row in data["batteries"]:
        if not isinstance(row, dict):
            return unknown
        label, count, quality = row.get("label"), row.get("cycle_count"), row.get("quality")
        if (not isinstance(label, str) or not label or len(label) > 48 or quality != expected_quality
                or isinstance(count, bool) or not isinstance(count, int) or not 0 <= count <= 1_000_000
                or (source == "windows_wmi_battery_cycle_count" and count == 0)):
            return unknown
        lines.append(f"{html.escape(label, quote=False)}: <b>{count:,}</b> циклов".replace(",", " "))
    lines.append("Это счётчик циклов, не текущий заряд и не оценка здоровья батареи.")
    lines.append("Проверено: " + html.escape(checked_at, quote=False))
    return "\n".join(lines)


def _format_energy_usage_snapshot(
    result: dict, device_name: str, *, expected_device_id: str, expected_request_id: str,
) -> str:
    """Render only a correlated, bounded SRUM estimate; never claim measured watts."""
    safe_name = html.escape(str(device_name)[:160])
    unknown = (
        f"🔋 <b>{safe_name}</b>\n\nЭнергозатраты приложений (D01-F09): "
        "<b>неизвестно</b>. Ответ пустой, устарел или не прошёл проверку."
    )
    if not isinstance(result, dict):
        return unknown
    source, data, state = result.get("source"), result.get("data"), result.get("state")
    valid = (
        result.get("type") == "energy_usage_snapshot"
        and result.get("schema") == "xider.energy-usage.v1" and result.get("feature_id") == "D01-F09"
        and result.get("device_id") == expected_device_id and result.get("request_id") == expected_request_id
        and state in {"supported", "unsupported", "unknown"}
        and source in {"windows_srum_energy_estimation", "macos_public_per_app_energy_api_unavailable"}
        and isinstance(data, dict)
    )
    checked_at = result.get("checked_at")
    try:
        valid = valid and isinstance(checked_at, str) and datetime.datetime.fromisoformat(checked_at).utcoffset() is not None
    except (TypeError, ValueError, OverflowError):
        valid = False
    if not valid:
        return unknown
    apps = data.get("apps")
    if state == "unknown":
        if data not in ({"unit": None, "apps": []}, {"apps": []}):
            return unknown
        return f"🔋 <b>{safe_name}</b>\n\nСистемный источник энергопотребления не вернул достоверную сводку."
    if state == "unsupported":
        if apps != [] or data.get("unit") is not None:
            return unknown
        if source == "macos_public_per_app_energy_api_unavailable":
            detail = "macOS показывает Energy Impact в Activity Monitor, но агент не получил его через поддерживаемый публичный источник."
        else:
            detail = "Энергетическая оценка приложений на этой платформе не поддерживается доступным источником."
        return f"🔋 <b>{safe_name}</b>\n\n{detail}"
    if source != "windows_srum_energy_estimation" or data.get("unit") != "mJ":
        return unknown
    if not isinstance(apps, list) or not 1 <= len(apps) <= 8:
        return unknown
    lines = [f"🔋 <b>{safe_name}</b>", "Оценка энергозатрат приложений (D01-F09)"]
    seen: set[str] = set()
    for row in apps:
        if not isinstance(row, dict):
            return unknown
        name, energy, quality = row.get("name"), row.get("energy_mj"), row.get("quality")
        if (not isinstance(name, str) or not 1 <= len(name) <= 96 or "/" in name or "\\" in name
                or any(ord(char) < 32 for char in name) or quality != "estimated"
                or isinstance(energy, bool) or not isinstance(energy, int) or not 0 <= energy <= 1_000_000_000_000):
            return unknown
        if name.casefold() in seen:
            return unknown
        seen.add(name.casefold())
        lines.append(f"{html.escape(name, quote=False)}: <b>{energy:,} mJ</b> (оценка)".replace(",", " "))
    lines.append("Это программная оценка SRUM, не показание ваттметра и не точное измерение энергии от розетки.")
    lines.append("Сырые строки SRUM не передаются; отправлена только сводка имён и оценок.")
    lines.append("Проверено: " + html.escape(checked_at, quote=False))
    return "\n".join(lines)


def _format_sleep_wake_history_snapshot(
    result: dict, device_name: str, *, expected_device_id: str, expected_request_id: str,
) -> str:
    """Render only fresh correlated sleep/wake timestamps from an allowlisted OS source."""
    safe_name = html.escape(str(device_name)[:160])
    unknown = (
        f"🛌 <b>{safe_name}</b>\n\nИстория сна и пробуждений (D01-F10): "
        "<b>неизвестно</b>. Ответ пустой, устарел или не прошёл проверку."
    )
    if not isinstance(result, dict):
        return unknown
    source = result.get("source")
    state = result.get("state")
    data = result.get("data")
    sources = {"windows_system_power_events", "macos_pmset_log"}
    valid = (
        result.get("type") == "sleep_wake_history_snapshot"
        and result.get("schema") == "xider.sleep-wake-history.v1"
        and result.get("feature_id") == "D01-F10"
        and result.get("device_id") == expected_device_id
        and result.get("request_id") == expected_request_id
        and source in sources and state in {"supported", "unsupported", "unknown"}
        and isinstance(data, dict) and type(data.get("history_days")) is int
        and data.get("history_days") == 7 and isinstance(data.get("events"), list)
    )
    checked = result.get("checked_at")
    try:
        checked_at = datetime.datetime.fromisoformat(checked)
        valid = valid and checked_at.utcoffset() is not None
    except (TypeError, ValueError, OverflowError):
        valid = False
        checked_at = None
    events = data.get("events") if isinstance(data, dict) else None
    if valid and state == "supported":
        valid = 1 <= len(events) <= 30
    elif valid:
        valid = len(events) == 0
    parsed = []
    if valid and state == "supported":
        cutoff = checked_at - datetime.timedelta(days=7)
        previous = None
        for event in events:
            if not isinstance(event, dict):
                valid = False
                break
            kind = event.get("kind")
            try:
                stamp = datetime.datetime.fromisoformat(event.get("timestamp"))
            except (TypeError, ValueError, OverflowError):
                valid = False
                break
            if (kind not in {"sleep", "wake"} or stamp.utcoffset() is None
                    or stamp < cutoff or stamp > checked_at or (previous is not None and stamp < previous)):
                valid = False
                break
            previous = stamp
            parsed.append((kind, stamp))
    if not valid:
        return unknown
    if state == "unsupported":
        return f"🛌 <b>{safe_name}</b>\n\nИстория сна и пробуждений (D01-F10): <b>недоступно</b> — системный источник не поддерживается."
    if state == "unknown":
        return f"🛌 <b>{safe_name}</b>\n\nИстория сна и пробуждений (D01-F10): системный источник не вернул достоверные события."
    source_label = "Windows System power events" if source == "windows_system_power_events" else "macOS pmset"
    lines = [f"🛌 <b>{safe_name}</b>", "Сон и пробуждения за последние 7 дней", f"Источник: {source_label}"]
    lines.extend(
        f"{'🌙 Сон' if kind == 'sleep' else '☀️ Пробуждение'} · {stamp.astimezone(datetime.timezone.utc).strftime('%Y-%m-%d %H:%M UTC')}"
        for kind, stamp in parsed
    )
    lines.append("Показаны только тип события и время; подробности системного журнала не передаются.")
    return "\n".join(lines)


def _format_startup_duration_snapshot(
    result: dict, device_name: str, *, expected_device_id: str, expected_request_id: str,
) -> str:
    """Render measured OS boot duration only; never substitute uptime or wall-clock guesses."""
    safe_name = html.escape(str(device_name)[:160])
    unknown = (
        f"⏱ <b>{safe_name}</b>\n\nДлительность системного старта (D01-F11): "
        "<b>неизвестно</b>. Ответ пустой, устарел или не прошёл проверку."
    )
    if not isinstance(result, dict):
        return unknown
    source, state, data = result.get("source"), result.get("state"), result.get("data")
    supported_source = "windows_diagnostics_performance_event_100"
    unsupported_source = "macos_boot_duration_api_unavailable"
    valid = (
        result.get("type") == "startup_duration_snapshot"
        and result.get("schema") == "xider.startup-duration.v1"
        and result.get("feature_id") == "D01-F11"
        and result.get("device_id") == expected_device_id
        and result.get("request_id") == expected_request_id
        and state in {"supported", "unsupported", "unknown"}
        and source in {supported_source, unsupported_source}
        and isinstance(data, dict)
    )
    checked_raw = result.get("checked_at")
    try:
        checked_at = datetime.datetime.fromisoformat(checked_raw)
        valid = valid and checked_at.utcoffset() is not None
    except (TypeError, ValueError, OverflowError):
        valid = False
        checked_at = None
    if valid and state == "supported":
        duration, completed_raw = data.get("duration_ms"), data.get("completed_at")
        try:
            completed_at = datetime.datetime.fromisoformat(completed_raw)
        except (TypeError, ValueError, OverflowError):
            valid = False
            completed_at = None
        valid = (
            valid and source == supported_source
            and isinstance(duration, int) and not isinstance(duration, bool) and 0 < duration <= 30 * 60 * 1000
            and completed_at is not None and completed_at.utcoffset() is not None
            and completed_at <= checked_at
        )
    elif valid:
        valid = data.get("duration_ms") is None and data.get("completed_at") is None
    if not valid:
        return unknown
    if state == "unsupported":
        return f"⏱ <b>{safe_name}</b>\n\nДлительность системного старта (D01-F11): <b>недоступно</b> — на этой ОС нет надёжного поддерживаемого источника."
    if state == "unknown":
        return f"⏱ <b>{safe_name}</b>\n\nДлительность системного старта (D01-F11): источник не дал измерение; время не рассчитано по uptime."
    seconds = duration / 1000
    duration_text = f"{seconds:.1f}".replace(".", ",")
    checked_text = html.escape(completed_at.astimezone(datetime.timezone.utc).strftime("%Y-%m-%d %H:%M UTC"), quote=False)
    return (
        f"⏱ <b>{safe_name}</b>\n\nИзмеренная длительность загрузки: <b>{duration_text} сек</b>\n"
        f"Событие: {checked_text}\nИсточник: Windows Diagnostics-Performance, BootTime. Это не uptime."
    )


def _format_pending_restart_snapshot(
    result: dict, device_name: str, *, expected_device_id: str, expected_request_id: str,
) -> str:
    """Render a correlated OS reboot marker without exposing raw registry data."""
    safe_name = html.escape(str(device_name)[:160])
    prefix = f"🔄 <b>{safe_name}</b>\n\nОжидающая перезагрузка (D01-F12): "
    unknown = prefix + "<b>неизвестно</b>. Ответ пустой, устарел или не прошёл проверку."
    if not isinstance(result, dict):
        return unknown
    data = result.get("data")
    state, source = result.get("state"), result.get("source")
    supported_source = "windows_pending_restart_registry"
    unsupported_source = "macos_pending_restart_flag_unavailable"
    valid = (
        result.get("type") == "pending_restart_snapshot"
        and result.get("schema") == "xider.pending-restart.v1"
        and result.get("feature_id") == "D01-F12"
        and result.get("device_id") == expected_device_id
        and result.get("request_id") == expected_request_id
        and state in {"supported", "unsupported", "unknown"}
        and source in {supported_source, unsupported_source}
        and isinstance(data, dict)
    )
    checked_raw = result.get("checked_at")
    try:
        checked_at = datetime.datetime.fromisoformat(checked_raw)
        valid = valid and checked_at.utcoffset() is not None
    except (TypeError, ValueError, OverflowError):
        valid = False
    if valid and state == "supported":
        pending, reasons, completeness = data.get("pending"), data.get("reasons"), data.get("completeness")
        known_reasons = {"component_servicing", "windows_update", "pending_file_operations", "update_exe_volatile"}
        valid = (
            source == supported_source and isinstance(pending, bool)
            and isinstance(reasons, list) and len(reasons) <= len(known_reasons)
            and all(reason in known_reasons for reason in reasons)
            and len(set(reasons)) == len(reasons)
            and completeness in {"complete", "partial"}
            and ((pending and bool(reasons)) or (not pending and not reasons))
            and (completeness != "partial" or pending)
        )
    elif valid:
        valid = (
            data.get("pending") is None and data.get("reasons") == []
            and data.get("completeness") == "unknown"
        )
    if not valid:
        return unknown
    if state == "unsupported":
        return prefix + "<b>недоступно</b> — macOS-агент не располагает надёжным публичным флагом этого состояния."
    if state == "unknown":
        return prefix + "источник ОС не вернул достоверный результат; отсутствие флага не подтверждено."
    if not pending:
        return prefix + "<b>не требуется по проверенным маркерам</b>. Это не гарантия, что приложения не попросят перезапуск."
    labels = {
        "component_servicing": "обслуживание компонентов Windows",
        "windows_update": "Windows Update",
        "pending_file_operations": "ожидающие файловые операции",
        "update_exe_volatile": "маркер установщика обновлений",
    }
    reason_text = ", ".join(labels[reason] for reason in reasons)
    partial_note = " Проверка частичная: некоторые маркеры прочитать не удалось." if completeness == "partial" else ""
    return prefix + f"<b>требуется</b>. Известные причины: {html.escape(reason_text)}.{partial_note}"


def _format_os_support_snapshot(
    result: dict | None, device_name: str, *, expected_device_id: str, expected_request_id: str,
) -> str:
    """Render the exact correlated OS identity against our dated official-source snapshot."""
    safe_name = html.escape(str(device_name)[:160])
    prefix = f"🧭 <b>{safe_name}</b>\n\nСтатус версии ОС (D01-F13): "
    unknown = prefix + "<b>неизвестно</b>. Ответ отсутствует, устарел или не прошёл проверку."
    if not isinstance(result, dict):
        return unknown
    data = result.get("data")
    if not isinstance(data, dict):
        return unknown
    family, release, edition = data.get("family"), data.get("release"), data.get("edition")
    source = result.get("source")
    allowed_sources = {
        "windows_current_version_registry": "windows",
        "macos_platform_version": "macos",
    }
    state = result.get("state")
    valid = (
        result.get("type") == "os_support_snapshot"
        and result.get("schema") == "xider.os-support.v1"
        and result.get("feature_id") == "D01-F13"
        and result.get("device_id") == expected_device_id
        and result.get("request_id") == expected_request_id
        and source in allowed_sources
        and family == allowed_sources.get(source)
        and state in {"supported", "unsupported", "unknown"}
    )
    checked_raw = result.get("checked_at")
    try:
        checked_at = datetime.datetime.fromisoformat(checked_raw)
        now = datetime.datetime.now(datetime.timezone.utc)
        age = (now - checked_at.astimezone(datetime.timezone.utc)).total_seconds()
        valid = valid and checked_at.utcoffset() is not None and -30 <= age <= 120
    except (TypeError, ValueError, OverflowError):
        valid = False
    if not valid:
        return unknown
    if state == "unsupported":
        return prefix + "<b>недоступно</b> — агент не смог прочитать версию этой ОС."
    if state == "unknown" or not isinstance(release, str) or not 1 <= len(release) <= 32:
        return unknown
    if family == "windows":
        if edition not in {"Home", "Pro"}:
            return unknown
    elif edition is not None:
        return unknown

    classification = classify_os_support(family, release, edition)
    status = classification.get("status")
    if status in {"unknown", "reference_expired"}:
        return prefix + "<b>неизвестно</b> — датированный справочник не содержит свежую запись для этой версии ОС."

    safe_release = html.escape(release.replace("|", " "), quote=False)
    suffix = f" · {html.escape(edition, quote=False)}" if edition else ""
    source_url = classification.get("source_url")
    source_labels = {
        "https://learn.microsoft.com/en-us/lifecycle/products/windows-11-home-and-pro": "Microsoft Lifecycle",
        "https://learn.microsoft.com/en-us/lifecycle/products/windows-10-home-and-pro": "Microsoft Lifecycle",
        "https://support.apple.com/en-us/100100": "Apple security releases",
    }
    if source_url not in source_labels:
        return unknown
    reference_date = html.escape(str(classification.get("as_of", "")), quote=False)
    expires_date = html.escape(str(classification.get("expires_on", "")), quote=False)
    source_link = f'<a href="{source_url}">{source_labels[source_url]}</a>'
    if family == "windows":
        end_date = html.escape(str(classification.get("support_end", "")), quote=False)
        claim = (
            f"Поддержка заявлена по <b>{end_date}</b>." if status == "supported"
            else f"Официальная поддержка завершилась <b>{end_date}</b>."
        )
    else:
        observed = html.escape(str(classification.get("last_security_update", "")), quote=False)
        if status == "security_update_observed":
            claim = f"В истории Apple найдены обновления безопасности для этой основной версии до <b>{observed}</b>."
        else:
            claim = f"В локальной выборке нет недавнего обновления безопасности для этой основной версии; последнее найденное — <b>{observed}</b>."
        claim += " Apple не публикует здесь фиксированную дату окончания поддержки macOS."
    return (
        f"{prefix}<b>{safe_release}{suffix}</b>\n{claim}\n"
        f"Сверено по {source_link} на <b>{reference_date}</b>; справочник требует обновления после <b>{expires_date}</b>."
    )


def _record_hardware_inventory_snapshot(
    result: dict | None, device_name: str, *, expected_device_id: str, expected_request_id: str,
) -> str:
    """Persist only allowlisted hardware fields from this fresh correlated reply."""
    prefix = f"🧩 <b>{html.escape(str(device_name)[:160])}</b>\n\nИстория оборудования (D01-F14): "
    unknown = prefix + "<b>неизвестно</b>. Нет свежего проверенного ответа; снимок не сохранён."
    if not isinstance(result, dict):
        return unknown
    state, source = result.get("state"), result.get("source")
    data = result.get("data")
    allowed_sources = {
        "windows_cim_hardware_inventory": "windows",
        "macos_sysctl_hardware_inventory": "macos",
    }
    valid = (
        result.get("type") == "hardware_inventory_snapshot"
        and result.get("schema") == "xider.hardware-inventory.v1"
        and result.get("feature_id") == "D01-F14"
        and result.get("device_id") == expected_device_id
        and result.get("request_id") == expected_request_id
        and source in allowed_sources and state in {"supported", "unsupported", "unknown"}
    )
    checked_raw = result.get("checked_at")
    try:
        checked_at = datetime.datetime.fromisoformat(checked_raw)
        age = (datetime.datetime.now(datetime.timezone.utc) - checked_at.astimezone(datetime.timezone.utc)).total_seconds()
        valid = valid and checked_at.utcoffset() is not None and -30 <= age <= 120
    except (TypeError, ValueError, OverflowError):
        valid = False
    if not valid:
        return unknown
    if state == "unsupported":
        return prefix + "<b>недоступно</b> — платформа не предоставила поддерживаемый источник характеристик."
    if state != "supported" or not isinstance(data, dict):
        return unknown
    try:
        inventory = DeviceStore._normalize_hardware_inventory(data)
    except ValueError:
        return unknown
    if not any(value is not None for key, value in inventory.items() if key != "graphics") and not inventory["graphics"]:
        return unknown
    devices.save_hardware_inventory_snapshot(expected_device_id, inventory)
    try:
        comparison = devices.compare_hardware_inventory_snapshots(expected_device_id)
    except ValueError:
        return prefix + "Снимок сохранён. Для сравнения нужен ещё один снимок; серийные номера не собираются."

    labels = {
        "manufacturer": "Производитель", "model": "Модель", "cpu": "Процессор",
        "architecture": "Архитектура", "memory_gib": "Память, ГиБ", "graphics": "Графика",
    }
    changes = comparison.get("changes")
    if not isinstance(changes, list) or len(changes) > 6:
        return unknown
    if not changes:
        return prefix + "Снимок сохранён; по наблюдаемым полям изменений нет. Серийные номера не собираются."

    def display(value):
        if isinstance(value, list):
            return ", ".join(html.escape(str(item)[:120]) for item in value[:8]) or "—"
        if value is None:
            return "—"
        return html.escape(str(value)[:240])

    lines = []
    for item in changes:
        if not isinstance(item, dict) or item.get("field") not in labels:
            return unknown
        lines.append(
            f"• <b>{labels[item['field']]}</b>: {display(item.get('before'))} → {display(item.get('after'))}"
        )
    return prefix + "Изменения между двумя последними снимками:\n" + "\n".join(lines) + "\nСерийные номера не сохраняются."


def _record_driver_inventory_snapshot(
    result: dict | None, device_name: str, *, expected_device_id: str, expected_request_id: str,
) -> str:
    prefix = f"🧰 <b>{html.escape(str(device_name)[:160])}</b>\n\nИстория драйверов (D01-F15): "
    unknown = prefix + "<b>неизвестно</b>. Нет свежего проверенного ответа; снимок не сохранён."
    if not isinstance(result, dict):
        return unknown
    source = result.get("source")
    state = result.get("state")
    allowed_sources = {
        "windows_cim_signed_drivers": "windows",
        "macos_driver_inventory_unavailable": "macos",
    }
    valid = (
        result.get("type") == "driver_inventory_snapshot"
        and result.get("schema") == "xider.driver-inventory.v1"
        and result.get("feature_id") == "D01-F15"
        and result.get("device_id") == expected_device_id
        and result.get("request_id") == expected_request_id
        and source in allowed_sources and state in {"supported", "unsupported", "unknown"}
    )
    checked_raw = result.get("checked_at")
    try:
        checked_at = datetime.datetime.fromisoformat(checked_raw)
        age = (datetime.datetime.now(datetime.timezone.utc) - checked_at.astimezone(datetime.timezone.utc)).total_seconds()
        valid = valid and checked_at.utcoffset() is not None and -30 <= age <= 120
    except (TypeError, ValueError, OverflowError):
        valid = False
    if not valid:
        return unknown
    if state == "unsupported":
        return prefix + "<b>недоступно</b> — эта платформа не предоставляет поддерживаемый список драйверов."
    if state != "supported" or not isinstance(result.get("data"), dict):
        return unknown
    try:
        rows = DeviceStore._normalize_driver_inventory(result["data"].get("drivers"))
    except ValueError:
        return unknown
    if not rows:
        return unknown
    devices.save_driver_inventory_snapshot(expected_device_id, rows)
    try:
        comparison = devices.compare_driver_inventory_snapshots(expected_device_id)
    except ValueError:
        return prefix + f"Снимок сохранён: {len(rows)} драйверов. Для сравнения нужен ещё один снимок."
    changes = comparison.get("changes")
    if not isinstance(changes, list) or len(changes) > 300:
        return unknown
    if not changes:
        return prefix + f"Снимок сохранён: {len(rows)} драйверов. Между двумя последними снимками изменений нет."
    labels = {"added": "добавлен", "removed": "исчез", "changed": "изменён"}
    lines = []
    for item in changes[:12]:
        if not isinstance(item, dict) or item.get("kind") not in labels:
            return unknown
        name = html.escape(str(item.get("device_name") or "?")[:120])
        provider = html.escape(str(item.get("provider") or "—")[:100])
        before, after = item.get("before"), item.get("after")
        if before is not None and not isinstance(before, dict) or after is not None and not isinstance(after, dict):
            return unknown
        old = html.escape(str((before or {}).get("version") or "—")[:80])
        new = html.escape(str((after or {}).get("version") or "—")[:80])
        lines.append(f"• <b>{labels[item['kind']]}</b>: {name} · {provider} · {old} → {new}")
    suffix = f"\n…ещё {len(changes) - len(lines)} изменений." if len(changes) > len(lines) else ""
    return prefix + "Изменения между двумя последними снимками:\n" + "\n".join(lines) + suffix


