def _format_crash_summary(
    result: dict | None, device_name: str, *, expected_device_id: str, expected_request_id: str,
) -> str:
    prefix = f"🧯 <b>{html.escape(str(device_name)[:160])}</b>\n\nСводка системных сбоев (D01-F19): "
    unknown = prefix + "<b>неизвестно</b>. Нет свежего проверенного ответа."
    if not isinstance(result, dict):
        return unknown
    state, source = result.get("state"), result.get("source")
    allowed_sources = {"windows_event_log_provider_event_aggregate": "windows", "macos_crash_summary_unavailable": "macos"}
    valid = (
        result.get("type") == "crash_summary_snapshot"
        and result.get("schema") == "xider.crash-summary.v1"
        and result.get("feature_id") == "D01-F19"
        and result.get("device_id") == expected_device_id
        and result.get("request_id") == expected_request_id
        and source in allowed_sources and state in {"supported", "unsupported", "unknown"}
    )
    try:
        checked_at = datetime.datetime.fromisoformat(result.get("checked_at"))
        age = (datetime.datetime.now(datetime.timezone.utc) - checked_at.astimezone(datetime.timezone.utc)).total_seconds()
        valid = valid and checked_at.utcoffset() is not None and -30 <= age <= 120
    except (TypeError, ValueError, OverflowError):
        valid = False
    if not valid:
        return unknown
    if state == "unsupported":
        return prefix + "<b>недоступно</b> — источник не поддержан без выгрузки приватного текста журнала."
    data = result.get("data")
    events = data.get("events") if isinstance(data, dict) else None
    if state != "supported" or not isinstance(events, list) or len(events) > 100:
        return unknown
    lines = []
    for item in events:
        if not isinstance(item, dict):
            return unknown
        provider, event_id, level, count = item.get("provider"), item.get("event_id"), item.get("level"), item.get("count")
        if (not isinstance(provider, str) or not 1 <= len(provider) <= 120
                or any(ord(char) < 32 for char in provider)
                or type(event_id) is not int or not 1 <= event_id <= 65535
                or type(level) is not int or level not in {1, 2}
                or type(count) is not int or not 1 <= count <= 500):
            return unknown
        severity = "критических" if level == 1 else "ошибок"
        lines.append(f"• {html.escape(provider)} · событие {event_id} · {severity}: {count}")
    if not lines:
        return prefix + "за последние 7 дней критических событий и ошибок не найдено. Текст журналов не собирался."
    return prefix + "за 7 дней:\n" + "\n".join(lines) + "\nПоказаны агрегаты; сообщения журналов не отправлялись."


def _record_smart_trend_snapshot(
    result: dict | None, device_name: str, *, expected_device_id: str, expected_request_id: str,
) -> str:
    prefix = f"💽 <b>{html.escape(str(device_name)[:160])}</b>\n\nSMART-тренд (D01-F20): "
    unknown = prefix + "<b>неизвестно</b> — нет свежего коррелированного ответа; снимок не сохранён."
    if not isinstance(result, dict):
        return unknown
    allowed_sources = {
        "windows_storage_reliability_counters": "windows",
        "macos_diskutil_smart_status_only": "macos",
    }
    source, state = result.get("source"), result.get("state")
    valid = (
        result.get("type") == "smart_trend_snapshot"
        and result.get("schema") == "xider.smart-trend.v1"
        and result.get("feature_id") == "D01-F20"
        and result.get("device_id") == expected_device_id
        and result.get("request_id") == expected_request_id
        and source in allowed_sources and state in {"supported", "unsupported", "unknown"}
    )
    try:
        checked_at = datetime.datetime.fromisoformat(result.get("checked_at"))
        age = (datetime.datetime.now(datetime.timezone.utc) - checked_at.astimezone(datetime.timezone.utc)).total_seconds()
        valid = valid and checked_at.utcoffset() is not None and -30 <= age <= 120
    except (TypeError, ValueError, OverflowError):
        valid = False
    if not valid:
        return unknown
    if state == "unsupported":
        return prefix + "счётчики для истории недоступны на этой платформе/накопителе; старый SMART-статус остаётся отдельной проверкой."
    if state != "supported":
        return unknown
    data = result.get("data")
    if not isinstance(data, dict) or set(data) != {"disks"}:
        return unknown
    try:
        normalized = devices._normalize_smart_trend_disks(data["disks"])
        if not normalized:
            return unknown
        devices.save_smart_trend_snapshot(expected_device_id, normalized, now=int(checked_at.timestamp()))
        comparison = devices.compare_smart_trend_snapshots(expected_device_id)
    except (AttributeError, TypeError, ValueError, OSError):
        return unknown
    if not comparison["changes"]:
        return prefix + "два сохранённых замера совпадают. Это показания, не диагноз состояния диска."
    lines = []
    for change in comparison["changes"][:12]:
        label = html.escape(change["label"][:160])
        counter = html.escape(change["counter"].replace("_", " "))
        before, after, delta = change["before"], change["after"], change["delta"]
        old = "—" if before is None else f"{before:g}"
        new = "—" if after is None else f"{after:g}"
        movement = "" if delta is None else f" (Δ {delta:+g})"
        lines.append(f"• {label} · {counter}: {old} → {new}{movement}")
    suffix = f"\n…ещё {len(comparison['changes']) - len(lines)} изменений." if len(comparison["changes"]) > len(lines) else ""
    elapsed = comparison["elapsed_seconds"]
    return (
        prefix + f"изменения за {elapsed // 3600} ч {(elapsed % 3600) // 60} мин:\n"
        + "\n".join(lines) + suffix + "\nСравниваются только одинаковые доступные счётчики; серийники не сохраняются."
    )


def _format_clock_drift(
    result: dict | None, device_name: str, *, expected_device_id: str,
    expected_request_id: str,
) -> str:
    """Render a local wall-vs-monotonic estimate without claiming NTP accuracy."""
    safe_name = html.escape(str(device_name)[:160])
    unknown = f"🕒 <b>{safe_name}</b>\n\nПроверка часов (D01-F22): <b>неизвестно</b> — нет свежего корректного ответа."
    valid = (
        isinstance(result, dict) and result.get("type") == "clock_drift_snapshot"
        and result.get("schema") == "xider.clock-drift.v1" and result.get("feature_id") == "D01-F22"
        and result.get("device_id") == expected_device_id and result.get("request_id") == expected_request_id
        and result.get("source") == "wall_vs_monotonic_elapsed"
        and result.get("state") in {"supported", "unknown"}
    )
    try:
        checked_at = datetime.datetime.fromisoformat(result.get("checked_at"))
        age = (datetime.datetime.now(datetime.timezone.utc) - checked_at.astimezone(datetime.timezone.utc)).total_seconds()
        valid = valid and checked_at.utcoffset() is not None and -30 <= age <= 120
    except (AttributeError, TypeError, ValueError, OverflowError):
        valid = False
    if not valid:
        return unknown
    if result["state"] != "supported":
        return f"🕒 <b>{safe_name}</b>\n\nПроверка часов (D01-F22): локальный замер не дал надёжного результата."
    data = result.get("data")
    if not isinstance(data, dict) or set(data) != {"drift_ms", "sample_ms"}:
        return unknown
    drift_ms, sample_ms = data.get("drift_ms"), data.get("sample_ms")
    if (type(drift_ms) is not int or not -60_000 <= drift_ms <= 60_000
            or type(sample_ms) is not int or not 500 <= sample_ms <= 5_000):
        return unknown
    return (
        f"🕒 <b>{safe_name}</b>\n\nОценка расхождения за {sample_ms} мс: <b>{drift_ms:+d} мс</b>.\n"
        "Сравнение системных часов с монотонными за короткий интервал; это не проверка NTP и не оценка точности времени."
    )


def _record_system_summary_snapshot(
    result: dict | None, device_name: str, *, expected_device_id: str,
    expected_request_id: str, expected_platform: str,
) -> str:
    """Persist only a fresh, correlated allowlist from the owner's sysinfo request."""
    safe_name = html.escape(str(device_name)[:160])
    unknown = f"📊 <b>{safe_name}</b>\n\nИстория системных снимков (D01-F24): нет свежей корректной сводки; ничего не сохранено."
    region = result.get("regional_settings") if isinstance(result, dict) else None
    valid = (
        isinstance(result, dict) and result.get("type") == "sysinfo"
        and result.get("device_id") == expected_device_id
        and isinstance(region, dict) and region.get("schema") == 1
        and region.get("feature_id") == "D01-F23"
        and region.get("device_id") == expected_device_id
        and region.get("request_id") == expected_request_id
        and region.get("source") == "local_os_runtime_apis"
        and region.get("state") in {"supported", "unknown"}
    )
    try:
        checked_at = datetime.datetime.fromisoformat(region.get("checked_at"))
        age = (datetime.datetime.now(datetime.timezone.utc) - checked_at.astimezone(datetime.timezone.utc)).total_seconds()
        valid = valid and checked_at.utcoffset() is not None and -30 <= age <= 120
    except (AttributeError, TypeError, ValueError, OverflowError):
        valid = False
    if not valid:
        return unknown
    raw_platform = result.get("os")
    platform_text = str(raw_platform) if isinstance(raw_platform, str) else ""
    reported = "macos" if platform_text.lower().startswith(("mac", "darwin")) else "windows" if platform_text.lower().startswith("win") else None
    expected = "macos" if expected_platform.lower().startswith(("mac", "darwin")) else "windows" if expected_platform.lower().startswith("win") else None
    if reported is None or expected is not None and reported != expected:
        return unknown
    summary = {"platform": platform_text}
    observed = 0
    for field in ("cpu_percent", "ram_percent", "disk_percent"):
        value = result.get(field)
        if (isinstance(value, bool) or not isinstance(value, (int, float))
                or not math.isfinite(value) or not 0 <= value <= 100):
            summary[field] = None
        else:
            summary[field] = round(float(value), 1)
            observed += 1
    if observed == 0:
        return unknown
    try:
        devices.save_system_summary_snapshot(
            expected_device_id, summary, captured_at=int(checked_at.timestamp()),
        )
        rows = devices.list_system_summary_snapshots(expected_device_id, limit=10)
    except (AttributeError, TypeError, ValueError, OSError):
        return unknown
    if not rows:
        return unknown
    lines = []
    for row in rows:
        stamp = datetime.datetime.fromtimestamp(row["captured_at"], datetime.timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
        values = row["summary"]
        def metric(field):
            value = values.get(field)
            return "—" if value is None else f"{value:g}%"
        lines.append(
            f"• {stamp} · {html.escape(values['platform'])} · CPU {metric('cpu_percent')} · "
            f"RAM {metric('ram_percent')} · диск {metric('disk_percent')}"
        )
    return (
        f"📊 <b>{safe_name}</b>\n\nИстория системных снимков (D01-F24), последние {len(lines)}:\n"
        + "\n".join(lines)
        + f"\nХранение ограничено: {devices.SYSTEM_SUMMARY_TTL_SECONDS // 86400} дней, до {devices.SYSTEM_SUMMARY_LIMIT} снимков. "
        "Сохраняются только платформа и проценты CPU/RAM/диска; имя хоста и MAC не сохраняются."
    )


def _format_volume_topology(
    result: dict | None, device_name: str, *, expected_device_id: str,
    expected_request_id: str, platform: str,
) -> str:
    """Render exact correlated volume aliases; raw provider identities never leave agents."""
    safe_name = html.escape(str(device_name)[:160])
    unknown = f"💽 <b>{safe_name}</b>\n\nКарта томов (D01-F21): <b>неизвестно</b> — нет свежего корректного ответа."
    is_macos = "mac" in platform.lower() or "darwin" in platform.lower()
    expected_source = (
        "macos_psutil_partitions_and_stat_device" if is_macos
        else "windows_get_volume_partition_access_paths"
    )
    valid = (
        isinstance(result, dict) and result.get("type") == "volume_topology_snapshot"
        and result.get("schema") == "xider.volume-topology.v1" and result.get("feature_id") == "D01-F21"
        and result.get("device_id") == expected_device_id and result.get("request_id") == expected_request_id
        and result.get("source") == expected_source
        and result.get("state") in {"supported", "unsupported", "unknown"}
    )
    try:
        checked_at = datetime.datetime.fromisoformat(result.get("checked_at"))
        age = (datetime.datetime.now(datetime.timezone.utc) - checked_at.astimezone(datetime.timezone.utc)).total_seconds()
        valid = valid and checked_at.utcoffset() is not None and -30 <= age <= 120
    except (AttributeError, TypeError, ValueError, OverflowError):
        valid = False
    if not valid:
        return unknown
    if result["state"] == "unsupported":
        return f"💽 <b>{safe_name}</b>\n\nКарта томов (D01-F21): эта платформа не предоставляет нужный источник."
    if result["state"] != "supported":
        return unknown
    data = result.get("data")
    if not isinstance(data, dict) or set(data) != {"volumes"}:
        return unknown
    volumes = data.get("volumes")
    if not isinstance(volumes, list) or not 1 <= len(volumes) <= 64:
        return unknown
    rows = []
    seen = set()
    for volume in volumes:
        if not isinstance(volume, dict) or set(volume) != {"volume_key", "mount_paths", "state"}:
            return unknown
        key, paths = volume.get("volume_key"), volume.get("mount_paths")
        if (not isinstance(key, str) or not re.fullmatch(r"vol-[0-9a-f]{16}", key)
                or key in seen or volume.get("state") != "supported"
                or not isinstance(paths, list) or not 1 <= len(paths) <= 16):
            return unknown
        seen.add(key)
        clean_paths = []
        for path in paths:
            if (not isinstance(path, str) or not path or len(path) > 512
                    or any(ord(char) < 32 for char in path)):
                return unknown
            clean_paths.append(html.escape(path))
        rows.append("• " + " · ".join(clean_paths))
    return (
        f"💽 <b>{safe_name}</b>\n\nКарта томов (D01-F21):\n" + "\n".join(rows)
        + "\nID показаны как локальные короткие отпечатки, не как серийные номера."
    )


def _format_volume_history(
    result: dict, device_name: str, *, expected_device_id: str, expected_request_id: str,
) -> str:
    """Render only bounded volume rows tied to this exact owner request."""
    safe_name = html.escape(str(device_name)[:160])
    data = result.get("data") if isinstance(result, dict) else None
    valid = (
        isinstance(result, dict) and result.get("type") == "volume_history"
        and result.get("schema") == "xider.volume-history.v1" and result.get("feature_id") == "D01-F04"
        and result.get("device_id") == expected_device_id and result.get("request_id") == expected_request_id
        and result.get("state") == "supported"
        and result.get("source") == "psutil.disk_partitions+psutil.disk_usage"
        and isinstance(data, dict) and data.get("history_minimum_span_seconds") == 21600
        and data.get("history_scope") == "agent_process"
        and isinstance(data.get("volumes"), list) and len(data["volumes"]) <= 64
    )
    checked_at = result.get("checked_at") if isinstance(result, dict) else None
    if valid:
        try:
            stamp = datetime.datetime.fromisoformat(checked_at)
            valid = stamp.utcoffset() is not None
        except (TypeError, ValueError, OverflowError):
            valid = False
    if not valid:
        return f"💾 <b>{safe_name}</b>\n\nТренд томов (D01-F04): <b>неизвестно</b>. Нет свежего корректного ответа для этого запроса."

    rows = []
    allowed_trends = {"insufficient_history", "capacity_changed", "increasing", "decreasing", "stable", "unknown"}
    for volume in data["volumes"]:
        if not isinstance(volume, dict):
            valid = False
            break
        mount = volume.get("mountpoint")
        filesystem = volume.get("filesystem")
        state = volume.get("state")
        trend = volume.get("trend_state")
        if (not isinstance(mount, str) or not mount or len(mount) > 512
                or not isinstance(filesystem, str) or len(filesystem) > 32
                or state not in {"supported", "unknown"} or trend not in allowed_trends):
            valid = False
            break
        if state == "unknown":
            if any(volume.get(key) is not None for key in (
                "total_bytes", "used_bytes", "free_bytes", "used_percent", "estimated_hours_to_full",
            )):
                valid = False
                break
            rows.append((mount, filesystem, None))
            continue
        total, used, free = volume.get("total_bytes"), volume.get("used_bytes"), volume.get("free_bytes")
        percent = volume.get("used_percent")
        if (type(total) is not int or type(used) is not int or type(free) is not int
                or total <= 0 or not 0 <= used <= total or free != total - used
                or isinstance(percent, bool) or not isinstance(percent, (int, float))
                or not math.isfinite(percent) or not 0 <= percent <= 100
                or abs(percent - round(used * 100 / total, 1)) > 0.11
                or volume.get("history_scope") != "agent_process"):
            valid = False
            break
        span, delta = volume.get("observed_span_seconds"), volume.get("delta_used_bytes")
        rate, eta = volume.get("used_bytes_per_hour"), volume.get("estimated_hours_to_full")
        if trend in {"insufficient_history", "capacity_changed"}:
            if any(value is not None for value in (span, delta, rate, eta)):
                valid = False
                break
        elif trend == "stable":
            if type(span) is not int or span < 21600 or delta != 0 or rate != 0 or eta is not None:
                valid = False
                break
        elif trend == "decreasing":
            if (type(span) is not int or span < 21600 or type(delta) is not int or delta >= 0
                    or isinstance(rate, bool) or not isinstance(rate, (int, float)) or rate >= 0 or eta is not None):
                valid = False
                break
        elif trend == "increasing":
            if (type(span) is not int or span < 21600 or type(delta) is not int or delta <= 0
                    or isinstance(rate, bool) or not isinstance(rate, (int, float)) or rate <= 0
                    or isinstance(eta, bool) or not isinstance(eta, (int, float))
                    or not math.isfinite(eta) or eta < 0):
                valid = False
                break
            expected_rate = delta * 3600.0 / span
            expected_eta = max(0, total - used) / expected_rate
            if abs(rate - expected_rate) > max(2.0, expected_rate * 0.02) or abs(eta - round(expected_eta, 1)) > 0.11:
                valid = False
                break
        rows.append((mount, filesystem, volume))

    if not valid or not rows:
        return f"💾 <b>{safe_name}</b>\n\nТренд томов (D01-F04): <b>неизвестно</b>. Данные отсутствуют или не прошли проверку."

    lines = [
        f"💾 <b>{safe_name}</b>",
        "Тренд заполнения томов (D01-F04)",
        "Локальный снимок; история живёт в памяти агента и сбрасывается после его перезапуска.",
        "Для оценки нужен тот же том и реальные замеры минимум за 6 часов.",
    ]
    for mount, filesystem, volume in rows[:12]:
        safe_mount = html.escape(mount, quote=False)
        safe_fs = html.escape(filesystem, quote=False) or "FS неизвестна"
        if volume is None:
            lines.append(f"<code>{safe_mount}</code> · {safe_fs}: неизвестно (замер недоступен)")
            continue
        gib = 1024 ** 3
        lines.append(
            f"<code>{safe_mount}</code> · {safe_fs}: {volume['used_bytes'] / gib:.1f} / "
            f"{volume['total_bytes'] / gib:.1f} ГиБ ({volume['used_percent']:g}%)"
        )
        trend = volume["trend_state"]
        if trend == "increasing":
            span_hours = volume["observed_span_seconds"] / 3600
            lines.append(
                f"  Рост: {volume['delta_used_bytes'] / gib:+.2f} ГиБ за {span_hours:.1f} ч; "
                f"линейная оценка до заполнения ≈ {volume['estimated_hours_to_full']:.1f} ч"
            )
        elif trend == "decreasing":
            lines.append("  Использование уменьшилось между замерами; ETA не рассчитываю.")
        elif trend == "stable":
            lines.append(f"  Между замерами без изменений ({volume['observed_span_seconds'] / 3600:.1f} ч).")
        else:
            lines.append("  Для тренда нужен такой же том и минимум 6 часов между реальными замерами.")
    if len(rows) > 12:
        lines.append(f"Показаны первые 12 из {len(rows)} томов.")
    lines.append("ETA — простая линейная оценка, не гарантия; короткие и фоновые замеры не используются.")
    lines.append("Проверено: " + html.escape(checked_at, quote=False))
    return "\n".join(lines)


def _sysinfo_percent_display(value) -> str:
    if (
        isinstance(value, bool)
        or not isinstance(value, (int, float))
        or not math.isfinite(value)
        or not 0 <= value <= 100
    ):
        return "?"
    return str(value)


def _format_resource_health(result: dict, expected_request_id: str | None) -> list[str]:
    """Give per-resource, request-bound reasons; never collapse metrics to a score."""
    correlated = isinstance(expected_request_id, str) and bool(expected_request_id.strip())
    rows = ["🩺 Обзор здоровья системы (D01-F01; единый балл не вычисляется):"]
    reasons = ["Эвристика XIDER r1, не диагноз ОС и не медицинская оценка."]
    for label, key, warning, critical in (
        ("CPU", "cpu_percent", 90.0, 98.0),
        ("RAM", "ram_percent", 85.0, 95.0),
        ("Диск", "disk_percent", 85.0, 95.0),
    ):
        value = result.get(key)
        if not correlated:
            rows.append(f"• {label}: неизвестно — коррелированный снимок не получен")
            reasons.append(f"{label}: значение скрыто, потому что ответ не привязан к текущему запросу.")
            continue
        if (
            isinstance(value, bool)
            or not isinstance(value, (int, float))
            or not math.isfinite(value)
            or not 0 <= value <= 100
        ):
            rows.append(f"• {label}: неизвестно — корректный замер не получен")
            reasons.append(f"{label}: неизвестно, если значение отсутствует, нечисловое или вне диапазона 0–100%.")
            continue
        shown = f"{value:.1f}%"
        if value >= critical:
            rows.append(f"• {label}: критично — {shown}")
        elif value >= warning:
            rows.append(f"• {label}: внимание — {shown}")
        else:
            rows.append(f"• {label}: норма — {shown}")
        reasons.append(
            f"{label}: критично ≥{critical:.0f}%; внимание ≥{warning:.0f}%; "
            f"текущее значение {shown}."
        )
    reasons.append("CPU — короткая выборка примерно за 1 секунду, а не прогноз длительной нагрузки.")
    rows.append("<blockquote expandable>Причины и пороги:\n" + "\n".join(reasons) + "</blockquote>")
    return rows


@router.callback_query(AdminFilter(), F.data == "cmd:lock")
async def on_cmd_lock(cq: CallbackQuery):
    target = SESSION.get("target")
    if not target:
        await cq.answer(_lex("target_required"), show_alert=True)
        return
    if target == "all":
        known = devices.all()
        candidates = [
            (device_id, info) for device_id, info in sorted(known.items())
            if _status_dot(info) in {"🟢", "🟡"}
            and info.get("approved", True)
            and not bot_settings.is_blocked(device_id)
        ]
        if not candidates:
            await _replace_callback_message(
                cq, "🔒 Нет одобренных устройств онлайн для блокировки.",
                reply_markup=back_to_device_kb(),
            )
            return
        await cq.answer(f"Отправляю запрос на {len(candidates)} онлайн-устройств…")
        request_ids = {device_id: uuid.uuid4().hex[:12] for device_id, _ in candidates}
        waits = {
            device_id: asyncio.create_task(fun_text_collector.wait_for(
                device_id, "lock", timeout=8.0, command_id=request_ids[device_id],
            ))
            for device_id, _ in candidates
        }
        # Let each ticketed waiter register before publishing its request.
        await asyncio.sleep(0)
        sent = {}
        for device_id, _info in candidates:
            sent[device_id] = publish("lock", _target=device_id, id=request_ids[device_id])
            if not sent[device_id]:
                waits[device_id].cancel()
        results = await asyncio.gather(*waits.values(), return_exceptions=True)
        by_device = dict(zip(waits, results))
        lines = []
        confirmed = 0
        for device_id, info in candidates:
            label = html.escape(str(info.get("name") or device_id))
            result = by_device.get(device_id)
            matched = (
                isinstance(result, dict)
                and result.get("type") == "lock"
                and str(result.get("id") or result.get("request_id") or "") == request_ids[device_id]
                and str(result.get("device_id") or "") == device_id
            )
            if not sent[device_id]:
                detail = "не отправлено"
            elif matched and result.get("state") == "unsupported":
                detail = "не поддерживается"
            elif matched and result.get("ok") is True:
                confirmed += 1
                detail = "подтверждено агентом"
            elif matched and result.get("ok") is False:
                detail = "не выполнено"
            else:
                detail = "не подтверждено агентом"
            lines.append(f"• <b>{label}</b>: {detail}")
        offline_count = sum(1 for info in known.values() if _status_dot(info) == "⚪")
        summary = f"🔒 Подтверждено {confirmed}/{len(candidates)} онлайн-устройств."
        if offline_count:
            summary += f" Офлайн пропущено: {offline_count}."
        await _replace_callback_message(
            cq, summary + "\n\n" + "\n".join(lines), reply_markup=back_to_device_kb(),
        )
        return

    sent, command_id = publish_tracked("lock", _target=target)
    if sent:
        result = await fun_text_collector.wait_for(target, "lock", timeout=8.0, command_id=command_id)
        matched = (
            isinstance(result, dict)
            and result.get("type") == "lock"
            and str(result.get("id") or result.get("request_id") or "") == command_id
            and str(result.get("device_id") or "") == str(target)
        )
        if matched and result.get("state") == "unsupported":
            status = f"🔒 macOS: блокировка сессии не поддерживается этим действием. {html.escape(str(result.get('error') or ''))}"
        elif matched and result.get("ok") is True:
            status = f"🔒 Экран заблокирован: <b>{html.escape(target_label(target))}</b> · подтверждено агентом."
        elif matched and result.get("ok") is False:
            status = f"🔒 Блокировка не выполнена: {html.escape(str(result.get('error') or 'агент вернул ошибку'))}"
        else:
            status = f"🔒 Запрос блокировки отправлен для <b>{html.escape(target_label(target))}</b>. Фактическая блокировка не подтверждена агентом."
        await _replace_callback_message(
            cq,
            status,
            reply_markup=back_to_device_kb(),
        )
    else:
        await _replace_callback_message(
            cq,
            _lex("mqtt_disconnected"),
            reply_markup=back_to_device_kb(),
        )


