# ---------- Массовые команды (все устройства) ----------

@router.callback_query(AdminFilter(), F.data == "all:status")
async def on_all_status(cq: CallbackQuery):
    multi_status.reset()
    if not publish("status_request", _target="all"):
        await _replace_callback_message(
            cq, _lex("mqtt_disconnected"), reply_markup=devices_menu()
        )
        await cq.answer()
        return
    await cq.answer("📡 Опрашиваю все устройства...")
    results = await multi_status.wait_window(6.0)
    known = devices.all()
    lines = []
    answered = 0
    for dev_id, info in sorted(known.items()):
        r = next((x for x in results if x.get("device_id") == dev_id), None)
        name = html.escape(info.get("name") or dev_id)
        if r:
            answered += 1
            lines.append(f"{_status_dot(info)} {name} · ✅ ответил · v{r.get('version', '?')}")
        else:
            lines.append(f"{_status_dot(info)} {name} · ⛔ молчит")
    text = (
        f"🖥 <b>Сводка</b> — ответили {answered}/{len(known)}\n\n"
        + "\n".join(lines if lines else ["Нет известных устройств."])
    )
    await _replace_callback_message(cq, text, reply_markup=devices_menu())
    await cq.answer()


@router.callback_query(AdminFilter(), F.data == "all:screenshot")
async def on_all_screenshot(cq: CallbackQuery):
    multi_screenshot.reset()
    if not publish("screenshot", _target="all"):
        await _replace_callback_message(
            cq, _lex("mqtt_disconnected"), reply_markup=devices_menu()
        )
        await cq.answer()
        return
    await cq.answer("📸 Собираю скриншоты...")
    results = await multi_screenshot.wait_window(14.0)
    collected = 0
    manifest = []
    diagnostics = []
    archive_bytes = io.BytesIO()
    with zipfile.ZipFile(archive_bytes, "w", zipfile.ZIP_DEFLATED) as archive:
        for index, result in enumerate(results, 1):
            if not result.get("image") or result.get("state") != "success":
                diagnostics.append(f"{html.escape(target_label(str(result.get('device_id') or 'unknown'))[:80])}: {_screenshot_failure_help(result)}")
                continue
            try:
                image = _decode_screenshot_image(result)
                device_id = str(result.get("device_id") or "unknown")
                name = target_label(device_id)
                filename = _safe_transfer_filename(
                    f"{index:02d}-{device_id}-{name}.jpg".replace("/", "_").replace("\\", "_")
                )
                archive.writestr(filename, image)
                manifest.append({"file": filename, "device_id": device_id, "device_name": name})
                collected += 1
            except (ValueError, TypeError, OSError):
                log.warning("Некорректный скриншот в сводке устройства", exc_info=True)
                diagnostics.append(f"{html.escape(str(result.get('device_id') or 'unknown')[:80])}: {_screenshot_failure_help({'state': 'file_unreadable'})}")
        archive.writestr("manifest.json", json.dumps(manifest, ensure_ascii=False).encode("utf-8"))
    caption = f"📸 Скриншоты собраны: {collected}."
    if diagnostics:
        # Keep complete HTML blocks within the Telegram message/caption bounds.
        for diagnostic in diagnostics:
            if len(caption) + len(diagnostic) + 2 > (1000 if collected else 3900):
                caption += "\nОстальные ответы: повтори запрос для конкретного устройства."
                break
            caption += "\n\n" + diagnostic
    if collected:
        await _replace_callback_with_media(
            cq, bot.send_document, chat_id=cq.message.chat.id,
            document=BufferedInputFile(archive_bytes.getvalue(), filename="screenshots.zip"),
            caption=caption, reply_markup=devices_menu(),
        )
    else:
        await _replace_callback_message(cq, caption, reply_markup=devices_menu())
    await cq.answer()


# ---------- Wake-on-LAN, диски, громкость, микрофон, буфер ----------

@router.callback_query(AdminFilter(), F.data == "cmd:wol")
async def on_cmd_wol(cq: CallbackQuery):
    target = SESSION.get("target")
    if not target or target == "all":
        await cq.answer("Разбудить можно только одно устройство", show_alert=True)
        return
    info = devices.get(target) or {}
    mac = info.get("mac")
    if not mac:
        await cq.answer("MAC неизвестен — запрашиваю у устройства...")
        sysinfo_collector.reset()
        if not publish("sysinfo", _target=target):
            await _replace_callback_message(
                cq, _lex("mqtt_disconnected"), reply_markup=back_to_device_kb()
            )
            await cq.answer()
            return
        res = await sysinfo_collector.wait(12.0)
        mac = (res or {}).get("mac")
        if mac:
            devices.upsert(target, {"mac": mac})
    if not mac:
        await _replace_callback_message(
            cq,
            "❌ MAC-адрес неизвестен: устройство ни разу не отвечало.",
            reply_markup=back_to_device_kb(),
        )
        await cq.answer()
        return
    try:
        send_wol(mac)
    except ValueError:
        await _replace_callback_message(
            cq,
            f"❌ Некорректный MAC: <code>{html.escape(str(mac))}</code>",
            reply_markup=back_to_device_kb(),
        )
        await cq.answer()
        return
    audit("wol", device_id=target, mac=mac)
    await _replace_callback_message(
        cq,
        f"🌐 Magic packet отправлен на <b>{html.escape(target_label(target))}</b> ({html.escape(str(mac))}).",
        reply_markup=back_to_device_kb(),
    )
    await cq.answer()


