def _microphone_selection_keyboard(token: str, inputs: list[dict[str, object]], *, purpose: str = "record"):
    kb = InlineKeyboardBuilder()
    callback_prefix = "mic:level" if purpose == "level" else "mic:balance" if purpose == "balance" else "mic:input"
    for row in inputs:
        input_id = str(row["input_id"])
        name = _limit_button_label(str(row["name"]))
        icon = "📶" if purpose == "level" else "⚖️" if purpose == "balance" else ("🎧" if purpose in {"roundtrip", "preview"} else "🎙")
        kb.button(text=f"{icon} {name}", callback_data=f"{callback_prefix}:{token}:{input_id}")
    kb.button(text=_nav("back_device"), callback_data="back:device")
    kb.adjust(1)
    return kb.as_markup()


def _validated_microphone_catalog(result: object, *, target: str, command_id: str) -> list[dict[str, object]] | None:
    if not isinstance(result, dict):
        return None
    try:
        checked = datetime.datetime.fromisoformat(str(result.get("checked_at")))
        if checked.tzinfo is None:
            return None
        age = time.time() - checked.timestamp()
    except (TypeError, ValueError, OverflowError):
        return None
    data = result.get("data")
    rows = data.get("inputs") if isinstance(data, dict) else None
    if not (
        result.get("type") == "microphone_catalog"
        and result.get("schema") == "xider.microphone-catalog.v1"
        and result.get("feature_id") == "D02-F15"
        and result.get("device_id") == target
        and result.get("request_id") == command_id
        and result.get("state") == "supported"
        and -60 <= age <= 60
        and isinstance(rows, list)
        and 0 < len(rows) <= 16
    ):
        return None
    inputs = []
    seen = set()
    for row in rows:
        if not isinstance(row, dict) or set(row) != {"input_id", "name", "channels", "sample_rate"}:
            return None
        input_id, name = row.get("input_id"), row.get("name")
        channels, sample_rate = row.get("channels"), row.get("sample_rate")
        if (not isinstance(input_id, str) or re.fullmatch(r"(?:0|[1-9][0-9]{0,4})", input_id) is None
                or input_id in seen or not isinstance(name, str) or not name.strip() or len(name) > 80
                or isinstance(channels, bool) or not isinstance(channels, int) or not 1 <= channels <= 32
                or (sample_rate is not None and (isinstance(sample_rate, bool) or not isinstance(sample_rate, int)
                                                  or not 8000 <= sample_rate <= 192000))):
            return None
        seen.add(input_id)
        inputs.append({"input_id": input_id, "name": name.strip(), "channels": channels, "sample_rate": sample_rate})
    return inputs


async def _start_microphone_selection(cq: CallbackQuery, *, purpose: str, duration: int | None = None):
    target = str(SESSION.get("target") or "")
    if not target or target == "all" or devices.get(target) is None:
        await cq.answer(_lex("single_device_only"), show_alert=True)
        return
    if purpose not in {"record", "level", "roundtrip", "balance", "preview"}:
        await cq.answer("Действие с микрофоном не распознано.", show_alert=True)
        return
    required_action = ("mic" if purpose == "record" else "microphone_level" if purpose == "level"
                       else "microphone_test" if purpose == "roundtrip" else "microphone_balance" if purpose == "balance" else "microphone_preview")
    if not await _callback_result_access_or_report(cq, target):
        return
    record = devices.get(target) or {}
    if (_device_declares_command(record, "microphone_catalog") is not True
            or _device_declares_command(record, required_action) is not True):
        action_name = ("запись" if purpose == "record" else "измерение уровня" if purpose == "level"
                       else "тест микрофона и выхода" if purpose == "roundtrip" else "проверка баланса каналов" if purpose == "balance" else "предпрослушивание записи")
        await cq.answer(f"Агент не поддерживает каталог микрофонов или {action_name}; запрос не запускался.", show_alert=True)
        await _replace_callback_message(cq, "🎙 Нужна полная установка агента с поддержкой microphone_catalog и выбранного действия. Запрос не запускался.", reply_markup=back_to_device_kb())
        return
    prompt = ("🎙 Ищу входы; запись пока не началась…" if purpose == "record" else
              "📶 Ищу входы для краткой проверки уровня; аудио не сохраняется…" if purpose == "level" else
              "🎧 Ищу входы для короткого локального теста; запись не отправляется в Telegram…" if purpose == "roundtrip" else
              "🎧 Ищу входы и выход; сначала запись прозвучит локально, отправка в Telegram будет только после подтверждения…" if purpose == "preview" else
              "⚖️ Ищу стереовходы для односекундного локального замера; аудио не сохраняется и не отправляется…")
    await cq.answer(prompt)
    sent, command_id = publish_tracked("microphone_catalog", _target=target)
    if not sent:
        await _replace_callback_message(cq, _lex("mqtt_disconnected"), reply_markup=back_to_device_kb())
        return
    guard = _callback_delivery_guard(cq, target)
    await _replace_callback_message(cq, "🎙 Получаю свежий список входных микрофонов…", delivery_guard=guard,
                                    reply_markup=back_to_device_kb())
    result = await microphone_catalog_collector.wait_for(target, "microphone_catalog", 15.0, command_id)
    if not await _callback_result_access_or_report(cq, target, published=True):
        return
    inputs = _validated_microphone_catalog(result, target=target, command_id=command_id)
    if inputs is not None and purpose == "balance":
        inputs = [row for row in inputs if int(row["channels"]) >= 2]
    if inputs is None:
        await _replace_callback_message(cq, "⚠️ Список микрофонов устарел, пуст или не подтверждён этим устройством. Запрос не запускался; обнови агента и повтори.",
                                        delivery_guard=guard, reply_markup=back_to_device_kb())
        return
    token = uuid.uuid4().hex[:12]
    chat_id = int(cq.message.chat.id)
    message_id = int(cq.message.message_id)
    user_id = int(cq.from_user.id)
    _MIC_INPUT_CATALOGS[token] = {
        "owner_id": user_id, "target": target, "duration": duration, "purpose": purpose, "chat_id": chat_id,
        "message_id": message_id, "expires_at": time.time() + _MIC_INPUT_CATALOG_TTL_SECONDS,
        "inputs": {str(row["input_id"]): str(row["name"]) for row in inputs},
    }
    prompt = ("🎙 Выбери входной микрофон. Запись начнётся только после выбора." if purpose == "record" else
              "📶 Выбери вход для краткой проверки уровня. Сохранять или отправлять аудио агент не будет." if purpose == "level" else
              "🎧 Выбери микрофон для короткого локального теста. Его звук будет проигран на выбранном выходе, без отправки в Telegram." if purpose == "roundtrip" else
              "🎧 Выбери вход для короткой записи. Агент сначала проиграет её на выбранном выходе; в Telegram аудио уйдёт только после твоего подтверждения." if purpose == "preview" else
              "⚖️ Выбери стереовход. Агент измерит уровни двух каналов одну секунду и удалит сэмплы из памяти.")
    await _replace_callback_message(cq, prompt, delivery_guard=guard,
                                    reply_markup=_microphone_selection_keyboard(token, inputs, purpose=purpose))


