@router.callback_query(OwnerFilter(), F.data.startswith("mic:input:"))
async def on_mic_input(cq: CallbackQuery):
    parts = str(cq.data or "").split(":")
    if len(parts) != 4 or not re.fullmatch(r"[a-f0-9]{12}", parts[2]) or re.fullmatch(r"(?:0|[1-9][0-9]{0,4})", parts[3]) is None:
        await cq.answer("Выбор микрофона некорректен; запись не запускалась.", show_alert=True)
        return
    token, input_id = parts[2], parts[3]
    entry = _MIC_INPUT_CATALOGS.get(token)
    user_id = int(cq.from_user.id)
    target = str(SESSION.get("target") or "")
    if (not isinstance(entry, dict) or entry.get("purpose") not in {"record", "roundtrip", "preview"}
            or entry.get("owner_id") != user_id or entry.get("target") != target
            or entry.get("chat_id") != int(cq.message.chat.id)
            or entry.get("message_id") != int(cq.message.message_id)
            or float(entry.get("expires_at", 0)) < time.time()
            or input_id not in (entry.get("inputs") or {})):
        _MIC_INPUT_CATALOGS.pop(token, None)
        await cq.answer("Список микрофонов устарел. Запись не запускалась; выбери длительность ещё раз.", show_alert=True)
        return
    if not target or devices.get(target) is None or not await _callback_result_access_or_report(cq, target):
        _MIC_INPUT_CATALOGS.pop(token, None)
        return
    record = devices.get(target) or {}
    required_action = ("mic" if entry.get("purpose") == "record" else
                       "microphone_test" if entry.get("purpose") == "roundtrip" else "microphone_preview")
    if (_device_declares_command(record, "microphone_catalog") is not True
            or _device_declares_command(record, required_action) is not True):
        _MIC_INPUT_CATALOGS.pop(token, None)
        await cq.answer("Агент больше не объявляет поддержку; запись не запускалась.", show_alert=True)
        return
    _MIC_INPUT_CATALOGS.pop(token, None)
    if entry.get("purpose") == "roundtrip":
        await _start_roundtrip_output_catalog(cq, target=target, input_id=input_id,
                                              input_name=str(entry["inputs"][input_id]))
        return
    if entry.get("purpose") == "preview":
        await _start_roundtrip_output_catalog(cq, target=target, input_id=input_id,
                                              input_name=str(entry["inputs"][input_id]), purpose="preview")
        return
    duration = int(entry["duration"])
    await cq.answer(f"🎙 Записываю выбранный вход {duration} сек…")
    sent, command_id = publish_tracked("mic", _target=target, duration=duration, input_device_id=input_id)
    if not sent:
        await _replace_callback_message(cq, _lex("mqtt_disconnected"), reply_markup=back_to_device_kb())
        return
    guard = _callback_delivery_guard(cq, target)
    await _replace_callback_message(cq, "🎙 Запись выполняется на выбранном входе…", delivery_guard=guard,
                                    reply_markup=back_to_device_kb())
    result = await mic_collector.wait_for(target, "mic", duration + 12.0, command_id)
    if not await _callback_result_access_or_report(cq, target, published=True):
        return
    if (not isinstance(result, dict) or result.get("type") != "mic" or result.get("device_id") != target
            or result.get("id") != command_id or not isinstance(result.get("audio"), str)):
        await _replace_callback_message(cq, "⏳ Запись не подтверждена или агент не ответил; аудио не доставлено.",
                                        delivery_guard=guard, reply_markup=back_to_device_kb())
        return
    try:
        audio_bytes = base64.b64decode(result["audio"], validate=True)
        if not audio_bytes or len(audio_bytes) > 8 * 1024 * 1024:
            raise ValueError("invalid audio size")
        audio = BufferedInputFile(audio_bytes, filename="mic.ogg")
        await _replace_callback_with_media(
            cq,
            bot.send_voice, delivery_guard=guard,
            voice=audio,
            caption=f"🎙 {html.escape(target_label(target))} · {duration}с",
        )
    except Exception:
        log.exception("Не удалось отправить аудио")
        await _replace_callback_message(
            cq, _lex("mqtt_publish_failed"), delivery_guard=_callback_delivery_guard(cq, target), reply_markup=back_to_device_kb()
        )


def _audio_output_selection_keyboard(token: str, outputs: list[dict[str, object]], *, purpose: str = "test"):
    kb = InlineKeyboardBuilder()
    for row in outputs:
        output_id = str(row["output_id"])
        name = _limit_button_label(str(row["name"]))
        route = "audio:setout" if purpose == "system_output" else "audio:previewout" if purpose == "preview" else "audio:testout"
        kb.button(text=f"🔊 {name}", callback_data=f"{route}:{token}:{output_id}")
    kb.button(text=_nav("back_device"), callback_data="back:device")
    kb.adjust(1)
    return kb.as_markup()


async def _start_roundtrip_output_catalog(cq: CallbackQuery, *, target: str,
                                         input_id: str, input_name: str, purpose: str = "roundtrip") -> None:
    record = devices.get(target) or {}
    required_action = "microphone_preview" if purpose == "preview" else "microphone_test"
    if (_device_declares_command(record, "audio_output_catalog") is not True
            or _device_declares_command(record, required_action) is not True):
        await _replace_callback_message(cq, "Агент не объявляет поддержку аудиовыходов/предпрослушивания. Запись не запускалась.",
                                        reply_markup=back_to_device_kb())
        return
    await cq.answer("🎧 Ищу свежий список выходов…")
    sent, command_id = publish_tracked("audio_output_catalog", _target=target)
    if not sent:
        await _replace_callback_message(cq, _lex("mqtt_disconnected"), reply_markup=back_to_device_kb())
        return
    guard = _callback_delivery_guard(cq, target)
    await _replace_callback_message(cq, "🎧 Получаю свежий список выходов; запись ещё не началась…",
                                    delivery_guard=guard, reply_markup=back_to_device_kb())
    result = await audio_output_catalog_collector.wait_for(target, "audio_output_catalog", 8.0, command_id)
    if not await _callback_result_access_or_report(cq, target, published=True):
        return
    outputs = _validated_audio_output_catalog(result, target=target, command_id=command_id)
    if outputs is None:
        await _replace_callback_message(cq, "⚠️ Свежий список аудиовыходов не подтверждён. Тест не запускался.",
                                        delivery_guard=guard, reply_markup=back_to_device_kb())
        return
    token = uuid.uuid4().hex[:12]
    _MIC_INPUT_CATALOGS[token] = {
        "owner_id": int(cq.from_user.id), "target": target,
        "purpose": "preview_output" if purpose == "preview" else "roundtrip_output",
        "input_id": input_id, "input_name": input_name,
        "chat_id": int(cq.message.chat.id), "message_id": int(cq.message.message_id),
        "expires_at": time.time() + _MIC_INPUT_CATALOG_TTL_SECONDS,
        "outputs": {str(row["output_id"]): str(row["name"]) for row in outputs},
    }
    prompt = ("🎧 Выбери выход: запись сначала прозвучит локально; отправка в Telegram потребует отдельного подтверждения."
              if purpose == "preview" else
              "🎧 Выбери выход, на который локально проиграть короткий тест. Аудио не отправляется в Telegram.")
    await _replace_callback_message(cq, prompt, delivery_guard=guard,
                                    reply_markup=_audio_output_selection_keyboard(token, outputs, purpose="preview" if purpose == "preview" else "test"))


@router.callback_query(OwnerFilter(), F.data.startswith("audio:testout:"))
async def on_microphone_test_output(cq: CallbackQuery):
    match = re.fullmatch(r"audio:testout:([a-f0-9]{12}):((?:0|[1-9][0-9]{0,4}))", str(cq.data or ""))
    if match is None:
        await cq.answer("Выбор выхода неверен; тест не запускался.", show_alert=True)
        return
    token, output_id = match.groups()
    entry = _MIC_INPUT_CATALOGS.get(token)
    target = str(SESSION.get("target") or "")
    if (not isinstance(entry, dict) or entry.get("purpose") != "roundtrip_output"
            or entry.get("owner_id") != int(cq.from_user.id) or entry.get("target") != target
            or entry.get("chat_id") != int(cq.message.chat.id)
            or entry.get("message_id") != int(cq.message.message_id)
            or float(entry.get("expires_at", 0)) < time.time()
            or output_id not in (entry.get("outputs") or {})):
        _MIC_INPUT_CATALOGS.pop(token, None)
        await cq.answer("Список выходов устарел; тест не запускался.", show_alert=True)
        return
    if (not target or devices.get(target) is None
            or not await _callback_result_access_or_report(cq, target)):
        _MIC_INPUT_CATALOGS.pop(token, None)
        return
    record = devices.get(target) or {}
    if (_device_declares_command(record, "microphone_test") is not True
            or _device_declares_command(record, "audio_output_catalog") is not True):
        _MIC_INPUT_CATALOGS.pop(token, None)
        await cq.answer("Агент больше не подтверждает поддержку; тест не запускался.", show_alert=True)
        return
    _MIC_INPUT_CATALOGS.pop(token, None)
    input_id, input_name = str(entry["input_id"]), str(entry["input_name"])
    output_name = str(entry["outputs"][output_id])
    await cq.answer("🎧 Запускаю короткий локальный тест…")
    sent, command_id = publish_tracked(
        "microphone_test", _target=target, input_device_id=input_id,
        input_device_name=input_name, output_device_id=output_id,
        output_device_name=output_name,
    )
    if not sent:
        await _replace_callback_message(cq, _lex("mqtt_disconnected"), reply_markup=back_to_device_kb())
        return
    guard = _callback_delivery_guard(cq, target)
    await _replace_callback_message(cq, "🎧 Тест записывает до 0,75 с локально, проигрывает на выбранный выход и удаляет временный файл…",
                                    delivery_guard=guard, reply_markup=back_to_device_kb())
    result = await microphone_test_collector.wait_for(target, "microphone_test", 10.0, command_id)
    if not await _callback_result_access_or_report(cq, target, published=True):
        return
    values = _validated_microphone_test(result, target=target, command_id=command_id)
    if values is None:
        await _replace_callback_message(cq, "⏳ Результат не подтверждён свежим ответом агента. Звук в Telegram не отправлялся.",
                                        delivery_guard=guard, reply_markup=back_to_device_kb())
    elif values["state"] == "played":
        await _replace_callback_message(cq, "✅ Агент завершил локальную запись и передал её выбранному выходу; временный файл удалён. "
                                           "Это подтверждает завершение команды, но не доказывает, что звук был слышен физически.",
                                        delivery_guard=guard, reply_markup=back_to_device_kb())
    else:
        descriptions = {
            "unavailable": "Выбранный вход/выход изменился или сейчас недоступен.",
            "unsupported": "На агенте недоступна аудиобиблиотека.",
            "unknown": "Агент не смог достоверно завершить тест.",
        }
        await _replace_callback_message(cq, f"⚠️ {descriptions[str(values['state'])]} Аудио не отправлялось в Telegram.",
                                        delivery_guard=guard, reply_markup=back_to_device_kb())


