def _file_inbox_owner_allowed(user_id: int, target: str | None = None) -> bool:
    if int(user_id) != int(ADMIN_ID) or get_user_role(int(user_id)) != Role.OWNER:
        return False
    if target is None:
        return True
    return bool(target != "all" and devices.get(target) and access_store.can_use_callback(
        int(user_id), "files:put", ADMIN_ID, target,
    ))


def _file_inbox_metadata(item_id: str) -> dict | None:
    """Read owner-scoped metadata without loading or trusting staged bytes."""
    if not re.fullmatch(r"[0-9a-f]{32}", str(item_id)):
        return None
    return next((
        item for item in file_inbox.list_items(actor_id=ADMIN_ID, owner_id=ADMIN_ID)
        if item.get("item_id") == item_id
    ), None)


