@router.message(OwnerFilter(), Form.wait_file_inbox_upload)
async def on_file_inbox_document(message: Message, state: FSMContext):
    document = message.document
    if document is None:
        await state.clear()
        try:
            await message.delete()
        except Exception:
            pass
        await _replace_user_card(
            message, "Нужен именно файл-документ. Входящие пока не изменены.",
            reply_markup=_file_inbox_keyboard(
                "files.inbox", message.from_user.id,
                items=file_inbox.list_items(actor_id=message.from_user.id, owner_id=ADMIN_ID),
            ),
        )
        return
    if document.file_size is not None and int(document.file_size) > file_inbox.max_item_bytes:
        await state.clear()
        try:
            await message.delete()
        except Exception:
            pass
        await _replace_user_card(
            message,
            f"Файл больше лимита {file_inbox.max_item_bytes // (1024 * 1024)} МиБ; ничего не сохранено.",
            reply_markup=_file_inbox_keyboard(
                "files.inbox", message.from_user.id,
                items=file_inbox.list_items(actor_id=message.from_user.id, owner_id=ADMIN_ID),
            ),
        )
        return
    try:
        buffer = await bot.download(document)
        data = buffer.read()
    except Exception:
        await state.clear()
        log.exception("Не удалось скачать owner-provided file into staging")
        await _replace_user_card(message, "Не удалось получить файл от Telegram; staging не изменён.", reply_markup=back_to_device_kb())
        return
    await state.clear()
    if not _file_inbox_owner_allowed(message.from_user.id):
        try:
            await message.delete()
        except Exception:
            pass
        await _replace_user_card(message, "Право владельца изменилось; файл не сохранён.", reply_markup=back_to_device_kb())
        return
    try:
        staged = file_inbox.stage(
            actor_id=message.from_user.id, owner_id=ADMIN_ID,
            name=document.file_name or "upload.bin", data=data,
            mime_type=document.mime_type,
        )
    except (PermissionError, ValueError) as exc:
        try:
            await message.delete()
        except Exception:
            pass
        rows = file_inbox.list_items(actor_id=message.from_user.id, owner_id=ADMIN_ID)
        await _replace_user_card(
            message,
            f"Файл не добавлен во входящие: {html.escape(str(exc))}.",
            reply_markup=_file_inbox_keyboard("files.inbox", message.from_user.id, items=rows),
        )
        return
    try:
        await message.delete()
    except Exception:
        # Telegram may refuse deletion; staging remains valid and no content is echoed.
        log.info("Incoming owner document message could not be deleted after staging")
    rows = file_inbox.list_items(actor_id=message.from_user.id, owner_id=ADMIN_ID)
    access_store.append_audit(
        "file_inbox_staged", actor_id=message.from_user.id,
        detail=f"item={staged['item_id']}; size={staged['size']}; sha256={staged['sha256']}",
    )
    await _replace_user_card(
        message,
        f"Файл <b>{html.escape(staged['name'])}</b> помещён во входящие. Он ничего не запускал; выбери его для просмотра, размещения или удаления.",
        reply_markup=_file_inbox_keyboard("files.inbox", message.from_user.id, items=rows),
    )


@router.callback_query(OwnerFilter(), F.data.startswith("files:inbox:view:"))
async def on_file_inbox_view(cq: CallbackQuery):
    item_id = cq.data.removeprefix("files:inbox:view:")
    selected_target = str(SESSION.get("target") or "")
    can_place = _file_inbox_owner_allowed(cq.from_user.id, selected_target)
    try:
        result = file_inbox.get(
            actor_id=cq.from_user.id, owner_id=ADMIN_ID, item_id=item_id,
        )
    except ValueError:
        metadata = _file_inbox_metadata(item_id)
        if metadata is None:
            await cq.answer("Запись повреждена или истекла; список обновлён.", show_alert=True)
            return
        await _replace_callback_message(
            cq,
            _file_inbox_item_text(metadata)
            + "\n\n⚠️ Контрольная сумма не совпадает. Размещение заблокировано; запись можно только удалить.",
            reply_markup=_file_inbox_keyboard(
                "files.inbox.detail", cq.from_user.id, item_id=item_id, can_place=False,
            ),
        )
        await cq.answer("Файл повреждён: размещение заблокировано.", show_alert=True)
        return
    if result is None:
        await cq.answer("Файл истёк, удалён или недоступен.", show_alert=True)
        return
    metadata, _data = result
    await _replace_callback_message(
        cq, _file_inbox_item_text(metadata),
        reply_markup=_file_inbox_keyboard(
            "files.inbox.detail", cq.from_user.id, item_id=item_id, can_place=can_place,
        ),
    )
    await cq.answer()


