@router.callback_query(OwnerFilter(), F.data.startswith("files:inbox:place:confirm:"))
async def on_file_inbox_place_confirm(cq: CallbackQuery, state: FSMContext):
    item_id = cq.data.removeprefix("files:inbox:place:confirm:")
    data = await state.get_data()
    target = str(data.get("file_inbox_target") or "")
    destination = data.get("file_inbox_destination")
    if (
        (await state.get_state()) != Form.wait_file_inbox_confirm.state
        or data.get("file_inbox_item_id") != item_id
        or not isinstance(destination, str)
        or str(SESSION.get("target") or "") != target
        or not _file_inbox_owner_allowed(cq.from_user.id, target)
    ):
        await state.clear()
        await cq.answer("Подтверждение истекло или выбранное устройство изменилось.", show_alert=True)
        return
    try:
        result = file_inbox.get(actor_id=cq.from_user.id, owner_id=ADMIN_ID, item_id=item_id)
    except ValueError:
        result = None
        await cq.answer("Контрольная сумма не совпала; файл не отправлен.", show_alert=True)
        return
    if result is None:
        await state.clear()
        await cq.answer("Файл истёк, удалён или недоступен.", show_alert=True)
        return
    metadata, payload = result
    await state.clear()
    sent, command_id = publish_tracked(
        "file_put", _target=target, name=metadata["name"], path=destination,
        b64=base64.b64encode(payload).decode("ascii"),
    )
    if not sent:
        await _replace_callback_message(cq, "Сервер недоступен; файл остался во входящих.", reply_markup=back_to_device_kb())
        await cq.answer()
        return
    reply = await fun_text_collector.wait_for(target, "file_put", timeout=25.0, command_id=command_id)
    if not _file_inbox_owner_allowed(cq.from_user.id, target):
        await _report_revoked_after_publish(cq.message)
        await cq.answer()
        return
    if reply and reply.get("ok"):
        access_store.append_audit(
            "file_inbox_placed", actor_id=cq.from_user.id,
            detail=f"item={item_id}; target={target}; destination={destination}",
        )
        text = f"Файл размещён: <code>{html.escape(str(reply.get('path') or destination))}</code>. Staging-копия сохранена до истечения срока или удаления."
    else:
        text = f"Не удалось разместить файл: {html.escape(str((reply or {}).get('error') or _lex('device_no_response')))}. Staging-копия не удалена."
    await _replace_callback_message(cq, text, reply_markup=back_to_device_kb())
    await cq.answer()


