@router.message(OwnerFilter(), Form.wait_file_inbox_path)
async def on_file_inbox_path(message: Message, state: FSMContext):
    data = await state.get_data()
    target = str(data.get("file_inbox_target") or "")
    item_id = str(data.get("file_inbox_item_id") or "")
    destination = (message.text or "").strip()
    if (
        not destination or len(destination) > 1024
        or any(ord(ch) < 32 for ch in destination)
        or destination.endswith(("/", "\\"))
        or str(SESSION.get("target") or "") != target
        or not _file_inbox_owner_allowed(message.from_user.id, target)
    ):
        await state.clear()
        try:
            await message.delete()
        except Exception:
            pass
        await _replace_user_card(message, "Путь пустой/некорректный либо устройство изменилось; файл не отправлен.", reply_markup=back_to_device_kb())
        return
    try:
        result = file_inbox.get(actor_id=message.from_user.id, owner_id=ADMIN_ID, item_id=item_id)
    except ValueError:
        result = None
    if result is None:
        await state.clear()
        try:
            await message.delete()
        except Exception:
            pass
        await _replace_user_card(message, "Файл недоступен или повреждён; размещение отменено.", reply_markup=back_to_device_kb())
        return
    metadata, _data = result
    await state.update_data(file_inbox_destination=destination)
    await state.set_state(Form.wait_file_inbox_confirm)
    try:
        await message.delete()
    except Exception:
        pass
    await _replace_user_card(
        message,
        f"<b>Подтверди размещение</b>\nУстройство: <b>{html.escape(target_label(target))}</b>\n"
        f"Файл: <b>{html.escape(metadata['name'])}</b> · {metadata['size']} байт\n"
        f"Путь: <code>{html.escape(destination)}</code>\nSHA-256: <code>{metadata['sha256']}</code>\n\n"
        "Нажатие отправит байты по MQTT. Staging-копия останется до истечения TTL или отдельного удаления.",
        reply_markup=_file_inbox_keyboard("files.inbox.place.confirm", message.from_user.id, item_id=item_id),
    )


