@router.callback_query(OwnerFilter(), F.data == "cmd:dns_resolution")
async def on_cmd_dns_resolution(cq: CallbackQuery, state: FSMContext):
    target = str(SESSION.get("target") or "")
    if not target or target == "all":
        await cq.answer(_lex("single_device_only"), show_alert=True)
        return
    if not await _callback_result_access_or_report(cq, target):
        return
    if _device_declares_command(devices.get(target) or {}, "dns_resolution") is not True:
        await _replace_callback_message(
            cq, "Агент не объявляет DNS-проверку; запрос не отправлялся.",
            reply_markup=back_to_device_kb(),
        )
        await cq.answer("Нужна версия агента с DNS-проверкой.", show_alert=True)
        return
    await _start_authorized_input(state, Form.wait_dns_resolution, "cmd:dns_resolution", target)
    await _replace_callback_message(
        cq,
        "Введи доменное имя; для сверки можно дописать ожидаемые IP через ` | ` и список через запятую.\n"
        "Пример: example.com | 203.0.113.10\n"
        "Бот выполнит только DNS-разрешение через системный resolver и не подключится к полученным адресам.",
        reply_markup=back_to_device_kb(),
    )
    await cq.answer()


@router.message(OwnerFilter(), Form.wait_dns_resolution)
async def on_dns_resolution_input(message: Message, state: FSMContext):
    form_data = await state.get_data()
    await state.clear()
    target = str(form_data.get("authorization_target") or "")
    if (not target or target == "all" or SESSION.get("target") != target
            or not _pending_device_input_still_allowed(message, form_data, target)):
        await _reject_revoked_device_input(message)
        return
    parsed = _parse_dns_resolution_input(message.text or "")
    if parsed is None:
        await _replace_user_card(
            message,
            "Формат не распознан. Введи домен или `домен | IP1,IP2`; адреса должны быть корректными и не повторяться.",
            reply_markup=back_to_device_kb(),
        )
        return
    record = devices.get(target) or {}
    if _device_declares_command(record, "dns_resolution") is not True:
        await _replace_user_card(message, "Агент больше не объявляет поддержку DNS-проверки; команда не отправлена.",
                                 reply_markup=back_to_device_kb())
        return
    sent, command_id = publish_tracked("dns_resolution", _target=target, **parsed)
    if not sent:
        await _replace_user_card(message, _lex("mqtt_disconnected"), reply_markup=back_to_device_kb())
        return
    await _replace_user_card(message, "🌐 Проверяю DNS через системный resolver устройства…",
                             reply_markup=back_to_device_kb())
    result = await dns_resolution_collector.wait_for(target, "dns_resolution", 9.0, command_id)
    if not _pending_device_input_still_allowed(message, form_data, target):
        await _replace_user_card(message, _lex("action_result_hidden_after_revoke"), reply_markup=back_to_device_kb())
        return
    values = _validated_dns_resolution(
        result, target=target, command_id=command_id, hostname=str(parsed["hostname"]),
        expected_addresses=parsed["expected_addresses"],
    )
    if values is None:
        body = "⏳ Нет подтверждённого свежего ответа агента; DNS-проверка осталась без результата."
    elif values["state"] == "supported":
        addresses = "\n".join(f"• <code>{html.escape(item)}</code>" for item in values["addresses"])
        match = values["expected_match"]
        comparison = "\nСверка с ожидаемым набором: " + ("совпадает" if match is True else "не совпадает" if match is False else "не определялась")
        truncation = "\nОтвет ограничен первыми 16 адресами." if values["truncated"] else ""
        body = f"🌐 <b>DNS: {html.escape(values['hostname'])}</b>\n{addresses}{comparison}{truncation}"
    else:
        labels = {
            "invalid_request": "запрос отклонён как некорректный",
            "unknown": "ответ неизвестен: resolver занят или истёк таймаут",
            "unavailable": "имя не разрешилось или системный resolver недоступен",
        }
        body = f"🌐 <b>DNS: {html.escape(str(parsed['hostname']))}</b>\n⚠️ {labels[str(values['state'])]}"
    await _replace_user_card(message, body, reply_markup=back_to_device_kb())

def _parse_dns_comparison_input(value: object) -> dict[str, object] | None:
    if not isinstance(value, str) or not value or len(value) > 512 or value != value.strip():
        return None
    parts = value.split("|")
    if len(parts) != 2:
        return None
    parsed_name = _parse_dns_resolution_input(parts[0].strip())
    if parsed_name is None:
        return None
    raw_servers = [item.strip() for item in parts[1].split(",")]
    if len(raw_servers) != 2 or any(not item for item in raw_servers):
        return None
    try:
        servers = [str(ipaddress.ip_address(item)) for item in raw_servers]
    except ValueError:
        return None
    if (len(set(servers)) != 2 or any(
        ipaddress.ip_address(item).is_unspecified
        or ipaddress.ip_address(item).is_multicast
        or ipaddress.ip_address(item).is_link_local
        for item in servers
    )):
        return None
    return {"hostname": parsed_name["hostname"], "resolvers": servers}


def _validated_dns_comparison(result: object, *, target: str, command_id: str,
                              hostname: str, resolvers: list[str]):
    if not isinstance(result, dict):
        return None
    if (result.get("type") != "dns_comparison"
            or result.get("schema") != "xider.dns-comparison.v1"
            or result.get("feature_id") != "D04-F07"
            or result.get("device_id") != target
            or result.get("request_id") != command_id
            or result.get("source") != "direct_udp_dns_to_owner_selected_resolvers"):
        return None
    try:
        checked_at = datetime.datetime.fromisoformat(str(result.get("checked_at", "")).replace("Z", "+00:00"))
    except ValueError:
        return None
    if checked_at.tzinfo is None:
        return None
    state = result.get("state")
    data = result.get("data")
    if state == "invalid_request":
        return ({"state": state, "detail": "invalid_dns_comparison_request", "checked_at": checked_at.isoformat()}
                if data is None and result.get("detail") == "invalid_dns_comparison_request" else None)
    if state not in {"supported", "unknown"} or not isinstance(data, dict):
        return None
    if data.get("hostname") != hostname or data.get("comparison") not in {"same", "different", "unknown"}:
        return None
    rows = data.get("resolvers")
    if not isinstance(rows, list) or len(rows) != 2:
        return None
    normalized_rows = []
    for index, row in enumerate(rows):
        if not isinstance(row, dict) or set(row) != {"address", "status", "records"}:
            return None
        if row.get("address") != resolvers[index]:
            return None
        status, records = row.get("status"), row.get("records")
        if status == "unknown":
            if records != {}:
                return None
            normalized_rows.append({"address": resolvers[index], "status": status, "records": {}})
            continue
        if status != "complete" or not isinstance(records, dict) or set(records) != {"A", "AAAA"}:
            return None
        parsed_records = {}
        for qtype, family in (("A", 4), ("AAAA", 6)):
            record = records.get(qtype)
            if not isinstance(record, dict) or set(record) != {"rcode", "addresses"}:
                return None
            rcode, addresses = record.get("rcode"), record.get("addresses")
            if not isinstance(rcode, str) or not re.fullmatch(r"(?:NOERROR|FORMERR|SERVFAIL|NXDOMAIN|NOTIMP|REFUSED|RCODE_[0-9]{1,2})", rcode):
                return None
            if not isinstance(addresses, list) or len(addresses) > 256:
                return None
            parsed = []
            try:
                for address in addresses:
                    ip = ipaddress.ip_address(address) if isinstance(address, str) else None
                    if ip is None or ip.version != family or str(ip) != address or address in parsed:
                        return None
                    parsed.append(address)
            except ValueError:
                return None
            parsed_records[qtype] = {"rcode": rcode, "addresses": sorted(parsed)}
        normalized_rows.append({"address": resolvers[index], "status": status, "records": parsed_records})
    if any(row["status"] != "complete" for row in normalized_rows):
        if state != "unknown" or data["comparison"] != "unknown":
            return None
    else:
        actual = "same" if normalized_rows[0]["records"] == normalized_rows[1]["records"] else "different"
        if state != "supported" or data["comparison"] != actual:
            return None
    return {"state": state, "checked_at": checked_at.isoformat(), "hostname": hostname,
            "comparison": data["comparison"], "resolvers": normalized_rows}


@router.callback_query(OwnerFilter(), F.data == "cmd:dns_comparison")
async def on_cmd_dns_comparison(cq: CallbackQuery, state: FSMContext):
    target = str(SESSION.get("target") or "")
    if not target or target == "all":
        await cq.answer(_lex("single_device_only"), show_alert=True)
        return
    if not await _callback_result_access_or_report(cq, target):
        return
    if _device_declares_command(devices.get(target) or {}, "dns_comparison") is not True:
        await _replace_callback_message(cq, "Агент не сообщает поддержку сравнения DNS-resolver-ов; запрос не отправлен.",
                                        reply_markup=back_to_device_kb())
        await cq.answer("Нужна совместимая версия агента.", show_alert=True)
        return
    await _start_authorized_input(state, Form.wait_dns_comparison, "cmd:dns_comparison", target)
    await _replace_callback_message(
        cq,
        "Введи домен и два DNS-сервера через ` | ` и запятую. Пример: `example.com | 1.1.1.1,8.8.8.8`.\n"
        "Агент отправит только A/AAAA DNS-запросы на эти два IP; системный resolver и адреса из ответов не используются.",
        reply_markup=back_to_device_kb(),
    )
    await cq.answer()


@router.message(OwnerFilter(), Form.wait_dns_comparison)
async def on_dns_comparison_input(message: Message, state: FSMContext):
    form_data = await state.get_data()
    await state.clear()
    target = str(form_data.get("authorization_target") or "")
    if (not target or target == "all" or SESSION.get("target") != target
            or not _pending_device_input_still_allowed(message, form_data, target)):
        await _reject_revoked_device_input(message)
        return
    parsed = _parse_dns_comparison_input(message.text or "")
    if parsed is None:
        await _replace_user_card(message, "Формат: `домен | IP-резолвера-1,IP-резолвера-2`; нужны два разных корректных IP.",
                                 reply_markup=back_to_device_kb())
        return
    if _device_declares_command(devices.get(target) or {}, "dns_comparison") is not True:
        await _replace_user_card(message, "Агент больше не объявляет поддержку сравнения DNS; запрос не отправлен.",
                                 reply_markup=back_to_device_kb())
        return
    sent, command_id = publish_tracked("dns_comparison", _target=target, **parsed)
    if not sent:
        await _replace_user_card(message, _lex("mqtt_disconnected"), reply_markup=back_to_device_kb())
        return
    await _replace_user_card(message, "🌐 Сравниваю A/AAAA-ответы выбранных DNS-resolver-ов…",
                             reply_markup=back_to_device_kb())
    result = await dns_comparison_collector.wait_for(target, "dns_comparison", 9.0, command_id)
    if not _pending_device_input_still_allowed(message, form_data, target):
        await _replace_user_card(message, _lex("action_result_hidden_after_revoke"), reply_markup=back_to_device_kb())
        return
    values = _validated_dns_comparison(result, target=target, command_id=command_id,
                                       hostname=str(parsed["hostname"]), resolvers=list(parsed["resolvers"]))
    if values is None:
        body = "⏳ Нет подтверждённого свежего ответа; сравнение осталось неизвестным."
    elif values["state"] == "invalid_request":
        body = "⚠️ Агент отклонил некорректный DNS-запрос."
    elif values["comparison"] == "unknown":
        body = f"🌐 <b>DNS-сравнение: {html.escape(values['hostname'])}</b>\n⚠️ Один или оба resolver-а не ответили; равенство не подтверждено."
    else:
        rendered = []
        for row in values["resolvers"]:
            rendered.append(f"<b>{html.escape(row['address'])}</b>")
            for qtype in ("A", "AAAA"):
                record = row["records"][qtype]
                addresses = ", ".join(html.escape(item) for item in record["addresses"]) or "нет адресов"
                rendered.append(f"{qtype} ({record['rcode']}): {addresses}")
        outcome = "ответы совпадают" if values["comparison"] == "same" else "ответы различаются"
        body = f"🌐 <b>DNS-сравнение: {html.escape(values['hostname'])}</b>\n{html.escape(outcome)}\n" + "\n".join(rendered)
    await _replace_user_card(message, body, reply_markup=back_to_device_kb())


def _validated_dns_settings(result: object, *, target: str, command_id: str, platform: str):
    if not isinstance(result, dict):
        return None
    expected_source = "windows_get_dns_client_server_address" if platform == "windows" else "macos_scutil_dns"
    if (result.get("type") != "dns_settings"
            or result.get("schema") != "xider.dns-settings.v1"
            or result.get("feature_id") != "D04-F06"
            or result.get("device_id") != target
            or result.get("request_id") != command_id
            or result.get("source") != expected_source):
        return None
    try:
        checked_at = datetime.datetime.fromisoformat(str(result.get("checked_at", "")).replace("Z", "+00:00"))
    except ValueError:
        return None
    if checked_at.tzinfo is None:
        return None
    state = result.get("state")
    if state not in {"supported", "unknown", "unsupported", "unavailable"}:
        return None
    data = result.get("data")
    if not isinstance(data, dict) or not isinstance(data.get("resolvers"), list) or len(data["resolvers"]) > 64:
        return None
    resolvers, seen_indexes = [], set()
    for row in data["resolvers"]:
        if not isinstance(row, dict) or set(row) != {"interface_index", "addresses"}:
            return None
        index, addresses = row.get("interface_index"), row.get("addresses")
        if type(index) is not int or not 1 <= index <= 2**31 - 1 or index in seen_indexes:
            return None
        if not isinstance(addresses, list) or not 1 <= len(addresses) <= 8:
            return None
        parsed = []
        try:
            for value in addresses:
                address = str(ipaddress.ip_address(value)) if isinstance(value, str) else None
                if address is None or address in parsed:
                    return None
                parsed.append(address)
        except ValueError:
            return None
        seen_indexes.add(index)
        resolvers.append({"interface_index": index, "addresses": parsed})
    if (state == "supported") != bool(resolvers):
        return None
    return {"state": state, "checked_at": checked_at.isoformat(), "resolvers": resolvers}


def _parse_route_trace_input(value: object) -> dict[str, str] | None:
    if not isinstance(value, str) or not value or len(value) > 64 or value != value.strip():
        return None
    try:
        address = ipaddress.ip_address(value)
    except ValueError:
        return None
    if address.is_unspecified or address.is_multicast or address.is_link_local:
        return None
    return {"target": str(address)}


def _validated_route_trace(result: object, *, target: str, command_id: str,
                           requested_target: str, platform: str):
    if not isinstance(result, dict):
        return None
    expected_source = "windows_tracert_icmp" if platform == "windows" else "macos_traceroute_udp"
    if (result.get("type") != "route_trace" or result.get("schema") != "xider.route-trace.v1"
            or result.get("feature_id") != "D04-F09" or result.get("device_id") != target
            or result.get("request_id") != command_id or result.get("source") != expected_source):
        return None
    try:
        checked_at = datetime.datetime.fromisoformat(str(result.get("checked_at", "")).replace("Z", "+00:00"))
    except ValueError:
        return None
    now = datetime.datetime.now(datetime.timezone.utc)
    if checked_at.tzinfo is None or checked_at > now + datetime.timedelta(seconds=60) or now - checked_at > datetime.timedelta(minutes=2):
        return None
    state, data, detail = result.get("state"), result.get("data"), result.get("detail")
    allowed_details = {None, "tracert_unavailable", "traceroute_unavailable", "invalid_route_trace_target", "route_trace_failed"}
    if detail not in allowed_details:
        return None
    if state == "invalid_request":
        return {"state": state, "detail": detail, "checked_at": checked_at.isoformat()} if data is None and detail == "invalid_route_trace_target" else None
    if state not in {"complete", "partial", "unknown", "unsupported"} or not isinstance(data, dict):
        return None
    if set(data) != {"target", "reached", "hops"} or data.get("target") != requested_target:
        return None
    hops = data.get("hops")
    if not isinstance(hops, list) or len(hops) > 12 or type(data.get("reached")) is not bool:
        return None
    family = ipaddress.ip_address(requested_target).version
    normalized, seen = [], set()
    for expected_index, row in enumerate(hops, 1):
        if not isinstance(row, dict) or set(row) != {"index", "address"} or type(row.get("index")) is not int or row["index"] != expected_index:
            return None
        value = row.get("address")
        if value is not None:
            if not isinstance(value, str):
                return None
            try:
                address = ipaddress.ip_address(value)
            except ValueError:
                return None
            if str(address) != value or address.version != family or address.is_unspecified or address.is_multicast or value in seen:
                return None
            seen.add(value)
        normalized.append({"index": expected_index, "address": value})
    reached = requested_target in seen
    if data["reached"] is not reached:
        return None
    expected_state = "complete" if reached else "partial" if normalized else "unknown"
    if state == "unsupported":
        if detail not in {"tracert_unavailable", "traceroute_unavailable"} or normalized or reached:
            return None
    elif state != expected_state:
        return None
    return {"state": state, "target": requested_target, "reached": reached,
            "hops": normalized, "detail": detail, "checked_at": checked_at.isoformat()}


def _parse_path_mtu_input(value: object) -> dict[str, str] | None:
    if not isinstance(value, str) or not value or len(value) > 64 or value != value.strip():
        return None
    try:
        address = ipaddress.ip_address(value)
    except ValueError:
        return None
    if address.version != 4 or address.is_unspecified or address.is_multicast or address.is_link_local:
        return None
    return {"target": str(address)}


def _parse_tls_certificate_input(value: object) -> dict[str, object] | None:
    """Accept one explicit hostname/IP and optional port; never a URL or range."""
    if not isinstance(value, str) or not value or len(value) > 300 or value != value.strip():
        return None
    host, port = value, 443
    if value.startswith("["):
        match = re.fullmatch(r"\[([^\]]+)\](?::([0-9]{1,5}))?", value)
        if not match:
            return None
        host = match.group(1)
        try:
            if ipaddress.ip_address(host).version != 6:
                return None
        except ValueError:
            return None
        if match.group(2):
            port = int(match.group(2))
    elif value.count(":") == 1:
        host, raw_port = value.rsplit(":", 1)
        if not raw_port.isdecimal():
            return None
        port = int(raw_port)
    elif ":" in value:
        try:
            if ipaddress.ip_address(value).version != 6:
                return None
        except ValueError:
            return None
    if not 1 <= port <= 65535 or not host or any(char in host for char in "/\\@?#% "):
        return None
    try:
        address = ipaddress.ip_address(host)
    except ValueError:
        try:
            host = host.encode("idna").decode("ascii").lower().rstrip(".")
        except UnicodeError:
            return None
        if len(host) > 253 or not host or any(not re.fullmatch(r"[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?", label)
                                               for label in host.split(".")):
            return None
    else:
        host = address.compressed
    return {"host": host, "port": port}


def _validated_tls_certificate(result: object, *, target: str, command_id: str, host: str, port: int):
    """Accept only a fresh, correlated TLS verification result for the requested host/port."""
    if not isinstance(result, dict):
        return None
    if (result.get("type") != "tls_certificate" or result.get("schema") != "xider.tls-certificate.v1"
            or result.get("feature_id") != "D04-F13" or result.get("device_id") != target
            or result.get("request_id") != command_id or result.get("source") != "verified_tls_certificate"
            or result.get("host") != host or type(result.get("port")) is not int or result.get("port") != port):
        return None
    try:
        checked_at = datetime.datetime.fromisoformat(str(result.get("checked_at", "")).replace("Z", "+00:00"))
    except ValueError:
        return None
    now = datetime.datetime.now(datetime.timezone.utc)
    if checked_at.tzinfo is None or checked_at > now + datetime.timedelta(seconds=60) or now - checked_at > datetime.timedelta(minutes=2):
        return None
    state, detail, data = result.get("state"), result.get("detail"), result.get("data")
    allowed_details = {None, "certificate_expired", "certificate_not_yet_valid", "certificate_chain_invalid",
                       "probe_timeout", "tls_probe_failed", "invalid_endpoint"}
    if detail not in allowed_details:
        return None
    clean_data = None
    if data is not None:
        if not isinstance(data, dict) or set(data) != {"not_before", "not_after", "sha256"}:
            return None
        if not isinstance(data.get("sha256"), str) or not re.fullmatch(r"[0-9a-f]{64}", data["sha256"]):
            return None
        try:
            not_before = datetime.datetime.fromisoformat(str(data["not_before"]).replace("Z", "+00:00"))
            not_after = datetime.datetime.fromisoformat(str(data["not_after"]).replace("Z", "+00:00"))
        except ValueError:
            return None
        if not_before.tzinfo is None or not_after.tzinfo is None or not_before >= not_after:
            return None
        clean_data = {"not_before": not_before.isoformat(), "not_after": not_after.isoformat(), "sha256": data["sha256"]}
    if state == "valid":
        if detail is not None or clean_data is None:
            return None
        before = datetime.datetime.fromisoformat(clean_data["not_before"])
        after = datetime.datetime.fromisoformat(clean_data["not_after"])
        if before > now or after <= now:
            return None
    elif state == "expired":
        if detail != "certificate_expired" or clean_data is None or datetime.datetime.fromisoformat(clean_data["not_after"]) > now:
            return None
    elif state == "not_yet_valid":
        if detail != "certificate_not_yet_valid" or clean_data is None or datetime.datetime.fromisoformat(clean_data["not_before"]) <= now:
            return None
    elif state == "chain_invalid":
        if detail != "certificate_chain_invalid":
            return None
        if clean_data is not None:
            before = datetime.datetime.fromisoformat(clean_data["not_before"])
            after = datetime.datetime.fromisoformat(clean_data["not_after"])
            if before > now or after <= now:
                return None
    elif state == "unknown":
        if detail not in {"probe_timeout", "tls_probe_failed"} or clean_data is not None:
            return None
    elif state == "invalid_request":
        if detail != "invalid_endpoint" or clean_data is not None:
            return None
    else:
        return None
    return {"state": state, "detail": detail, "data": clean_data, "checked_at": checked_at.isoformat()}


def _parse_service_probe_input(value: object) -> dict[str, object] | None:
    if not isinstance(value, str) or not value or value != value.strip() or len(value) > 310:
        return None
    pieces = value.split(" ")
    if len(pieces) != 2 or pieces[0].lower() not in {"tcp", "tls"}:
        return None
    endpoint = _parse_tls_certificate_input(pieces[1])
    if endpoint is None:
        return None
    return {**endpoint, "protocol": pieces[0].lower()}


def _parse_latency_series_input(value: object) -> dict[str, object] | None:
    """Accept exactly one explicit host:port for a bounded TCP-connect series."""
    if not isinstance(value, str) or not value or value != value.strip() or len(value) > 300:
        return None
    endpoint = _parse_tls_certificate_input(value)
    if endpoint is None:
        return None
    return endpoint


def _validated_latency_series(result: object, *, target: str, command_id: str, host: str, port: int):
    if not isinstance(result, dict):
        return None
    expected_fields = {"type", "schema", "feature_id", "device_id", "request_id", "host", "port",
                       "source", "state", "checked_at", "samples", "summary", "detail"}
    if (set(result) != expected_fields or result.get("type") != "latency_series"
            or result.get("schema") != "xider.latency-series.v1" or result.get("feature_id") != "D04-F01"
            or result.get("device_id") != target or result.get("request_id") != command_id
            or result.get("host") != host or type(result.get("port")) is not int or result.get("port") != port
            or result.get("source") != "tcp_connect_monotonic"):
        return None
    try:
        checked_at = datetime.datetime.fromisoformat(str(result.get("checked_at", "")).replace("Z", "+00:00"))
    except ValueError:
        return None
    now = datetime.datetime.now(datetime.timezone.utc)
    if (checked_at.tzinfo is None or checked_at > now + datetime.timedelta(seconds=60)
            or now - checked_at > datetime.timedelta(minutes=2)):
        return None
    samples = result.get("samples")
    if not isinstance(samples, list) or len(samples) != 5:
        return None
    successful = []
    for index, row in enumerate(samples, start=1):
        if not isinstance(row, dict) or set(row) != {"index", "state", "latency_ms"} or row.get("index") != index:
            return None
        sample_state, latency = row.get("state"), row.get("latency_ms")
        if sample_state == "connected":
            if (type(latency) not in {int, float} or not math.isfinite(float(latency))
                    or not 0 <= latency <= 5000):
                return None
            successful.append(float(latency))
        elif sample_state in {"timeout", "refused", "unknown"}:
            if latency is not None:
                return None
        else:
            return None
    summary = result.get("summary")
    summary_fields = {"successful", "attempted", "min_ms", "mean_ms", "max_ms"}
    if (not isinstance(summary, dict) or set(summary) != summary_fields
            or type(summary.get("successful")) is not int or summary.get("successful") != len(successful)
            or type(summary.get("attempted")) is not int or summary.get("attempted") != 5):
        return None
    expected_stats = ({"min_ms": min(successful), "mean_ms": round(sum(successful) / len(successful), 2),
                      "max_ms": max(successful)} if successful else
                     {"min_ms": None, "mean_ms": None, "max_ms": None})
    if any(summary.get(key) != value for key, value in expected_stats.items()):
        return None
    state, detail = result.get("state"), result.get("detail")
    expected_state = "available" if len(successful) == 5 else "partial" if successful else "unknown"
    if state != expected_state or detail != (None if successful else "no_tcp_connection_confirmed"):
        return None
    return {"state": state, "checked_at": checked_at.isoformat(), "samples": samples, "summary": summary}


def _parse_packet_loss_address(value: object) -> str | None:
    if not isinstance(value, str) or not 1 <= len(value.strip()) <= 64:
        return None
    try:
        address = ipaddress.ip_address(value.strip())
    except ValueError:
        return None
    if (address.is_unspecified or address.is_loopback or address.is_multicast
            or (isinstance(address, ipaddress.IPv4Address) and int(address) == 0xFFFFFFFF)):
        return None
    return str(address)


def _validated_network_jitter(result: object, *, target: str, command_id: str, address: str):
    if not isinstance(result, dict):
        return None
    fields = {"type", "schema", "feature_id", "device_id", "request_id", "address", "source", "state", "checked_at", "data"}
    if (set(result) != fields or result.get("type") != "network_jitter"
            or result.get("schema") != "xider.network-jitter.v1" or result.get("feature_id") != "D04-F03"
            or result.get("device_id") != target or result.get("request_id") != command_id
            or result.get("address") != address or result.get("source") != "icmp_rtt_adjacent_mean_abs_delta"):
        return None
    try:
        checked_at = datetime.datetime.fromisoformat(str(result["checked_at"]).replace("Z", "+00:00"))
        age = (datetime.datetime.now(datetime.timezone.utc) - checked_at.astimezone(datetime.timezone.utc)).total_seconds()
    except (TypeError, ValueError, OverflowError):
        return None
    if age < -5 or age > 120:
        return None
    data = result.get("data")
    data_fields = {"address", "state", "source", "detail", "attempted", "received", "lost", "unknown", "pairs", "jitter_ms", "samples"}
    if not isinstance(data, dict) or set(data) != data_fields:
        return None
    if data.get("address") != address or data.get("source") != "icmp_rtt_adjacent_mean_abs_delta":
        return None
    if type(data.get("attempted")) is not int or data["attempted"] != 10:
        return None
    samples = data.get("samples")
    if not isinstance(samples, list) or len(samples) != 10:
        return None
    states = []
    for index, sample in enumerate(samples, 1):
        if not isinstance(sample, dict) or set(sample) != {"index", "state", "rtt_ms", "elapsed_ms"}:
            return None
        state = sample.get("state")
        rtt = sample.get("rtt_ms")
        if (type(sample.get("index")) is not int or sample["index"] != index
                or state not in {"reply", "lost", "unknown"}
                or (state != "reply" and rtt is not None)
                or (rtt is not None and (type(rtt) not in {int, float} or not 0 <= rtt <= 60000))
                or type(sample.get("elapsed_ms")) is not int or not 0 <= sample["elapsed_ms"] <= 30000):
            return None
        states.append(state)
    deltas = [abs(current["rtt_ms"] - previous["rtt_ms"])
              for previous, current in zip(samples, samples[1:])
              if previous["state"] == current["state"] == "reply"
              and previous["rtt_ms"] is not None and current["rtt_ms"] is not None]
    received, lost, unknown = states.count("reply"), states.count("lost"), states.count("unknown")
    pairs = len(deltas)
    expected_state = "available" if pairs == 9 else "partial" if pairs else "unknown"
    expected_jitter = round(sum(deltas) / pairs, 3) if pairs else None
    if (data.get("received") != received or data.get("lost") != lost or data.get("unknown") != unknown
            or data.get("pairs") != pairs or data.get("jitter_ms") != expected_jitter
            or data.get("state") != expected_state or result.get("state") != expected_state
            or data.get("detail") != (None if pairs else "no_adjacent_exact_rtt_pair")):
        return None
    return {"state": expected_state, "checked_at": checked_at.isoformat(), "received": received,
            "lost": lost, "unknown": unknown, "pairs": pairs,
            "jitter_ms": expected_jitter, "samples": samples}


@router.callback_query(OwnerFilter(), F.data == "cmd:network_jitter")
async def on_cmd_network_jitter(cq: CallbackQuery, state: FSMContext):
    target = str(SESSION.get("target") or "")
    if not target or target == "all":
        await cq.answer(_lex("single_device_only"), show_alert=True)
        return
    if not await _callback_result_access_or_report(cq, target):
        return
    info = devices.get(target) or {}
    if _device_declares_command(info, "network_jitter") is not True:
        await _replace_callback_message(cq, "Устройство не объявляет ICMP jitter-замер; запрос не отправлен.",
                                        reply_markup=back_to_device_kb())
        await cq.answer("Нужен совместимый агент.", show_alert=True)
        return
    await _start_authorized_input(state, Form.wait_network_jitter, "cmd:network_jitter", target)
    await _replace_callback_message(
        cq,
        "Введи один IP-адрес. Агент сделает ровно 10 ICMP echo-запросов и посчитает среднюю разницу RTT соседних ответов. "
        "Это ICMP RTT jitter, не TCP connect latency; домены и диапазоны не принимаются.",
        reply_markup=back_to_device_kb(),
    )
    await cq.answer()


@router.message(OwnerFilter(), Form.wait_network_jitter)
async def on_network_jitter_input(message: Message, state: FSMContext):
    form_data = await state.get_data()
    await state.clear()
    target = str(form_data.get("authorization_target") or "")
    if (not target or target == "all" or SESSION.get("target") != target
            or not _pending_device_input_still_allowed(message, form_data, target)):
        await _reject_revoked_device_input(message)
        return
    address = _parse_packet_loss_address(message.text or "")
    try:
        await message.delete()
    except Exception:
        pass
    if address is None:
        await _replace_user_card(message, "Нужен один literal IP без домена, диапазона или broadcast-адреса.",
                                 reply_markup=back_to_device_kb())
        return
    record = devices.get(target) or {}
    if _device_declares_command(record, "network_jitter") is not True:
        await _replace_user_card(message, "Агент больше не объявляет ICMP jitter; запрос не отправлен.",
                                 reply_markup=back_to_device_kb())
        return
    sent, command_id = publish_tracked("network_jitter", _target=target, address=address)
    if not sent:
        await _replace_user_card(message, _lex("mqtt_disconnected"), reply_markup=back_to_device_kb())
        return
    await _replace_user_card(message, "📶 Снимаю десять ограниченных ICMP RTT-проб одного IP…",
                             reply_markup=back_to_device_kb())
    result = await network_jitter_collector.wait_for(target, "network_jitter", 30.0, command_id)
    if not _pending_device_input_still_allowed(message, form_data, target):
        await _replace_user_card(message, _lex("action_result_hidden_after_revoke"), reply_markup=back_to_device_kb())
        return
    values = _validated_network_jitter(result, target=target, command_id=command_id, address=address)
    if values is None:
        body = "⏳ Нет подтверждённой свежей серии ICMP RTT; jitter неизвестен."
    elif values["jitter_ms"] is None:
        body = (f"📶 <b>ICMP RTT jitter</b> · <code>{html.escape(address)}</code>\n"
                f"Проб: 10 · ответов: {values['received']} · таймаутов: {values['lost']} · неизвестных: {values['unknown']}\n"
                "Недостаточно соседних точных RTT для расчёта jitter.")
    else:
        body = (f"📶 <b>ICMP RTT jitter</b> · <code>{html.escape(address)}</code>\n"
                f"Средняя абсолютная разница соседних RTT: <b>{values['jitter_ms']:g} ms</b> · "
                f"пар: {values['pairs']}/9\n"
                f"Ответов: {values['received']} · таймаутов: {values['lost']} · неизвестных: {values['unknown']}")
        if values["state"] == "partial":
            body += "\nНеполная серия; расчёт только по соседним точным RTT-ответам."
    await _replace_user_card(message, body, reply_markup=back_to_device_kb())


def _parse_network_throughput_endpoint(value: object) -> str | None:
    path = "/.well-known/xider-bandwidth"
    if not isinstance(value, str) or not value or len(value) > 300 or value != value.strip():
        return None
    try:
        parsed = urlsplit(value)
        port = parsed.port
    except ValueError:
        return None
    host = parsed.hostname
    if (parsed.scheme.lower() != "https" or not host or parsed.username is not None or parsed.password is not None
            or parsed.path != path or parsed.query or parsed.fragment):
        return None
    try:
        address = ipaddress.ip_address(host)
        canonical_host = f"[{address.compressed}]" if address.version == 6 else address.compressed
    except ValueError:
        try:
            canonical_host = host.encode("idna").decode("ascii").lower().rstrip(".")
        except UnicodeError:
            return None
        labels = canonical_host.split(".")
        if (not canonical_host or len(canonical_host) > 253
                or any(not label or len(label) > 63 or label.startswith("-") or label.endswith("-")
                       or not re.fullmatch(r"[a-z0-9-]+", label) for label in labels)):
            return None
    suffix = f":{port}" if port and port != 443 else ""
    return f"https://{canonical_host}{suffix}{path}"


def _validated_network_throughput(result: object, *, target: str, command_id: str, endpoint: str):
    if not isinstance(result, dict):
        return None
    fields = {"type", "schema", "feature_id", "device_id", "request_id", "endpoint", "source", "state", "checked_at", "data"}
    if (set(result) != fields or result.get("type") != "network_throughput"
            or result.get("schema") != "xider.network-throughput.v1" or result.get("feature_id") != "D04-F04"
            or result.get("device_id") != target or result.get("request_id") != command_id
            or result.get("endpoint") != endpoint or result.get("source") != "https_xider_bandwidth_endpoint"):
        return None
    try:
        checked_at = datetime.datetime.fromisoformat(str(result["checked_at"]).replace("Z", "+00:00"))
        age = (datetime.datetime.now(datetime.timezone.utc) - checked_at.astimezone(datetime.timezone.utc)).total_seconds()
    except (TypeError, ValueError, OverflowError):
        return None
    if age < -5 or age > 120:
        return None
    data = result.get("data")
    fields = {"state", "source", "download_bytes", "download_duration_ms", "download_bytes_per_second",
              "upload_bytes", "upload_duration_ms", "upload_bytes_per_second"}
    if not isinstance(data, dict) or set(data) != fields or data.get("source") != "https_xider_bandwidth_endpoint":
        return None
    if data.get("state") != "available" or result.get("state") != "available":
        return None
    download_bytes, download_ms = data.get("download_bytes"), data.get("download_duration_ms")
    upload_bytes, upload_ms = data.get("upload_bytes"), data.get("upload_duration_ms")
    numbers = (download_bytes, download_ms, data.get("download_bytes_per_second"),
               upload_bytes, upload_ms, data.get("upload_bytes_per_second"))
    if any(type(value) is not int for value in numbers):
        return None
    if (not 1 <= download_bytes <= 256 * 1024 or not 1 <= download_ms <= 30000
            or upload_bytes != 64 * 1024 or not 1 <= upload_ms <= 30000
            or data["download_bytes_per_second"] != round(download_bytes * 1000 / download_ms)
            or data["upload_bytes_per_second"] != round(upload_bytes * 1000 / upload_ms)):
        return None
    return {key: data[key] for key in fields if key not in {"state", "source"}}


