def _parse_route_lookup_destination(value: object) -> str | None:
    if not isinstance(value, str) or value != value.strip() or "%" in value or not value:
        return None
    try:
        address = ipaddress.ip_address(value)
    except ValueError:
        return None
    if address.is_unspecified or address.is_multicast:
        return None
    return address.compressed


def _validated_route_lookup(result: object, *, target: str, command_id: str, destination: str):
    fields = {"type", "schema", "feature_id", "device_id", "request_id", "source", "state", "checked_at", "data"}
    if (not isinstance(result, dict) or set(result) != fields
            or result.get("type") != "route_lookup" or result.get("schema") != "xider.route-lookup.v1"
            or result.get("feature_id") != "D04-F22" or result.get("device_id") != target
            or result.get("request_id") != command_id or result.get("source") not in {"windows_find_net_route", "macos_route_get"}):
        return None
    try:
        checked = datetime.datetime.fromisoformat(str(result["checked_at"]).replace("Z", "+00:00"))
        now = datetime.datetime.now(datetime.timezone.utc)
        if checked.tzinfo is None or checked > now + datetime.timedelta(seconds=60) or now - checked > datetime.timedelta(minutes=2):
            return None
    except (TypeError, ValueError, OverflowError):
        return None
    data, state = result.get("data"), result.get("state")
    if not isinstance(data, dict) or state not in {"available", "unknown", "unsupported"} or data.get("state") != state:
        return None
    if state != "available":
        if set(data) not in ({"state", "destination"}, {"state"}) or data.get("destination", destination) != destination:
            return None
        return {"state": state}
    if set(data) != {"state", "destination", "route_prefix", "gateway", "interface", "metric", "source"}:
        return None
    if (data.get("destination") != destination or data.get("source") != result.get("source")
            or not isinstance(data.get("route_prefix"), str) or len(data["route_prefix"]) > 64
            or not isinstance(data.get("gateway"), str) or len(data["gateway"]) > 64
            or not isinstance(data.get("interface"), str) or not data["interface"] or len(data["interface"]) > 128
            or any(ord(ch) < 32 for ch in data["interface"])):
        return None
    metric = data.get("metric")
    if metric is not None and (type(metric) is not int or not 0 <= metric <= 2**31 - 1):
        return None
    return {"state": state, "route_prefix": data["route_prefix"], "gateway": data["gateway"],
            "interface": data["interface"], "metric": metric, "checked_at": checked.astimezone(datetime.timezone.utc)}


