def _validated_service_probe(result: object, *, target: str, command_id: str,
                             host: str, port: int, protocol: str):
    if not isinstance(result, dict):
        return None
    expected_fields = {"type", "schema", "feature_id", "device_id", "request_id", "host", "port",
                       "protocol", "source", "state", "checked_at", "detail"}
    if (set(result) != expected_fields or result.get("type") != "service_probe"
            or result.get("schema") != "xider.service-probe.v1" or result.get("feature_id") != "D04-F14"
            or result.get("device_id") != target or result.get("request_id") != command_id
            or result.get("host") != host or type(result.get("port")) is not int or result.get("port") != port
            or result.get("protocol") != protocol or result.get("source") != "single_endpoint_tcp_tls"):
        return None
    try:
        checked_at = datetime.datetime.fromisoformat(str(result.get("checked_at", "")).replace("Z", "+00:00"))
    except ValueError:
        return None
    now = datetime.datetime.now(datetime.timezone.utc)
    if checked_at.tzinfo is None or checked_at > now + datetime.timedelta(seconds=60) or now - checked_at > datetime.timedelta(minutes=2):
        return None
    state, detail = result.get("state"), result.get("detail")
    valid = (
        (state == "reachable" and detail is None)
        or (state == "reachable_untrusted" and protocol == "tls" and detail == "tls_certificate_untrusted")
        or (state == "unreachable" and detail == "connection_refused")
        or (state == "unknown" and detail in ({"probe_timeout", "probe_failed"} if protocol == "tcp"
                                               else {"probe_timeout", "probe_failed", "tls_handshake_failed"}))
        or (state == "invalid_request" and detail == "invalid_endpoint_or_protocol")
    )
    if not valid:
        return None
    return {"state": state, "detail": detail, "checked_at": checked_at.isoformat()}


def _validated_wifi_quality_history(result: object, *, target: str, command_id: str):
    if not isinstance(result, dict):
        return None
    expected = {"type", "schema", "feature_id", "device_id", "request_id", "source", "state",
                "metric", "value", "checked_at", "detail"}
    if (set(result) != expected or result.get("type") != "wifi_quality_history"
            or result.get("schema") != "xider.wifi-quality.v1" or result.get("feature_id") != "D04-F15"
            or result.get("device_id") != target or result.get("request_id") != command_id):
        return None
    source = result.get("source")
    if source not in {"windows_netsh_signal_percent", "macos_ipconfig_agrctlrssi"}:
        return None
    try:
        checked_at = datetime.datetime.fromisoformat(str(result.get("checked_at", "")).replace("Z", "+00:00"))
    except ValueError:
        return None
    now = datetime.datetime.now(datetime.timezone.utc)
    if (checked_at.tzinfo is None or checked_at > now + datetime.timedelta(seconds=60)
            or now - checked_at > datetime.timedelta(minutes=2)):
        return None
    state, metric, value, detail = (result.get("state"), result.get("metric"),
                                    result.get("value"), result.get("detail"))
    if state == "available":
        if source == "windows_netsh_signal_percent":
            valid = metric == "signal_percent" and type(value) is int and 0 <= value <= 100 and detail is None
        else:
            valid = metric == "rssi_dbm" and type(value) is int and -120 <= value <= 0 and detail is None
        if not valid:
            return None
    elif state == "unsupported":
        if metric is not None or value is not None or detail not in {"signal_unavailable", "wifi_interface_unavailable"}:
            return None
    elif state == "unknown":
        if metric is not None or value is not None or detail not in {"wifi_query_failed", "invalid_signal_sample"}:
            return None
    else:
        return None
    return {"state": state, "source": source, "metric": metric, "value": value,
            "checked_at": checked_at.isoformat(), "detail": detail}


def _validated_wifi_channel_summary(result: object, *, target: str, command_id: str):
    if not isinstance(result, dict):
        return None
    expected = {"type", "schema", "feature_id", "device_id", "request_id", "source", "state",
                "channel", "width_mhz", "width_state", "checked_at", "detail"}
    if (set(result) != expected or result.get("type") != "wifi_channel_summary"
            or result.get("schema") != "xider.wifi-channel.v1" or result.get("feature_id") != "D04-F16"
            or result.get("device_id") != target or result.get("request_id") != command_id):
        return None
    source = result.get("source")
    if source not in {"windows_netsh_wlan_channel", "macos_wdutil_channel"}:
        return None
    try:
        checked_at = datetime.datetime.fromisoformat(str(result.get("checked_at", "")).replace("Z", "+00:00"))
    except ValueError:
        return None
    now = datetime.datetime.now(datetime.timezone.utc)
    if checked_at.tzinfo is None or checked_at > now + datetime.timedelta(seconds=60) or now - checked_at > datetime.timedelta(minutes=2):
        return None
    state, channel, width, width_state, detail = (result.get("state"), result.get("channel"),
                                                   result.get("width_mhz"), result.get("width_state"),
                                                   result.get("detail"))
    if state == "available":
        if type(channel) is not int or not 1 <= channel <= 233 or detail is not None:
            return None
        if width_state == "available":
            if type(width) is not int or width not in {20, 40, 80, 160, 320}:
                return None
        elif width_state == "unsupported":
            if width is not None:
                return None
        else:
            return None
    elif state == "unsupported":
        if channel is not None or width is not None or width_state != "unsupported" or detail != "channel_unavailable":
            return None
    elif state == "unknown":
        if channel is not None or width is not None or width_state != "unknown" or detail not in {"wifi_query_failed", "invalid_channel_sample"}:
            return None
    else:
        return None
    return {"state": state, "source": source, "channel": channel, "width_mhz": width,
            "width_state": width_state, "checked_at": checked_at.isoformat(), "detail": detail}


def _validated_wifi_connection_history(result: object, *, target: str, command_id: str):
    if not isinstance(result, dict):
        return None
    expected = {"type", "schema", "feature_id", "device_id", "request_id", "source", "state",
                "events", "checked_at", "detail"}
    if (set(result) != expected or result.get("type") != "wifi_connection_history"
            or result.get("schema") != "xider.wifi-connection-history.v1"
            or result.get("feature_id") != "D04-F17" or result.get("device_id") != target
            or result.get("request_id") != command_id):
        return None
    source = result.get("source")
    if source not in {"windows_wlan_autoconfig_events", "macos_unified_airportd_events"}:
        return None
    try:
        checked_at = datetime.datetime.fromisoformat(str(result.get("checked_at", "")).replace("Z", "+00:00"))
    except ValueError:
        return None
    now = datetime.datetime.now(datetime.timezone.utc)
    if (checked_at.tzinfo is None or checked_at > now + datetime.timedelta(seconds=60)
            or now - checked_at > datetime.timedelta(minutes=2)):
        return None
    state, events, detail = result.get("state"), result.get("events"), result.get("detail")
    if not isinstance(events, list) or len(events) > 20:
        return None
    parsed = []
    for event in events:
        if not isinstance(event, dict) or set(event) != {"at", "kind"} or event.get("kind") not in {"connected", "disconnected"}:
            return None
        try:
            at = datetime.datetime.fromisoformat(str(event.get("at", "")).replace("Z", "+00:00"))
        except ValueError:
            return None
        if at.tzinfo is None or at > checked_at + datetime.timedelta(seconds=60) or checked_at - at > datetime.timedelta(hours=24, minutes=1):
            return None
        parsed.append((at.astimezone(datetime.timezone.utc), {"at": at.isoformat(), "kind": event["kind"]}))
    if parsed != sorted(parsed, key=lambda item: item[0]):
        return None
    if state == "available":
        if not events or detail is not None:
            return None
    elif state == "unsupported":
        if events or detail != "no_connection_events":
            return None
    elif state == "unknown":
        if events or detail not in {"event_log_unavailable", "invalid_event_log"}:
            return None
    else:
        return None
    return {"state": state, "source": source, "events": [item[1] for item in parsed],
            "checked_at": checked_at.isoformat(), "detail": detail}


def _validated_proxy_status(result: object, *, target: str, command_id: str):
    if not isinstance(result, dict):
        return None
    expected = {"type", "schema", "feature_id", "device_id", "request_id", "source", "state",
                "sources", "checked_at", "detail"}
    if (set(result) != expected or result.get("type") != "proxy_status"
            or result.get("schema") != "xider.proxy-status.v1" or result.get("feature_id") != "D04-F23"
            or result.get("device_id") != target or result.get("request_id") != command_id):
        return None
    platform_sources = {
        "windows_proxy_flags": {"current_user_manual", "current_user_pac", "current_user_auto_detect", "winhttp", "environment"},
        "macos_scutil_proxy_flags": {"http", "https", "socks", "pac", "auto_detect"},
    }
    source = result.get("source")
    state, sources, detail = result.get("state"), result.get("sources"), result.get("detail")
    if source not in platform_sources or not isinstance(sources, list) or len(sources) > 5:
        return None
    if any(not isinstance(item, str) or item not in platform_sources[source] for item in sources):
        return None
    if len(set(sources)) != len(sources):
        return None
    try:
        checked_at = datetime.datetime.fromisoformat(str(result.get("checked_at", "")).replace("Z", "+00:00"))
    except ValueError:
        return None
    now = datetime.datetime.now(datetime.timezone.utc)
    if checked_at.tzinfo is None or checked_at > now + datetime.timedelta(seconds=60) or now - checked_at > datetime.timedelta(minutes=2):
        return None
    if state == "available":
        if detail is not None:
            return None
    elif state == "unknown":
        if sources or detail not in {None, "registry_unavailable", "winhttp_query_failed", "scutil_unavailable", "scutil_query_failed"}:
            return None
    else:
        return None
    return {"state": state, "source": source, "sources": list(sources),
            "checked_at": checked_at.isoformat(), "detail": detail}


def _validated_vpn_route_status(result: object, *, target: str, command_id: str):
    if not isinstance(result, dict):
        return None
    expected = {"type", "schema", "feature_id", "device_id", "request_id", "source", "state",
                "up_tunnel_candidates", "down_tunnel_candidates", "route_assessment", "checked_at", "detail"}
    if (set(result) != expected or result.get("type") != "vpn_route_status"
            or result.get("schema") != "xider.vpn-route.v1" or result.get("feature_id") != "D04-F24"
            or result.get("device_id") != target or result.get("request_id") != command_id):
        return None
    source = result.get("source")
    if source not in {"windows_interface_hints", "macos_interface_hints"}:
        return None
    state = result.get("state")
    up, down = result.get("up_tunnel_candidates"), result.get("down_tunnel_candidates")
    detail = result.get("detail")
    if (not isinstance(up, int) or isinstance(up, bool) or not 0 <= up <= 128
            or not isinstance(down, int) or isinstance(down, bool) or not 0 <= down <= 128
            or result.get("route_assessment") != "not_verified"):
        return None
    if state == "available":
        if detail is not None:
            return None
    elif state == "unknown":
        if up or down or detail not in {"psutil_unavailable", "interface_query_failed"}:
            return None
    else:
        return None
    try:
        checked_at = datetime.datetime.fromisoformat(str(result.get("checked_at", "")).replace("Z", "+00:00"))
    except ValueError:
        return None
    now = datetime.datetime.now(datetime.timezone.utc)
    if checked_at.tzinfo is None or checked_at > now + datetime.timedelta(seconds=60) or now - checked_at > datetime.timedelta(minutes=2):
        return None
    return {"state": state, "source": source, "up_tunnel_candidates": up,
            "down_tunnel_candidates": down, "route_assessment": "not_verified",
            "checked_at": checked_at.isoformat(), "detail": detail}


def _validated_endpoint_batch(result: object, *, target: str, command_id: str):
    if not isinstance(result, dict):
        return None
    expected = {"type", "schema", "feature_id", "device_id", "request_id", "source", "preset", "state", "results", "checked_at"}
    if (set(result) != expected or result.get("type") != "endpoint_batch"
            or result.get("schema") != "xider.endpoint-batch.v1" or result.get("feature_id") != "D04-F25"
            or result.get("device_id") != target or result.get("request_id") != command_id
            or result.get("source") != "fixed_public_tcp_endpoints" or result.get("preset") != "public_basics"):
        return None
    rows = result.get("results")
    if not isinstance(rows, list) or len(rows) != 3 or result.get("state") not in {"available", "unknown"}:
        return None
    expected_ids = ("example", "cloudflare", "github")
    allowed_states = {"reachable", "unreachable", "unknown"}
    allowed_details = {None, "probe_timeout", "connection_refused", "probe_failed"}
    parsed = []
    for row, target_id in zip(rows, expected_ids, strict=True):
        if (not isinstance(row, dict) or set(row) != {"target_id", "state", "detail"}
                or row.get("target_id") != target_id or row.get("state") not in allowed_states
                or row.get("detail") not in allowed_details):
            return None
        parsed.append({"target_id": target_id, "state": row["state"], "detail": row["detail"]})
    try:
        checked_at = datetime.datetime.fromisoformat(str(result.get("checked_at", "")).replace("Z", "+00:00"))
    except ValueError:
        return None
    now = datetime.datetime.now(datetime.timezone.utc)
    if checked_at.tzinfo is None or checked_at > now + datetime.timedelta(seconds=60) or now - checked_at > datetime.timedelta(minutes=2):
        return None
    return {"state": result["state"], "results": parsed, "checked_at": checked_at.isoformat()}


def _format_path_diagnostic(*, gateway, dns, route, endpoints) -> str:
    """Summarize bounded probes without treating silence as proof of an outage."""
    gateway_state = gateway.get("state") if isinstance(gateway, dict) else None
    if gateway_state == "reachable":
        gateway_text = "шлюз ответил на ICMP"
    elif gateway_state == "no_gateway":
        gateway_text = "IPv4-маршрут по умолчанию отсутствует"
    elif gateway_state == "unsupported":
        gateway_text = "проверка шлюза не поддерживается"
    else:
        gateway_text = "нет подтверждённого ответа (возможны фильтрация или тайм-аут)"

    dns_state = dns.get("state") if isinstance(dns, dict) else None
    if dns_state == "supported":
        dns_text = f"example.com разрешён ({len(dns.get('addresses', []))} адрес.)"
    elif dns_state == "unavailable":
        dns_text = "имя не разрешилось или системный resolver недоступен"
    elif dns_state == "unknown":
        dns_text = "ответ не подтверждён"
    else:
        dns_text = "не проверен"

    route_state = route.get("state") if isinstance(route, dict) else None
    if route_state == "complete":
        route_text = "цель 1.1.1.1 встретилась в трассе"
    elif route_state == "partial":
        route_text = "трасса частичная; это не доказывает место сбоя"
    elif route_state == "unsupported":
        route_text = "утилита трассировки недоступна"
    else:
        route_text = "результат неизвестен"

    endpoint_rows = endpoints.get("results", []) if isinstance(endpoints, dict) else []
    if endpoint_rows:
        reachable = sum(row.get("state") == "reachable" for row in endpoint_rows)
        unknown = sum(row.get("state") == "unknown" for row in endpoint_rows)
        endpoint_text = f"доступно {reachable}/3; неизвестно {unknown}/3"
    else:
        endpoint_text = "не проверены"

    confirmed = None
    if gateway_state == "no_gateway":
        confirmed = "IPv4-маршрут по умолчанию отсутствует"
    elif endpoint_rows:
        refused = next((row.get("target_id") for row in endpoint_rows
                        if row.get("state") == "unreachable" and row.get("detail") == "connection_refused"), None)
        if refused:
            labels = {"example": "example.com", "cloudflare": "www.cloudflare.com", "github": "github.com"}
            confirmed = f"TCP-соединение отклонено endpoint {labels.get(refused, 'из фиксированного набора')}"
    confirmed_text = (f"Подтверждённый отказ: {confirmed}." if confirmed else
                      "Подтверждённый отказ: не найден; тайм-ауты и частичная трасса сами по себе не доказывают обрыв.")
    return ("🧭 <b>Где обрыв? · сводка проверок</b>\n"
            f"• Шлюз: {gateway_text}\n• DNS: {dns_text}\n• Маршрут: {route_text}\n"
            f"• Endpoints TCP/443: {endpoint_text}\n\n{confirmed_text}")


def _build_network_path_report_json(*, device_id: str, checked_at: str, gateway, dns, route, endpoints) -> bytes:
    """Create an editable, allowlisted network report; raw probe values never leave this function."""
    states = {"reachable", "no_gateway", "unsupported", "unknown", "supported", "unavailable", "complete", "partial"}
    gateway_state = gateway.get("state") if isinstance(gateway, dict) else None
    dns_state = dns.get("state") if isinstance(dns, dict) else None
    route_state = route.get("state") if isinstance(route, dict) else None
    gateway_state = gateway_state if gateway_state in states else "unknown"
    dns_state = dns_state if dns_state in states else "unknown"
    route_state = route_state if route_state in states else "unknown"
    endpoint_states = {}
    allowed_ids = ("example", "cloudflare", "github")
    rows = endpoints.get("results", []) if isinstance(endpoints, dict) else []
    if isinstance(rows, list):
        by_id = {row.get("target_id"): row for row in rows if isinstance(row, dict)}
        for target_id in allowed_ids:
            row = by_id.get(target_id)
            state = row.get("state") if isinstance(row, dict) else None
            endpoint_states[target_id] = state if state in {"reachable", "unreachable", "unknown"} else "unknown"
    else:
        endpoint_states = {target_id: "unknown" for target_id in allowed_ids}

    confirmed_failure = "no_ipv4_default_route" if gateway_state == "no_gateway" else None
    if confirmed_failure is None and isinstance(rows, list):
        refused = next((row.get("target_id") for row in rows if isinstance(row, dict)
                        and row.get("target_id") in allowed_ids and row.get("state") == "unreachable"
                        and row.get("detail") == "connection_refused"), None)
        if refused:
            confirmed_failure = f"tcp_refused:{refused}"
    report = {
        "schema": "xider.network-diagnostic-report.v1",
        "feature_id": "D04-F28",
        "device_id": str(device_id)[:128],
        "checked_at": str(checked_at)[:64],
        "checks": {
            "gateway": gateway_state,
            "dns": dns_state,
            "route": route_state,
            "endpoints": endpoint_states,
        },
        "confirmed_failure": confirmed_failure,
    }
    return json.dumps(report, ensure_ascii=False, indent=2, sort_keys=True).encode("utf-8")


