@router.message(OwnerFilter(), Form.wait_tls_certificate)
async def on_tls_certificate_input(message: Message, state: FSMContext):
    form_data = await state.get_data()
    await state.clear()
    target = str(form_data.get("authorization_target") or "")
    if (not target or target == "all" or SESSION.get("target") != target
            or not _pending_device_input_still_allowed(message, form_data, target)):
        await _reject_revoked_device_input(message)
        return
    parsed = _parse_tls_certificate_input(message.text or "")
    try:
        await message.delete()
    except Exception:
        pass
    if parsed is None:
        await _replace_user_card(message, "Введи один hostname/IP и необязательный порт — без URL, пути и списка.",
                                 reply_markup=back_to_device_kb())
        return
    record = devices.get(target) or {}
    if _device_declares_command(record, "tls_certificate") is not True:
        await _replace_user_card(message, "Агент больше не объявляет TLS-проверку; запрос не отправлен.",
                                 reply_markup=back_to_device_kb())
        return
    sent, command_id = publish_tracked("tls_certificate", _target=target, **parsed)
    if not sent:
        await _replace_user_card(message, _lex("mqtt_disconnected"), reply_markup=back_to_device_kb())
        return
    await _replace_user_card(message, "🔐 Выполняю TLS handshake и проверяю сертификат выбранного адреса…",
                             reply_markup=back_to_device_kb())
    result = await tls_certificate_collector.wait_for(target, "tls_certificate", 8.0, command_id)
    if not _pending_device_input_still_allowed(message, form_data, target):
        await _replace_user_card(message, _lex("action_result_hidden_after_revoke"), reply_markup=back_to_device_kb())
        return
    values = _validated_tls_certificate(result, target=target, command_id=command_id,
                                         host=parsed["host"], port=parsed["port"])
    if values is None:
        body = "⏳ Нет подтверждённого свежего ответа; состояние сертификата неизвестно."
    elif values["state"] == "valid":
        cert = values["data"]
        body = (f"🔐 <b>Цепочка доверия подтверждена</b>\n"
                f"Адрес: <code>{html.escape(parsed['host'])}:{parsed['port']}</code>\n"
                f"Действует до: <code>{html.escape(cert['not_after'])}</code>\n"
                f"SHA-256: <code>{cert['sha256']}</code>")
    elif values["state"] == "expired":
        body = ("🔐 <b>Сертификат истёк</b>\n" +
                (f"Срок закончился: <code>{html.escape(values['data']['not_after'])}</code>" if values["data"] else "Дата сертификата недоступна."))
    elif values["state"] == "not_yet_valid":
        body = ("🔐 <b>Срок сертификата ещё не начался</b>\n" +
                (f"Начало: <code>{html.escape(values['data']['not_before'])}</code>" if values["data"] else "Дата сертификата недоступна."))
    elif values["state"] == "chain_invalid":
        body = "🔐 <b>Сертификат не прошёл проверку цепочки доверия или имени</b>. Не считай соединение доверенным."
    elif values["state"] == "invalid_request":
        body = "⚠️ Агент отклонил адрес проверки."
    else:
        body = "🔐 <b>Проверка TLS не дала подтверждённого результата</b>; состояние неизвестно."
    await _replace_user_card(message, body, reply_markup=back_to_device_kb())


