@router.message(OwnerFilter(), Form.wait_network_check_set_name)
async def on_network_check_set_name(message: Message, state: FSMContext):
    form_data = await state.get_data()
    target = str(form_data.get("authorization_target") or "")
    if (not target or SESSION.get("target") != target
            or not _pending_device_input_still_allowed(message, form_data, target)):
        await state.clear()
        await _reject_revoked_device_input(message)
        return
    name = " ".join((message.text or "").split())
    try:
        DeviceStore._normalize_network_check_set_name(name)
    except ValueError:
        await _replace_user_card(message, "Название должно содержать от 1 до 40 печатных символов.",
                                 reply_markup=back_to_device_kb())
        return
    await state.set_state(Form.wait_network_check_set_endpoints)
    await state.update_data(network_check_set_name=name)
    try:
        await message.delete()
    except Exception:
        pass
    await _replace_user_card(
        message,
        "Пришли 1–5 адресов, каждый с новой строки:\n<code>tcp host:port</code> или <code>tls host:port</code>.\n"
        "Пример: <code>tcp 192.168.1.1:22</code>. Только отдельные цели — URL, диапазоны и списки портов запрещены.",
        reply_markup=back_to_device_kb(),
    )


@router.message(OwnerFilter(), Form.wait_network_check_set_endpoints)
async def on_network_check_set_endpoints(message: Message, state: FSMContext):
    form_data = await state.get_data()
    await state.clear()
    target = str(form_data.get("authorization_target") or "")
    if (not target or SESSION.get("target") != target
            or not _pending_device_input_still_allowed(message, form_data, target)):
        await _reject_revoked_device_input(message)
        return
    lines = [line.strip() for line in (message.text or "").splitlines() if line.strip()]
    parsed = [_parse_service_probe_input(line) for line in lines]
    try:
        if not 1 <= len(lines) <= 5 or any(item is None for item in parsed):
            raise ValueError("invalid endpoint list")
        saved = devices.save_network_check_set(
            message.from_user.id, ADMIN_ID, str(form_data.get("network_check_set_name") or ""), parsed,
        )
    except ValueError:
        await _replace_user_card(message, "Набор не сохранён: проверь формат и число целей (1–5).", reply_markup=back_to_device_kb())
        return
    try:
        await message.delete()
    except Exception:
        pass
    if saved is None:
        await _replace_user_card(message, "Набор не сохранён: требуется владелец.", reply_markup=back_to_device_kb())
        return
    audit("network.check_set.created", actor_id=message.from_user.id, set_id=saved["set_id"], endpoint_count=len(saved["endpoints"]))
    await _replace_user_card(message, f"✅ Набор <b>{html.escape(saved['name'])}</b> сохранён: {len(saved['endpoints'])} целей.",
                             reply_markup=_network_check_sets_keyboard(message.from_user.id,
                                                                      devices.list_network_check_sets(message.from_user.id, ADMIN_ID)))


@router.callback_query(OwnerFilter(), F.data.startswith("network-set:delete:"))
async def on_network_check_set_delete(cq: CallbackQuery):
    match = re.fullmatch(r"network-set:delete:([a-f0-9]{32})", str(cq.data or ""))
    if match is None:
        await cq.answer("Набор не найден.", show_alert=True)
        return
    target = str(SESSION.get("target") or "")
    if not target or not await _callback_result_access_or_report(cq, target):
        return
    record = devices.get_network_check_set(cq.from_user.id, ADMIN_ID, match.group(1))
    if record is None:
        await cq.answer("Набор уже удалён или недоступен.", show_alert=True)
        return
    if not devices.delete_network_check_set(cq.from_user.id, ADMIN_ID, match.group(1)):
        await cq.answer("Не получилось удалить набор.", show_alert=True)
        return
    audit("network.check_set.deleted", actor_id=cq.from_user.id, set_id=match.group(1), endpoint_count=len(record["endpoints"]))
    rows = devices.list_network_check_sets(cq.from_user.id, ADMIN_ID)
    await _replace_callback_message(cq, "🗑 Набор удалён.", reply_markup=_network_check_sets_keyboard(cq.from_user.id, rows))
    await cq.answer()


@router.callback_query(OwnerFilter(), F.data.startswith("network-set:run:"))
async def on_network_check_set_run(cq: CallbackQuery):
    match = re.fullmatch(r"network-set:run:([a-f0-9]{32})", str(cq.data or ""))
    if match is None:
        await cq.answer("Набор не найден.", show_alert=True)
        return
    target = str(SESSION.get("target") or "")
    if not target or target == "all" or not await _callback_result_access_or_report(cq, target):
        return
    record = devices.get_network_check_set(cq.from_user.id, ADMIN_ID, match.group(1))
    if record is None:
        await cq.answer("Набор удалён или содержит повреждённые данные.", show_alert=True)
        return
    info = devices.get(target) or {}
    if _device_declares_command(info, "service_probe") is not True:
        await _replace_callback_message(cq, "Агент не объявляет поддержку проверки сервисов; запросы не отправлены.",
                                        reply_markup=back_to_device_kb())
        await cq.answer("Нужен совместимый агент.", show_alert=True)
        return
    requests = []
    for endpoint in record["endpoints"]:
        if not await _callback_result_access_or_report(cq, target):
            return
        sent, command_id = publish_tracked("service_probe", _target=target, **endpoint)
        if not sent:
            await _replace_callback_message(cq, _lex("mqtt_disconnected"), reply_markup=back_to_device_kb())
            return
        requests.append((endpoint, command_id))
    await _replace_callback_message(cq, f"🌐 Запускаю {len(requests)} выбранных проверок набора <b>{html.escape(record['name'])}</b>…",
                                    reply_markup=back_to_device_kb())

    async def wait_result(endpoint, command_id):
        try:
            raw = await service_probe_collector.wait_for(target, "service_probe", 8.0, command_id)
        except Exception:
            raw = None
        return _validated_service_probe(raw, target=target, command_id=command_id, **endpoint)

    results = await asyncio.gather(*(wait_result(endpoint, command_id) for endpoint, command_id in requests))
    if not await _callback_result_access_or_report(cq, target, published=True):
        return
    lines = []
    for endpoint, result in zip(record["endpoints"], results, strict=True):
        where = f"{html.escape(endpoint['host'])}:{endpoint['port']} ({endpoint['protocol'].upper()})"
        if result is None:
            status = "нет свежего подтверждённого ответа"
        else:
            status = {
                "reachable": "доступен, проверка успешна",
                "reachable_untrusted": "TCP доступен, TLS-проверка не пройдена",
                "unreachable": "соединение отклонено",
                "invalid_request": "агент отклонил запрос",
                "unknown": "состояние неизвестно",
            }.get(result["state"], "состояние неизвестно")
        lines.append(f"• <code>{where}</code> — {status}")
    await _replace_callback_message(cq, f"🌐 <b>{html.escape(record['name'])}</b>\n" + "\n".join(lines),
                                    reply_markup=_network_check_sets_keyboard(cq.from_user.id,
                                                                             devices.list_network_check_sets(cq.from_user.id, ADMIN_ID)))
    audit("network.check_set.ran", actor_id=cq.from_user.id, set_id=record["set_id"], endpoint_count=len(requests))
    await cq.answer()


@router.callback_query(OwnerFilter(), F.data == "cmd:wifi_quality_history")
async def on_cmd_wifi_quality_history(cq: CallbackQuery):
    target = str(SESSION.get("target") or "")
    if not target or target == "all":
        await cq.answer(_lex("single_device_only"), show_alert=True)
        return
    if not await _callback_result_access_or_report(cq, target):
        return
    info = devices.get(target) or {}
    if _device_declares_command(info, "wifi_quality_history") is not True:
        await _replace_callback_message(cq, "Устройство не сообщает поддержку тренда Wi-Fi; запрос не отправлен.",
                                        reply_markup=back_to_device_kb())
        await cq.answer("Нужен совместимый агент.", show_alert=True)
        return
    sent, command_id = publish_tracked("wifi_quality_history", _target=target)
    if not sent:
        await _replace_callback_message(cq, _lex("mqtt_disconnected"), reply_markup=back_to_device_kb())
        return
    await _replace_callback_message(cq, "📶 Снимаю один замер качества Wi-Fi…", reply_markup=back_to_device_kb())
    result = await wifi_quality_history_collector.wait_for(target, "wifi_quality_history", 8.0, command_id)
    if not await _callback_result_access_or_report(cq, target):
        return
    values = _validated_wifi_quality_history(result, target=target, command_id=command_id)
    if values is None:
        body = "⏳ Нет подтверждённого свежего замера; состояние сигнала неизвестно."
    elif values["state"] == "unsupported":
        body = "📶 ОС не предоставляет сигнал Wi-Fi для этого подключения; замер в историю не добавлен."
    elif values["state"] == "unknown":
        body = "📶 Замер не подтвердился; в историю добавляются только реальные значения сигнала."
    else:
        captured_at = int(datetime.datetime.fromisoformat(values["checked_at"]).timestamp())
        sample = {"captured_at": captured_at, "source": values["source"],
                  "metric": values["metric"], "value": values["value"]}
        try:
            saved = devices.record_wifi_quality_sample(cq.from_user.id, ADMIN_ID, target, sample)
            rows = devices.list_wifi_quality_samples(cq.from_user.id, ADMIN_ID, target) or []
        except (ValueError, OSError):
            saved, rows = None, []
        if saved is None:
            body = "📶 Замер получен, но запись в историю не подтверждена."
        else:
            same_metric = [row for row in rows if row["source"] == values["source"] and row["metric"] == values["metric"]][-8:]
            unit = "%" if values["metric"] == "signal_percent" else " dBm"
            sequence = " → ".join(f"{row['value']}{unit}" for row in same_metric)
            heading = "Уровень сигнала" if unit == "%" else "RSSI"
            body = (f"📈 <b>Тренд Wi-Fi · {heading}</b>\n"
                    f"Новый замер: <code>{values['value']}{unit}</code>\n"
                    f"История: <code>{sequence}</code>\n"
                    f"Записано значений: {len(rows)} (хранится до 60).\n"
                    "Снимается только по нажатию владельца; SSID и пароли не сохраняются.")
    await _replace_callback_message(cq, body, reply_markup=back_to_device_kb())
    await cq.answer()


