@router.callback_query(OwnerFilter(), F.data == "cmd:path_diagnostic")
async def on_cmd_path_diagnostic(cq: CallbackQuery):
    """Run the existing bounded probes together and summarize only confirmed evidence."""
    target = str(SESSION.get("target") or "")
    if not target or target == "all":
        await cq.answer(_lex("single_device_only"), show_alert=True)
        return
    if not await _callback_result_access_or_report(cq, target):
        return
    info = devices.get(target) or {}
    required = ("gateway_probe", "dns_resolution", "route_trace", "endpoint_batch")
    if any(_device_declares_command(info, command) is not True for command in required):
        await _replace_callback_message(
            cq, "Агент не объявляет поддержку всех четырёх проверок; ничего не отправлено. Обнови агент и повтори.",
            reply_markup=back_to_device_kb(),
        )
        await cq.answer("Нужна совместимая версия агента.", show_alert=True)
        return
    os_name = str(info.get("os") or "").lower()
    platform = "macos" if "mac" in os_name or "darwin" in os_name else "windows" if "win" in os_name else None
    if platform is None:
        await _replace_callback_message(cq, "Не удалось определить платформу устройства; запросы не отправлены.",
                                        reply_markup=back_to_device_kb())
        return

    tracked = []

    def track(sent, command_id, command, collector, timeout):
        if not sent:
            return False
        tracked.append((command, command_id, collector, timeout))
        return True

    if not track(*publish_tracked("gateway_probe", _target=target), "gateway_probe", gateway_probe_collector, 9.0):
        await _replace_callback_message(cq, _lex("mqtt_disconnected"), reply_markup=back_to_device_kb())
        return
    if not track(*publish_tracked("dns_resolution", _target=target, hostname="example.com", expected_addresses=None),
                 "dns_resolution", dns_resolution_collector, 9.0):
        await _replace_callback_message(cq, _lex("mqtt_disconnected"), reply_markup=back_to_device_kb())
        return
    if not track(*publish_tracked("route_trace", _target=target, target="1.1.1.1"),
                 "route_trace", route_trace_collector, 18.0):
        await _replace_callback_message(cq, _lex("mqtt_disconnected"), reply_markup=back_to_device_kb())
        return
    if not track(*publish_tracked("endpoint_batch", _target=target),
                 "endpoint_batch", endpoint_batch_collector, 12.0):
        await _replace_callback_message(cq, _lex("mqtt_disconnected"), reply_markup=back_to_device_kb())
        return

    await _replace_callback_message(
        cq, "🧭 Проверяю шлюз, системный DNS, ограниченную трассу и три фиксированных TCP-endpoint…",
        reply_markup=back_to_device_kb(),
    )

    async def wait_one(command, command_id, collector, timeout):
        try:
            return await collector.wait_for(target, command, timeout, command_id)
        except Exception:
            return None

    raw = await asyncio.gather(*(wait_one(*entry) for entry in tracked))
    if not await _callback_result_access_or_report(cq, target, published=True):
        return
    ids = {command: command_id for command, command_id, _collector, _timeout in tracked}
    by_command = dict(zip((entry[0] for entry in tracked), raw, strict=True))
    gateway = _validated_gateway_probe(by_command.get("gateway_probe"), target=target,
                                       command_id=ids["gateway_probe"])
    dns = _validated_dns_resolution(by_command.get("dns_resolution"), target=target,
                                    command_id=ids["dns_resolution"], hostname="example.com",
                                    expected_addresses=None)
    route = _validated_route_trace(by_command.get("route_trace"), target=target,
                                   command_id=ids["route_trace"], requested_target="1.1.1.1",
                                   platform=platform)
    endpoints = _validated_endpoint_batch(by_command.get("endpoint_batch"), target=target,
                                          command_id=ids["endpoint_batch"])
    body = _format_path_diagnostic(gateway=gateway, dns=dns, route=route, endpoints=endpoints)
    checked_at = datetime.datetime.now(datetime.timezone.utc).isoformat()
    export_payload = _build_network_path_report_json(
        device_id=target, checked_at=checked_at, gateway=gateway, dns=dns, route=route, endpoints=endpoints,
    )
    now = time.monotonic()
    for old_token, entry in list(_NETWORK_PATH_REPORT_EXPORTS.items()):
        if entry.get("expires_at", 0) <= now:
            _NETWORK_PATH_REPORT_EXPORTS.pop(old_token, None)
    while len(_NETWORK_PATH_REPORT_EXPORTS) >= 128:
        _NETWORK_PATH_REPORT_EXPORTS.pop(next(iter(_NETWORK_PATH_REPORT_EXPORTS)))
    export_token = uuid.uuid4().hex[:16]
    _NETWORK_PATH_REPORT_EXPORTS[export_token] = {
        "owner_id": int(cq.from_user.id), "device_id": target,
        "chat_id": int(cq.message.chat.id), "message_id": int(cq.message.message_id),
        "expires_at": now + _NETWORK_PATH_REPORT_EXPORT_TTL, "payload": export_payload,
        "checked_at": checked_at,
    }
    await _replace_callback_message(cq, body, reply_markup=_network_path_report_keyboard(export_token))
    await cq.answer()


@router.callback_query(OwnerFilter(), F.data.startswith("network-report:export:"))
async def on_network_path_report_export(cq: CallbackQuery):
    match = re.fullmatch(r"network-report:export:([a-f0-9]{16})", str(cq.data or ""))
    if match is None:
        await cq.answer("Кнопка экспорта повреждена или устарела.", show_alert=True)
        return
    token = match.group(1)
    entry = _NETWORK_PATH_REPORT_EXPORTS.get(token)
    if not isinstance(entry, dict):
        await cq.answer("Отчёт уже выгружен или истёк. Запусти диагностику заново.", show_alert=True)
        return
    target = str(entry.get("device_id") or "")
    user_id = int(cq.from_user.id)
    if (user_id != entry.get("owner_id") or SESSION.get("target") != target
            or int(cq.message.chat.id) != entry.get("chat_id")
            or int(cq.message.message_id) != entry.get("message_id")
            or entry.get("expires_at", 0) <= time.monotonic()):
        _NETWORK_PATH_REPORT_EXPORTS.pop(token, None)
        await cq.answer("Отчёт привязан к другой карточке или истёк. Запусти проверку заново.", show_alert=True)
        return
    if not await _callback_result_access_or_report(cq, target):
        return
    _NETWORK_PATH_REPORT_EXPORTS.pop(token, None)
    stamp = str(entry.get("checked_at") or "").replace(":", "").replace("+", "-")[:24]
    await _replace_callback_with_media(
        cq, bot.send_document,
        document=BufferedInputFile(entry["payload"], filename=f"xider-network-report-{stamp}.json"),
        caption="📄 Редактируемый JSON-отчёт. В него входят только состояния проверок — без Wi-Fi-ключей, cookie, токенов и IP-адресов из результатов.",
        reply_markup=back_to_device_kb(),
    )
    audit("network.path_report.exported", actor_id=user_id, device_id=target)
    await cq.answer()


