@router.message(OwnerFilter(), Form.wait_dnssec_check)
async def on_dnssec_check_input(message: Message, state: FSMContext):
    form_data = await state.get_data()
    await state.clear()
    target = str(form_data.get("authorization_target") or "")
    if (not target or target == "all" or form_data.get("authorization_callback") != "cmd:dnssec_check"
            or not _pending_device_input_still_allowed(message, form_data, target)):
        await _reject_revoked_device_input(message)
        return
    parsed = _parse_dnssec_check_input(message.text or "")
    if parsed is None:
        await _replace_user_card(message, "Формат: `домен | IP настроенного DNS-сервера`; пример: `example.com | 1.1.1.1`.",
                                 reply_markup=back_to_device_kb())
        return
    if _device_declares_command(devices.get(target) or {}, "dnssec_check") is not True:
        await _replace_user_card(message, "Агент больше не объявляет поддержку DNSSEC; запрос не отправлен.",
                                 reply_markup=back_to_device_kb())
        return
    sent, command_id = publish_tracked("dnssec_check", _target=target, **parsed)
    if not sent:
        await _replace_user_card(message, _lex("mqtt_disconnected"), reply_markup=back_to_device_kb())
        return
    await _replace_user_card(message, "🧭 Проверяю один домен через его настроенный DNS-resolver…",
                             reply_markup=back_to_device_kb())
    result = await dnssec_check_collector.wait_for(target, "dnssec_check", 9.0, command_id)
    if not _pending_device_input_still_allowed(message, form_data, target):
        await _replace_user_card(message, _lex("action_result_hidden_after_revoke"), reply_markup=back_to_device_kb())
        return
    values = _validated_dnssec_check(result, target=target, command_id=command_id,
                                     hostname=parsed["hostname"], resolver=parsed["resolver"])
    if values is None or values["state"] == "unknown":
        body = "⏳ DNSSEC не подтверждён: нет свежего ответа от агента или резолвера."
    elif values["state"] == "invalid_request":
        body = "⚠️ Этот DNS-resolver не совпадает с DNS-настройками устройства или запрос отклонён."
    elif values["state"] == "validated_by_resolver":
        body = f"✅ {parsed['hostname']}: выбранный resolver вернул AD=1 ({values['rcode']}). Это его подтверждение DNSSEC, не самостоятельная криптопроверка клиента."
    else:
        body = f"❔ {parsed['hostname']}: AD=0 ({values['rcode']}); DNSSEC не подтверждён. Это не доказывает, что домен неисправен."
    await _replace_user_card(message, body, reply_markup=back_to_device_kb())


def _network_traffic_device_tag(device_id: str) -> str:
    return hashlib.sha256(str(device_id).encode("utf-8")).hexdigest()[:12]


def _network_traffic_markup(device_id: str, *, interfaces=None, interface_id: str | None = None):
    tag = _network_traffic_device_tag(device_id)
    rows = []
    if isinstance(interfaces, list):
        for item in interfaces[:32]:
            label = str(item["label"])[:32]
            rows.append([InlineKeyboardButton(
                text=label, callback_data=f"traffic:sample:{tag}:{item['interface_id']}",
            )])
    elif interface_id is not None:
        rows.append([InlineKeyboardButton(
            text="📊 Замерить ещё раз", callback_data=f"traffic:sample:{tag}:{interface_id}",
        )])
        rows.append([InlineKeyboardButton(
            text=feature_catalog.button_text("traffic_threshold"), callback_data=f"traffic:alert-menu:{tag}:{interface_id}",
        )])
        rows.append([InlineKeyboardButton(
            text="🧾 Хронология online/offline", callback_data=f"traffic:status-menu:{tag}:{interface_id}",
        )])
    rows.extend(back_to_device_kb().inline_keyboard)
    return InlineKeyboardMarkup(inline_keyboard=rows)


async def _run_network_traffic(cq: CallbackQuery, *, interface_id: str | None = None) -> None:
    target = str(SESSION.get("target") or "")
    if not target or target == "all":
        await cq.answer(_lex("single_device_only"), show_alert=True)
        return
    if not await _callback_result_access_or_report(cq, target):
        return
    info = devices.get(target) or {}
    if _device_declares_command(info, "network_traffic") is not True:
        await _replace_callback_message(cq, "Устройство не подтвердило поддержку замеров трафика; команда не отправлена.",
                                        reply_markup=back_to_device_kb())
        await cq.answer("Нужен совместимый агент.", show_alert=True)
        return
    kwargs = {"_target": target}
    if interface_id is not None:
        kwargs["interface_id"] = interface_id
    sent, command_id = publish_tracked("network_traffic", **kwargs)
    if not sent:
        await _replace_callback_message(cq, _lex("mqtt_disconnected"), reply_markup=back_to_device_kb())
        return
    pending = "📡 Запрашиваю список локальных сетевых адаптеров…" if interface_id is None else "📊 Снимаю счётчики выбранного адаптера…"
    await _replace_callback_message(cq, pending, reply_markup=back_to_device_kb())
    result = await network_traffic_collector.wait_for(target, "network_traffic", 8.0, command_id)
    if not await _callback_result_access_or_report(cq, target):
        return
    mode = "catalog" if interface_id is None else "sample"
    values = _validated_network_traffic(result, target=target, command_id=command_id, mode=mode)
    if values is None:
        await _replace_callback_message(cq, "⏳ Нет свежего подтверждённого ответа; состояние счётчиков неизвестно.",
                                        reply_markup=back_to_device_kb())
        await cq.answer()
        return
    if mode == "catalog":
        if values["state"] != "available":
            body = "📡 Список интерфейсов недоступен; корректные счётчики получить не удалось."
            markup = back_to_device_kb()
        else:
            body = ("📊 <b>Выбери сетевой адаптер</b>\n"
                    "Дальше будет разовый базовый замер; для дельты нажми повторный замер. "
                    "Фонового опроса нет.")
            markup = _network_traffic_markup(target, interfaces=values["interfaces"])
        await _replace_callback_message(cq, body, reply_markup=markup)
        await cq.answer()
        return
    if values["interface_id"] != interface_id:
        await _replace_callback_message(cq, "Ответ относится к другому адаптеру; показания не сохранены.",
                                        reply_markup=back_to_device_kb())
        await cq.answer()
        return
    if values["state"] != "available":
        await _replace_callback_message(cq, "Счётчики выбранного адаптера сейчас неизвестны.",
                                        reply_markup=_network_traffic_markup(target, interface_id=interface_id))
        await cq.answer()
        return
    try:
        sampled_at = datetime.datetime.fromisoformat(values["sampled_at"].replace("Z", "+00:00"))
        sample_time = int(sampled_at.timestamp())
        comparison = devices.record_network_traffic_sample(
            target, interface_id, values["label"], sent_bytes=values["sent_bytes"],
            received_bytes=values["received_bytes"], sampled_at=sample_time,
        )
    except (AttributeError, TypeError, ValueError, OverflowError, OSError):
        comparison = {"state": "unknown"}
    label = html.escape(values["label"])
    if comparison.get("state") == "delta":
        body = (f"📊 <b>Трафик адаптера: {label}</b>\n"
                f"Отправлено: <code>+{comparison['sent_delta']} байт</code>\n"
                f"Получено: <code>+{comparison['received_delta']} байт</code>\n"
                f"Интервал: <code>{comparison['elapsed_seconds']} с</code>\n"
                "Разница между двумя ручными замерами; не фоновый мониторинг.")
    elif comparison.get("state") == "counter_reset":
        body = f"📊 <b>{label}</b>\nСчётчик ОС сбросился или интерфейс переинициализировался. Это новый базовый замер; дельта пока неизвестна."
    elif comparison.get("state") == "baseline":
        body = f"📊 <b>{label}</b>\nБазовый замер сохранён. Нажми «Замерить ещё раз», чтобы получить дельту между двумя ручными замерами."
    else:
        body = f"📊 <b>{label}</b>\nДельта неизвестна: нет двух последовательных свежих замеров."
    await _replace_callback_message(
        cq, body, reply_markup=_network_traffic_markup(target, interface_id=interface_id),
    )
    await cq.answer()


