def _validated_interface_status_history(result: object, *, target: str, command_id: str, mode: str,
                                        interface_id: str):
    if not isinstance(result, dict):
        return None
    expected = {"type", "schema", "feature_id", "device_id", "request_id", "source", "mode", "state",
                "interface_id", "interval_seconds", "interfaces", "events", "checked_at", "detail"}
    if (set(result) != expected or result.get("type") != "interface_status_history"
            or result.get("schema") != "xider.interface-status-history.v1"
            or result.get("feature_id") != "D04-F20" or result.get("device_id") != target
            or result.get("request_id") != command_id or result.get("mode") != mode
            or result.get("interface_id") != interface_id):
        return None
    allowed_sources = {"windows_psutil_interface_status", "macos_psutil_interface_status"}
    if result.get("source") not in allowed_sources:
        return None
    try:
        checked = datetime.datetime.fromisoformat(str(result.get("checked_at", "")).replace("Z", "+00:00"))
    except ValueError:
        return None
    now = datetime.datetime.now(datetime.timezone.utc)
    if checked.tzinfo is None or checked > now + datetime.timedelta(seconds=60) or now - checked > datetime.timedelta(minutes=2):
        return None
    state, interval, interfaces, events, detail = (
        result.get("state"), result.get("interval_seconds"), result.get("interfaces"),
        result.get("events"), result.get("detail"),
    )
    if state not in {"available", "unsupported", "unknown", "monitoring"}:
        return None
    if type(interval) is not int or interval not in {0, 60, 300, 900}:
        return None
    if not isinstance(interfaces, list) or len(interfaces) > 32 or not isinstance(events, list) or len(events) > 120:
        return None
    parsed_events = []
    previous = ""
    for event in events:
        if (not isinstance(event, dict) or set(event) != {"at", "state", "kind"}
                or event.get("state") not in {"online", "offline"}
                or event.get("kind") not in {"baseline", "transition"}):
            return None
        try:
            stamp = datetime.datetime.fromisoformat(str(event.get("at", "")).replace("Z", "+00:00"))
        except ValueError:
            return None
        if stamp.tzinfo is None or stamp > checked + datetime.timedelta(seconds=60):
            return None
        normalized = stamp.astimezone(datetime.timezone.utc).isoformat(timespec="seconds").replace("+00:00", "Z")
        if normalized < previous:
            return None
        previous = normalized
        parsed_events.append({"at": normalized, "state": event["state"], "kind": event["kind"]})
    if detail not in {None, "status_source_unavailable", "no_interfaces", "invalid_interface",
                      "interface_not_found", "no_observed_transitions", "initial_state_unknown",
                      "monitor_configuration_failed", "invalid_request"}:
        return None
    if state == "monitoring" and (mode != "start" or interval not in {60, 300, 900}):
        return None
    return {"state": state, "interval_seconds": interval, "events": parsed_events, "detail": detail}


def _interface_status_history_markup(device_id: str, interface_id: str):
    tag = _network_traffic_device_tag(device_id)
    kb = InlineKeyboardBuilder()
    for interval, label in ((60, "1 мин"), (300, "5 мин"), (900, "15 мин")):
        kb.button(text=f"▶ Следить · {label}", callback_data=f"traffic:status:start:{tag}:{interface_id}:{interval}")
    kb.button(text="🧾 Показать хронологию", callback_data=f"traffic:status:read:{tag}:{interface_id}:0")
    kb.button(text="⏹ Остановить наблюдение", callback_data=f"traffic:status:stop:{tag}:{interface_id}:0")
    kb.button(text=_nav("back_device"), callback_data="back:device")
    kb.adjust(1)
    return kb.as_markup()


@router.callback_query(OwnerFilter(), F.data.startswith("traffic:status-"))
@router.callback_query(OwnerFilter(), F.data.startswith("traffic:status:"))
async def on_interface_status_history(cq: CallbackQuery):
    parts = str(cq.data or "").split(":")
    target = str(SESSION.get("target") or "")
    if (len(parts) not in {4, 6} or not target or target == "all"
            or _network_traffic_device_tag(target) != (parts[2] if len(parts) == 4 else parts[3])):
        await cq.answer("Кнопка устарела или относится к другому устройству.", show_alert=True)
        return
    menu = len(parts) == 4 and parts[1] == "status-menu"
    if menu:
        interface_id = parts[3]
        mode, interval = "menu", 0
    else:
        if len(parts) != 6 or parts[1] != "status" or parts[2] not in {"start", "read", "stop"}:
            await cq.answer("Некорректная команда хронологии.", show_alert=True)
            return
        mode, interface_id = parts[2], parts[4]
        try:
            interval = int(parts[5])
        except ValueError:
            interval = -1
        if re.fullmatch(r"[0-9a-f]{20}", interface_id) is None:
            await cq.answer("Некорректный сетевой адаптер.", show_alert=True)
            return
    if not await _callback_result_access_or_report(cq, target):
        return
    callback = str(cq.data or "")
    if not _device_action_still_allowed(int(cq.from_user.id), callback, target):
        await cq.answer(_lex("input_access_revoked"), show_alert=True)
        return
    if menu:
        await _replace_callback_message(
            cq,
            "🧾 <b>Хронология состояния адаптера</b>\n"
            "Явное наблюдение выбранного адаптера: только подтверждённые переходы online/offline, "
            "без IP/MAC/имени Wi‑Fi. Интервал — 1, 5 или 15 минут; наблюдение само остановится через 6 часов.",
            reply_markup=_interface_status_history_markup(target, interface_id),
        )
        await cq.answer()
        return
    if ((mode == "start" and interval not in {60, 300, 900})
            or (mode in {"read", "stop"} and interval != 0)):
        await cq.answer("Интервал не разрешён.", show_alert=True)
        return
    info = devices.get(target) or {}
    if _device_declares_command(info, "interface_status_history") is not True:
        await _replace_callback_message(cq, "Агент не подтвердил поддержку истории состояний; запрос не отправлен.",
                                        reply_markup=back_to_device_kb())
        await cq.answer("Нужен обновлённый агент.", show_alert=True)
        return
    sent, command_id = publish_tracked(
        "interface_status_history", _target=target, mode=mode,
        interface_id=interface_id, interval_seconds=interval,
    )
    if not sent:
        await _replace_callback_message(cq, _lex("mqtt_disconnected"), reply_markup=back_to_device_kb())
        return
    pending = {"start": "⏳ Включаю ограниченное наблюдение…", "read": "⏳ Читаю локальную хронологию…",
               "stop": "⏳ Останавливаю наблюдение и читаю сохранённые события…"}[mode]
    await _replace_callback_message(cq, pending, reply_markup=back_to_device_kb())
    result = await interface_status_history_collector.wait_for(target, "interface_status_history", 8.0, command_id)
    if not await _callback_result_access_or_report(cq, target):
        return
    values = _validated_interface_status_history(
        result, target=target, command_id=command_id, mode=mode, interface_id=interface_id,
    )
    if values is None:
        body = "⏳ Свежий подтверждённый ответ не получен; состояние неизвестно."
    elif values["state"] == "unknown":
        body = "📶 Состояние интерфейса неизвестно; неподтверждённые данные не добавлены."
    elif values["state"] == "unsupported":
        body = "📶 История пока пуста или ОС не предоставила подтверждённые состояния."
    else:
        lines = [f"• <code>{event['at']}</code> — "
                 f"{'исходное состояние' if event['kind'] == 'baseline' else 'переход'}: "
                 f"{'online' if event['state'] == 'online' else 'offline'}"
                 for event in values["events"]]
        header = (f"Наблюдение включено · шаг {values['interval_seconds']} с · максимум 6 часов"
                  if values["state"] == "monitoring" else "Наблюдение остановлено" if mode == "stop" else "Сохранённые переходы")
        body = "🧾 <b>Хронология интерфейса</b>\n" + header
        body += "\n" + "\n".join(lines) if lines else "\nПока нет подтверждённых переходов."
        body += "\nOnline/offline здесь — link-state адаптера по ОС, не проверка доступа в интернет. "
        body += "Хранятся только время и состояние; имена сетей и адреса не сохраняются."
    await _replace_callback_message(cq, body, reply_markup=_interface_status_history_markup(target, interface_id))
    await cq.answer()


def _network_traffic_alert_markup(device_id: str, interface_id: str, *, enabled: bool = False):
    tag = _network_traffic_device_tag(device_id)
    kb = InlineKeyboardBuilder()
    for threshold, key, title in ((100_000_000, "100m", "100 МБ"),
                                  (500_000_000, "500m", "500 МБ"),
                                  (1_000_000_000, "1g", "1 ГБ"),
                                  (5_000_000_000, "5g", "5 ГБ")):
        for interval, every in ((900, "15 мин"), (1800, "30 мин"), (3600, "60 мин")):
            kb.button(text=f"{title} · {every}", callback_data=(
                f"traffic:alert-set:{tag}:{interface_id}:{key}:{interval}"
            ))
    if enabled:
        kb.button(text=f"⏹ {_nav('cancel')}", callback_data=f"traffic:alert-off:{tag}:{interface_id}")
    kb.button(text=_nav("back_device"), callback_data="back:device")
    kb.adjust(2)
    return kb.as_markup()


async def _show_network_traffic_alert_menu(cq: CallbackQuery, *, target: str, interface_id: str):
    if not await _callback_result_access_or_report(cq, target):
        return
    info = devices.get(target) or {}
    if _device_declares_command(info, "network_traffic_interval") is not True:
        await _replace_callback_message(
            cq, "Агент не подтвердил поддержку пороговых уведомлений. Ничего не включено.",
            reply_markup=back_to_device_kb(),
        )
        await cq.answer("Нужна поддерживаемая версия агента.", show_alert=True)
        return
    cached = devices.get_network_traffic_sample(target, interface_id)
    alert = devices.get_network_traffic_alert(target)
    if cached is None and not (alert.get("interface_id") == interface_id and alert.get("label")):
        await _replace_callback_message(
            cq, "Сначала сделай один ручной замер этого адаптера — тогда подпишем мониторинг на точный интерфейс.",
            reply_markup=back_to_device_kb(),
        )
        await cq.answer()
        return
    label = html.escape(str(alert.get("label") if alert.get("interface_id") == interface_id
                            else cached["label"]))
    interval_label = {900: "15 минут", 1800: "30 минут", 3600: "60 минут"}.get(
        alert.get("interval_seconds"), "не задан"
    )
    threshold_label = {100_000_000: "100 МБ", 500_000_000: "500 МБ",
                       1_000_000_000: "1 ГБ", 5_000_000_000: "5 ГБ"}.get(
        alert.get("threshold_bytes"), "не задан"
    )
    body = (f"🔔 <b>Порог трафика · {label}</b>\n"
            f"Сейчас: {'включён' if alert.get('enabled') and alert.get('interface_id') == interface_id else 'выключен'}\n"
            "Выбери порог накопленного входящего + исходящего трафика и частоту замера. "
            "Это включает явный мониторинг выбранного интерфейса; уведомление придёт только владельцу.")
    if alert.get("interface_id") == interface_id:
        body += f"\nТекущие параметры: <b>{threshold_label}</b>, проверка каждые <b>{interval_label}</b>."
    await _replace_callback_message(
        cq, body,
        reply_markup=_network_traffic_alert_markup(
            target, interface_id, enabled=bool(alert.get("enabled") and alert.get("interface_id") == interface_id),
        ),
    )
    await cq.answer()


async def _configure_network_traffic_alert(
    cq: CallbackQuery, *, target: str, interface_id: str,
    interval_seconds: int, threshold_bytes: int,
) -> None:
    callback = str(cq.data or "")
    if not target or target == "all" or not await _callback_result_access_or_report(cq, target):
        return
    if not _device_action_still_allowed(int(cq.from_user.id), callback, target):
        await cq.answer(_lex("input_access_revoked"), show_alert=True)
        return
    info = devices.get(target) or {}
    if _device_declares_command(info, "network_traffic_interval") is not True:
        await cq.answer("Агент не подтвердил эту функцию.", show_alert=True)
        return
    old = devices.get_network_traffic_alert(target)
    cached = devices.get_network_traffic_sample(target, interface_id)
    label = old.get("label") if old.get("interface_id") == interface_id else (cached or {}).get("label")
    if not isinstance(label, str) or not label:
        await cq.answer("Нет свежей привязки к адаптеру; сначала сделай ручной замер.", show_alert=True)
        return
    schedule_id = uuid.uuid4().hex
    sent, command_id = publish_tracked(
        "network_traffic_interval", _target=target,
        interval_seconds=interval_seconds, schedule_id=schedule_id,
        interface_id=interface_id, threshold_bytes=threshold_bytes,
    )
    if not sent:
        await _replace_callback_message(cq, _lex("mqtt_disconnected"), reply_markup=back_to_device_kb())
        return
    await _replace_callback_message(
        cq, "⏳ Применяю настройки к агенту… Мониторинг считается включённым только после точного подтверждения.",
        reply_markup=back_to_device_kb(),
    )
    result = await network_traffic_alert_collector.wait_for(
        target, "network_traffic_alert_status", 8.0, command_id,
    )
    if (SESSION.get("target") != target
            or not _device_action_still_allowed(int(cq.from_user.id), callback, target)):
        await cq.answer(_lex("input_access_revoked"), show_alert=True)
        return
    expected = {
        "type": "network_traffic_alert_status", "schema": "xider.network-traffic-alert.v1",
        "feature_id": "D04-F19", "device_id": target, "request_id": command_id,
        "state": "supported", "interval_seconds": interval_seconds,
        "schedule_id": schedule_id, "interface_id": interface_id,
        "threshold_bytes": threshold_bytes,
    }
    if (not isinstance(result, dict) or set(result) != set(expected) | {"next_sample_at"}
            or any(result.get(key) != value for key, value in expected.items())
            or (interval_seconds == 0 and result.get("next_sample_at") is not None)
            or (interval_seconds > 0 and (type(result.get("next_sample_at")) is not int
                                          or result["next_sample_at"] < int(time.time()) - 60))):
        await _replace_callback_message(
            cq, "⚠️ Нет точного свежего подтверждения. Состояние мониторинга неизвестно; не буду рисовать зелёный статус.",
            reply_markup=back_to_device_kb(),
        )
        await cq.answer()
        return
    try:
        devices.configure_network_traffic_alert(
            target, schedule_id=schedule_id, interface_id=interface_id, label=label,
            interval_seconds=interval_seconds, threshold_bytes=threshold_bytes,
            enabled=interval_seconds > 0,
        )
    except (AttributeError, TypeError, ValueError, OSError):
        await _replace_callback_message(
            cq, "⚠️ Агент подтвердил действие, но состояние сервера не сохранилось. Проверь мониторинг повторно.",
            reply_markup=back_to_device_kb(),
        )
        await cq.answer(show_alert=True)
        return
    if interval_seconds:
        body = (f"🔔 <b>Пороговый мониторинг включён</b> · {html.escape(label)}\n"
                f"Порог: <code>{threshold_bytes:,} байт</code>; проверка каждые {interval_seconds // 60} мин. "
                "Накопление начинается с первого подтверждённого замера, поэтому перезапуск счётчика ОС не засчитывается.")
    else:
        body = f"⏹ <b>Мониторинг трафика выключен</b> · {html.escape(label)}"
    await _replace_callback_message(
        cq, body,
        reply_markup=_network_traffic_markup(target, interface_id=interface_id),
    )
    await cq.answer("Подтверждено")


