@router.callback_query(OwnerFilter(), F.data == "cmd:route_trace")
async def on_cmd_route_trace(cq: CallbackQuery, state: FSMContext):
    target = str(SESSION.get("target") or "")
    if not target or target == "all":
        await cq.answer(_lex("single_device_only"), show_alert=True)
        return
    if not await _callback_result_access_or_report(cq, target):
        return
    info = devices.get(target) or {}
    if _device_declares_command(info, "route_trace") is not True:
        await _replace_callback_message(cq, "Устройство не сообщает поддержку трассировки; запрос не отправлен.",
                                        reply_markup=back_to_device_kb())
        await cq.answer("Нужен совместимый агент.", show_alert=True)
        return
    await _start_authorized_input(state, Form.wait_route_trace, "cmd:route_trace", target)
    await _replace_callback_message(
        cq,
        "Введи один IPv4- или IPv6-адрес. Только числовой IP, без домена; максимум 12 переходов. "
        "В отчёте показываются IP переходов, без имён узлов.",
        reply_markup=back_to_device_kb(),
    )
    await cq.answer()


@router.message(OwnerFilter(), Form.wait_route_trace)
async def on_route_trace_input(message: Message, state: FSMContext):
    form_data = await state.get_data()
    await state.clear()
    target = str(form_data.get("authorization_target") or "")
    if (not target or target == "all" or SESSION.get("target") != target
            or not _pending_device_input_still_allowed(message, form_data, target)):
        await _reject_revoked_device_input(message)
        return
    parsed = _parse_route_trace_input(message.text or "")
    if parsed is None:
        await _replace_user_card(message, "Введи один корректный IPv4/IPv6 unicast-адрес — без домена и списка.",
                                 reply_markup=back_to_device_kb())
        return
    record = devices.get(target) or {}
    if _device_declares_command(record, "route_trace") is not True:
        await _replace_user_card(message, "Агент больше не объявляет поддержку трассировки; запрос не отправлен.",
                                 reply_markup=back_to_device_kb())
        return
    os_name = str(record.get("os") or "").lower()
    platform = "macos" if "mac" in os_name or "darwin" in os_name else "windows" if "win" in os_name else None
    if platform is None:
        await _replace_user_card(message, "Не удалось определить платформу устройства; запрос не отправлен.",
                                 reply_markup=back_to_device_kb())
        return
    sent, command_id = publish_tracked("route_trace", _target=target, **parsed)
    if not sent:
        await _replace_user_card(message, _lex("mqtt_disconnected"), reply_markup=back_to_device_kb())
        return
    await _replace_user_card(message, "🧭 Трассирую ограниченный маршрут до выбранного IP…",
                             reply_markup=back_to_device_kb())
    result = await route_trace_collector.wait_for(target, "route_trace", 18.0, command_id)
    if not _pending_device_input_still_allowed(message, form_data, target):
        await _replace_user_card(message, _lex("action_result_hidden_after_revoke"), reply_markup=back_to_device_kb())
        return
    values = _validated_route_trace(result, target=target, command_id=command_id,
                                    requested_target=parsed["target"], platform=platform)
    if values is None:
        body = "⏳ Нет подтверждённого свежего ответа; маршрут остался неизвестным."
    elif values["state"] == "unsupported":
        body = "🧭 Утилита трассировки недоступна на устройстве; маршрут не определён."
    elif values["state"] == "invalid_request":
        body = "⚠️ Агент отклонил некорректную цель."
    elif values["state"] == "unknown":
        body = f"🧭 Маршрут до <code>{html.escape(values['target'])}</code> не получил ответов."
    else:
        lines = [f"{hop['index']}. " + (f"<code>{html.escape(hop['address'])}</code>" if hop["address"] else "нет ответа")
                 for hop in values["hops"]]
        status = "цель встретилась в трассе" if values["reached"] else "цель не подтверждена; трасса частичная"
        body = (f"🧭 <b>Маршрут до <code>{html.escape(values['target'])}</code></b>\n"
                + "\n".join(lines) + f"\n⚠️ {status}")
    await _replace_user_card(message, body, reply_markup=back_to_device_kb())


@router.callback_query(OwnerFilter(), F.data == "cmd:path_mtu")
async def on_cmd_path_mtu(cq: CallbackQuery, state: FSMContext):
    target = str(SESSION.get("target") or "")
    if not target or target == "all":
        await cq.answer(_lex("single_device_only"), show_alert=True)
        return
    if not await _callback_result_access_or_report(cq, target):
        return
    info = devices.get(target) or {}
    if _device_declares_command(info, "path_mtu") is not True:
        await _replace_callback_message(cq, "Устройство не сообщает поддержку MTU-диагностики; запрос не отправлен.",
                                        reply_markup=back_to_device_kb())
        await cq.answer("Нужен совместимый агент.", show_alert=True)
        return
    await _start_authorized_input(state, Form.wait_path_mtu, "cmd:path_mtu", target)
    await _replace_callback_message(
        cq,
        "Введи один IPv4-адрес, не домен. Агент отправит ICMP-пакеты с запретом фрагментации. "
        "Если ICMP фильтруется, результат будет «неизвестно», а не выдуманный MTU.",
        reply_markup=back_to_device_kb(),
    )
    await cq.answer()


@router.message(OwnerFilter(), Form.wait_path_mtu)
async def on_path_mtu_input(message: Message, state: FSMContext):
    form_data = await state.get_data()
    await state.clear()
    target = str(form_data.get("authorization_target") or "")
    if (not target or target == "all" or SESSION.get("target") != target
            or not _pending_device_input_still_allowed(message, form_data, target)):
        await _reject_revoked_device_input(message)
        return
    parsed = _parse_path_mtu_input(message.text or "")
    if parsed is None:
        await _replace_user_card(message, "Введи один корректный IPv4 unicast-адрес — без домена и списка.",
                                 reply_markup=back_to_device_kb())
        return
    record = devices.get(target) or {}
    if _device_declares_command(record, "path_mtu") is not True:
        await _replace_user_card(message, "Агент больше не объявляет поддержку MTU-диагностики; запрос не отправлен.",
                                 reply_markup=back_to_device_kb())
        return
    os_name = str(record.get("os") or "").lower()
    platform = "macos" if "mac" in os_name or "darwin" in os_name else "windows" if "win" in os_name else None
    if platform is None:
        await _replace_user_card(message, "Не удалось определить платформу устройства; запрос не отправлен.",
                                 reply_markup=back_to_device_kb())
        return
    sent, command_id = publish_tracked("path_mtu", _target=target, **parsed)
    if not sent:
        await _replace_user_card(message, _lex("mqtt_disconnected"), reply_markup=back_to_device_kb())
        return
    await _replace_user_card(message, "🧭 Проверяю ICMP DF-пакеты до выбранного IPv4-адреса…",
                             reply_markup=back_to_device_kb())
    result = await path_mtu_collector.wait_for(target, "path_mtu", 20.0, command_id)
    if not _pending_device_input_still_allowed(message, form_data, target):
        await _replace_user_card(message, _lex("action_result_hidden_after_revoke"), reply_markup=back_to_device_kb())
        return
    values = _validated_path_mtu(result, target=target, command_id=command_id,
                                 requested_target=parsed["target"], platform=platform)
    if values is None:
        body = "⏳ Нет подтверждённого свежего ответа; MTU остался неизвестным."
    elif values["state"] == "unsupported":
        body = "🧭 Утилита ping недоступна на устройстве; MTU не определён."
    elif values["state"] == "invalid_request":
        body = "⚠️ Агент отклонил некорректную цель."
    elif values["state"] == "unknown":
        body = "🧭 ICMP-ответ не подтверждён. Фильтрация или потеря пакетов не позволяют оценить MTU."
    else:
        value = f"≥{values['mtu']} байт" if values["max_tested"] else f"около {values['mtu']} байт"
        body = (f"🧭 <b>ICMP DF-проверка до <code>{html.escape(values['target'])}</code></b>\n"
                f"Подтверждённая граница MTU: <b>{value}</b>.\n"
                "Это оценка по ICMP, не изменение сетевых настроек; другие протоколы могут иметь иную границу.")
    await _replace_user_card(message, body, reply_markup=back_to_device_kb())


